/* ===========================================================
   照片 —— 前端逻辑
   数据来自本地服务 /api/*：选一个根文件夹 → 里面的子文件夹变成相簿 →
   点相簿，右侧铺出这个文件夹里的照片和视频。
   =========================================================== */

const $ = (sel) => document.querySelector(sel);

const cssMotionToken = (name, fallback) =>
  getComputedStyle(document.documentElement).getPropertyValue(name).trim() ||
  fallback;
const UI_EASE_OUT = cssMotionToken(
  "--ease-out",
  "cubic-bezier(0.23, 1, 0.32, 1)",
);
const collator = new Intl.Collator("zh-Hans-CN", {
  numeric: true,
  sensitivity: "base",
});
const DEFAULT_ITEM_SORT = "custom";
const ITEM_SORT_KEY = "photo-item-sort";
const ITEM_SORT_IDS = Object.freeze([
  "newest",
  "oldest",
  "nameAsc",
  "nameDesc",
  "custom",
]);
function normalizeItemSort(value) {
  return ITEM_SORT_IDS.includes(value) ? value : DEFAULT_ITEM_SORT;
}
function readItemSort() {
  try {
    return normalizeItemSort(localStorage.getItem(ITEM_SORT_KEY));
  } catch {
    return DEFAULT_ITEM_SORT;
  }
}
function persistItemSort(kind) {
  try {
    localStorage.setItem(ITEM_SORT_KEY, normalizeItemSort(kind));
  } catch {}
}
