function normalizeLibraryTitle(value) {
  const title = String(value ?? "")
    .trim()
    .slice(0, LIBRARY_TITLE_MAX_LENGTH);
  return title || DEFAULT_LIBRARY_TITLE;
}

function readLibraryTitle() {
  try {
    const title = normalizeLibraryTitle(
      localStorage.getItem(LIBRARY_TITLE_KEY),
    );
    if (
      title.toLowerCase() === "library" &&
      localStorage.getItem(LIBRARY_TITLE_MIGRATION_KEY) !== "done"
    ) {
      localStorage.setItem(LIBRARY_TITLE_KEY, DEFAULT_LIBRARY_TITLE);
      localStorage.setItem(LIBRARY_TITLE_MIGRATION_KEY, "done");
      return DEFAULT_LIBRARY_TITLE;
    }
    localStorage.setItem(LIBRARY_TITLE_MIGRATION_KEY, "done");
    return title;
  } catch {
    return DEFAULT_LIBRARY_TITLE;
  }
}

function normalizeInterfaceName(value, fallback) {
  const name = String(value ?? "")
    .trim()
    .slice(0, INTERFACE_NAME_MAX_LENGTH);
  return name || fallback;
}

function normalizeInterfaceNames(value) {
  const source = value && typeof value === "object" ? value : {};
  const names = {};
  for (const [key, defaultName] of Object.entries(DEFAULT_INTERFACE_NAMES)) {
    const name = normalizeInterfaceName(source[key], defaultName);
    names[key] = name === defaultName ? "" : name;
  }
  return names;
}

function readInterfaceNames() {
  try {
    return normalizeInterfaceNames(
      JSON.parse(localStorage.getItem(INTERFACE_NAMES_KEY) || "{}"),
    );
  } catch {
    return normalizeInterfaceNames({});
  }
}

function interfaceDisplayName(key, names = interfaceNames) {
  const fallback = DEFAULT_INTERFACE_NAMES[key];
  return fallback ? normalizeInterfaceName(names?.[key], fallback) : key;
}

function interfaceFieldDisplayName(key, draft = settingsDraft) {
  if (key === "libraryTitle") {
    return normalizeLibraryTitle(draft?.libraryTitle ?? libraryTitle);
  }
  return interfaceDisplayName(key, draft?.interfaceNames ?? interfaceNames);
}

