function syncAppControlActionsHost() {
  const actions = document.getElementById("headActions");
  const sidebarHead = document.querySelector(".sidebar-head");
  if (!actions || !sidebarHead) return;

  if (actions.parentElement !== sidebarHead) sidebarHead.append(actions);
  const collapsed =
    document
      .getElementById("sidebar")
      ?.classList.contains("is-rail-collapsed") === true;
  actions.inert = collapsed;
  actions.setAttribute("aria-hidden", String(collapsed));
}

