function normalizeWallpaperCruiseCustomSeconds(
  value,
  fallback = WALLPAPER_CRUISE_DEFAULT_CUSTOM_SECONDS,
) {
  if (value == null || String(value).trim() === "") return fallback;
  const seconds = Math.round(Number(value));
  if (!Number.isFinite(seconds)) return fallback;
  return Math.min(
    WALLPAPER_CRUISE_CUSTOM_MAX_SECONDS,
    Math.max(WALLPAPER_CRUISE_CUSTOM_MIN_SECONDS, seconds),
  );
}

function readWallpaperCruiseCustomSeconds() {
  try {
    return normalizeWallpaperCruiseCustomSeconds(
      localStorage.getItem(WALLPAPER_CRUISE_CUSTOM_SECONDS_KEY),
    );
  } catch {
    return WALLPAPER_CRUISE_DEFAULT_CUSTOM_SECONDS;
  }
}

