function applyPreviewAudioPreference(video, { live = false } = {}) {
  if (!video) return;
  video.muted = live ? mutePreviewLivePhoto : mutePreviewVideo;
  video.volume = 1;
}

function syncPreviewAudioPreferences() {
  const previewVideos = document.querySelectorAll(
    ".filmstrip-video, .filmstrip-live-video, .context-source-video",
  );
  for (const video of previewVideos) {
    const live =
      video.classList.contains("filmstrip-live-video") ||
      video.classList.contains("context-source-live-video");
    applyPreviewAudioPreference(video, { live });
  }
}

function syncSidebarFooterVisibility() {
  const importButton = document.getElementById("importLibraryBtn");
  const switchButton = document.getElementById("librarySwitchBtn");
  document.documentElement.classList.toggle(
    "import-library-hover-only",
    hideImportLibraryButton,
  );
  document.documentElement.classList.toggle(
    "library-switch-hover-only",
    hideLibrarySwitchButton,
  );
  /* 保留按钮占位与命中区域；隐藏状态只控制透明度，鼠标移入或键盘
     聚焦时仍能显示入口。 */
  if (importButton) importButton.hidden = false;
  if (switchButton) switchButton.hidden = false;
}

