/* 相簿网格的鼠标滚轮和 Folia 一样做指数趋近：
   普通滚轮格数先累加成待滚动距离，再由 requestAnimationFrame 逐帧追；
   触控板自身已经连续且有系统惯性，继续交给浏览器原生滚动。 */
const ALBUM_WHEEL_SMOOTHING = {
  timeConstantMs: 80,
  restDistancePx: 0.5,
  maxFrameMs: 50,
  lineHeightPx: 16,
  minNotchPx: 50,
  gestureGapMs: 120,
};
/* 地图照片栏比普通项目网格更紧凑，滚轮需要更大的位移才容易浏览。 */
const MAP_FILMSTRIP_WHEEL_MULTIPLIER = 1.8;
const albumWheelScroll = {
  pending: 0,
  frame: 0,
  lastTime: null,
  gesture: null,
  lastEventTime: Number.NEGATIVE_INFINITY,
};

/* 与 Folia 相同的松手惯性参数：
   速度按最后一段指针位移计算，松手后速度指数衰减并停止。 */
const PHOTO_WALL_INERTIA = {
  minSpeed: 40,
  maxSpeed: 4000,
  power: 0.3,
  timeConstant: 280,
  restDelta: 0.5,
  staleReleaseMs: 80,
};
const photoWallWheel = {
  pendingX: 0,
  pendingY: 0,
  frame: 0,
  lastTime: null,
  gesture: null,
  lastEventTime: Number.NEGATIVE_INFINITY,
};
const albumGridDragScroll = {
  frame: 0,
  inertia: null,
};
let albumGridDrag = null;
let albumGridDragClickGuardUntil = 0;

/* 照片墙是一块比内容区更宽的画布：拖动移动的是整面墙，
   照片之间的相对位置始终不变。位置、惯性和边界都不写进持久状态，
   退出照片墙后下一次打开会重新从画布中央开始。 */
const photoWallCamera = {
  x: 0,
  y: 0,
  vx: 0,
  vy: 0,
  bounds: null,
  frame: 0,
  lastFrame: 0,
  inertia: null,
};
let photoWallPan = null;
let photoWallClickGuardUntil = 0;
let photoWallLayoutFrame = 0;
let photoWallFrame = null;
let photoWallReady = false;
let photoWallTransition = "idle";
let photoWallExitResolver = null;
let photoWallSidebarRailMarker = null;
let photoWallDomFrozen = false;
let photoWallAppWasInert = false;
let photoWallAppAriaHidden = null;
let photoWallFocus = null;
let photoWallFocusSeq = 0;
let photoWallEnterTimer = 0;
let photoWallLoadingShowTimer = 0;
let photoWallLoadingHideTimer = 0;
let photoWallLoadingRequest = 0;
let photoWallLoadWatchdogTimer = 0;
let photoWallInitRetryAttempted = false;

const PHOTO_WALL_ENTER_TIMEOUT_MS = 12000;
const PHOTO_WALL_LOADING_FADE_MS = 180;
const PHOTO_WALL_LIBRARY_LOADING_DELAY_MS = 240;
const PHOTO_WALL_LOAD_WATCHDOG_MS = 5000;
const PHOTO_WALL_PENDING_ENTRY_KEY = "photo-wall-pending-entry";
const PHOTO_WALL_PENDING_ENTRY_MAX_AGE_MS = 15000;

function rememberPhotoWallPendingEntry(mode) {
  try {
    sessionStorage.setItem(
      PHOTO_WALL_PENDING_ENTRY_KEY,
      JSON.stringify({
        mode,
        activeId: state.activeId,
        photoWallAlbumId: state.photoWallAlbumId,
        masonryWallAlbumId: state.masonryWallAlbumId,
        filmrollWallAlbumId: state.filmrollWallAlbumId,
        mosaicWallAlbumId: state.mosaicWallAlbumId,
        at: Date.now(),
      }),
    );
  } catch {}
}

function readPhotoWallPendingEntry() {
  try {
    const pending = JSON.parse(
      sessionStorage.getItem(PHOTO_WALL_PENDING_ENTRY_KEY) || "null",
    );
    if (
      !pending ||
      !["wall", "library"].includes(pending.mode) ||
      !Number.isFinite(Number(pending.at)) ||
      Date.now() - Number(pending.at) > PHOTO_WALL_PENDING_ENTRY_MAX_AGE_MS
    ) {
      return null;
    }
    return pending;
  } catch {
    return null;
  }
}

function clearPhotoWallPendingEntry() {
  try {
    sessionStorage.removeItem(PHOTO_WALL_PENDING_ENTRY_KEY);
  } catch {}
}

function showPhotoWallLoading({ delay = 0 } = {}) {
  const layer = $("#photoWallLoading");
  if (!layer) return;
  window.clearTimeout(photoWallLoadingShowTimer);
  window.clearTimeout(photoWallLoadingHideTimer);
  photoWallLoadingShowTimer = 0;
  photoWallLoadingHideTimer = 0;
  const request = ++photoWallLoadingRequest;
  const reveal = () => {
    photoWallLoadingShowTimer = 0;
    if (request !== photoWallLoadingRequest) return;
    layer.hidden = false;
    document.body.classList.add("photo-wall-loading-active");
    requestAnimationFrame(() => {
      if (request === photoWallLoadingRequest && !layer.hidden) {
        hydrateLemniscateCurveLoaders();
        layer.classList.add("is-visible");
        restartLemniscateCurveLoader(layer);
      }
    });
  };
  /* 资料库通常能在一两帧内读出缓存，短暂遮住整窗反而像界面闪了一下。
     只有读取确实变慢时才显示载入层。 */
  if (delay > 0 && !layer.classList.contains("is-visible")) {
    photoWallLoadingShowTimer = window.setTimeout(reveal, delay);
    return;
  }
  reveal();
}

function hidePhotoWallLoading({ immediate = false } = {}) {
  const layer = $("#photoWallLoading");
  if (!layer) return;
  photoWallLoadingRequest += 1;
  window.clearTimeout(photoWallLoadingShowTimer);
  window.clearTimeout(photoWallLoadingHideTimer);
  photoWallLoadingShowTimer = 0;
  photoWallLoadingHideTimer = 0;
  layer.classList.remove("is-visible");
  if (immediate) {
    disposeLemniscateCurveLoaders(layer);
    layer.hidden = true;
    document.body.classList.remove("photo-wall-loading-active");
    return;
  }
  photoWallLoadingHideTimer = window.setTimeout(() => {
    photoWallLoadingHideTimer = 0;
    if (!layer.classList.contains("is-visible")) {
      disposeLemniscateCurveLoaders(layer);
      layer.hidden = true;
      document.body.classList.remove("photo-wall-loading-active");
    }
  }, PHOTO_WALL_LOADING_FADE_MS);
}

function clearPhotoWallEnterTimeout() {
  window.clearTimeout(photoWallEnterTimer);
  photoWallEnterTimer = 0;
}

function clearPhotoWallLoadWatchdog() {
  window.clearTimeout(photoWallLoadWatchdogTimer);
  photoWallLoadWatchdogTimer = 0;
}

function armPhotoWallLoadWatchdog() {
  clearPhotoWallLoadWatchdog();
  photoWallLoadWatchdogTimer = window.setTimeout(() => {
    photoWallLoadWatchdogTimer = 0;
    if (photoWallInitRetryAttempted) return;
    if (!state.photoWall || photoWallTransition !== "entering") return;
    if (!photoWallFrame?.isConnected) {
      mountPhotoWallApp();
    } else if (photoWallReady) {
      /* ready 已到达但没有进入 reveal-start，说明初始化消息没有完成处理。
         清掉去重标记后再发一次同一份数据。 */
      photoWallFrame.dataset.payload = "";
      postPhotoWallData(photoWallFrame);
    } else {
      /* iframe 首轮导航或懒加载没有完成：换一个全新的 iframe 再试一次。 */
      unmountPhotoWallApp();
      mountPhotoWallApp();
    }
    photoWallInitRetryAttempted = true;
  }, PHOTO_WALL_LOAD_WATCHDOG_MS);
}

function armPhotoWallEnterTimeout() {
  clearPhotoWallEnterTimeout();
  photoWallEnterTimer = window.setTimeout(() => {
    photoWallEnterTimer = 0;
    if (!state.photoWall || photoWallTransition !== "entering") return;
    clearPhotoWallLoadWatchdog();
    clearPhotoWallPendingEntry();
    photoWallPlaybackOpenSeq += 1;
    unmountPhotoWallApp();
    releasePhotoWallBackdrop();
    state.photoWall = false;
    state.photoWallPlayback = null;
    photoWallTransition = "idle";
    hidePhotoWallLoading({ immediate: true });
    flushPendingUpdate();
    toast("照片墙载入超时，请重试");
  }, PHOTO_WALL_ENTER_TIMEOUT_MS);
}

async function resumePendingPhotoWallEntry() {
  const pending = readPhotoWallPendingEntry();
  if (!pending) return false;
  clearPhotoWallPendingEntry();
  if (pending.mode === "library") {
    await select("photoWall");
    return state.activeId === "photoWall";
  }
  try {
    if (pending.activeId === "photoWall") {
      state.activeId = "photoWall";
      await loadPhotoWallAlbums();
      const pendingAlbumId = (value) => {
        const id = Number(value);
        return Number.isInteger(id) && id > 0 ? id : null;
      };
      const tileAlbumId = pendingAlbumId(pending.photoWallAlbumId);
      const masonryAlbumId = pendingAlbumId(pending.masonryWallAlbumId);
      const filmrollAlbumId = pendingAlbumId(pending.filmrollWallAlbumId);
      const mosaicAlbumId = pendingAlbumId(pending.mosaicWallAlbumId);
      if (mosaicAlbumId != null) {
        return startMosaicWallPlayback("photos-some", [mosaicAlbumId]);
      }
      if (filmrollAlbumId != null) {
        return startFilmrollWallPlayback("photos-some", [filmrollAlbumId]);
      }
      if (masonryAlbumId != null) {
        return startMasonryWallPlayback("photos-some", [masonryAlbumId]);
      }
      return startPhotoWallPlayback(
        tileAlbumId != null ? "photos-some" : "photos-all",
        tileAlbumId != null ? [tileAlbumId] : null,
      );
    }
    const pendingId = Number(pending.activeId);
    if (Number.isInteger(pendingId) && albumById(pendingId)) {
      state.activeId = pendingId;
      await loadAlbum(pendingId, { quiet: true });
    } else if (pending.activeId === "library") {
      state.activeId = "library";
      await loadLibrary();
    } else {
      return false;
    }
    if (!photoWallCandidates().length) return false;
    setPhotoWall(true);
    return true;
  } catch {
    return false;
  }
}

function clearSelection() {
  state.selected.clear();
  state.selectedTrashAlbums.clear();
}

const ACTIVE_VIEW_KEY = "album-active-view";
const COLLECTION_SCROLL_KEY = "photo-collection-scroll-positions";
const readCollectionScrollPositions = () => {
  try {
    const value = JSON.parse(
      localStorage.getItem(COLLECTION_SCROLL_KEY) || "{}",
    );
    return value && typeof value === "object" ? value : {};
  } catch {
    return {};
  }
};
const collectionScrollPositions = readCollectionScrollPositions();

function collectionScrollKey(id = state.activeId) {
  if (id !== "library" && typeof id !== "number") return "";
  return `${Number(state.activeRootId) || 0}:${id}`;
}

function rememberCollectionScroll(id = state.activeId) {
  const key = collectionScrollKey(id);
  const content = $("#content");
  if (!key || !content || content.hidden || isAlbumMapView?.()) return;
  collectionScrollPositions[key] = Math.max(0, content.scrollTop);
  try {
    localStorage.setItem(
      COLLECTION_SCROLL_KEY,
      JSON.stringify(collectionScrollPositions),
    );
  } catch {}
}

function restoreCollectionScroll(id = state.activeId) {
  const key = collectionScrollKey(id);
  const content = $("#content");
  if (!key || !content) return;
  const top = Math.max(0, Number(collectionScrollPositions[key]) || 0);
  content.scrollTop = top;
  syncVirtualPhotoGridWindowNow();
  requestAnimationFrame(() => {
    if ($("#content") !== content) return;
    content.scrollTop = top;
    syncVirtualPhotoGridWindowNow();
  });
}

let collectionScrollPersistTimer = 0;
$("#content").addEventListener(
  "scroll",
  () => {
    scheduleProgressivePhotoGridFill();
    clearTimeout(collectionScrollPersistTimer);
    collectionScrollPersistTimer = setTimeout(() => {
      collectionScrollPersistTimer = 0;
      rememberCollectionScroll();
    }, 140);
  },
  { passive: true },
);
window.addEventListener("beforeunload", () => rememberCollectionScroll());

/* sessionStorage 只在当前这个应用窗口里有效：
   窗口内刷新会保留当前视图，关闭软件后重新启动则从「图库」开始。 */
const rememberActiveView = () =>
  sessionStorage.setItem(ACTIVE_VIEW_KEY, String(state.activeId));

/* 兜底的全局版本号：没有单项版本信息的旧数据才用它。
   网格和相簿封面各自带自己的版本，移动照片时不会整片换 URL。 */
const thumbVersion = () => state.coverEpoch || state.scan?.finishedAt || 0;
const thumbUrlAt = (id, size = 400, fit = "cover", version = thumbVersion()) =>
  `/api/thumb/${id}?size=${size}${fit === "inside" ? "&fit=inside" : ""}&v=${version}`;
/* 网格里的照片按自己的修改时间和大小版本化：移动别的照片时，
   剩下的照片 URL 不变，不会整片闪空。根文件夹的 addedAt 用来防换库后 id 复用。 */
const itemThumbVersion = (item) => {
  const root = state.roots.find(
    (entry) => Number(entry.id) === Number(item?.rootId),
  );
  return `${Number(root?.addedAt) || 0}-${Number(item?.mtime) || 0}-${Number(item?.size) || 0}-${Number(item?.editRevision) || 0}-${Number(item?.videoPosterRevision) || 0}`;
};
const itemThumbUrl = (item, size = 400, fit = "inside") =>
  thumbUrlAt(item.id, size, fit, itemThumbVersion(item));
const filmrollWallThumbUrl = (item, size = 900) => {
  const crop = item?.filmrollCrop || {};
  const version = [
    crop.ratioKey || "",
    crop.updatedAt || 0,
    crop.anchor || "center",
    itemThumbVersion(item),
  ].join("-");
  return `/api/filmroll-wall/thumb/${item.id}?size=${size}&v=${encodeURIComponent(
    version,
  )}`;
};
const mosaicWallThumbUrl = (item, size = 1200) => {
  const crop = item?.mosaicCrop || {};
  const version = [
    crop.ratioKey || "",
    crop.updatedAt || 0,
    crop.anchor || "center",
    itemThumbVersion(item),
  ].join("-");
  return `/api/mosaic-wall/thumb/${item.id}?size=${size}&v=${encodeURIComponent(
    version,
  )}`;
};
const mosaicWallDataCache = new Map();
const mosaicWallDataRequests = new Map();
const mosaicWallSeedCache = new Map();
const mosaicWallWarmThumbs = new Set();
let mosaicWallWarmQueue = [];
let mosaicWallWarmActive = 0;
const MOSAIC_WALL_THUMB_SIZE = 1000;
const MOSAIC_WALL_WARM_CONCURRENCY = 8;

function mosaicWallCacheKey(albumIds = null) {
  const scope = albumIds
    ? [...albumIds]
        .map(Number)
        .sort((first, second) => first - second)
        .join(",")
    : "all";
  return `${state.activeRootId || 0}:${scope}`;
}

function mosaicWallSeedFor(albumIds = null) {
  const normalized = albumIds?.length ? [...albumIds].map(Number) : null;
  const key = mosaicWallCacheKey(normalized);
  if (mosaicWallSeedCache.has(key)) return mosaicWallSeedCache.get(key);
  const seed = randomPhotoWallSeed();
  if (mosaicWallSeedCache.size >= 32 && !mosaicWallSeedCache.has(key)) {
    mosaicWallSeedCache.delete(mosaicWallSeedCache.keys().next().value);
  }
  mosaicWallSeedCache.set(key, seed);
  return seed;
}

function pumpMosaicWallWarmQueue() {
  while (
    mosaicWallWarmActive < MOSAIC_WALL_WARM_CONCURRENCY &&
    mosaicWallWarmQueue.length
  ) {
    const url = mosaicWallWarmQueue.shift();
    if (!url || mosaicWallWarmThumbs.has(url)) continue;
    mosaicWallWarmActive += 1;
    const image = new Image();
    image.decoding = "async";
    const finish = () => {
      mosaicWallWarmThumbs.add(url);
      mosaicWallWarmActive = Math.max(0, mosaicWallWarmActive - 1);
      pumpMosaicWallWarmQueue();
    };
    image.onload = finish;
    image.onerror = finish;
    image.src = url;
  }
}

function warmMosaicWallThumbnails(items) {
  const urls = [
    ...new Set(
      (items || [])
        .map((item) => mosaicWallThumbUrl(item, MOSAIC_WALL_THUMB_SIZE))
        .filter(Boolean),
    ),
  ];
  mosaicWallWarmQueue.push(
    ...urls.filter((url) => !mosaicWallWarmThumbs.has(url)),
  );
  pumpMosaicWallWarmQueue();
}

async function loadMosaicWallData(albumIds = null) {
  const normalized = albumIds?.length ? [...albumIds].map(Number) : null;
  const key = mosaicWallCacheKey(normalized);
  if (mosaicWallDataCache.has(key)) {
    return mosaicWallDataCache.get(key);
  }
  if (mosaicWallDataRequests.has(key)) {
    return mosaicWallDataRequests.get(key);
  }
  const query = normalized
    ? `?albums=${[...new Set(normalized)].join(",")}`
    : "";
  const request = api(`/api/mosaic-wall/photos${query}`)
    .then((data) => {
      mosaicWallDataCache.set(key, data);
      return data;
    })
    .finally(() => {
      mosaicWallDataRequests.delete(key);
    });
  mosaicWallDataRequests.set(key, request);
  return request;
}
const photoWallCropForItem = (item) =>
  item?.photoWallCropX != null && item?.photoWallCropY != null
    ? {
        x: Number(item.photoWallCropX),
        y: Number(item.photoWallCropY),
        size: Number(item.photoWallCropSize) || 1,
        updatedAt: Number(item.photoWallCropUpdatedAt) || 0,
      }
    : { x: 0.5, y: 0.5, size: 1, updatedAt: 0 };
const photoWallThumbUrl = (item, size = 600) => {
  const crop = photoWallCropForItem(item);
  return `/api/photo-wall/thumb/${item.id}?size=${size}&v=${encodeURIComponent(
    `${itemThumbVersion(item)}-${crop.updatedAt}`,
  )}`;
};
const isLivePhoto = (item) =>
  item?.kind === "photo" && Number(item.liveVideoId) > 0;
const liveVideoId = (item) =>
  isLivePhoto(item) ? Number(item.liveVideoId) : 0;
const viewItemUrl = (item) =>
  `/api/view/${item.id}?v=${encodeURIComponent(itemThumbVersion(item))}`;
const itemActionIds = (items) => [
  ...new Set(
    (items || []).flatMap((item) => {
      const ids = [Number(item.id)];
      const companion = liveVideoId(item);
      if (companion) ids.push(companion);
      return ids.filter((id) => Number.isInteger(id) && id > 0);
    }),
  ),
];
const itemActionIdsFromIds = (ids) => {
  const known = new Map();
  for (const item of [
    ...state.items,
    ...state.albumItems,
    ...state.albumItemsRaw,
  ]) {
    if (item?.id != null) known.set(Number(item.id), item);
  }
  const result = itemActionIds(
    (ids || []).map((id) => known.get(Number(id))).filter(Boolean),
  );
  for (const id of ids || []) {
    const number = Number(id);
    if (Number.isInteger(number) && number > 0 && !result.includes(number))
      result.push(number);
  }
  return result;
};
const coverThumbUrl = (id, size = 400, version = "") =>
  thumbUrlAt(id, size, "cover", version || thumbVersion());
const openingPosterUrl = (item, version = thumbVersion()) => {
  const id = typeof item === "object" && item ? item.id : item;
  /* 开场封面也按视频内容版本化。只带全局 coverEpoch 时，服务端缓存
     被重建但版本号没变，浏览器仍会继续使用同一 URL 的旧封面。 */
  const sourceVersion =
    item && typeof item === "object"
      ? `${item.mtime || item.taken_at || item.size || 0}-${Number(item.videoPosterRevision) || 0}`
      : 0;
  return `/api/opening/${id}?v=${version}-${sourceVersion}`;
};
const fileUrl = (itemOrId) => {
  const id = typeof itemOrId === "object" ? itemOrId?.id : itemOrId;
  const item =
    typeof itemOrId === "object"
      ? itemOrId
      : state.items.find((entry) => Number(entry.id) === Number(itemOrId));
  const version = item
    ? `${Number(item.mtime) || 0}-${Number(item.size) || 0}-${Number(item.editRevision) || 0}`
    : thumbVersion();
  return `/api/file/${id}?v=${version}`;
};
const esc = (s) =>
  String(s ?? "").replace(
    /[&<>"]/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
  );

async function api(path, opts) {
  const headers = new Headers(opts?.headers || {});
  if (opts?.body != null && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }
  const res = await fetch(path, { ...opts, headers });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || `请求失败（${res.status}）`);
  return data;
}

function applyState(payload) {
  state.roots = payload.roots || [];
  state.activeRootId =
    payload.activeRootId == null ? null : Number(payload.activeRootId);
  state.albums = payload.albums || [];
  state.revision = Number(payload.revision) || 0;
  state.scan = payload.scan || null;
  state.coverEpoch = payload.coverEpoch || 0;
  state.folderPrompts = payload.folderPrompts || [];
  state.trashCount = payload.trashCount || 0;
  state.favoriteCount = Number(payload.favoriteCount) || 0;
}

const activeRootEntry = () =>
  state.roots.find((root) => Number(root.id) === Number(state.activeRootId)) ||
  state.roots[0] ||
  null;

/* 图库与相簿的 DOM / 数据缓存必须带当前根目录身份。
   两个图库的 revision 或照片 ID 恰好相同时，也不能互相命中缓存。 */
function activeRootCacheKey() {
  const root = activeRootEntry();
  if (!root) return "none";
  return `${Number(root.id) || 0}:${Number(root.addedAt) || 0}`;
}

function resetPhotoWallLibraryState() {
  state.photoWallAlbums = [];
  state.photoWallAlbumId = null;
  state.photoWallPlayback = null;
  state.photoWallSelectedAlbums.clear();
  state.photoWallSelectMode = null;
  state.masonryWallAlbums = [];
  state.masonryWallAlbumId = null;
  state.masonryWallSelectedAlbums.clear();
  state.masonryWallSelectMode = null;
  state.filmrollWallAlbums = [];
  state.filmrollWallAlbumId = null;
  state.filmrollWallSelectedAlbums.clear();
  state.filmrollWallSelectMode = null;
  state.mosaicWallAlbums = [];
  state.mosaicWallAlbumId = null;
  state.mosaicWallSelectedAlbums.clear();
  state.mosaicWallSelectMode = null;
  photoWallAlbumConfirmBusy = false;
}

const albumById = (id) => state.albums.find((a) => a.id === Number(id));
const compareAlbumOrder = (x, y) => {
  const xUnfiled = !!x.isUnfiled || !!x.isRoot;
  const yUnfiled = !!y.isUnfiled || !!y.isRoot;
  /* 根文件夹里的直属项目显示成「未归档」，永远排在普通相簿后面。 */
  if (xUnfiled !== yUnfiled) return xUnfiled ? 1 : -1;
  const xo = x.sortOrder == null ? null : Number(x.sortOrder);
  const yo = y.sortOrder == null ? null : Number(y.sortOrder);
  if (xo != null || yo != null) {
    if (xo == null) return 1;
    if (yo == null) return -1;
    if (xo !== yo) return xo - yo;
  }
  return collator.compare(x.name, y.name);
};
const childrenOf = (id) =>
  state.albums.filter((a) => a.parentId === id).sort(compareAlbumOrder);
const kidsOf = (id) => childrenOf(id);
const topAlbumsOf = (rootId) =>
  state.albums
    .filter((a) => a.rootId === rootId && a.parentId === null)
    .sort(compareAlbumOrder);
const isUnfiledAlbum = (album) =>
  !!album?.isUnfiled || album?.kind === "unfiled" || !!album?.isRoot;
const albumDisplayName = (album) => {
  if (!isUnfiledAlbum(album)) return album?.name || "";
  return interfaceDisplayName("unfiled");
};
const isAlbumMapView = () =>
  Boolean(
    state.albumMapOpen &&
    (state.activeId === "library" ||
      (typeof state.activeId === "number" && albumById(state.activeId))),
  );
const visibleTopAlbumsOf = (rootId) =>
  topAlbumsOf(rootId).filter(
    (album) => !isUnfiledAlbum(album) || (showUnfiledCard && album.count > 0),
  );
const visibleAlbumCardsOf = (rootId) =>
  topAlbumsOf(rootId).filter((album) => !isUnfiledAlbum(album));

/* 筛选只属于当前一次集合浏览。布局和排序是长期偏好，
   进入其他视图再回来时不能与筛选一起被清掉。 */
function resetTransientAlbumFilters() {
  state.filterKind = "all";
  state.typeKind = "all";
  state.deviceKind = "all";
  state.locationFilter = "all";
  state.extensionFilter = null;
}

function fallbackToAllAlbums() {
  state.activeId = "all";
  state.album = null;
  state.items = [];
  state.albumItems = [];
  state.albumItemsRaw = [];
  state.albumMapOpen = false;
  state.albumMapAssignMode = false;
  state.albumMapItems = [];
  resetTransientAlbumFilters();
  state.zoomAnchorId = null;
  rememberActiveView();
}

/* 设置页写入全局默认；右上角布局菜单只覆盖当前图库或相簿。
   临时覆盖在当前运行期间保留，重新打开软件后回到全局默认。 */
const ratioViewKey = () =>
  `${state.activeRootId == null ? "" : state.activeRootId}:${state.activeId}`;
function defaultPhotoStyle() {
  if (photoLayoutMode === "justified" || photoLayoutMode === "masonry") {
    return photoLayoutMode;
  }
  return defaultOriginalRatio ? "original" : "square";
}
function activePhotoStyle() {
  return (
    state.photoStyleOverrides.get(ratioViewKey()) || defaultPhotoStyle()
  );
}
const isOriginalRatio = () => activePhotoStyle() === "original";
const GALLERY_ZOOM_MIN = 1;
const GALLERY_ZOOM_MAX = 4;
const clampGalleryZoom = (level) =>
  Math.max(GALLERY_ZOOM_MIN, Math.min(GALLERY_ZOOM_MAX, level));
/* 浏览网格不再始终请求 600px。缩略图尺寸跟着四档网格走，
   高质量文件只在查看器和编辑界面加载。 */
function galleryThumbSizeForZoom(level = state.photoZoom) {
  const zoom = clampGalleryZoom(level);
  if (zoom <= 2) return 200;
  if (zoom === 3) return 400;
  return 600;
}
const galleryZoomClasses = () => {
  const level = clampGalleryZoom(state.photoZoom);
  return ` gallery-zoom-${level}${level <= 2 ? " gallery-square" : ""}`;
};
const canZoomGallery = () => {
  if (state.copyTarget || state.photoWall || state.filmstrip) return false;
  return (
    (state.activeId === "library" ||
      (state.activeId === "locations" && state.locationSubview !== "map") ||
      !!albumById(state.activeId)) &&
    state.items.length > 0
  );
};

/* ---------------------- 照片网格布局 ---------------------- */

const PHOTO_LAYOUT_GAP = 5;
const VIRTUAL_PHOTO_GRID_MIN_ITEMS = 160;
const VIRTUAL_PHOTO_GRID_OVERSCAN = 1.5;
let photoGridLayoutFrame = 0;
let photoGridLastWidth = -1;
let photoGridLayoutSuspended = false;
let virtualPhotoGridWindowFrame = 0;
const virtualPhotoGridLayouts = new WeakMap();

function photoLayoutGrids() {
  return [...document.querySelectorAll("#content .photo-grid")].filter(
    (grid) =>
      !grid.classList.contains("photo-wall-grid") &&
      !grid.classList.contains("photo-wall-library-photo-grid"),
  );
}

/* 原始比例保留固定方格作为排版槽位，照片在槽位内按自身比例显示。
   格子周围的空间属于原始比例模式本身；空白页问题必须从图片加载/
   缩略图状态修复，不能通过替换整个布局来掩盖。 */
function effectivePhotoLayoutMode() {
  const style = activePhotoStyle();
  return style === "original" || style === "square" ? "tile" : style;
}

function syncPhotoGridLayoutClasses() {
  const effectiveMode = effectivePhotoLayoutMode();
  const originalRatio = isOriginalRatio();
  const content = $("#content");
  if (content) {
    content.classList.toggle("original", originalRatio);
    for (const mode of PHOTO_LAYOUT_MODES) {
      content.classList.toggle(
        `photo-layout-${mode.id}`,
        mode.id === effectiveMode,
      );
    }
  }
  for (const grid of photoLayoutGrids()) {
    grid.classList.toggle("original", originalRatio);
    for (const mode of PHOTO_LAYOUT_MODES) {
      grid.classList.toggle(
        `photo-layout-${mode.id}`,
        mode.id === effectiveMode,
      );
    }
  }
}

function photoLayoutTargetSize(grid) {
  const style = getComputedStyle(grid);
  const baseSize =
    parseFloat(style.getPropertyValue("--photo-tile-base")) || 190;
  const level = clampGalleryZoom(state.photoZoom);
  const scale = level === 1 ? 0.25 : level === 2 ? 0.5 : level === 3 ? 1 : 1.55;
  return Math.max(36, baseSize * scale);
}

function photoLayoutGap(grid) {
  const value = parseFloat(
    getComputedStyle(grid).getPropertyValue("--photo-grid-current-gap"),
  );
  return Number.isFinite(value) ? Math.max(0, value) : PHOTO_LAYOUT_GAP;
}

function photoAspect(item, tile) {
  const width = Number(item?.width);
  const height = Number(item?.height);
  const fallback = Number(tile?.style.getPropertyValue("--ar")) || 1;
  const ratio = width > 0 && height > 0 ? width / height : fallback;
  return Math.max(0.08, Math.min(12, Number.isFinite(ratio) ? ratio : 1));
}

/* 行内布局：先按同一目标高度估宽，再比较“提前换行”和“带上这张再换行”
   哪种更接近目标高度。完整行最终拉到容器宽度，最后一行不强行放大。 */
function justifiedPhotoBoxes(
  entries,
  width,
  targetSize,
  gap = PHOTO_LAYOUT_GAP,
) {
  const boxes = [];
  let row = [];
  let rowAspect = 0;
  let rowWidth = 0;
  let y = 0;

  const flush = (isLastRow) => {
    if (!row.length) return;
    const available = Math.max(1, width - gap * (row.length - 1));
    const rowHeight = isLastRow
      ? Math.min(targetSize, available / rowAspect)
      : available / rowAspect;
    let x = 0;
    for (const entry of row) {
      const itemWidth = rowHeight * entry.aspect;
      boxes.push({
        index: entry.index,
        x,
        y,
        width: itemWidth,
        height: rowHeight,
      });
      x += itemWidth + gap;
    }
    y += rowHeight + gap;
    row = [];
    rowAspect = 0;
    rowWidth = 0;
  };

  for (const entry of entries) {
    const nextWidth =
      rowWidth + (row.length ? gap : 0) + entry.aspect * targetSize;
    if (row.length && nextWidth > width) {
      const heightBefore =
        Math.max(1, width - gap * (row.length - 1)) / rowAspect;
      const heightAfter =
        Math.max(1, width - gap * row.length) / (rowAspect + entry.aspect);
      if (
        Math.abs(heightBefore - targetSize) < Math.abs(heightAfter - targetSize)
      ) {
        flush(false);
        row.push(entry);
        rowAspect = entry.aspect;
        rowWidth = entry.aspect * targetSize;
      } else {
        row.push(entry);
        rowAspect += entry.aspect;
        flush(false);
      }
    } else {
      row.push(entry);
      rowAspect += entry.aspect;
      rowWidth = nextWidth;
    }
  }
  flush(true);
  return {
    boxes,
    height: boxes.length ? Math.max(0, y - gap) : 0,
  };
}

/* 等宽成列固定列宽，每一项保持自己的宽高比，放进当前最矮的一列。 */
function masonryPhotoBoxes(
  entries,
  width,
  targetWidth,
  gap = PHOTO_LAYOUT_GAP,
) {
  const columns = Math.max(
    1,
    Math.floor((width + gap) / Math.max(1, targetWidth + gap)),
  );
  const columnWidth = Math.max(1, (width - gap * (columns - 1)) / columns);
  const heights = new Array(columns).fill(0);
  const boxes = entries.map((entry) => {
    let column = 0;
    for (let i = 1; i < columns; i += 1) {
      if (heights[i] < heights[column]) column = i;
    }
    const itemHeight = columnWidth / entry.aspect;
    const box = {
      index: entry.index,
      x: column * (columnWidth + gap),
      y: heights[column],
      width: columnWidth,
      height: itemHeight,
    };
    heights[column] += itemHeight + gap;
    return box;
  });
  return {
    boxes,
    height: boxes.length ? Math.max(...heights) - gap : 0,
  };
}

function tilePhotoBoxes(entries, width, targetSize, gap = PHOTO_LAYOUT_GAP) {
  const columns = Math.max(
    1,
    Math.floor((width + gap) / Math.max(1, targetSize + gap)),
  );
  const cellSize = Math.max(1, (width - gap * (columns - 1)) / columns);
  const boxes = entries.map((entry, position) => ({
    index: entry.index,
    x: (position % columns) * (cellSize + gap),
    y: Math.floor(position / columns) * (cellSize + gap),
    width: cellSize,
    height: cellSize,
  }));
  const rows = Math.ceil(entries.length / columns);
  return {
    boxes,
    height: rows ? rows * cellSize + (rows - 1) * gap : 0,
  };
}

function virtualPhotoGridEntries(grid) {
  const rawIndices = grid?.dataset.windowIndices;
  if (rawIndices == null) return [];
  return rawIndices
    .split(",")
    .map(Number)
    .filter(Number.isInteger)
    .map((index) => {
      const item = state.items[index];
      return item ? { item, index, aspect: photoAspect(item) } : null;
    })
    .filter(Boolean);
}

function syncVirtualPhotoGrid(grid, layout) {
  const content = $("#content");
  if (!grid?.isConnected || !content || !layout?.boxes.length) return;
  const contentRect = content.getBoundingClientRect();
  const gridRect = grid.getBoundingClientRect();
  const contentTop = content.scrollTop + gridRect.top - contentRect.top;
  const overscan = content.clientHeight * VIRTUAL_PHOTO_GRID_OVERSCAN;
  const rangeTop = content.scrollTop - overscan;
  const rangeBottom = content.scrollTop + content.clientHeight + overscan;
  const visibleBoxes = layout.boxes.filter(
    (box) =>
      box.y + box.height + contentTop >= rangeTop &&
      box.y + contentTop <= rangeBottom,
  );
  const visible = new Set(visibleBoxes.map((box) => box.index));
  const focusedTile = document.activeElement?.closest?.(
    ".photo-grid .tile[data-index]",
  );
  const focusedIndex =
    focusedTile && grid.contains(focusedTile)
      ? Number(focusedTile.dataset.index)
      : -1;

  for (const tile of grid.querySelectorAll(":scope > .tile[data-index]")) {
    const index = Number(tile.dataset.index);
    if (visible.has(index) || index === focusedIndex) continue;
    galleryImageWindowObserver?.unobserve(tile);
    tile.remove();
  }

  const present = new Set(
    [...grid.querySelectorAll(":scope > .tile[data-index]")].map((tile) =>
      Number(tile.dataset.index),
    ),
  );
  const missing = visibleBoxes.filter((box) => !present.has(box.index));
  if (missing.length) {
    const template = document.createElement("template");
    template.innerHTML = missing
      .map((box) => itemTile(state.items[box.index], box.index))
      .join("");
    grid.append(template.content);
  }

  for (const box of visibleBoxes) {
    const tile = grid.querySelector(
      `:scope > .tile[data-index="${box.index}"]`,
    );
    if (!tile) continue;
    tile.style.left = `${box.x.toFixed(3)}px`;
    tile.style.top = `${box.y.toFixed(3)}px`;
    tile.style.width = `${box.width.toFixed(3)}px`;
    tile.style.height = `${box.height.toFixed(3)}px`;
  }
  observeGalleryImageTiles([grid]);
}

function syncVirtualPhotoGridWindowNow() {
  if (virtualPhotoGridWindowFrame) {
    cancelAnimationFrame(virtualPhotoGridWindowFrame);
    virtualPhotoGridWindowFrame = 0;
  }
  for (const grid of photoLayoutGrids()) {
    const layout = virtualPhotoGridLayouts.get(grid);
    if (layout) syncVirtualPhotoGrid(grid, layout);
  }
}

function scheduleVirtualPhotoGridWindow() {
  if (photoGridLayoutSuspended) return;
  if (virtualPhotoGridWindowFrame) return;
  virtualPhotoGridWindowFrame = requestAnimationFrame(() => {
    virtualPhotoGridWindowFrame = 0;
    syncVirtualPhotoGridWindowNow();
  });
}

function virtualPhotoLayoutForIndex(index) {
  for (const grid of photoLayoutGrids()) {
    const layout = virtualPhotoGridLayouts.get(grid);
    const box = layout?.boxByIndex.get(Number(index));
    if (!box) continue;
    const content = $("#content");
    const contentRect = content.getBoundingClientRect();
    const gridTop =
      content.scrollTop + grid.getBoundingClientRect().top - contentRect.top;
    return { grid, layout, box, gridTop };
  }
  return null;
}

function ensureVirtualPhotoTile(index) {
  const existing = document.querySelector(
    `.photo-grid .tile[data-index="${Number(index)}"]`,
  );
  if (existing) return existing;
  const found = virtualPhotoLayoutForIndex(index);
  if (!found) return null;
  const template = document.createElement("template");
  template.innerHTML = itemTile(state.items[Number(index)], Number(index));
  const tile = template.content.firstElementChild;
  if (!tile) return null;
  const { box } = found;
  tile.style.left = `${box.x.toFixed(3)}px`;
  tile.style.top = `${box.y.toFixed(3)}px`;
  tile.style.width = `${box.width.toFixed(3)}px`;
  tile.style.height = `${box.height.toFixed(3)}px`;
  found.grid.append(tile);
  observeGalleryImageTiles([found.grid]);
  return tile;
}

function capturePhotoViewportAnchor() {
  const content = $("#content");
  if (!content || content.scrollTop <= 1) return null;
  const contentRect = content.getBoundingClientRect();
  const centerY = contentRect.top + content.clientHeight / 2;
  let anchor = null;
  for (const tile of content.querySelectorAll(
    ".photo-grid .tile[data-index]",
  )) {
    const rect = tile.getBoundingClientRect();
    if (rect.bottom < contentRect.top || rect.top > contentRect.bottom)
      continue;
    const distance = Math.abs(rect.top + rect.height / 2 - centerY);
    if (anchor && distance >= anchor.distance) continue;
    anchor = {
      index: Number(tile.dataset.index),
      offset: rect.top - contentRect.top,
      distance,
    };
  }
  return anchor;
}

function restorePhotoViewportAnchor(anchor) {
  if (!anchor) return;
  const content = $("#content");
  const grid = photoLayoutGrids().find((target) =>
    virtualPhotoGridLayouts.get(target)?.boxByIndex.has(anchor.index),
  );
  const layout = grid && virtualPhotoGridLayouts.get(grid);
  const box = layout?.boxByIndex.get(anchor.index);
  if (!content || !grid || !box) return;
  const contentRect = content.getBoundingClientRect();
  const gridTop =
    content.scrollTop + grid.getBoundingClientRect().top - contentRect.top;
  content.scrollTop = Math.max(0, gridTop + box.y - anchor.offset);
}

function capturePhotoGridPositions() {
  const snapshots = new Map();
  for (const grid of photoLayoutGrids()) {
    const gridRect = grid.getBoundingClientRect();
    const tiles = new Map();
    for (const tile of grid.querySelectorAll(":scope > .tile[data-index]")) {
      const rect = tile.getBoundingClientRect();
      tiles.set(tile, {
        left: rect.left - gridRect.left,
        top: rect.top - gridRect.top,
        width: rect.width,
        height: rect.height,
      });
    }
    snapshots.set(grid, tiles);
  }
  return snapshots;
}

function animatePhotoGridLayout(grid, before) {
  if (
    !before?.size ||
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  )
    return;
  for (const tile of grid.querySelectorAll(":scope > .tile[data-index]")) {
    const old = before.get(tile);
    if (!old) continue;
    const left = Number.parseFloat(tile.style.left);
    const top = Number.parseFloat(tile.style.top);
    const width = Number.parseFloat(tile.style.width);
    const height = Number.parseFloat(tile.style.height);
    if (![left, top, width, height].every(Number.isFinite)) continue;
    if (
      Math.abs(old.left - left) < 0.5 &&
      Math.abs(old.top - top) < 0.5 &&
      Math.abs(old.width - width) < 0.5 &&
      Math.abs(old.height - height) < 0.5
    )
      continue;
    tile.animate(
      [
        {
          left: `${old.left}px`,
          top: `${old.top}px`,
          width: `${old.width}px`,
          height: `${old.height}px`,
        },
        {
          left: `${left}px`,
          top: `${top}px`,
          width: `${width}px`,
          height: `${height}px`,
        },
      ],
      {
        duration: 320,
        easing: "cubic-bezier(0.22, 0.72, 0.24, 1)",
      },
    );
  }
}

function applyPhotoGridLayouts({
  animate = false,
  before = null,
  preserveViewport = true,
} = {}) {
  if (photoGridLayoutSuspended) return;
  const content = $("#content");
  const initialScrollTop = content?.scrollTop ?? 0;
  const snapshots = animate ? before || capturePhotoGridPositions() : null;
  const viewportAnchor = preserveViewport ? capturePhotoViewportAnchor() : null;
  const virtualGrids = [];
  const effectiveMode = effectivePhotoLayoutMode();
  syncPhotoGridLayoutClasses();

  for (const grid of photoLayoutGrids()) {
    const windowed = grid.classList.contains("photo-grid-windowed");
    const tiles = [...grid.querySelectorAll(":scope > .tile[data-index]")];
    grid.classList.remove("photo-layout-measured");
    grid.style.removeProperty("height");
    for (const tile of tiles) {
      tile.style.removeProperty("left");
      tile.style.removeProperty("top");
      tile.style.removeProperty("width");
      tile.style.removeProperty("height");
    }

    const width = grid.clientWidth;
    if (width <= 0) continue;
    const entries = windowed
      ? virtualPhotoGridEntries(grid)
      : tiles.map((tile) => {
          const index = Number(tile.dataset.index);
          return {
            tile,
            index,
            aspect: photoAspect(state.items[index], tile),
          };
        });
    if (!entries.length) continue;
    const entriesByIndex = new Map(
      entries.map((entry) => [entry.index, entry]),
    );
    const targetSize = photoLayoutTargetSize(grid);
    const layoutGap = photoLayoutGap(grid);
    const result =
      effectiveMode === "tile"
        ? tilePhotoBoxes(entries, width, targetSize, layoutGap)
        : effectiveMode === "justified"
          ? justifiedPhotoBoxes(entries, width, targetSize, layoutGap)
          : masonryPhotoBoxes(entries, width, targetSize, layoutGap);
    if (windowed) {
      const layout = {
        boxes: result.boxes,
        boxByIndex: new Map(result.boxes.map((box) => [box.index, box])),
      };
      virtualPhotoGridLayouts.set(grid, layout);
      grid.style.height = `${Math.ceil(result.height)}px`;
      grid.classList.add("photo-layout-measured");
      virtualGrids.push(grid);
      continue;
    }
    if (effectiveMode === "tile") continue;
    for (const box of result.boxes) {
      const tile = entriesByIndex.get(box.index)?.tile;
      if (!tile) continue;
      tile.style.left = `${box.x.toFixed(3)}px`;
      tile.style.top = `${box.y.toFixed(3)}px`;
      tile.style.width = `${box.width.toFixed(3)}px`;
      tile.style.height = `${box.height.toFixed(3)}px`;
    }
    grid.style.height = `${Math.ceil(result.height)}px`;
    grid.classList.add("photo-layout-measured");
    if (snapshots) animatePhotoGridLayout(grid, snapshots.get(grid));
  }
  if (content && Math.abs(content.scrollTop - initialScrollTop) > 0.5) {
    content.scrollTop = initialScrollTop;
  }
  restorePhotoViewportAnchor(viewportAnchor);
  for (const grid of virtualGrids) {
    const layout = virtualPhotoGridLayouts.get(grid);
    if (layout) syncVirtualPhotoGrid(grid, layout);
  }
  if (libraryTimelineIsVisible()) scheduleLibraryTimelineScrubberSync();
}

function schedulePhotoGridLayout() {
  if (photoGridLayoutSuspended) return;
  if (photoGridLayoutFrame) return;
  photoGridLayoutFrame = requestAnimationFrame(() => {
    photoGridLayoutFrame = 0;
    if (photoGridLayoutSuspended) return;
    const grid = photoLayoutGrids()[0];
    if (!grid) return;
    if (grid.clientWidth === photoGridLastWidth) return;
    photoGridLastWidth = grid.clientWidth;
    applyPhotoGridLayouts();
  });
}

function setDefaultPhotoStyle(style, { persist = true } = {}) {
  const nextStyle = PHOTO_STYLE_CYCLE.includes(style) ? style : "square";
  const changed = nextStyle !== defaultPhotoStyle();
  const hasViewOverrides = state.photoStyleOverrides.size > 0;
  if (!changed && !hasViewOverrides) return false;
  const before = capturePhotoGridPositions();
  const contentCrossfade = document.querySelector("#content .photo-grid")
    ? beginContentCrossfade()
    : null;
  defaultOriginalRatio = nextStyle === "original";
  photoLayoutMode =
    nextStyle === "original" || nextStyle === "square" ? "tile" : nextStyle;
  state.photoStyleOverrides.clear();
  photoGridLastWidth = -1;
  try {
    localStorage.setItem(PHOTO_LAYOUT_KEY, photoLayoutMode);
    localStorage.setItem(
      DEFAULT_ORIGINAL_RATIO_KEY,
      String(defaultOriginalRatio),
    );
  } catch {}
  applyPhotoGridLayouts({ animate: !contentCrossfade, before });
  syncToolbarForState();
  if (persist) void persistPersistentSettings();
  if (contentCrossfade) {
    playContentCrossfade(contentCrossfade);
    startContentCrossfadeFade(contentCrossfade, ".photo-grid .tile");
  }
  return true;
}

function setColorMode(mode, { persist = true } = {}) {
  const next = normalizeColorMode(mode);
  colorMode = next;
  document.documentElement.dataset.colorMode = next;
  document.documentElement.style.colorScheme =
    next === "auto" ? "light dark" : next;
  try {
    localStorage.setItem(COLOR_MODE_KEY, next);
  } catch {}
  for (const frame of document.querySelectorAll("iframe")) {
    try {
      frame.contentWindow?.postMessage(
        { type: "photo:color-mode", mode: next },
        window.location.origin,
      );
    } catch {}
  }
  if (persist) void persistPersistentSettings();
  return next;
}

