function formatGlyphHTML(letter) {
  const letterPaths = {
    A: "M6 11.7 8.9 6.3 11.8 11.7M7.2 9.4h3.4",
    F: "M6.5 11.8V6.2h5M6.5 8.9h4.1",
    H: "M6.3 6.2v5.6M11.5 6.2v5.6M6.3 9h5.2",
    J: "M11.3 6.2v4.1c0 1.1-.9 2-2 2s-2-.9-2-2",
    P: "M6.5 11.8V6.2h2.1a2.1 2.1 0 1 1 0 4.2H6.5",
    R: "M6.3 11.8V6.2h2.3a2 2 0 0 1 0 4H6.3M9.2 10.2l2.5 1.6",
  };
  const safeLetter = Object.hasOwn(letterPaths, letter) ? letter : "A";
  return `<svg class="menu-icon-format" data-format-letter="${safeLetter}"
    viewBox="0 0 22 22" fill="none"
    stroke="currentColor" stroke-width="1.55" stroke-linejoin="round"
    aria-hidden="true" focusable="false">
    <rect x="8.1" y="7.2" width="10.7" height="11.6" rx="2.7"/>
    <rect x="3.2" y="3.2" width="11.4" height="11.5" rx="2.7"
      fill="var(--sheet-bg)"/>
    <path d="${letterPaths[safeLetter]}" stroke-width="1.3"
      stroke-linecap="round"/>
  </svg>`;
}
