const ALBUM_MENU_HIDDEN_ITEMS_KEY = "album-menu-hidden-items";
const ALBUM_MENU_ITEM_IDS = new Set(
  ALBUM_MENU_GROUPS.flatMap((group) => group.items.map((item) => item.id)),
);

function readAlbumMenuHiddenItems() {
  try {
    const value = JSON.parse(
      localStorage.getItem(ALBUM_MENU_HIDDEN_ITEMS_KEY) || "[]",
    );
    return new Set(
      Array.isArray(value)
        ? value.filter(
            (id) => typeof id === "string" && ALBUM_MENU_ITEM_IDS.has(id),
          )
        : [],
    );
  } catch {
    return new Set();
  }
}

