function togglePhotoWallAlbumSelected(albumId) {
  if (!photoWallAlbumSelectionActive()) return;
  const id = Number(albumId);
  if (!state.photoWallAlbums.some((album) => album.id === id)) return;
  if (state.photoWallSelectedAlbums.has(id)) {
    state.photoWallSelectedAlbums.delete(id);
  } else {
    state.photoWallSelectedAlbums.add(id);
  }
  syncPhotoWallAlbumSelectionUi();
}

