let photoWallPlaybackOpenSeq = 0;

async function startPhotoWallPlayback(mode, albumIds = null) {
  photoWallPlaybackOpenSeq += 1;
  const albums = albumIds
    ? state.photoWallAlbums.filter((album) => albumIds.includes(album.id))
    : state.photoWallAlbums.slice();
  if (!albums.length) {
    toast("照片墙里还没有可播放的相簿");
    return false;
  }
  const photoMode = mode === "photos-all" || mode === "photos-some";
  let photos = [];
  if (photoMode) {
    const query =
      mode === "photos-some"
        ? `?albums=${albums.map((album) => album.id).join(",")}`
        : "";
    try {
      const result = await api(`/api/photo-wall/photos${query}`);
      photos = Array.isArray(result.items) ? result.items : [];
    } catch (err) {
      alert(err.message);
      return false;
    }
  }
  if (state.photoWallSelectMode) {
    state.photoWallSelectMode = null;
    state.photoWallSelectedAlbums.clear();
    photoWallAlbumConfirmBusy = false;
    syncPhotoWallAlbumSelectionUi();
  }
  state.photoWallPlayback = {
    wallKind: "tile",
    mode: photoMode ? "photos" : "albums",
    albums,
    photos,
    basePhotos: photoMode ? photos : [],
    seed: randomPhotoWallSeed(),
    currentAlbumId: null,
  };
  state.photoWallAlbumId = null;
  state.masonryWallAlbumId = null;
  state.filmrollWallAlbumId = null;
  state.mosaicWallAlbumId = null;
  state.masonryWallSelectMode = null;
  state.filmrollWallSelectMode = null;
  state.mosaicWallSelectMode = null;
  state.masonryWallSelectedAlbums.clear();
  state.filmrollWallSelectedAlbums.clear();
  state.mosaicWallSelectedAlbums.clear();
  setPhotoWall(true);
  return true;
}

