function interfaceNameOptionsHTML(fields = INTERFACE_NAME_FIELDS) {
  return fields
    .map(({ id, defaultName }) => {
      const displayName = interfaceFieldDisplayName(id);
      return `<button class="menu-row menu-submenu-option menu-interface-name-option"
      data-interface-name="${id}"
      aria-label="编辑${esc(defaultName)}的显示名称">
      <span class="menu-leading menu-submenu-chevron" aria-hidden="true">${ICON_CHEVRON}</span>
      <span class="menu-label">${esc(displayName)}</span>
    </button>`;
    })
    .join("");
}

function interfaceNameEditorHTML(key) {
  const field = INTERFACE_NAME_FIELDS.find((entry) => entry.id === key);
  if (!field) return "";
  return `<div class="menu-inline-edit menu-interface-name-edit">
    <input class="menu-inline-input" type="text"
      maxlength="${INTERFACE_NAME_MAX_LENGTH}"
      autocomplete="off" spellcheck="false"
      aria-label="${esc(field.defaultName)}的显示名称"
      value="${esc(interfaceFieldDisplayName(key))}" />
    <button class="menu-inline-confirm" type="button"
      aria-label="应用${esc(field.defaultName)}的显示名称">${ICON_CHECK}</button>
  </div>`;
}

function previewInterfaceName(key, value) {
  if (key === "libraryTitle") {
    syncSidebarTitle(value);
    return;
  }
  if (key === "unfiled") {
    syncUnfiledInterfaceLabels(value);
    return;
  }
  const fallback = DEFAULT_INTERFACE_NAMES[key];
  if (!fallback) return;
  const displayName = normalizeInterfaceName(value, fallback);
  const label = document.querySelector(
    `#sidebarList [data-id="${key}"] .nav-label`,
  );
  if (label) label.textContent = displayName;
  if (state.activeId === key) setViewTitle(displayName);
}

function resizeInterfaceNameSubmenu(layer, mutate) {
  const inner = layer?.querySelector(".menu-submenu-inner");
  if (!inner) return;
  const from = layer.getBoundingClientRect().height;
  mutate(inner);
  const to = inner.offsetHeight;
  layer.style.height = `${from}px`;
  const anim = layer.animate([{ height: `${from}px` }, { height: `${to}px` }], {
    duration: 160,
    easing: MENU_MOTION_EASING,
    fill: "forwards",
  });
  anim.onfinish = () => {
    layer.style.height = `${to}px`;
    anim.cancel();
  };
}

function showInterfaceNameOptions(layer) {
  delete layer?.dataset.interfaceNameEditing;
  resizeInterfaceNameSubmenu(layer, (inner) => {
    inner.classList.remove("menu-interface-name-editor-inner");
    inner.innerHTML = interfaceNameOptionsHTML(
      albumSubmenu === "albumRename"
        ? ALBUM_RENAME_FIELDS
        : INTERFACE_NAME_FIELDS,
    );
  });
}

function replaceInterfaceNameEditorRow(editor, key) {
  const field = INTERFACE_NAME_FIELDS.find((entry) => entry.id === key);
  if (!field || !editor?.parentElement) return null;
  const template = document.createElement("template");
  template.innerHTML = interfaceNameOptionsHTML([field]);
  const row = template.content.firstElementChild;
  if (!row) return null;
  editor.replaceWith(row);
  return row;
}

function restoreSettingsInterfaceNameEditor(editor) {
  const key = editor?.dataset.interfaceNameEditor;
  if (!settingsDraft || !key) return null;
  const original = editor.dataset.interfaceNameOriginal || "";
  if (key === "libraryTitle") settingsDraft.libraryTitle = original;
  else settingsDraft.interfaceNames[key] = original;
  syncInterfaceNavigationLabels();
  return replaceInterfaceNameEditorRow(editor, key);
}

function syncInlineSettingsNameEditorHeight(anchor) {
  const content = anchor?.closest(".settings-region-content");
  const panel = content?.closest(".settings-region-secondary");
  const stage = panel?.closest(".settings-region-secondary-stage");
  if (!content || !panel || !stage) return;
  const top = Number.parseFloat(panel.style.top) || 0;
  panel.style.height = `${settingsRegionPanelHeight(content, top, stage)}px`;
}

function closeInlineSettingsInterfaceNameEditor({ restore = true } = {}) {
  const editor = $("#popMenu .settings-inline-name-editor");
  if (!editor || !settingsDraft) return;
  const group = editor.closest(".settings-inline-setting");
  const key = editor.dataset.interfaceNameEditor;
  if (restore && key) {
    const original = editor.dataset.interfaceNameOriginal || "";
    if (key === "libraryTitle") settingsDraft.libraryTitle = original;
    else settingsDraft.interfaceNames[key] = original;
    previewInterfaceName(key, original);
    const button = editor
      .closest(".settings-inline-setting")
      ?.querySelector(`[data-interface-name="${key}"]`);
    const label = button?.querySelector(".menu-label");
    if (label) label.textContent = interfaceFieldDisplayName(key);
    button?.classList.remove("is-editing");
  }
  editor.remove();
  requestAnimationFrame(() => syncInlineSettingsNameEditorHeight(group));
}

function openInlineSettingsInterfaceNameEditor(row) {
  if (
    !settingsDraft ||
    !row.matches(".settings-inline-options [data-interface-name]")
  ) {
    return false;
  }
  const field = INTERFACE_NAME_FIELDS.find(
    (entry) => entry.id === row.dataset.interfaceName,
  );
  const group = row.closest(".settings-inline-setting");
  if (!field || !group) return false;

  closeInlineSettingsInterfaceNameEditor();
  const key = field.id;
  const original =
    key === "libraryTitle"
      ? settingsDraft.libraryTitle
      : settingsDraft.interfaceNames[key];
  const template = document.createElement("template");
  template.innerHTML = interfaceNameEditorHTML(key);
  const editorContent = template.content.firstElementChild;
  if (!editorContent) return false;

  const editor = document.createElement("div");
  editor.className = "settings-inline-name-editor";
  editor.dataset.interfaceNameEditor = key;
  editor.dataset.interfaceNameOriginal = original || "";
  editor.append(editorContent);
  group.append(editor);
  row.classList.add("is-editing");

  const input = editor.querySelector(".menu-inline-input");
  const confirm = editor.querySelector(".menu-inline-confirm");
  const updateLabel = () => {
    const label = row.querySelector(".menu-label");
    if (label) label.textContent = interfaceFieldDisplayName(key);
  };
  const submit = () => {
    if (!input) return;
    if (key === "libraryTitle") {
      applyLibraryTitle(input.value);
      settingsDraft.libraryTitle = libraryTitle;
    } else {
      const fallback = DEFAULT_INTERFACE_NAMES[key];
      const displayName = normalizeInterfaceName(input.value, fallback);
      applyInterfaceName(key, input.value);
      settingsDraft.interfaceNames[key] =
        displayName === fallback ? "" : displayName;
    }
    updateLabel();
    editor.remove();
    row.classList.remove("is-editing");
    row.focus({ preventScroll: true });
    requestAnimationFrame(() => syncInlineSettingsNameEditorHeight(group));
    void persistPersistentSettings();
  };

  input?.addEventListener("input", () => {
    if (key === "libraryTitle") settingsDraft.libraryTitle = input.value;
    else settingsDraft.interfaceNames[key] = input.value;
    previewInterfaceName(key, input.value);
    updateLabel();
  });
  input?.addEventListener("click", (event) => event.stopPropagation());
  input?.addEventListener("keydown", (event) => {
    event.stopPropagation();
    if (event.key === "Enter") {
      event.preventDefault();
      submit();
    } else if (event.key === "Escape") {
      event.preventDefault();
      closeInlineSettingsInterfaceNameEditor();
      row.focus({ preventScroll: true });
    }
  });
  confirm?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    submit();
  });
  requestAnimationFrame(() => {
    syncInlineSettingsNameEditorHeight(group);
    if (!input?.isConnected) return;
    editor.scrollIntoView({ block: "nearest" });
    input.focus({ preventScroll: true });
    input.select();
  });
  return true;
}

function openSettingsInterfaceNameEditor(row) {
  if (openInlineSettingsInterfaceNameEditor(row)) return true;
  if (
    !settingsDraft ||
    !row.matches(".settings-region-tertiary [data-interface-name]")
  ) {
    return false;
  }
  const field = INTERFACE_NAME_FIELDS.find(
    (entry) => entry.id === row.dataset.interfaceName,
  );
  if (!field) return false;

  const panel = row.closest(".settings-region-tertiary");
  const activeEditor = panel?.querySelector(
    ".settings-interface-name-editor-row",
  );
  if (activeEditor) restoreSettingsInterfaceNameEditor(activeEditor);

  const key = field.id;
  const original =
    key === "libraryTitle"
      ? settingsDraft.libraryTitle
      : settingsDraft.interfaceNames[key];
  const editorTemplate = document.createElement("template");
  editorTemplate.innerHTML = interfaceNameEditorHTML(key);
  const editorContent = editorTemplate.content.firstElementChild;
  if (!editorContent) return false;

  const editor = document.createElement("div");
  editor.className =
    "menu-row menu-submenu-option settings-interface-name-editor-row";
  editor.dataset.interfaceNameEditor = key;
  editor.dataset.interfaceNameOriginal = original || "";
  editor.setAttribute("role", "group");
  editor.setAttribute("aria-label", `Edit ${field.defaultName}`);
  const leading = document.createElement("span");
  leading.className = "menu-leading settings-region-leading";
  leading.setAttribute("aria-hidden", "true");
  editor.append(leading, ...editorContent.children);
  row.replaceWith(editor);

  const input = editor.querySelector(".menu-inline-input");
  const confirm = editor.querySelector(".menu-inline-confirm");
  const submit = () => {
    if (!input) return;
    if (key === "libraryTitle") {
      applyLibraryTitle(input.value);
      settingsDraft.libraryTitle = libraryTitle;
    } else {
      const fallback = DEFAULT_INTERFACE_NAMES[key];
      const displayName = normalizeInterfaceName(input.value, fallback);
      applyInterfaceName(key, input.value);
      settingsDraft.interfaceNames[key] =
        displayName === fallback ? "" : displayName;
    }
    void persistPersistentSettings();
    replaceInterfaceNameEditorRow(editor, key)?.focus({ preventScroll: true });
  };

  input?.addEventListener("input", () => {
    if (key === "libraryTitle") settingsDraft.libraryTitle = input.value;
    else settingsDraft.interfaceNames[key] = input.value;
    previewInterfaceName(key, input.value);
  });
  input?.addEventListener("click", (event) => event.stopPropagation());
  input?.addEventListener("keydown", (event) => {
    event.stopPropagation();
    if (event.key === "Enter") {
      event.preventDefault();
      submit();
    } else if (event.key === "Escape") {
      event.preventDefault();
      restoreSettingsInterfaceNameEditor(editor)?.focus({
        preventScroll: true,
      });
    }
  });
  confirm?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    submit();
  });
  requestAnimationFrame(() => {
    if (!input?.isConnected) return;
    input.focus({ preventScroll: true });
    input.select();
  });
  return true;
}

function openInterfaceNameEditor(row) {
  if (!settingsDraft) return;
  if (openSettingsInterfaceNameEditor(row)) return;
  const layer = row.closest(".menu-submenu, .settings-region-tertiary");
  const inner = layer?.querySelector(".menu-submenu-inner");
  const key = row.dataset.interfaceName;
  if (!inner || !INTERFACE_NAME_FIELDS.some((field) => field.id === key)) {
    return;
  }
  const original =
    key === "libraryTitle"
      ? settingsDraft.libraryTitle
      : settingsDraft.interfaceNames[key];
  layer.dataset.interfaceNameEditing = key;
  resizeInterfaceNameSubmenu(layer, (target) => {
    target.classList.add("menu-interface-name-editor-inner");
    target.innerHTML = interfaceNameEditorHTML(key);
  });

  const input = layer.querySelector(
    ".menu-interface-name-edit .menu-inline-input",
  );
  const confirm = layer.querySelector(
    ".menu-interface-name-edit .menu-inline-confirm",
  );
  const restore = () => {
    if (key === "libraryTitle") settingsDraft.libraryTitle = original;
    else settingsDraft.interfaceNames[key] = original;
    syncInterfaceNavigationLabels();
    showInterfaceNameOptions(layer);
  };
  const submit = () => {
    if (key === "libraryTitle") {
      applyLibraryTitle(input?.value);
      settingsDraft.libraryTitle = libraryTitle;
    } else {
      const fallback = DEFAULT_INTERFACE_NAMES[key];
      const displayName = normalizeInterfaceName(input?.value, fallback);
      applyInterfaceName(key, input?.value);
      settingsDraft.interfaceNames[key] =
        displayName === fallback ? "" : displayName;
    }
    void persistPersistentSettings();
    showInterfaceNameOptions(layer);
  };

  input?.addEventListener("input", () => {
    if (key === "libraryTitle") settingsDraft.libraryTitle = input.value;
    else settingsDraft.interfaceNames[key] = input.value;
    previewInterfaceName(key, input.value);
  });
  input?.addEventListener("click", (event) => event.stopPropagation());
  input?.addEventListener("keydown", (event) => {
    event.stopPropagation();
    if (event.key === "Enter") {
      event.preventDefault();
      submit();
    } else if (event.key === "Escape") {
      event.preventDefault();
      restore();
    }
  });
  confirm?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    submit();
  });
  requestAnimationFrame(() => {
    if (!input?.isConnected) return;
    input.focus({ preventScroll: true });
    input.select();
  });
}

function colorModeOptionsHTML() {
  const current = normalizeColorMode(settingsDraft?.colorMode ?? colorMode);
  return COLOR_MODES.map(({ id, label }) => {
    const selected = id === current;
    return `<button class="menu-row menu-submenu-option menu-color-mode-option${selected ? " is-current" : ""}"
      data-color-mode="${id}"
      role="menuitemradio" aria-checked="${selected}">
      <span class="menu-leading">${selected ? ICON_CHECK : ""}</span>
      <span class="menu-label">${label}</span>
    </button>`;
  }).join("");
}

