function cameraDeviceOptionsHTML() {
  const items = selectedItems();
  const cameras = new Set(
    items
      .map((item) => String(item.originalCamera || "").trim())
      .filter(Boolean),
  );
  const lenses = new Set(
    items.map((item) => String(item.originalLens || "").trim()).filter(Boolean),
  );
  const hasOriginalDetails =
    items.length > 0 &&
    items.every(
      (item) =>
        String(item.originalCamera || "").trim() &&
        String(item.originalLens || "").trim(),
    ) &&
    cameras.size === 1 &&
    lenses.size === 1;
  const originalRow = hasOriginalDetails
    ? `<div class="menu-camera-original" role="note"
        aria-label="项目原始设备和镜头">
        <span class="menu-camera-original-device">${esc(cameraDisplayName([...cameras][0]))}</span>
        <span class="menu-camera-original-lens">${esc([...lenses][0])}</span>
      </div><div class="menu-group-gap" aria-hidden="true"></div>`
    : "";
  const rows = CAMERA_DEVICE_OPTIONS.map((device) => {
    const selected = cameraDeviceDraftId === device.id;
    return `<button class="menu-row menu-submenu-option menu-camera-device-option${
      selected ? " is-current" : ""
    }" data-camera-device="${device.id}"
      role="menuitemradio" aria-checked="${selected}">
      <span class="menu-label">${esc(device.label)}</span>
      <span class="menu-camera-device-lens">${esc(device.lens)}</span>
    </button>`;
  });
  const hasOverride = items.some((item) => item.cameraOverride);
  if (hasOverride) {
    const restoreSelected =
      cameraDeviceDraftActive && cameraDeviceDraftId == null;
    rows.push(`<button class="menu-row menu-submenu-option menu-camera-device-option menu-camera-device-restore${
      restoreSelected ? " is-current" : ""
    }"
      data-camera-device="" role="menuitemradio" aria-checked="${restoreSelected}">
      <span class="menu-label">还原设备</span>
      <span class="menu-camera-device-lens"></span>
    </button>`);
  }
  return originalRow + rows.join("");
}

function currentSharedCameraOverrideId() {
  const items = selectedItems();
  const first = items[0]?.cameraOverride || null;
  return first && items.every((item) => item.cameraOverride === first)
    ? first
    : null;
}

function syncCameraDeviceDraftUI() {
  const inner = $("#popMenu .menu-cameraDevice-submenu .menu-submenu-inner");
  for (const row of inner?.querySelectorAll("[data-camera-device]") || []) {
    const restore =
      row.hasAttribute("data-camera-device") && row.dataset.cameraDevice === "";
    const selected = restore
      ? cameraDeviceDraftActive && cameraDeviceDraftId == null
      : cameraDeviceDraftId === row.dataset.cameraDevice;
    row.classList.toggle("is-current", selected);
    row.setAttribute("aria-checked", String(selected));
  }

  const group = $(
    '#popMenu .menu-submenu-group[data-submenu-group="cameraDevice"]',
  );
  const anchor = group?.querySelector(":scope > .menu-row");
  if (!group || !anchor) return;
  let controls = group.querySelector(".menu-camera-anchor-actions");
  if (!controls) {
    anchor.querySelectorAll(":scope > svg").forEach((icon) => icon.remove());
    controls = document.createElement("span");
    controls.className = "menu-camera-anchor-actions";
    controls.innerHTML = `
      <span class="menu-camera-anchor-action" role="button" tabindex="0"
        data-camera-cancel aria-label="取消设备修改" title="取消">${ICON_X}</span>
      <span class="menu-camera-anchor-action" role="button" tabindex="-1"
        data-camera-commit aria-label="应用设备修改" title="应用" hidden>${ICON_CHECK}</span>`;
    group.append(controls);
    controls.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      const action = event.target.closest(".menu-camera-anchor-action");
      if (!action || action.getAttribute("aria-disabled") === "true") return;
      event.preventDefault();
      event.stopPropagation();
      action.click();
    });
  }
  const cancel = controls.querySelector("[data-camera-cancel]");
  const commit = controls.querySelector("[data-camera-commit]");
  if (commit) commit.hidden = !cameraDeviceDraftActive;
  for (const action of [cancel, commit]) {
    if (!action) continue;
    action.setAttribute("aria-disabled", String(cameraDeviceDraftSaving));
    action.tabIndex = action.hidden || cameraDeviceDraftSaving ? -1 : 0;
  }
}

