function prepareExtensionFilterDraft() {
  const choices = availableFileExtensions();
  extensionFilterDraft =
    state.extensionFilter == null
      ? new Set(choices)
      : new Set(choices.filter((key) => state.extensionFilter.has(key)));
}

function extensionFilterDraftMatchesApplied() {
  const choices = availableFileExtensions();
  const applied =
    state.extensionFilter == null
      ? new Set(choices)
      : new Set(choices.filter((key) => state.extensionFilter.has(key)));
  return choices.every(
    (key) => extensionFilterDraft.has(key) === applied.has(key),
  );
}

function extensionFilterOptionsHTML() {
  const choices = availableFileExtensions();
  const allSelected =
    choices.length > 0 && choices.every((key) => extensionFilterDraft.has(key));
  const allRow = `<button class="menu-row menu-submenu-option menu-extension-option${allSelected ? " is-current" : ""}"
    data-extension-filter-all>
    <span class="menu-leading">${allSelected ? ICON_CHECK : ""}</span>
    <span class="menu-label">全部</span>
  </button>`;
  const typeRows = choices
    .map((key) => {
      const current = extensionFilterDraft.has(key);
      return `<button class="menu-row menu-submenu-option menu-extension-option${current ? " is-current" : ""}"
      data-file-extension-filter="${key}">
      <span class="menu-leading">${current ? ICON_CHECK : ""}</span>
      <span class="menu-label">${extensionFilterLabel(key)}</span>
    </button>`;
    })
    .join("");
  return `${allRow}${choices.length ? '<div class="menu-group-gap" aria-hidden="true"></div>' : ""}${typeRows}`;
}

function syncExtensionFilterDraftUI(menu = $("#popMenu")) {
  const group = menu.querySelector(
    '.menu-submenu-group[data-submenu-group="extension"]',
  );
  if (!group) return;
  const choices = availableFileExtensions();
  const allSelected =
    choices.length > 0 && choices.every((key) => extensionFilterDraft.has(key));
  const allRow = group.querySelector("[data-extension-filter-all]");
  allRow?.classList.toggle("is-current", allSelected);
  if (allRow)
    allRow.querySelector(".menu-leading").innerHTML = allSelected
      ? ICON_CHECK
      : "";
  for (const row of group.querySelectorAll("[data-file-extension-filter]")) {
    const current = extensionFilterDraft.has(row.dataset.fileExtensionFilter);
    row.classList.toggle("is-current", current);
    row.querySelector(".menu-leading").innerHTML = current ? ICON_CHECK : "";
  }
  const dirty = !extensionFilterDraftMatchesApplied();
  const confirm = group.querySelector("[data-extension-confirm]");
  group.classList.toggle("has-extension-confirm", dirty);
  if (confirm) {
    confirm.setAttribute("aria-hidden", String(!dirty));
    if (dirty) confirm.removeAttribute("tabindex");
    else confirm.setAttribute("tabindex", "-1");
    confirm.disabled = extensionFilterDraft.size === 0;
  }
}

/* 菜单里真正占一行高度的项目；二级菜单里的选项不算。 */
function mainMenuRows(menu) {
  return [
    ...menu.querySelectorAll(":scope > .menu-submenu-group > .menu-row"),
    ...menu.querySelectorAll(":scope > .menu-row"),
  ];
}

/* 二级菜单收回时，外壳要回到所有一级行和功能分隔带的实际总高度。
   只累加 menu-row 会漏掉分组带，导致底边先缩短再突然弹回。 */
function collapsedMainMenuHeight(menu) {
  const rowHeight = mainMenuRows(menu).reduce(
    (sum, row) => sum + row.offsetHeight,
    0,
  );
  const separatorHeight = [
    ...menu.querySelectorAll(
      ":scope > .album-menu-separator, :scope > .settings-group-divider",
    ),
  ].reduce((sum, separator) => sum + separator.offsetHeight, 0);
  return rowHeight + separatorHeight;
}

const MENU_WEEKDAYS = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];

function menuDateInputValue(ms) {
  const d = new Date(Number(ms) || Date.now());
  const pad = (n) => String(n).padStart(2, "0");
  return (
    `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}` +
    `T${pad(d.getHours())}:${pad(d.getMinutes())}`
  );
}

const MENU_DATE_WHEEL_VISIBLE_RADIUS = 2;
const MENU_DATE_WHEEL_PEEK_RADIUS = 2;
const MENU_DATE_WHEEL_BUFFER_RADIUS = 4;
const MENU_DATE_WHEEL_RADIUS_PX = 112;
const MENU_DATE_WHEEL_PERSPECTIVE_PX = 720;
const MENU_DATE_WHEEL_STEP_ANGLE = 22.5;
const MENU_DATE_WHEEL_LENS_SCALE = 1.16;
const MENU_DATE_WHEEL_TRAPEZOID_SKEW = 0.027;
const MENU_DATE_WHEEL_COLUMNS = ["month", "day", "hour", "minute"];
const MENU_DATE_ROLL_MS = 225;
const MENU_DATE_ROLL_EASING = "cubic-bezier(0.18, 0.74, 0.2, 1)";
const menuDateRollStates = new WeakMap();

/* 每列是一段横放圆柱的正面。±2 档正好跨越 90°，也就是屏幕上能看到的
   四分之一圆周；再各多缓存两档，供滚动时从视窗上下边缘接替。 */
function menuDateWheelSteps(radius = MENU_DATE_WHEEL_BUFFER_RADIUS) {
  const visible = Array.from(
    { length: MENU_DATE_WHEEL_VISIBLE_RADIUS * 2 + 1 },
    (_, index) => index - MENU_DATE_WHEEL_VISIBLE_RADIUS,
  );
  const buffer = [];
  for (
    let step = MENU_DATE_WHEEL_VISIBLE_RADIUS + 1;
    step <= radius;
    step += 1
  ) {
    buffer.push(step);
  }
  for (let step = -radius; step < -MENU_DATE_WHEEL_VISIBLE_RADIUS; step += 1) {
    buffer.push(step);
  }
  return [...visible, ...buffer];
}

function menuDateWheelGeometry(position) {
  const radians = (position * MENU_DATE_WHEEL_STEP_ANGLE * Math.PI) / 180;
  const distance = Math.abs(position);
  const z = MENU_DATE_WHEEL_RADIUS_PX * Math.cos(radians);
  const perspectiveScale =
    MENU_DATE_WHEEL_PERSPECTIVE_PX / (MENU_DATE_WHEEL_PERSPECTIVE_PX - z);
  const interpolateStops = (stops) => {
    const clamped = Math.min(stops.length - 1, distance);
    const from = Math.floor(clamped);
    const to = Math.min(stops.length - 1, from + 1);
    const progress = clamped - from;
    return stops[from] + (stops[to] - stops[from]) * progress;
  };
  return {
    angle: -position * MENU_DATE_WHEEL_STEP_ANGLE,
    z,
    /* 给点击命中与旧样式读取的近似投影纵向位置。真正的位置、转向和
       近大远小由下面的 CSS 3D 变换一次计算，不再逐行伪造。 */
    y: MENU_DATE_WHEEL_RADIUS_PX * Math.sin(radians) * perspectiveScale,
    trapezoid: Math.sin(radians) * MENU_DATE_WHEEL_TRAPEZOID_SKEW,
    scale: Math.min(
      1,
      (MENU_DATE_WHEEL_PERSPECTIVE_PX - MENU_DATE_WHEEL_RADIUS_PX) /
        (MENU_DATE_WHEEL_PERSPECTIVE_PX - z),
    ),
    opacity: interpolateStops([1, 0.73, 0.34, 0.1, 0]),
    blur: interpolateStops([0, 0, 0.14, 1.2, 2.8]),
  };
}

function menuDateWheelTransform(position) {
  const depth = menuDateWheelGeometry(position);
  return (
    "translate3d(0, -50%, 0) " +
    `perspective(${MENU_DATE_WHEEL_PERSPECTIVE_PX}px) ` +
    `rotateX(${depth.angle}deg) ` +
    `translateZ(${MENU_DATE_WHEEL_RADIUS_PX}px)`
  );
}

function menuDateWheelLensTransform(position) {
  const depth = menuDateWheelGeometry(position);
  return (
    "translate3d(0, -50%, 0) " +
    `perspective(${MENU_DATE_WHEEL_PERSPECTIVE_PX}px) ` +
    `rotateX(${depth.angle}deg) ` +
    `translateZ(${MENU_DATE_WHEEL_RADIUS_PX}px)`
  );
}

/* 两点之间直接插值会让数字沿直线跳格。沿圆周多采几帧后，
   上下位移按正弦轨迹经过，梯形角度和明暗也随圆柱转角连续变化。 */
function menuDateWheelMotionFrames(
  from,
  to,
  inLens,
  { fromColor, toColor, fromWeight, toWeight },
) {
  const distance = Math.abs(to - from);
  const frameCount = Math.min(25, Math.max(5, Math.ceil(distance * 4) + 1));
  return Array.from({ length: frameCount }, (_, index) => {
    const offset = index / (frameCount - 1);
    const position = from + (to - from) * offset;
    const depth = menuDateWheelGeometry(position);
    const frame = {
      offset,
      transform: inLens
        ? menuDateWheelLensTransform(position)
        : menuDateWheelTransform(position),
      opacity: depth.opacity,
      filter: `blur(${depth.blur}px)`,
    };
    if (index === 0) {
      frame.color = fromColor;
      frame.fontWeight = fromWeight;
    } else if (index === frameCount - 1) {
      frame.color = toColor;
      frame.fontWeight = toWeight;
    }
    return frame;
  });
}

function menuDateWheelDepthStyle(step) {
  const depth = menuDateWheelGeometry(step);
  return (
    `--wheel-angle:${depth.angle}deg;--wheel-radius:${MENU_DATE_WHEEL_RADIUS_PX}px;` +
    `--wheel-perspective:${MENU_DATE_WHEEL_PERSPECTIVE_PX}px;` +
    `--wheel-y:${depth.y}px;--wheel-trapezoid:${depth.trapezoid};` +
    `--wheel-scale:${depth.scale};` +
    `--wheel-opacity:${depth.opacity};--wheel-blur:${depth.blur}px;` +
    `pointer-events:${depth.opacity > 0.01 ? "auto" : "none"}`
  );
}

/* 拖动时同一个数字会经过 0.5 档的中间位置。直接在节点上重算整套圆柱
   参数，让位置、大小、明暗和选中颜色都按连续角度变化，而不是等越过
   半格后换一次 class 才整体跳到新状态。 */
function applyMenuDateWheelDepth(node, position) {
  if (!node) return;
  const depth = menuDateWheelGeometry(position);
  node.style.setProperty("--wheel-angle", `${depth.angle}deg`);
  node.style.setProperty("--wheel-radius", `${MENU_DATE_WHEEL_RADIUS_PX}px`);
  node.style.setProperty(
    "--wheel-perspective",
    `${MENU_DATE_WHEEL_PERSPECTIVE_PX}px`,
  );
  node.style.setProperty("--wheel-y", `${depth.y}px`);
  node.style.setProperty("--wheel-trapezoid", String(depth.trapezoid));
  node.style.setProperty("--wheel-scale", String(depth.scale));
  node.style.setProperty("--wheel-opacity", String(depth.opacity));
  node.style.setProperty("--wheel-blur", `${depth.blur}px`);
  node.style.setProperty(
    "--wheel-focus",
    String(Math.max(0, 1 - Math.min(1, Math.abs(position) / 0.5))),
  );
  node.style.pointerEvents =
    depth.opacity > 0.01 && Math.abs(position) <= MENU_DATE_WHEEL_VISIBLE_RADIUS
      ? "auto"
      : "none";
}

/* 滚轮用多个层叠的 3D 数字做出椭圆弧面，缓存数字的命中框会与可见数字
   重叠。点击不能依赖最上层 DOM 节点，而要按指针所在的列和弧形中的一行
   来判定；这样连续点击时，即使数字正在滚动或刚被重建也不会丢点击。 */
function menuDateWheelPointerHit(face, clientX, clientY) {
  const wheel = face?.querySelector(".menu-date-wheel");
  if (!wheel) return null;
  const wheelRect = wheel.getBoundingClientRect();
  if (
    clientX < wheelRect.left ||
    clientX > wheelRect.right ||
    clientY < wheelRect.top ||
    clientY > wheelRect.bottom
  ) {
    return null;
  }
  const column = [...wheel.querySelectorAll(".menu-date-wheel-col")].find(
    (node) => {
      const rect = node.getBoundingClientRect();
      return clientX >= rect.left && clientX <= rect.right;
    },
  );
  if (!column) return null;

  const centerY = wheelRect.top + wheelRect.height / 2;
  let step = 0;
  let nearest = Infinity;
  for (
    let candidate = -MENU_DATE_WHEEL_VISIBLE_RADIUS;
    candidate <= MENU_DATE_WHEEL_VISIBLE_RADIUS;
    candidate += 1
  ) {
    const distance = Math.abs(
      clientY - centerY - menuDateWheelGeometry(candidate).y,
    );
    if (distance < nearest) {
      nearest = distance;
      step = candidate;
    }
  }
  return { part: column.dataset.wheel, step };
}

function menuDateWheelTargetHit(event) {
  const value = event.target.closest?.("[data-date-ms]");
  if (!value) return null;
  const part = value.dataset.wheel;
  const step = Number(value.dataset.step) || 0;
  if (
    !MENU_DATE_WHEEL_COLUMNS.includes(part) ||
    Math.abs(step) > MENU_DATE_WHEEL_VISIBLE_RADIUS
  ) {
    return null;
  }
  return { part, step };
}

function finishMenuDateRoll(face) {
  const state = face && menuDateRollStates.get(face);
  if (!state) return;
  menuDateRollStates.delete(face);
  state.animations.forEach((animation) => {
    try {
      animation.cancel();
    } catch {}
  });
  state.finalize();
}

const wrapMenuDateValue = (value, size) => ((value % size) + size) % size;

function menuDatePartStep(ms, part, step) {
  const d = new Date(Number(ms));
  const delta = Number(step) || 0;
  if (part === "month") {
    const year = d.getFullYear();
    const month = wrapMenuDateValue(d.getMonth() + delta, 12);
    const lastDay = new Date(year, month + 1, 0).getDate();
    d.setFullYear(year, month, Math.min(d.getDate(), lastDay));
  } else if (part === "day") {
    const lastDay = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
    d.setDate(wrapMenuDateValue(d.getDate() - 1 + delta, lastDay) + 1);
  } else if (part === "hour") {
    d.setHours(wrapMenuDateValue(d.getHours() + delta, 24));
  } else {
    d.setMinutes(wrapMenuDateValue(d.getMinutes() + delta, 60));
  }
  return d.getTime();
}

function menuDateWheelColumn(part, ms, radius = MENU_DATE_WHEEL_BUFFER_RADIUS) {
  const base = new Date(Number(ms) || Date.now());
  const steps = menuDateWheelSteps(radius);
  const values = steps.map((step) => {
    const d = new Date(menuDatePartStep(base.getTime(), part, step));
    const pad = (n) => String(n).padStart(2, "0");
    const text =
      part === "month"
        ? pad(d.getMonth() + 1)
        : part === "day"
          ? pad(d.getDate())
          : part === "hour"
            ? pad(d.getHours())
            : pad(d.getMinutes());
    const spoken =
      part === "month"
        ? `${d.getFullYear()}年${d.getMonth() + 1}月`
        : part === "day"
          ? `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`
          : `${pad(d.getHours())}时${pad(d.getMinutes())}分`;
    return {
      ms: d.getTime(),
      text,
      spoken,
      step,
      current: step === 0,
      peeked: Math.abs(step) === MENU_DATE_WHEEL_PEEK_RADIUS,
      buffered: Math.abs(step) > MENU_DATE_WHEEL_PEEK_RADIUS,
    };
  });
  return `<div class="menu-date-wheel-col" data-wheel="${part}">
    <div class="menu-date-wheel-base">
      ${values
        .map(
          (
            entry,
          ) => `<button class="menu-date-wheel-value${entry.current ? " is-current" : ""}${entry.peeked ? " is-peek" : ""}"
      type="button" data-wheel="${part}" data-date-ms="${entry.ms}" data-step="${entry.step}"
      style="${menuDateWheelDepthStyle(entry.step, part)}"
      aria-label="${entry.spoken}"${entry.current ? ' aria-current="true"' : ""}
      ${entry.buffered ? 'aria-hidden="true" tabindex="-1"' : ""}>
        <span class="menu-date-wheel-glyph">${entry.text}</span>
      </button>`,
        )
        .join("")}
    </div>
    <div class="menu-date-wheel-lens" data-wheel="${part}" aria-hidden="true">
      <div class="menu-date-wheel-lens-content"
        style="--wheel-lens-magnify:${MENU_DATE_WHEEL_LENS_SCALE}">
        ${values
          .map(
            (
              entry,
            ) => `<span class="menu-date-wheel-lens-value${entry.current ? " is-current" : ""}"
          data-wheel="${part}" data-date-ms="${entry.ms}" data-step="${entry.step}"
          style="${menuDateWheelDepthStyle(entry.step, part)}">
            <span class="menu-date-wheel-glyph">${entry.text}</span>
          </span>`,
          )
          .join("")}
      </div>
    </div>
  </div>`;
}

function menuDateWheelHTML(ms, radius = MENU_DATE_WHEEL_BUFFER_RADIUS) {
  return `<div class="menu-date-wheel-labels" aria-hidden="true">
      <span>月</span><span>日</span><span>时</span><span>分</span>
    </div>
    <div class="menu-date-wheel">
      <span class="menu-date-selection" aria-hidden="true"></span>
      ${menuDateWheelColumn("month", ms, radius)}
      ${menuDateWheelColumn("day", ms, radius)}
      ${menuDateWheelColumn("hour", ms, radius)}
      ${menuDateWheelColumn("minute", ms, radius)}
    </div>`;
}

function menuDateEditorHTML(ms, { showHint = false } = {}) {
  const base = new Date(Number(ms) || Date.now());
  return `<div class="menu-submenu-inner menu-date-inner">
    <div class="menu-date-head" data-date-reveal>
      <span class="menu-date-weekday">${MENU_WEEKDAYS[base.getDay()]}</span>
      <span class="menu-date-year-field">
        <span class="menu-date-year" role="button" tabindex="0">${base.getFullYear()}年</span>
        <input class="menu-date-year-input" type="text" inputmode="numeric"
          maxlength="4" autocomplete="off" spellcheck="false"
          aria-label="输入年份" hidden />
      </span>
      <button class="menu-inline-confirm menu-date-confirm" type="button"
        aria-label="关闭时间调整">${ICON_X}</button>
    </div>
    <div class="menu-date-face" tabindex="0" role="group" data-part="day"
      aria-label="上下键调整当前一列，左右键切换年、月、日、时、分">
      ${menuDateWheelHTML(ms)}
    </div>
    <div class="menu-date-foot${showHint ? "" : " is-status-only"}" data-date-reveal>
      ${showHint ? "<span>滚轮或按住上下拖动调整 · 回车存储</span>" : ""}
      <span class="menu-date-status" aria-live="polite"></span>
    </div>
    <input class="menu-date-input" type="datetime-local" step="60" tabindex="-1"
      value="${menuDateInputValue(ms)}" aria-hidden="true" />
  </div>`;
}

function syncMenuDateEditor(
  layer,
  ms,
  { animate = true, rollPart = null, rollSteps = 0, radius = null } = {},
) {
  finishMenuDateReveal();
  if (!layer || !Number.isFinite(Number(ms))) return;
  const face = layer.querySelector(".menu-date-face");
  finishMenuDateRoll(face);
  const input = layer.querySelector(".menu-date-input");
  if (input) input.value = menuDateInputValue(ms);
  const weekday = layer.querySelector(".menu-date-weekday");
  const year = layer.querySelector(".menu-date-year");
  const base = new Date(Number(ms));
  if (weekday) weekday.textContent = MENU_WEEKDAYS[base.getDay()];
  if (year) year.textContent = `${base.getFullYear()}年`;
  if (!face) return;
  const part = face.dataset.part || "day";
  const wheelRadius = radius ?? MENU_DATE_WHEEL_BUFFER_RADIUS;
  const replacementParts = rollPart
    ? rollPart === "month"
      ? ["day"]
      : [rollPart]
    : [];
  const replaceWheelColumns = (parts, value) => {
    for (const partName of parts) {
      const current = face.querySelector(
        `.menu-date-wheel-col[data-wheel="${partName}"]`,
      );
      if (!current) continue;
      const template = document.createElement("template");
      template.innerHTML = menuDateWheelColumn(
        partName,
        value,
        wheelRadius,
      ).trim();
      current.replaceWith(template.content.firstElementChild);
    }
  };
  const applyActiveColumn = () => {
    face.dataset.part = part;
    face.querySelectorAll(".menu-date-wheel-col").forEach((node) => {
      node.classList.toggle("is-active", node.dataset.wheel === part);
    });
  };
  const motionAllowed =
    animate && !window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const animatedColumn = rollPart
    ? face.querySelector(`.menu-date-wheel-col[data-wheel="${rollPart}"]`)
    : null;
  let rolling = false;

  if (motionAllowed && animatedColumn && rollSteps) {
    rolling = true;
    /* 月份变化可能同时收窄日期范围；日期列直接更新，月份列连续滚动。 */
    if (rollPart === "month") replaceWheelColumns(["day"], ms);
    applyActiveColumn();

    const currentSample = animatedColumn.querySelector(
      ".menu-date-wheel-value.is-current",
    );
    const restSample = animatedColumn.querySelector(
      ".menu-date-wheel-value:not(.is-current)",
    );
    const currentColor = currentSample
      ? getComputedStyle(currentSample).color
      : "";
    const restColor = restSample ? getComputedStyle(restSample).color : "";
    const currentWeight = currentSample
      ? getComputedStyle(currentSample).fontWeight
      : "500";
    const restWeight = restSample
      ? getComputedStyle(restSample).fontWeight
      : "400";
    const duration =
      MENU_DATE_ROLL_MS + Math.min(170, (Math.abs(rollSteps) - 1) * 70);
    const buttons = [
      ...animatedColumn.querySelectorAll(".menu-date-wheel-value"),
    ];
    const lensValues = [
      ...animatedColumn.querySelectorAll(".menu-date-wheel-lens-value"),
    ];
    const animateValue = (node, inLens) => {
      const from = Number(node.dataset.step) || 0;
      const to = from - rollSteps;
      return node.animate(
        menuDateWheelMotionFrames(from, to, inLens, {
          fromColor: getComputedStyle(node).color,
          toColor: to === 0 ? currentColor : restColor,
          fromWeight: getComputedStyle(node).fontWeight,
          toWeight: to === 0 ? currentWeight : restWeight,
        }),
        {
          duration,
          easing: MENU_DATE_ROLL_EASING,
          fill: "both",
        },
      );
    };
    const animations = [
      ...buttons.map((button) => animateValue(button, false)),
      ...lensValues.map((value) => animateValue(value, true)),
    ];
    let finalized = false;
    const finalize = () => {
      if (finalized) return;
      finalized = true;
      if (menuDateRollStates.get(face)?.animations === animations) {
        menuDateRollStates.delete(face);
      }
      if (!face.isConnected) return;
      const finalMs = new Date(input?.value || "").getTime();
      if (!Number.isFinite(finalMs)) return;
      const rebuiltParts = [
        ...new Set([rollPart, ...replacementParts].filter(Boolean)),
      ];
      replaceWheelColumns(rebuiltParts, finalMs);
      applyActiveColumn();
    };
    menuDateRollStates.set(face, { animations, finalize });
    Promise.all(animations.map((animation) => animation.finished))
      .then(finalize)
      .catch(() => {});
  } else {
    /* 拖动时不做滚动动画，但当前拖动列也必须立即重建；
       月份变化还要同步重建“日”列，避免月底日期范围过期。 */
    const directParts = rollPart
      ? [...new Set([rollPart, ...replacementParts])]
      : replacementParts;
    replaceWheelColumns(directParts, ms);
    if (!directParts.length)
      face.innerHTML = menuDateWheelHTML(ms, wheelRadius);
    applyActiveColumn();
  }

  if (motionAllowed && !rolling) {
    const wheel = face.querySelector(".menu-date-wheel");
    wheel?.animate(
      [
        { opacity: 0.45, transform: "translateY(2px)" },
        { opacity: 1, transform: "translateY(0)" },
      ],
      { duration: 150, easing: "cubic-bezier(0.22, 0.72, 0.3, 1)" },
    );
    const activeColumn = face.querySelector(
      `.menu-date-wheel-col[data-wheel="${part}"]`,
    );
    activeColumn
      ?.querySelectorAll(".is-current .menu-date-wheel-glyph")
      .forEach((glyph) => {
        glyph.animate(
          [
            { transform: "scale(0.92)" },
            { transform: "scale(1.02)", offset: 0.7 },
            { transform: "scale(1)" },
          ],
          { duration: 170, easing: "cubic-bezier(0.22, 0.72, 0.3, 1)" },
        );
      });
  }
}

function shiftMenuDate(ms, part, delta) {
  return menuDatePartStep(ms, part, delta);
}

function shiftMenuDateMonth(ms, delta) {
  return menuDatePartStep(ms, "month", delta);
}

function setMenuDateYear(ms, year) {
  const d = new Date(Number(ms));
  const month = d.getMonth();
  const day = d.getDate();
  /* 先把日期落在目标月份，再夹到该月最后一天，闰日跨年不会滚到下个月。 */
  d.setDate(1);
  d.setFullYear(year, month + 1, 0);
  const lastDay = d.getDate();
  d.setFullYear(year, month, Math.min(day, lastDay));
  return d.getTime();
}

const MENU_DATE_OPEN_MS = 280;
const MENU_DATE_OPEN_EASING = "cubic-bezier(0.32, 0.72, 0.42, 1)";
const MENU_DATE_CLOSE_MS = 240;
const MENU_DATE_CLOSE_EASING = "cubic-bezier(0.16, 1, 0.3, 1)";
const VIEWER_DATE_CLOSE_MS = 190;

/* 日期卡片放大时，标题、日期、滚轮一档一档浮出来；所有阶段的终点
   都对齐到外框展开完成的那一刻，不再出现框已经停稳、内容还在浮现。 */
function revealMenuDate(inner, { duration = MENU_DATE_OPEN_MS } = {}) {
  menuDateRevealAnims.forEach((anim) => anim.cancel());
  menuDateRevealAnims = [];
  if (!inner || window.matchMedia("(prefers-reduced-motion: reduce)").matches)
    return;
  const groups = inner.querySelectorAll("[data-date-reveal]");
  groups.forEach((node, index) => {
    const delay = Math.round(duration * (0.12 + index * 0.055));
    menuDateRevealAnims.push(
      node.animate(
        [
          { opacity: 0, transform: "translateY(9px)", filter: "blur(2px)" },
          { opacity: 1, transform: "translateY(0)", filter: "blur(0)" },
        ],
        {
          duration: duration - delay,
          delay,
          easing: "cubic-bezier(0.2, 0.72, 0.26, 1)",
          fill: "both",
        },
      ),
    );
  });
  const values = inner.querySelectorAll(".menu-date-wheel-glyph");
  values.forEach((node, index) => {
    const delay = Math.round(duration * (0.3 + Math.min(index, 8) * 0.025));
    menuDateRevealAnims.push(
      node.animate(
        [
          { opacity: 0, transform: "translateY(5px) scale(0.97)" },
          { opacity: 1, transform: "translateY(0) scale(1)" },
        ],
        {
          duration: duration - delay,
          delay,
          easing: "cubic-bezier(0.2, 0.72, 0.26, 1)",
          fill: "both",
        },
      ),
    );
  });
}

/* 用户很快开始滚动或点击时，不要让其后的列还停在展开动画的中间透明态。 */
function finishMenuDateReveal() {
  menuDateRevealAnims.forEach((animation) => {
    try {
      animation.finish();
    } catch {}
  });
  menuDateRevealAnims = [];
}

/* 照片菜单和查看器共用同一套时间滚轮交互。保存与关闭由调用方决定：
   菜单里写选中的项目并收回菜单，查看器里只写当前这一项并收起右上角卡片。 */
function bindDateEditorControls(
  layer,
  {
    items = [],
    save,
    onClose,
    onDismiss,
    focusOnOpen = true,
    showSavingStatus = true,
  } = {},
) {
  const input = layer.querySelector(".menu-date-input");
  const confirm = layer.querySelector(".menu-date-confirm");
  const face = layer.querySelector(".menu-date-face");
  const status = layer.querySelector(".menu-date-status");
  const yearLabel = layer.querySelector(".menu-date-year");
  const yearInput = layer.querySelector(".menu-date-year-input");
  const columns = MENU_DATE_WHEEL_COLUMNS;
  const editorItems = [...items];
  let saving = false;
  let editingYear = false;

  const closeEditor = () => {
    stopAllDateFlings(true);
    if (typeof onClose === "function") onClose();
  };
  const dismissEditor = () => {
    if (typeof onDismiss === "function") onDismiss();
    else closeEditor();
  };
  const currentMs = () => {
    const value = new Date(input?.value || "").getTime();
    return Number.isFinite(value) ? value : null;
  };
  const isUnchanged = (ms = currentMs()) =>
    editorItems.length > 0 &&
    editorItems.every(
      (item) => Math.floor(itemTime(item) / 60000) === Math.floor(ms / 60000),
    );
  const syncConfirm = () => {
    if (!confirm) return;
    const ms = currentMs();
    const unchanged = isUnchanged(ms);
    const mode = unchanged ? "unchanged" : "changed";
    confirm.disabled = saving || !ms;
    confirm.dataset.mode = mode;
    confirm.innerHTML = unchanged ? ICON_X : ICON_CHECK;
    confirm.setAttribute(
      "aria-label",
      unchanged ? "关闭时间调整" : "保存并关闭时间调整",
    );
  };
  const setDate = (ms, animate = true, rollPart = null, rollSteps = 0) => {
    if (!Number.isFinite(Number(ms)) || !input) return;
    syncMenuDateEditor(layer, Number(ms), { animate, rollPart, rollSteps });
    syncConfirm();
  };
  const setPart = (part) => {
    if (!face || !columns.includes(part)) return;
    face.dataset.part = part;
    face.querySelectorAll(".menu-date-wheel-col").forEach((node) => {
      node.classList.toggle("is-active", node.dataset.wheel === part);
    });
  };
  const finishYearEdit = (commit) => {
    if (!editingYear || !yearInput || !yearLabel) return;
    editingYear = false;
    const yearText = yearInput.value.trim();
    const ms = currentMs();
    if (commit && ms && /^\d{4}$/.test(yearText) && Number(yearText) >= 1000) {
      setDate(setMenuDateYear(ms, Number(yearText)), false);
    }
    yearInput.hidden = true;
    yearLabel.hidden = false;
    yearInput.value = "";
  };
  const beginYearEdit = (event) => {
    const ms = currentMs();
    if (!ms || !yearInput || !yearLabel || saving) return;
    event?.preventDefault();
    event?.stopPropagation();
    stopAllDateFlings(true);
    editingYear = true;
    yearInput.value = String(new Date(ms).getFullYear());
    yearLabel.hidden = true;
    yearInput.hidden = false;
    yearInput.focus({ preventScroll: true });
    yearInput.select();
  };
  const submit = async () => {
    stopAllDateFlings(true);
    const ms = currentMs();
    if (!input || !ms) {
      input?.focus({ preventScroll: true });
      return;
    }
    if (isUnchanged(ms)) {
      dismissEditor();
      return;
    }
    if (saving || typeof save !== "function") return;
    saving = true;
    input.disabled = true;
    if (confirm) confirm.disabled = true;
    if (status && showSavingStatus) status.textContent = "正在保存到“照片”…";
    const ok = await save(ms, editorItems);
    if (!ok && input.isConnected) {
      saving = false;
      input.disabled = false;
      face?.focus({ preventScroll: true });
      if (status) status.textContent = "写入失败，请重试";
      syncConfirm();
    }
  };

  input?.addEventListener("input", () => {
    setDate(currentMs());
  });
  input?.addEventListener("change", () => {
    setDate(currentMs());
  });
  input?.addEventListener("keydown", (event) => {
    event.stopPropagation();
    if (event.key === "Enter") {
      event.preventDefault();
      submit();
    } else if (event.key === "Escape") {
      event.preventDefault();
      if (!saving) closeEditor();
    }
  });
  yearLabel?.addEventListener("dblclick", beginYearEdit);
  yearLabel?.addEventListener("keydown", (event) => {
    event.stopPropagation();
    if (event.key !== "Enter" && event.key !== " ") return;
    beginYearEdit(event);
  });
  yearInput?.addEventListener("input", () => {
    yearInput.value = yearInput.value.replace(/\D/g, "").slice(0, 4);
  });
  yearInput?.addEventListener("keydown", (event) => {
    event.stopPropagation();
    if (event.key === "Enter") {
      event.preventDefault();
      finishYearEdit(true);
      face?.focus({ preventScroll: true });
    } else if (event.key === "Escape") {
      event.preventDefault();
      finishYearEdit(false);
      face?.focus({ preventScroll: true });
    }
  });
  yearInput?.addEventListener("blur", () => finishYearEdit(true));
  const activateWheelValue = (part, step, event) => {
    event.preventDefault();
    event.stopPropagation();
    stopDateFling(part, true);
    setPart(part);
    if (step) setDate(shiftMenuDate(currentMs(), part, step), true, part, step);
    face.focus({ preventScroll: true });
  };
  /* 相邻刻度中心距离的一半，就是“下一格已经进入阴影区域一半”的位置。
     从那里开始磁吸，因此不用继续拖满一整格，也不必等松手。 */
  const DATE_DRAG_ROW_GAP_PX = Math.max(
    1,
    menuDateWheelGeometry(1).y - menuDateWheelGeometry(0).y,
  );
  const DATE_DRAG_MAGNET_TRIGGER_PX = DATE_DRAG_ROW_GAP_PX / 2;
  /* 与前版 160ms 相比速度降低 30%：160 / 0.7 ≈ 229ms。 */
  const DATE_DRAG_MAGNET_MS = 229;
  const DATE_DRAG_MAGNET_STRENGTH = 0.7;
  const menuDateMagnetEase = (progress) => {
    const magneticEase = 1 - Math.pow(1 - progress, 3);
    return progress + (magneticEase - progress) * DATE_DRAG_MAGNET_STRENGTH;
  };
  let dateDrag = null;
  let dateDragPointerResidual = 0;
  let dateDragVisualResidual = 0;
  let dateDragMagnetFrame = 0;
  let dateDragMagnetColumn = null;
  const dateFlings = new Map();
  const applyDateDragOffset = (column, residual) => {
    if (!column) return;
    dateDragVisualResidual = residual;
    const residualSteps = residual / DATE_DRAG_ROW_GAP_PX;
    column.querySelectorAll("[data-date-ms]").forEach((node) => {
      applyMenuDateWheelDepth(node, Number(node.dataset.step) + residualSteps);
    });
  };
  const stopDateDragMagnet = (removeOffset = false) => {
    if (dateDragMagnetFrame) cancelAnimationFrame(dateDragMagnetFrame);
    dateDragMagnetFrame = 0;
    if (removeOffset) {
      applyDateDragOffset(dateDragMagnetColumn, 0);
    }
    dateDragMagnetColumn = null;
  };
  const startDateDragMagnet = (column, offset) => {
    stopDateDragMagnet();
    if (!column) return;
    dateDragMagnetColumn = column;
    column.classList.add("is-wheel-moving");
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      applyDateDragOffset(column, dateDragPointerResidual);
      dateDragMagnetColumn = null;
      column.classList.remove("is-wheel-moving");
      return;
    }
    const startedAt = performance.now();
    applyDateDragOffset(column, dateDragPointerResidual + offset);
    const tick = (now) => {
      if (!column.isConnected) {
        dateDragMagnetFrame = 0;
        return;
      }
      const progress = Math.min(1, (now - startedAt) / DATE_DRAG_MAGNET_MS);
      /* 保留一部分线性跟随，只叠加 70% 的磁吸加速度：
         总时长不变，但刚越过半格时的吸力比原来弱约 30%。 */
      const eased = menuDateMagnetEase(progress);
      const target = dateDrag ? dateDragPointerResidual : 0;
      applyDateDragOffset(column, target + offset * (1 - eased));
      if (progress < 1) {
        dateDragMagnetFrame = requestAnimationFrame(tick);
      } else {
        dateDragMagnetFrame = 0;
        if (!dateDrag) {
          applyDateDragOffset(column, 0);
          dateDragMagnetColumn = null;
          column.classList.remove("is-wheel-moving");
        }
      }
    };
    dateDragMagnetFrame = requestAnimationFrame(tick);
  };
  const roundedWheelPosition = (position) =>
    position < 0 ? -Math.floor(-position + 0.5) : Math.floor(position + 0.5);
  const commitDateFlingStep = (fling, position) => {
    const nextStep = roundedWheelPosition(position);
    if (nextStep === fling.committed) return;
    const ms = currentMs();
    if (!ms) return;
    const stepDelta = nextStep - fling.committed;
    setDate(
      shiftMenuDate(ms, fling.part, stepDelta),
      false,
      fling.part,
      stepDelta,
    );
    fling.committed = nextStep;
    fling.column = face.querySelector(
      `.menu-date-wheel-col[data-wheel="${fling.part}"]`,
    );
  };
  const stopDateFling = (part, removeOffset = true) => {
    const fling = dateFlings.get(part);
    if (!fling) return;
    if (fling.frame) cancelAnimationFrame(fling.frame);
    if (removeOffset) applyDateDragOffset(fling.column, 0);
    fling.column?.classList.remove("is-wheel-moving");
    dateFlings.delete(part);
  };
  const stopAllDateFlings = (removeOffset = true) => {
    [...dateFlings.keys()].forEach((part) => {
      stopDateFling(part, removeOffset);
    });
  };
  const startDateFling = (fling) => {
    stopDateFling(fling.part, false);
    const state = {
      ...fling,
      frame: 0,
      lastTime: performance.now(),
    };
    dateFlings.set(state.part, state);
    state.column?.classList.add("is-wheel-moving");
    const tick = (now) => {
      const current = dateFlings.get(state.part);
      if (!current || current !== state || !current.column?.isConnected) {
        if (current === state) dateFlings.delete(state.part);
        return;
      }
      const elapsed = Math.min(42, Math.max(8, now - current.lastTime));
      current.lastTime = now;
      /* 约 310ms 的速度衰减时间常数，让快拖有连续余速，
         慢拖松手后则尽快停住；最低速度会把剩余距离柔和地收进整数刻度。 */
      current.velocity *= Math.exp(-0.0032 * elapsed);
      if (Math.abs(current.velocity) >= 0.0012) {
        current.position += current.velocity * elapsed;
        current.settle = null;
      } else {
        const target = roundedWheelPosition(current.position);
        if (!current.settle || current.settle.target !== target) {
          current.settle = {
            target,
            origin: current.position,
            startedAt: now,
          };
        }
        const settleProgress = Math.min(
          1,
          (now - current.settle.startedAt) / DATE_DRAG_MAGNET_MS,
        );
        current.position =
          current.settle.origin +
          (target - current.settle.origin) * menuDateMagnetEase(settleProgress);
        current.settle.progress = settleProgress;
      }
      commitDateFlingStep(current, current.position);
      const residual =
        (current.committed - current.position) * DATE_DRAG_ROW_GAP_PX;
      applyDateDragOffset(current.column, residual);
      const settled =
        Math.abs(current.velocity) < 0.0012 &&
        current.settle?.progress >= 1 &&
        Math.abs(current.committed - current.position) < 0.004;
      if (!settled) {
        current.frame = requestAnimationFrame(tick);
      } else {
        applyDateDragOffset(current.column, 0);
        current.column?.classList.remove("is-wheel-moving");
        dateFlings.delete(current.part);
      }
    };
    state.frame = requestAnimationFrame(tick);
  };
  const finishDateDrag = (event, cancelled = false) => {
    if (!dateDrag || event.pointerId !== dateDrag.pointerId) return;
    const drag = dateDrag;
    const releaseResidual = dateDragVisualResidual;
    const releaseTime = performance.now();
    dateDrag = null;
    face.classList.remove("is-dragging");
    try {
      face.releasePointerCapture(event.pointerId);
    } catch {}
    if (!cancelled && !drag.moved && drag.hit) {
      stopDateFling(drag.part, true);
      stopDateDragMagnet(true);
      activateWheelValue(drag.hit.part, drag.hit.step, event);
    } else if (!cancelled && drag.moved) {
      const recentSamples = [
        ...drag.samples.filter((sample) => releaseTime - sample.time <= 120),
        { time: releaseTime, y: drag.latestY },
      ];
      const firstSample = recentSamples[0];
      const lastSample = recentSamples[recentSamples.length - 1];
      const sampleDuration = lastSample.time - firstSample.time;
      const travelVelocity =
        sampleDuration >= 16
          ? -(lastSample.y - firstSample.y) / sampleDuration
          : 0;
      const flingVelocity = Math.max(
        -0.055,
        Math.min(0.055, travelVelocity / DATE_DRAG_ROW_GAP_PX),
      );
      const traveled = drag.startY - drag.latestY;
      /* 只越过半格才进入下一档；松手时不会额外补一次尚未达到门槛的滚动。 */
      const finalStep = Math.trunc(traveled / DATE_DRAG_MAGNET_TRIGGER_PX);
      const steps = finalStep - drag.committedSteps;
      const ms = currentMs();
      let committedSteps = drag.committedSteps;
      let residual = releaseResidual;
      let column = face.querySelector(
        `.menu-date-wheel-col[data-wheel="${drag.part}"]`,
      );
      if (steps && ms) {
        setDate(shiftMenuDate(ms, drag.part, steps), false, drag.part, steps);
        committedSteps = finalStep;
        residual = Math.sign(steps) * DATE_DRAG_MAGNET_TRIGGER_PX;
        column = face.querySelector(
          `.menu-date-wheel-col[data-wheel="${drag.part}"]`,
        );
      }
      stopDateDragMagnet();
      const position = committedSteps - residual / DATE_DRAG_ROW_GAP_PX;
      if (Math.abs(flingVelocity) >= 0.0014) {
        startDateFling({
          part: drag.part,
          column,
          committed: committedSteps,
          position,
          velocity: flingVelocity,
        });
      } else if (Math.abs(residual) > 0.05) {
        dateDragPointerResidual = 0;
        startDateDragMagnet(column, residual);
      } else {
        applyDateDragOffset(column, 0);
        column?.classList.remove("is-wheel-moving");
      }
    } else {
      stopDateFling(drag.part, true);
      stopDateDragMagnet(true);
    }
  };
  face?.addEventListener("pointerdown", (event) => {
    if (event.button !== 0 || event.isPrimary === false) return;
    /* 可见数字自身优先；缓存数字和层叠命中框则退回按坐标判定。 */
    const hit =
      menuDateWheelTargetHit(event) ||
      menuDateWheelPointerHit(face, event.clientX, event.clientY);
    if (!hit || !currentMs()) return;
    event.preventDefault();
    event.stopPropagation();
    stopDateFling(hit.part, true);
    stopDateDragMagnet(true);
    setPart(hit.part);
    dateDragPointerResidual = 0;
    dateDrag = {
      pointerId: event.pointerId,
      startY: event.clientY,
      latestY: event.clientY,
      committedSteps: 0,
      part: hit.part,
      column: face.querySelector(
        `.menu-date-wheel-col[data-wheel="${hit.part}"]`,
      ),
      hit,
      moved: false,
      samples: [{ time: performance.now(), y: event.clientY }],
    };
    dateDrag.column?.classList.add("is-wheel-moving");
    applyDateDragOffset(dateDrag.column, 0);
    face.classList.add("is-dragging");
    face.focus({ preventScroll: true });
    try {
      face.setPointerCapture(event.pointerId);
    } catch {}
  });
  face?.addEventListener("pointermove", (event) => {
    if (!dateDrag || event.pointerId !== dateDrag.pointerId) return;
    const deltaY = event.clientY - dateDrag.startY;
    if (Math.abs(deltaY) < 2) return;
    event.preventDefault();
    event.stopPropagation();
    dateDrag.latestY = event.clientY;
    dateDrag.moved = true;
    dateDrag.samples.push({ time: performance.now(), y: event.clientY });
    if (dateDrag.samples.length > 8) dateDrag.samples.shift();
    const traveled = dateDrag.startY - event.clientY;
    const rawSteps = Math.trunc(traveled / DATE_DRAG_MAGNET_TRIGGER_PX);
    const stepDelta = rawSteps - dateDrag.committedSteps;
    if (stepDelta) {
      const ms = currentMs();
      if (ms) {
        setDate(
          shiftMenuDate(ms, dateDrag.part, stepDelta),
          false,
          dateDrag.part,
          stepDelta,
        );
        dateDrag.committedSteps = rawSteps;
        dateDrag.column = face.querySelector(
          `.menu-date-wheel-col[data-wheel="${dateDrag.part}"]`,
        );
      }
    }
    dateDragPointerResidual = -(
      traveled -
      dateDrag.committedSteps * DATE_DRAG_MAGNET_TRIGGER_PX
    );
    if (stepDelta) {
      startDateDragMagnet(
        dateDrag.column,
        Math.sign(stepDelta) * DATE_DRAG_MAGNET_TRIGGER_PX,
      );
    } else if (!dateDragMagnetFrame) {
      applyDateDragOffset(dateDrag.column, dateDragPointerResidual);
    }
  });
  face?.addEventListener("pointerup", (event) => finishDateDrag(event));
  face?.addEventListener("pointercancel", (event) =>
    finishDateDrag(event, true),
  );
  /* 键盘 / 辅助技术产生的 click 没有鼠标指针坐标，继续按数字节点处理。 */
  face?.addEventListener("click", (event) => {
    if (event.detail !== 0) return;
    const value = event.target.closest("[data-date-ms]");
    if (!value) return;
    activateWheelValue(
      value.dataset.wheel,
      Number(value.dataset.step) || 0,
      event,
    );
  });
  let lastWheelAt = 0;
  face?.addEventListener(
    "wheel",
    (event) => {
      if (dateDrag) return;
      const hit = menuDateWheelPointerHit(face, event.clientX, event.clientY);
      const ms = currentMs();
      if (!hit || !ms) return;
      event.preventDefault();
      event.stopPropagation();
      stopDateFling(hit.part, true);
      const now = performance.now();
      if (now - lastWheelAt < 38) return;
      lastWheelAt = now;
      setPart(hit.part);
      const direction = event.deltaY > 0 ? 1 : -1;
      setDate(
        shiftMenuDate(ms, hit.part, direction),
        true,
        hit.part,
        direction,
      );
    },
    { passive: false },
  );
  layer.addEventListener("keydown", (event) => {
    if (event.target === input) return;
    const ms = currentMs();
    if (!ms) return;
    const part = face?.dataset.part || "day";
    stopDateFling(part, true);
    if (event.key === "ArrowUp" || event.key === "ArrowDown") {
      event.preventDefault();
      event.stopPropagation();
      const direction = event.key === "ArrowDown" ? 1 : -1;
      setDate(shiftMenuDate(ms, part, direction), true, part, direction);
    } else if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
      event.preventDefault();
      event.stopPropagation();
      const index = columns.indexOf(part);
      const next =
        (index + (event.key === "ArrowRight" ? 1 : -1) + columns.length) %
        columns.length;
      setPart(columns[next]);
    } else if (event.key === "PageUp" || event.key === "PageDown") {
      event.preventDefault();
      event.stopPropagation();
      const direction = event.key === "PageUp" ? -1 : 1;
      setDate(shiftMenuDateMonth(ms, direction), true, "month", direction);
    } else if (event.key === "Enter") {
      event.preventDefault();
      event.stopPropagation();
      submit();
    } else if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      if (!saving) closeEditor();
    }
  });
  confirm?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    submit();
  });
  setPart("day");
  syncConfirm();
  if (focusOnOpen) {
    requestAnimationFrame(() => {
      if (!face?.isConnected) return;
      face.focus({ preventScroll: true });
    });
  }
}

function animateMenuContent(kind = menuKind) {
  const menu = $("#popMenu");
  if (
    kind !== "album" &&
    kind !== "library" &&
    kind !== "settings" &&
    kind !== "photos"
  ) {
    renderMenu(kind);
    return;
  }
  finishNumberingBranchMotion();
  menuContentAnim?.cancel();
  menuSubmenuAnim?.cancel();
  menuSubmenuContentAnim?.cancel();
  cancelAnimationFrame(rootSwitchScrollFrame);
  rootSwitchScrollFrame = 0;
  menuContentAnim = null;
  menuSubmenuAnim = null;
  menuSubmenuContentAnim = null;
  menuHeadRadiusAnim?.cancel();
  menuHeadRadiusAnim = null;
  menuGroupPaddingAnim?.cancel();
  menuGroupPaddingAnim = null;
  menuAnchorBottomRadiusAnim?.cancel();
  menuAnchorBottomRadiusAnim = null;
  menuBorderRadiusAnim?.cancel();
  menuBorderRadiusAnim = null;
  detachedSubmenuCleanup?.();
  detachedSubmenuCleanup = null;
  menuDateRevealAnims.forEach((anim) => anim.cancel());
  menuDateRevealAnims = [];

  const timing = {
    duration: MENU_MOTION_DURATION_MS,
    easing: MENU_MOTION_EASING,
  };
  const submenuOpenTiming = {
    duration: MENU_SUBMENU_OPEN_MS,
    easing: MENU_MOTION_EASING,
  };
  const submenu = menu.querySelector(".menu-submenu");
  /* 菜单圆角由 CSS 统一控制；展开 / 收回时别把半径写死回旧值。 */
  const menuRadius = getComputedStyle(menu).borderTopLeftRadius;

  if (albumSubmenu && !submenu) {
    const group = menu.querySelector(
      `.menu-submenu-group[data-submenu-group="${albumSubmenu}"]`,
    );
    const anchorRow = group?.querySelector(":scope > .menu-row");
    if (!group || !anchorRow) return;
    const editingRename = albumSubmenu === "rename";
    const editingTitle =
      menuKind === "settings" && albumSubmenu === "libraryTitle";
    const editingInline = editingRename || editingTitle;
    const editingDate = albumSubmenu === "date";
    if (albumSubmenu === "cameraDevice") syncCameraDeviceDraftUI();
    const atMenuTop = group.offsetTop === 0;
    const beforeHeight = menu.offsetHeight;
    const anchorHeight = anchorRow.offsetHeight;
    anchorRow.classList.remove("is-closing");
    const fromRadius = getComputedStyle(anchorRow).borderTopLeftRadius;
    anchorRow.classList.add("menu-submenu-head");
    if (editingInline) {
      anchorRow.classList.add("menu-rename-anchor");
      group.classList.add("menu-rename-group");
    } else if (editingDate) {
      anchorRow.classList.add("menu-date-anchor");
      group.classList.add("menu-date-group-expanded");
    } else if (!atMenuTop) {
      menuHeadRadiusAnim = anchorRow.animate(
        [
          { borderTopLeftRadius: fromRadius, borderTopRightRadius: fromRadius },
          { borderTopLeftRadius: menuRadius, borderTopRightRadius: menuRadius },
        ],
        submenuOpenTiming,
      );
    }
    if (editingTitle) anchorRow.classList.add("menu-title-anchor");
    anchorRow.dataset.menuOriginal = anchorRow.dataset.menu;
    anchorRow.removeAttribute("data-menu");
    anchorRow.dataset.submenuBack = "";
    anchorRow.querySelector(".menu-submenu-chevron")?.classList.add("is-open");
    menu.classList.add("has-submenu-expanded");

    const layer = document.createElement("div");
    layer.className = editingInline
      ? `menu-submenu menu-rename-editor${editingTitle ? " menu-title-editor" : ""}`
      : editingDate
        ? "menu-submenu menu-date-editor"
        : `menu-submenu menu-${albumSubmenu}-submenu`;
    /* 日期这一行在菜单中间，展开层从这一行开始接管到菜单底部；
       和二级菜单不同，它覆盖原行，让拍摄时间替代菜单文案出现。 */
    layer.style.top =
      editingInline || editingDate
        ? `${anchorRow.offsetTop}px`
        : `${anchorRow.offsetTop + anchorHeight}px`;
    layer.style.height = "0px";
    if (editingRename) {
      const currentName = albumById(state.activeId)?.name || "";
      layer.innerHTML = `<div class="menu-submenu-inner menu-rename-inner">
        <div class="menu-inline-edit">
          <input class="menu-inline-input" type="text" maxlength="100"
            autocomplete="off" spellcheck="false" aria-label="相簿名称"
            value="${esc(currentName)}" />
          <button class="menu-inline-confirm" type="button" aria-label="确认重命名">${ICON_CHECK}</button>
        </div>
      </div>`;
    } else if (editingTitle) {
      const currentTitle = normalizeLibraryTitle(
        settingsDraft?.libraryTitle ?? libraryTitle,
      );
      layer.innerHTML = `<div class="menu-submenu-inner menu-rename-inner">
        <div class="menu-inline-edit">
          <input class="menu-inline-input" type="text"
            maxlength="${LIBRARY_TITLE_MAX_LENGTH}"
            autocomplete="off" spellcheck="false" aria-label="相簿栏标题"
            value="${esc(currentTitle)}" />
          <button class="menu-inline-confirm" type="button"
            aria-label="应用相簿栏标题">${ICON_CHECK}</button>
        </div>
      </div>`;
    } else if (editingDate) {
      const first = selectedItems()[0];
      const initialMs = first ? itemTime(first) : Date.now();
      layer.innerHTML = menuDateEditorHTML(initialMs);
    } else {
      if (albumSubmenu === "extension") prepareExtensionFilterDraft();
      let options;
      switch (albumSubmenu) {
        case "rootSwitch":
          options = rootSwitchOptionsHTML();
          break;
        case "sort":
          options = albumSortOptionsHTML();
          break;
        case "numbering":
          options = numberingMenuOptionsHTML();
          break;
        case "style":
          options = photoStyleOptionsHTML();
          break;
        case "locationFilter":
          options = locationFilterOptionsHTML();
          break;
        case "type":
          options = albumTypeOptionsHTML();
          break;
        case "device":
          options = albumDeviceOptionsHTML();
          break;
        case "extension":
          options = extensionFilterOptionsHTML();
          break;
        case "interfaceNames":
          options = interfaceNameOptionsHTML();
          break;
        case "colorMode":
          options = colorModeOptionsHTML();
          break;
        case "windowControls":
          options = windowControlsOptionsHTML();
          break;
        case "closeWindowBehavior":
          options = closeWindowBehaviorOptionsHTML();
          break;
        case "filmstripPosition":
          options = filmstripPositionOptionsHTML();
          break;
        case "viewerWheel":
          options = viewerWheelOptionsHTML();
          break;
        case "locationFlightSpeed":
          options = locationFlightSpeedOptionsHTML();
          break;
        case "thumbnailCorners":
          options = thumbnailCornerOptionsHTML();
          break;
        case "photoWallDefault":
          options = photoWallDefaultOptionsHTML();
          break;
        case "defaultOpen":
          options = defaultOpenOptionsHTML();
          break;
        case "wallpaperCruise":
          options = wallpaperCruiseOptionsHTML();
          break;
        case "wallpaperCruiseSpeed":
          options = wallpaperCruiseSpeedOptionsHTML();
          break;
        case "masonryWallDirection":
          options = masonryWallDirectionOptionsHTML();
          break;
        case "display":
          options = displayOptionsHTML();
          break;
        case "cameraDevice":
          options = cameraDeviceOptionsHTML();
          break;
        case "filter":
        default:
          options = albumFilterOptionsHTML();
          break;
      }
      layer.innerHTML = `<div class="menu-submenu-inner">${options}</div>`;
    }
    group.append(layer);
    for (const row of mainMenuRows(menu)) {
      if (row === anchorRow) continue;
      row.classList.add("is-menu-receding");
      row.inert = true;
      row.setAttribute("aria-hidden", "true");
    }

    const inner = layer.querySelector(".menu-submenu-inner");
    let submenuHeight = editingInline
      ? anchorHeight
      : editingDate
        ? Math.max(anchorHeight, inner.offsetHeight)
        : inner.offsetHeight;
    if (!DETACHED_SETTINGS_SUBMENUS.has(albumSubmenu)) {
      const availableBelow =
        window.innerHeight -
        anchorRow.getBoundingClientRect().bottom -
        POPOVER_EDGE_GAP;
      if (submenuHeight > availableBelow) {
        inner.style.maxHeight = `${Math.max(anchorHeight, availableBelow)}px`;
        inner.style.overflowY = "auto";
        inner.style.overscrollBehavior = "contain";
        submenuHeight = inner.offsetHeight;
      }
    }
    if (DETACHED_SETTINGS_SUBMENUS.has(albumSubmenu)) {
      layer.classList.add("menu-settings-submenu");
      /* 设置菜单的行高是 42px，须在类名生效后重新测量。否则内容未溢出时
         会沿用通用菜单的 44px 行高，在最后一项下方留下空白，并让末行悬停
         底色错位到菜单底边。 */
      submenuHeight = Math.max(anchorHeight, inner.offsetHeight);
      const rootSwitchExpanded = albumSubmenu === "rootSwitch";
      menu.classList.add("is-detached-settings-submenu-expanded");
      const anchorBottom = anchorRow.getBoundingClientRect().bottom;
      const maximumCardHeight = Math.max(
        anchorHeight,
        window.innerHeight - anchorBottom - POPOVER_EDGE_GAP,
      );
      if (submenuHeight > maximumCardHeight) {
        inner.style.maxHeight = `${maximumCardHeight}px`;
        inner.style.overflowY = "auto";
        inner.style.overscrollBehavior = "contain";
        submenuHeight = inner.offsetHeight;
      }
      layer.classList.add("is-detached");
      layer.style.position = "absolute";
      layer.style.left = "0";
      layer.style.right = "0";
      layer.style.width = "auto";
      layer.style.top = `${anchorRow.offsetTop + anchorHeight}px`;
      if (rootSwitchExpanded) {
        const fromBottomRadius = getComputedStyle(menu).borderBottomLeftRadius;
        menu.classList.add("is-root-switch-expanded");
        menuBorderRadiusAnim = menu.animate(
          [
            {
              borderBottomLeftRadius: fromBottomRadius,
              borderBottomRightRadius: fromBottomRadius,
            },
            { borderBottomLeftRadius: "0px", borderBottomRightRadius: "0px" },
          ],
          { ...timing, fill: "forwards" },
        );
      }
    }
    /* 筛选、类型、排序都只让当前行的二级菜单向下铺开；
       三横杠菜单本身始终保持展开前的高度，下边缘不能跟着变长。
       内嵌的重命名 / 时间编辑也不需要拉伸外壳。 */
    const expandedHeight = beforeHeight;
    menu.style.height = `${beforeHeight}px`;
    layer.style.height =
      editingInline || editingDate ? `${submenuHeight}px` : "0px";
    void layer.offsetHeight;
    group.getBoundingClientRect();
    group.classList.add("is-expanded", "has-open-submenu");
    if (editingInline || editingDate) {
      if (editingDate) {
        /* 时间卡片先占住“调整时间”这一整行，再从行底向下铺开。
           外框、阴影和内部内容共用同一条 280ms 时间线；内容和外框
           在最后一帧同时就位，类似右键项目预览从原卡片展开。 */
        const dateOpenTiming = {
          duration: MENU_DATE_OPEN_MS,
          easing: MENU_DATE_OPEN_EASING,
        };
        const dateWidthRatio = Math.min(
          1,
          anchorRow.offsetWidth / Math.max(1, layer.offsetWidth),
        );
        layer.style.transformOrigin = "100% 50%";
        menuContentAnim =
          expandedHeight !== beforeHeight
            ? menu.animate(
                [
                  { height: `${beforeHeight}px` },
                  { height: `${expandedHeight}px` },
                ],
                { ...dateOpenTiming, fill: "forwards" },
              )
            : null;
        const menuGlassColor = getComputedStyle(menu).backgroundColor;
        const dateSurfaceColor = getComputedStyle(layer).backgroundColor;
        const cardShadow = getComputedStyle(layer).boxShadow;
        menu.classList.add("is-date-expanded");
        menuSubmenuAnim = layer.animate(
          [
            {
              height: `${anchorHeight}px`,
              boxShadow: "0 0 0 rgba(0, 0, 0, 0), 0 0 0 rgba(0, 0, 0, 0)",
              backgroundColor: menuGlassColor,
              transform: `scale(${dateWidthRatio}, 1)`,
            },
            {
              height: `${submenuHeight}px`,
              boxShadow: cardShadow,
              backgroundColor: dateSurfaceColor,
              transform: "scale(1, 1)",
            },
          ],
          { ...dateOpenTiming, fill: "forwards" },
        );
        menuSubmenuContentAnim = inner.animate(
          [
            {
              transform: "translateY(-12px) scale(0.985)",
            },
            {
              transform: "translateY(0) scale(1)",
            },
          ],
          { ...dateOpenTiming, fill: "forwards" },
        );
        revealMenuDate(inner, { duration: MENU_DATE_OPEN_MS });
      } else {
        /* 行内重命名不做高度推拉：输入框直接在原行位置从略小、透明
           放大到原尺寸，像整块浮层向屏幕外弹出来。 */
        layer.style.transformOrigin = "50% 50%";
        menuSubmenuAnim = layer.animate(
          [
            { opacity: 0, transform: "scale(0.92)" },
            { opacity: 1, transform: "scale(1.01)", offset: 0.7 },
            { opacity: 1, transform: "scale(1)" },
          ],
          { ...timing, fill: "forwards" },
        );
      }
    } else {
      menuContentAnim = menu.animate(
        [{ height: `${beforeHeight}px` }, { height: `${expandedHeight}px` }],
        { ...submenuOpenTiming, fill: "forwards" },
      );
      menuSubmenuAnim = layer.animate(
        [{ height: "0px" }, { height: `${submenuHeight}px` }],
        { ...submenuOpenTiming, fill: "forwards" },
      );
      menuSubmenuContentAnim = inner.animate(
        [{ transform: "translateY(-20px)" }, { transform: "translateY(0)" }],
        submenuOpenTiming,
      );
    }

    if (editingRename) {
      const input = layer.querySelector(".menu-inline-input");
      const confirm = layer.querySelector(".menu-inline-confirm");
      const syncConfirm = () => {
        if (confirm) confirm.disabled = !input?.value.trim();
      };
      const submit = async () => {
        if (!input) return;
        const value = input.value.trim();
        if (!value) {
          input.focus({ preventScroll: true });
          return;
        }
        const album = albumById(state.activeId);
        if (album && value === album.name) {
          albumSubmenu = null;
          animateMenuContent("album");
          return;
        }
        input.disabled = true;
        if (confirm) confirm.disabled = true;
        const ok = await renameAlbumTo(Number(state.activeId), value);
        if (!ok && input.isConnected) {
          input.disabled = false;
          input.focus({ preventScroll: true });
          input.select();
          syncConfirm();
        }
      };
      input?.addEventListener("input", syncConfirm);
      input?.addEventListener("click", (event) => event.stopPropagation());
      input?.addEventListener("keydown", (event) => {
        event.stopPropagation();
        if (event.key === "Enter") {
          event.preventDefault();
          submit();
        } else if (event.key === "Escape") {
          event.preventDefault();
          albumSubmenu = null;
          animateMenuContent("album");
        }
      });
      confirm?.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        submit();
      });
      syncConfirm();
      requestAnimationFrame(() => {
        if (!input?.isConnected) return;
        input.focus({ preventScroll: true });
        input.select();
      });
    }
    if (editingTitle) {
      const input = layer.querySelector(".menu-inline-input");
      const confirm = layer.querySelector(".menu-inline-confirm");
      const closeEditor = () => {
        albumSubmenu = null;
        animateMenuContent(menuKind);
      };
      const submit = () => {
        if (!input) return;
        const next = normalizeLibraryTitle(input.value);
        applyLibraryTitle(next);
        void persistPersistentSettings();
        closeEditor();
      };
      input?.addEventListener("input", () => {
        settingsDraft.libraryTitle = input.value;
        syncSidebarTitle(input.value);
      });
      input?.addEventListener("click", (event) => event.stopPropagation());
      input?.addEventListener("keydown", (event) => {
        event.stopPropagation();
        if (event.key === "Enter") {
          event.preventDefault();
          submit();
        } else if (event.key === "Escape") {
          event.preventDefault();
          syncSidebarTitle();
          closeEditor();
        }
      });
      confirm?.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        submit();
      });
      requestAnimationFrame(() => {
        if (!input?.isConnected) return;
        input.focus({ preventScroll: true });
        input.select();
      });
    }
    if (editingDate) {
      bindDateEditorControls(layer, {
        items: selectedItems(),
        save: saveSelectedItemDate,
        onDismiss: () => closeMenu(),
        onClose: () => {
          albumSubmenu = null;
          animateMenuContent(menuKind);
        },
      });
    }
    const finish = () => {
      const menuAnim = menuContentAnim;
      const submenuAnim = menuSubmenuAnim;
      const contentAnim = menuSubmenuContentAnim;
      const radiusAnim = menuHeadRadiusAnim;
      const borderAnim = menuBorderRadiusAnim;
      menu.style.height = `${expandedHeight}px`;
      layer.style.height = `${submenuHeight}px`;
      menuAnim?.cancel();
      submenuAnim?.cancel();
      contentAnim?.cancel();
      radiusAnim?.cancel();
      borderAnim?.cancel();
      menuContentAnim = null;
      menuSubmenuAnim = null;
      menuSubmenuContentAnim = null;
      menuHeadRadiusAnim = null;
      menuBorderRadiusAnim = null;
    };
    Promise.all(
      [
        menuContentAnim?.finished,
        menuSubmenuAnim?.finished,
        menuSubmenuContentAnim?.finished,
      ].filter(Boolean),
    ).then(finish, finish);
    return;
  }

  if (!albumSubmenu && submenu) {
    const beforeHeight = menu.offsetHeight;
    const submenuHeight = submenu.offsetHeight;
    const editingRename = submenu.classList.contains("menu-rename-editor");
    const editingDate = submenu.classList.contains("menu-date-editor");
    const group = submenu.closest(".menu-submenu-group");
    const groupName = group?.dataset.submenuGroup;
    const closingDetachedSubmenu = DETACHED_SETTINGS_SUBMENUS.has(groupName);
    const closingRootSwitch = groupName === "rootSwitch";
    if (closingRootSwitch) {
      const targetRadius =
        getComputedStyle(menu).borderTopLeftRadius || menuRadius;
      menuBorderRadiusAnim = menu.animate(
        [
          { borderBottomLeftRadius: "0px", borderBottomRightRadius: "0px" },
          {
            borderBottomLeftRadius: targetRadius,
            borderBottomRightRadius: targetRadius,
          },
        ],
        { ...timing, fill: "forwards" },
      );
    }
    const editingInline = editingRename || editingDate;
    const closeTiming = editingDate
      ? {
          duration: MENU_DATE_CLOSE_MS,
          easing: MENU_DATE_CLOSE_EASING,
        }
      : editingInline
        ? timing
        : {
            duration: MENU_SUBMENU_CLOSE_MS,
            easing: MENU_MOTION_EASING,
          };
    if (editingDate) menu.classList.remove("is-date-expanded");
    if (closingRootSwitch) {
      const paddingBottom =
        parseFloat(getComputedStyle(group).paddingBottom) || 0;
      if (paddingBottom > 0) {
        menuGroupPaddingAnim = group.animate(
          [{ paddingBottom: `${paddingBottom}px` }, { paddingBottom: "0px" }],
          { ...timing, fill: "forwards" },
        );
      }
    }
    const anchorRow = group?.querySelector(".menu-submenu-head");
    if (closingRootSwitch && anchorRow) {
      const fromBottomRadius =
        parseFloat(getComputedStyle(anchorRow).borderBottomLeftRadius) || 0;
      menuAnchorBottomRadiusAnim = anchorRow.animate(
        [
          {
            borderBottomLeftRadius: `${fromBottomRadius}px`,
            borderBottomRightRadius: `${fromBottomRadius}px`,
          },
          {
            borderBottomLeftRadius: menuRadius,
            borderBottomRightRadius: menuRadius,
          },
        ],
        { ...closeTiming, fill: "forwards" },
      );
    }
    const atMenuTop = group?.offsetTop === 0;
    anchorRow
      ?.querySelector(".menu-submenu-chevron")
      ?.classList.remove("is-open");
    const fromRadius = anchorRow
      ? getComputedStyle(anchorRow).borderTopLeftRadius
      : menuRadius;
    const straightenAnchorCorners = !!anchorRow && !atMenuTop && !editingRename;
    if (straightenAnchorCorners) anchorRow.classList.add("is-closing");
    if (straightenAnchorCorners) {
      menuHeadRadiusAnim = anchorRow.animate(
        [
          { borderTopLeftRadius: fromRadius, borderTopRightRadius: fromRadius },
          { borderTopLeftRadius: "0px", borderTopRightRadius: "0px" },
        ],
        closeTiming,
      );
    }
    /* 收起过程中二级菜单仍然存在，先让这一组继续压在其他行上面，
       等最后一帧移除二级菜单后再恢复普通层级。 */
    group?.classList.add("has-open-submenu");
    group?.classList.remove("is-expanded");
    group?.classList.remove("has-extension-confirm");
    mainMenuRows(menu).forEach((row) => {
      row.classList.remove("is-menu-receding", "is-hover-pinned");
      row.inert = false;
      row.removeAttribute("aria-hidden");
    });
    menuSubmenuCollapsing = true;
    menu.classList.add("is-submenu-collapsing");
    menu.style.setProperty(
      "--menu-submenu-collapse-ms",
      `${closeTiming.duration}ms`,
    );
    menu.style.setProperty("--menu-submenu-collapse-ease", closeTiming.easing);
    anchorRow?.classList.add("is-menu-anchor-closing");
    submenu.style.pointerEvents = "none";
    const baseHeight = collapsedMainMenuHeight(menu);
    menu.style.height = `${beforeHeight}px`;
    submenu.style.height = `${submenuHeight}px`;
    if (editingInline) {
      menuContentAnim = menu.animate(
        [{ height: `${beforeHeight}px` }, { height: `${baseHeight}px` }],
        { ...closeTiming, fill: "forwards" },
      );
      if (editingDate) {
        /* 时间卡片把“调整时间”文字中心作为折叠原点：
           顶边向下、底边向上同时合拢，最终消失在这一行文字的位置。 */
        anchorRow?.classList.remove("menu-date-anchor");
        group?.classList.remove("menu-date-group-expanded");
        const anchorHeight = anchorRow?.offsetHeight || 44;
        const anchorTextY = anchorHeight / 2;
        const retractY = anchorTextY - submenuHeight / 2;
        const anchorWidth = anchorRow?.offsetWidth || menu.offsetWidth;
        const widthRatio = Math.min(
          1,
          anchorWidth / Math.max(1, submenu.offsetWidth),
        );
        submenu.style.transformOrigin = "100% 50%";
        menuSubmenuAnim = submenu.animate(
          [
            { opacity: 1, transform: "translateY(0) scale(1, 1)" },
            {
              opacity: 0,
              transform: `translateY(${retractY}px) scale(${widthRatio}, 0.03)`,
            },
          ],
          { ...closeTiming, fill: "forwards" },
        );
      } else {
        /* 重命名仍保留原来的原位淡出与小幅度缩小。 */
        submenu.style.transformOrigin = "50% 50%";
        menuSubmenuAnim = submenu.animate(
          [
            { opacity: 1, transform: "scale(1)" },
            { opacity: 0, transform: "scale(0.955)" },
          ],
          { duration: 180, easing: UI_EASE_OUT, fill: "forwards" },
        );
      }
      menuSubmenuContentAnim = null;
    } else {
      menuContentAnim = menu.animate(
        [{ height: `${beforeHeight}px` }, { height: `${baseHeight}px` }],
        { ...closeTiming, fill: "forwards" },
      );
      menuSubmenuAnim = submenu.animate(
        [{ height: `${submenuHeight}px` }, { height: "0px" }],
        { ...closeTiming, fill: "forwards" },
      );
      const inner = submenu.querySelector(".menu-submenu-inner");
      menuSubmenuContentAnim = inner?.animate(
        [{ transform: "translateY(0)" }, { transform: "translateY(-20px)" }],
        closeTiming,
      );
    }
    const finish = () => {
      const menuAnim = menuContentAnim;
      const submenuAnim = menuSubmenuAnim;
      const contentAnim = menuSubmenuContentAnim;
      const radiusAnim = menuHeadRadiusAnim;
      const borderAnim = menuBorderRadiusAnim;
      const paddingAnim = menuGroupPaddingAnim;
      const anchorBottomAnim = menuAnchorBottomRadiusAnim;
      const wasHovered = !!anchorRow?.matches(":hover");
      menu.style.height = "";
      menuAnim?.cancel();
      submenuAnim?.cancel();
      contentAnim?.cancel();
      radiusAnim?.cancel();
      borderAnim?.cancel();
      paddingAnim?.cancel();
      anchorBottomAnim?.cancel();
      menuContentAnim = null;
      menuSubmenuAnim = null;
      menuSubmenuContentAnim = null;
      menuHeadRadiusAnim = null;
      menuBorderRadiusAnim = null;
      menuGroupPaddingAnim = null;
      menuAnchorBottomRadiusAnim = null;
      menu.classList.remove("is-submenu-collapsing");
      if (closingDetachedSubmenu) {
        menu.classList.remove("is-detached-settings-submenu-expanded");
      }
      if (closingRootSwitch) {
        menu.classList.remove("is-root-switch-expanded");
        group?.style.removeProperty("padding-bottom");
        cancelAnimationFrame(rootSwitchScrollFrame);
        rootSwitchScrollFrame = 0;
        if (menu.dataset.rootSwitchBaseScroll != null) {
          menu.scrollTop = Number(menu.dataset.rootSwitchBaseScroll) || 0;
          delete menu.dataset.rootSwitchBaseScroll;
        }
      }
      menu.style.removeProperty("--menu-submenu-collapse-ms");
      menu.style.removeProperty("--menu-submenu-collapse-ease");
      menuSubmenuCollapsing = false;
      menu.classList.remove("has-submenu-expanded");
      if (!menuOpen) return;
      /* 动画最后一帧直接重建菜单内容：把展开时留下的圆角合成层一起丢掉，
         否则某些显卡下旧的圆角会一直留在缓存里，直到鼠标再次移动。 */
      renderMenu(menuKind);
      if (wasHovered && groupName) {
        const freshRow = menu.querySelector(
          `.menu-submenu-group[data-submenu-group="${groupName}"] > .menu-row`,
        );
        if (freshRow) {
          freshRow.classList.add("is-hover-pinned");
          const clearPin = () => {
            freshRow.classList.remove("is-hover-pinned");
            document.removeEventListener("pointermove", clearPin, true);
          };
          document.addEventListener("pointermove", clearPin, true);
        }
      }
    };
    Promise.all(
      [
        menuContentAnim?.finished,
        menuSubmenuAnim?.finished,
        ...(menuSubmenuContentAnim ? [menuSubmenuContentAnim.finished] : []),
      ].filter(Boolean),
    ).then(finish, finish);
  }
}

/* ------------------- 顶栏按键的进出场 ------------------- */
/* 以前是直接切 hidden，一进选择模式这一排按键「啪」地一下整块换掉，很生硬。
   现在改成：要退场的先量好位置、钉在原地（绝对定位，脱离文档流）再淡出缩一点，
   这样进场的按键立刻落到它最终该在的位置，不会被正在退场的那几颗挤着走、
   等它们没了再跳一下。落点差不多重合的两颗（比如「选择」和「⋯」）
   看着就是一进一出的交叉淡入淡出。
   以后顶栏再加按键，只要在 render() 的 wanted 里收一下，动画自动就有。 */
const topbarBtns = [...document.querySelectorAll(".toolbar button")];
const topbarShown = new Set(); /* 现在显示着哪几颗 */
const topbarAnims = new Map(); /* 每颗按键身上正跑着的那个进退场动画 */
const topbarShifts = new Map(); /* 因为旁边按键变宽 / 出现而挪位置的动画 */

const TOP_ENTER_MS = 170; /* 进场：淡入，顺带从 0.88 倍弹回原大小 */
const TOP_EXIT_MS = 100; /* 退场：淡出缩一点。快一点，先把位置腾出来 */
const TOP_ENTER_GAP = 18; /* 一起进场的几颗依次错开，看着有先后，而不是一整块冒出来 */
const TOP_EXIT_GAP = 12;
const TOP_SHIFT_MS = 220; /* 「⋯」进出、按键变宽变窄时，旁边按键滑开 / 让位 */
/* 两组按键换班时，退场的先走、进场的等 TOP_HANDOFF_MS 再开始 ——
   两排字（比如「选择」和「取消」）宽度不一样，同时淡入淡出会糊成一团。
   错开这一小段，进场的字亮起来的时候，退场的已经淡到看不清了。
   没有人退场时（比如从「所有相簿」进相簿，只是冒出来）就不必等这一下。 */
const TOP_HANDOFF_MS = 70;

/* 退场期间钉在原地：量出它现在待的地方，改成绝对定位摆在那儿，不再占位置 */
function topbarPin(el, measuredRect = null) {
  const r = measuredRect || el.getBoundingClientRect();
  const p = el.parentElement.getBoundingClientRect();
  const cs = getComputedStyle(el);
  /* 绝对定位仍然会吃 margin。先补偿现有外边距，
     避免从文档流切到绝对定位的第一帧凭空横向跳动。 */
  const marginLeft = parseFloat(cs.marginLeft) || 0;
  const marginTop = parseFloat(cs.marginTop) || 0;
  el.style.position = "absolute";
  el.style.left = `${r.left - p.left - marginLeft}px`;
  el.style.top = `${r.top - p.top - marginTop}px`;
  el.style.width = `${r.width}px`;
  el.style.height = `${r.height}px`;
}

function topbarUnpin(el) {
  el.style.position = "";
  el.style.left = "";
  el.style.top = "";
  el.style.width = "";
  el.style.height = "";
}

/* 动画播到一半被打断：从它「现在看得见的样子」接着走，别跳回起点 */
function topbarNow(el) {
  const cs = getComputedStyle(el);
  return {
    opacity: cs.opacity,
    transform: cs.transform === "none" ? "scale(1)" : cs.transform,
  };
}

/* 用独立 translate 做横向补位，不碰按钮自身的 transform：
   这样正在淡入 / 缩放的按键，也能同时被旁边新出现的按键推着走。 */
function animateTopbarShift(el, dx) {
  if (Math.abs(dx) < 0.5) return;
  topbarShifts.get(el)?.cancel();
  const anim = el.animate([{ translate: `${dx}px 0` }, { translate: "0 0" }], {
    duration: TOP_SHIFT_MS,
    easing: "cubic-bezier(0.32, 0.72, 0.42, 1)",
    fill: "both",
  });
  topbarShifts.set(el, anim);
  anim.onfinish = () => {
    if (topbarShifts.get(el) !== anim) return;
    topbarShifts.delete(el);
    anim.cancel();
  };
}

function topbarIsHiddenByHoverMode(el) {
  return (
    document.documentElement.classList.contains("toolbar-hover-controls") &&
    getComputedStyle(el).opacity === "0" &&
    !el.matches(":hover, :focus-visible, .is-open")
  );
}

function syncTopbar(wanted) {
  const leaving = topbarBtns.filter(
    (el) => topbarShown.has(el) && !wanted.has(el.id),
  );
  const coming = topbarBtns.filter(
    (el) => !topbarShown.has(el) && wanted.has(el.id),
  );
  if (!leaving.length && !coming.length) return;

  /* 先把所有还在顶栏里的按键位置记下来；等「⋯」出现或让开之后，
     没进出场的按键就按这份旧位置滑到新位置。 */
  const before = new Map();
  for (const el of topbarBtns) {
    if (el.hidden || el.getBoundingClientRect().width === 0) continue;
    before.set(el, el.getBoundingClientRect().left);
  }

  /* 退场的：位置要在「进场的还没显出来」的时候量，那才是它本来的位置；
     而且要先把几颗都量完再钉 —— 边量边钉的话，前一颗一脱离文档流，
     后一颗量到的位置就被带偏了 */
  const spots = leaving.map((el) => el.getBoundingClientRect());
  leaving.forEach((el, i) => {
    const isBack = el.id === "backBtn";
    const prev = topbarAnims.get(el);
    const from = prev ? topbarNow(el) : null;
    prev?.cancel();
    topbarShifts.get(el)?.cancel();
    topbarShifts.delete(el);
    topbarShown.delete(el);
    if (topbarIsHiddenByHoverMode(el)) {
      topbarAnims.delete(el);
      topbarUnpin(el);
      if (isBack) el.style.transformOrigin = "";
      el.hidden = true;
      return;
    }
    topbarPin(el, spots[i]);
    if (isBack) el.style.transformOrigin = "left center";

    const exitStart = from || { opacity: 1, transform: "scale(1)" };
    /* 新建相簿的「＋」和进入选择模式后的「选择」只原地淡出，
       不缩小、不位移，避免看起来像被旁边新出现的按键推走。 */
    const exitEnd =
      el.id === "createBtn" || el.id === "selectBtn"
        ? { opacity: 0, transform: exitStart.transform }
        : isBack
          ? { opacity: 0, transform: "translateX(-9px) scale(0.96)" }
          : { opacity: 0, transform: "scale(0.92)" };
    const anim = el.animate(
      [exitStart, exitEnd],
      /* 淡出用 ease-out：开头掉得快，位置早点腾干净，不给后面那排字留重影 */
      {
        duration: isBack ? 130 : TOP_EXIT_MS,
        delay: i * TOP_EXIT_GAP,
        easing: "cubic-bezier(0.32, 0.62, 0.32, 1)",
        fill: "forwards",
      },
    );
    topbarAnims.set(el, anim);
    anim.onfinish = () => {
      if (topbarAnims.get(el) !== anim)
        return; /* 没播完又被叫回来了：交给新的那次管 */
      topbarAnims.delete(el);
      anim.cancel();
      topbarUnpin(el);
      if (isBack) el.style.transformOrigin = "";
      el.hidden = true;
    };
  });

  /* 进场的：显出来，就地淡入（落点就是最终位置，不飘） */
  coming.forEach((el, i) => {
    const isBack = el.id === "backBtn";
    const prev = topbarAnims.get(el);
    const from = prev ? topbarNow(el) : null;
    prev?.cancel();
    topbarShifts.get(el)?.cancel();
    topbarShifts.delete(el);
    if (prev)
      topbarUnpin(el); /* 上一轮退到一半被叫回来：先松开，回到正常占位 */
    topbarShown.add(el);
    el.hidden = false;
    if (isBack) el.style.transformOrigin = "left center";

    /* 悬停模式下，普通按钮不该为了出场动画短暂显示一次。
       先让浏览器按当前 CSS 算目标透明度；若它本来就应隐藏，直接结束。 */
    if (topbarIsHiddenByHoverMode(el)) {
      topbarAnims.delete(el);
      if (isBack) el.style.transformOrigin = "";
      return;
    }

    const anim = el.animate(
      [
        from ||
          (isBack
            ? { opacity: 0, transform: "translateX(-9px) scale(0.96)" }
            : { opacity: 0, transform: "scale(0.88)" }),
        { opacity: 1, transform: "scale(1)" },
      ],
      {
        duration: isBack ? 150 : TOP_ENTER_MS,
        delay: (leaving.length ? TOP_HANDOFF_MS : 0) + i * TOP_ENTER_GAP,
        easing: "cubic-bezier(0.32, 0.72, 0.42, 1)",
        fill: "backwards",
      },
    );
    topbarAnims.set(el, anim);
    anim.onfinish = () => {
      if (topbarAnims.get(el) !== anim) return;
      topbarAnims.delete(el);
      if (isBack) el.style.transformOrigin = "";
    };
  });

  const changing = new Set([...leaving, ...coming]);
  for (const el of topbarBtns) {
    if (!topbarShown.has(el) || changing.has(el)) continue;
    const oldLeft = before.get(el);
    if (oldLeft == null) continue;
    animateTopbarShift(el, oldLeft - el.getBoundingClientRect().left);
  }
}

/* 选择模式里的「⋯」只在选中东西后出现。逐张点选、滑选时顶栏不重绘，
   所以这里单独把这一颗按钮接进同一套进出场动画；一件都没选时也顺手收起菜单。 */
function syncSelectionMenuButton(isTrash) {
  const shouldShow =
    state.select && !state.copyTarget && !isTrash && state.selected.size > 0;
  if (!shouldShow && menuKind !== "settings") closeMenu();

  const wanted = new Set([...topbarShown].map((el) => el.id));
  if (shouldShow) wanted.add("moreTopBtn");
  else wanted.delete("moreTopBtn");
  syncTopbar(wanted);
}

function toolbarContext() {
  const isTrash = state.activeId === "trash";
  const isAll = state.activeId === "all";
  const isLibrary = state.activeId === "library";
  const isFavorites = state.activeId === "favorites";
  const isPhotoWall = state.activeId === "photoWall";
  const isLocations = state.activeId === "locations";
  const isAlbumMap = isAlbumMapView();
  const activeWallAlbumId =
    state.photoWallAlbumId ||
    state.masonryWallAlbumId ||
    state.filmrollWallAlbumId ||
    state.mosaicWallAlbumId;
  const album =
    isAll || isTrash || isLibrary || isFavorites || isPhotoWall || isLocations
      ? null
      : albumById(state.activeId);
  /* 在相簿里就显示「返回上一级」，标签是上一级的名字 */
  const parent = album && album.parentId ? albumById(album.parentId) : null;
  /* 相簿里要么是照片/视频，要么是子相簿，两种不会混着来：
     只要有照片或视频，浏览时右上角是「样式 / 选择」，
     进入选择模式并选中东西后才多出「⋯」，不出现「编辑」；
     只有「纯文件夹相簿」（里面一张照片都没有）才给「编辑」，用来新建 / 删除子相簿。
     「所有相簿」也用同一套编辑方式：新建一级相簿、删除一级相簿。 */
  const media = isAlbumMap
    ? false
    : isLocations
      ? state.locationSubview !== "map" && state.items.length > 0
      : isPhotoWall
        ? activeWallAlbumId
          ? state.items.length > 0
          : state.photoWallAlbums.length > 0 ||
            state.masonryWallAlbums.length > 0 ||
            state.filmrollWallAlbums.length > 0 ||
            state.mosaicWallAlbums.length > 0
        : isLibrary || isFavorites
          ? state.items.length > 0
          : isTrash
            ? state.items.length > 0 || state.trashAlbums.length > 0
            : !!album && album.count > 0;
  const hasPhotos = isTrash ? state.items.length > 0 : media;
  const canSelect = media;
  const folder = !!album && album.kind === "folder" && album.count === 0;
  const canEdit = !isAlbumMap && (folder || (isAll && state.roots.length > 0));
  const canRename = !isAlbumMap && !!album && !isUnfiledAlbum(album);
  /* 显示选项只属于相簿详情页：从「所有相簿」点进来后才出现 */
  const showAlbumOptions =
    isAlbumMap || isPhotoWall || isLocations
      ? false
      : isLibrary
        ? media
        : !!album && media;
  return {
    isTrash,
    isAll,
    isLibrary,
    isFavorites,
    isPhotoWall,
    isLocations,
    isAlbumMap,
    album,
    parent,
    media,
    hasPhotos,
    canSelect: isAlbumMap || isPhotoWall || isLocations ? false : canSelect,
    canEdit,
    canRename,
    showAlbumOptions,
  };
}

function syncToolbarForState(ctx = toolbarContext()) {
  const {
    isTrash,
    isAll,
    isLibrary,
    isFavorites,
    isPhotoWall,
    isLocations,
    isAlbumMap,
    album,
    parent,
    canSelect,
    canEdit,
    canRename,
    showAlbumOptions,
  } = ctx;
  const targetParent =
    state.copyTarget && state.copyTargetParentId != null
      ? albumById(state.copyTargetParentId)
      : null;
  const targetUp = targetParent?.parentId
    ? albumById(targetParent.parentId)
    : null;
  const wallActive =
    state.photoWall && !state.copyTarget && state.items.length > 0;
  const libraryDisplayName = interfaceDisplayName("library");
  const locationsDisplayName = interfaceDisplayName("locations");
  const photoWallDisplayName = interfaceDisplayName("photoWall");
  const allAlbumsDisplayName = interfaceDisplayName("all");
  syncLibraryTimelineModeControl(isLibrary);
  const backLabel = isAlbumMap
    ? isLibrary
      ? `返回${libraryDisplayName}`
      : "返回相簿"
    : wallActive
      ? "照片网格"
      : isPhotoWall &&
          (state.photoWallAlbumId ||
            state.masonryWallAlbumId ||
            state.filmrollWallAlbumId ||
            state.mosaicWallAlbumId)
        ? state.mosaicWallAlbumId
          ? "嵌合拼图"
          : state.filmrollWallAlbumId
            ? "横向胶卷"
            : state.masonryWallAlbumId
              ? "纵向画廊"
              : "错落磁贴"
        : state.copyTarget
          ? targetParent
            ? targetUp
              ? albumDisplayName(targetUp)
              : allAlbumsDisplayName
            : "照片"
          : parent
            ? parent.name
            : allAlbumsDisplayName;
  $("#backLabel").textContent = backLabel;
  $("#backBtn").setAttribute(
    "aria-label",
    isAlbumMap
      ? isLibrary
        ? `返回${libraryDisplayName}`
        : "返回相簿"
      : wallActive
        ? "退出照片墙，返回照片网格"
        : "返回上一级",
  );
  setViewTitle(
    state.copyTarget
      ? targetParent
        ? albumDisplayName(targetParent)
        : copyTargetMode === "move"
          ? "移动到相簿"
          : "加入相簿"
      : isLocations
        ? locationsDisplayName
        : isTrash
          ? "最近删除"
          : isLibrary
            ? libraryDisplayName
            : isFavorites
              ? "收藏"
              : isPhotoWall
                ? anyWallSelectionActive()
                  ? "选择相簿"
                  : state.photoWallAlbumId
                    ? state.photoWallAlbums.find(
                        (entry) => entry.id === state.photoWallAlbumId,
                      )?.displayName ||
                      albumDisplayName(albumById(state.photoWallAlbumId) || {})
                    : state.masonryWallAlbumId
                      ? state.masonryWallAlbums.find(
                          (entry) => entry.id === state.masonryWallAlbumId,
                        )?.displayName ||
                        albumDisplayName(
                          albumById(state.masonryWallAlbumId) || {},
                        )
                      : state.mosaicWallAlbumId
                        ? state.mosaicWallAlbums.find(
                            (entry) => entry.id === state.mosaicWallAlbumId,
                          )?.displayName ||
                          albumDisplayName(
                            albumById(state.mosaicWallAlbumId) || {},
                          )
                        : state.filmrollWallAlbumId
                          ? state.filmrollWallAlbums.find(
                              (entry) => entry.id === state.filmrollWallAlbumId,
                            )?.displayName ||
                            albumDisplayName(
                              albumById(state.filmrollWallAlbumId) || {},
                            )
                          : photoWallDisplayName
                : album
                  ? albumDisplayName(album)
                  : allAlbumsDisplayName,
  );
  syncTitleRenameControls(
    canRename && state.edit && !state.select && !state.copyTarget,
  );
  $("#editBtn").textContent = state.edit ? "完成" : "编辑";
  $("#createBtn").setAttribute(
    "aria-label",
    isAll ? "在根文件夹里新建一个相簿" : "在当前相簿里新建一个相簿",
  );
  /* 顶栏该出现哪几颗，交给 syncTopbar 去办 —— 它顺手管进出场动画 */
  const wanted = new Set();
  const selectingPhotoWallAlbums = isPhotoWall && anyWallSelectionActive();
  const selectedAlbumCount = state.photoWallSelectedAlbums.size;
  const selectedMasonryAlbumCount = state.masonryWallSelectedAlbums.size;
  const selectedFilmrollAlbumCount = state.filmrollWallSelectedAlbums.size;
  const selectedMosaicAlbumCount = state.mosaicWallSelectedAlbums.size;
  const photoWallConfirmBtn = document.querySelector(
    `[data-wall-album-confirm-kind="${normalizeWallLibraryKind(
      state.wallLibraryKind,
    )}"]`,
  );
  const activeSelectedCount = state.mosaicWallSelectMode
    ? selectedMosaicAlbumCount
    : state.filmrollWallSelectMode
      ? selectedFilmrollAlbumCount
      : state.masonryWallSelectMode
        ? selectedMasonryAlbumCount
        : selectedAlbumCount;
  const showPhotoWallConfirm =
    selectingPhotoWallAlbums && activeSelectedCount > 0;
  for (const button of document.querySelectorAll(
    "[data-wall-album-confirm-kind]",
  )) {
    button.hidden = true;
    button
      .closest(".photo-wall-style-choice")
      ?.classList.remove("has-inline-confirm");
  }
  if (photoWallConfirmBtn) {
    photoWallConfirmBtn.disabled =
      !activeSelectedCount || photoWallAlbumConfirmBusy;
    photoWallConfirmBtn.setAttribute(
      "aria-label",
      activeSelectedCount
        ? `播放所选的 ${activeSelectedCount} 个相簿`
        : "播放所选相簿",
    );
    photoWallConfirmBtn.hidden = !showPhotoWallConfirm;
    photoWallConfirmBtn
      .closest(".photo-wall-style-choice")
      ?.classList.toggle("has-inline-confirm", showPhotoWallConfirm);
  }
  if (isAlbumMap) {
    wanted.add("backBtn");
  } else if (isLocations && state.locationSubview !== "map") {
    wanted.add("locationBackBtn");
  } else if (state.copyTarget) {
    wanted.add("backBtn");
    wanted.add("cancelSelBtn");
  } else {
    /* 顶层项目已经有侧栏的「所有相簿」入口，不再在标题栏重复一个
       「返回所有相簿」按钮。只有真正位于子相簿时，才保留返回上一级。 */
    if (
      (album?.parentId != null ||
        (isPhotoWall &&
          (state.photoWallAlbumId ||
            state.masonryWallAlbumId ||
            state.filmrollWallAlbumId ||
            state.mosaicWallAlbumId))) &&
      !state.edit
    ) {
      wanted.add("backBtn");
    }
    if ((album || isAll) && state.edit) wanted.add("createBtn");
    if (canEdit && !state.select) wanted.add("editBtn");
    if (showAlbumOptions && !state.select) wanted.add("albumMenuBtn");
    if (canSelect && !state.select) wanted.add("selectBtn");
    /* 顶栏那颗「⋯」只属于选择模式，而且要等真正选中东西后才出现 */
    if (state.select) {
      wanted.add("selectAllBtn");
      wanted.add("cancelSelBtn");
      /* 最近删除里的底栏已经有「全部删除 / 全部恢复」，那颗「⋯」里的相簿操作不适用 */
      if (!isTrash && !numberingSession && state.selected.size > 0)
        wanted.add("moreTopBtn");
    }
  }
  /* 左下角「移动到相簿」面板打开时，左上角不再留返回入口，
     避免在挑选目标相簿的过程中误离开当前照片页。 */
  if (pickerOpen) wanted.delete("backBtn");
  const filmstripButton = $("#filmstripBtn");
  filmstripButton.setAttribute("aria-pressed", String(state.filmstrip));
  filmstripButton.classList.toggle("is-active", state.filmstrip);
  syncTopbar(wanted);
}

let titleRenameOpen = false;
let titleRenameClickGuardUntil = 0;

const titleNameMeasure = document.createElement("span");
titleNameMeasure.className = "title-rename-measure";
titleNameMeasure.setAttribute("aria-hidden", "true");
document.body.append(titleNameMeasure);

function measureTitleName(text) {
  const style = getComputedStyle($("#viewTitle"));
  titleNameMeasure.style.font = style.font;
  titleNameMeasure.style.fontWeight = style.fontWeight;
  titleNameMeasure.style.letterSpacing = style.letterSpacing;
  titleNameMeasure.textContent = String(text || " ");
  return Math.max(
    18,
    Math.ceil(titleNameMeasure.getBoundingClientRect().width),
  );
}

function fitTitleNameWidth(text) {
  const slot = $(".title-name-slot");
  const maxWidth = Math.max(48, Math.min(680, window.innerWidth * 0.52));
  const nextWidth = Math.min(maxWidth, measureTitleName(text));
  const currentWidth = slot.getBoundingClientRect().width;

  /* 变长必须立即为完整名称腾出空间，否则新名字会先被挤成省略号；
     变短才走 220ms 过渡，让右侧按钮慢慢回到更靠中间的位置。 */
  if (nextWidth > currentWidth + 0.5) {
    slot.style.transition = "none";
    slot.style.width = `${nextWidth}px`;
    void slot.offsetWidth;
    slot.style.removeProperty("transition");
  } else {
    slot.style.width = `${nextWidth}px`;
  }
}

let viewTitleAnim = null;

/* 换名时从中间向两边展开，末尾带一点回弹；
   文字本身已经占好最终宽度，所以不会先出现省略号。 */
function animateViewTitleChange() {
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  const title = $("#viewTitle");
  viewTitleAnim?.cancel();
  const anim = title.animate(
    [
      {
        clipPath: "inset(0 50% 0 50%)",
        transform: "scale(0.84)",
        opacity: 0.2,
        easing: "cubic-bezier(0.2, 0.78, 0.25, 1)",
      },
      {
        clipPath: "inset(0 0 0 0)",
        transform: "scale(1.028)",
        opacity: 1,
        offset: 0.58,
        easing: "ease-in-out",
      },
      {
        clipPath: "inset(0 0 0 0)",
        transform: "scale(0.992)",
        opacity: 1,
        offset: 0.8,
        easing: "ease-in-out",
      },
      {
        clipPath: "inset(0 0 0 0)",
        transform: "scale(1)",
        opacity: 1,
      },
    ],
    {
      duration: 460,
      easing: "linear",
    },
  );
  viewTitleAnim = anim;
  anim.onfinish = () => {
    if (viewTitleAnim === anim) viewTitleAnim = null;
  };
}

function setViewTitle(text) {
  const title = $("#viewTitle");
  const changed = title.textContent !== text;
  title.textContent = text;
  fitTitleNameWidth(text);
  if (changed) animateViewTitleChange();
}

function hideTitleRenameImmediately(showPencil = true) {
  titleRenameOpen = false;
  const form = $("#titleRenameForm");
  const input = $("#titleRenameInput");
  const pencil = $("#renameAlbumBtn");
  form.hidden = true;
  input.disabled = false;
  $("#toolbarTitleGroup").classList.remove("is-editing");
  pencil.disabled = false;
  pencil.classList.remove("is-confirming");
  pencil.classList.toggle("is-shown", showPencil);
  pencil.setAttribute("aria-label", "重命名相簿");
  $("#viewTitle").setAttribute("aria-hidden", "false");
  fitTitleNameWidth($("#viewTitle").textContent);
}

function syncTitleRenameControls(canShow) {
  if (titleRenameOpen && !canShow) {
    hideTitleRenameImmediately(false);
  }
  const pencil = $("#renameAlbumBtn");
  $("#toolbarTitleGroup").classList.toggle(
    "is-editing",
    canShow && titleRenameOpen,
  );
  pencil.classList.toggle("is-shown", canShow);
  pencil.classList.toggle("is-confirming", canShow && titleRenameOpen);
  pencil.setAttribute(
    "aria-label",
    canShow && titleRenameOpen ? "确认重命名" : "重命名相簿",
  );
  $("#titleRenameForm").hidden = !(canShow && titleRenameOpen);
  $("#viewTitle").setAttribute(
    "aria-hidden",
    String(canShow && titleRenameOpen),
  );
  if (!titleRenameOpen) fitTitleNameWidth($("#viewTitle").textContent);
}

function openTitleRename() {
  const album = albumById(state.activeId);
  if (!album || isUnfiledAlbum(album) || !state.edit || titleRenameOpen) return;

  const group = $("#toolbarTitleGroup");
  const pencil = $("#renameAlbumBtn");
  const form = $("#titleRenameForm");
  const input = $("#titleRenameInput");

  titleRenameOpen = true;
  input.value = album.name;
  input.disabled = false;
  fitTitleNameWidth(album.name);
  group.classList.add("is-editing");
  form.hidden = false;
  pencil.classList.add("is-shown", "is-confirming");
  pencil.setAttribute("aria-label", "确认重命名");
  $("#viewTitle").setAttribute("aria-hidden", "true");
  requestAnimationFrame(() => {
    if (!titleRenameOpen) return;
    input.focus({ preventScroll: true });
    input.select();
  });
}

function closeTitleRename(focusPencil = false) {
  if (!titleRenameOpen) return;
  const pencil = $("#renameAlbumBtn");
  hideTitleRenameImmediately(!!albumById(state.activeId) && state.edit);

  if (focusPencil) {
    requestAnimationFrame(() => {
      pencil.focus({ preventScroll: true });
    });
  }
}

async function submitTitleRename() {
  if (!titleRenameOpen) return;
  const album = albumById(state.activeId);
  const input = $("#titleRenameInput");
  const pencil = $("#renameAlbumBtn");
  const value = input.value.trim();
  if (!album || !value) {
    input.focus({ preventScroll: true });
    return;
  }
  if (value === album.name) {
    closeTitleRename(true);
    return;
  }

  input.disabled = true;
  pencil.disabled = true;
  const ok = await renameAlbumTo(album.id, value);
  if (ok) {
    hideTitleRenameImmediately(true);
    syncTitleRenameControls(!!albumById(state.activeId) && state.edit);
    requestAnimationFrame(() => {
      pencil.focus({ preventScroll: true });
    });
    return;
  }

  input.disabled = false;
  pencil.disabled = false;
  pencil.classList.add("is-shown", "is-confirming");
  requestAnimationFrame(() => {
    if (!titleRenameOpen) return;
    input.focus({ preventScroll: true });
    input.select();
  });
}

/* 普通相簿与图库的 DOM 和本地索引数据只在版本真正变化时重建。
   切换视图时把节点整体摘下，返回后原节点直接接回，照片元素及其解码状态
   不会被 innerHTML 销毁；入场动画仍由 revealRightContent() 重新播放。 */
const CONTENT_VIEW_CACHE_LIMIT = 2;
const CONTENT_VIEW_CACHE_MAX_TILES = 360;
const COLLECTION_DATA_CACHE_LIMIT = 4;
const contentViewCache = new Map();
const collectionDataCache = new Map();
let renderedContentView = null;

function itemViewSignature(items) {
  let hash = 2166136261;
  const add = (value) => {
    const text = String(value ?? "");
    for (let index = 0; index < text.length; index += 1) {
      hash ^= text.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
  };
  for (const item of items) {
    add(item.id);
    add(item.name);
    add("\u001f");
    add(item.kind);
    add(item.width);
    add(item.height);
    add(item.mtime);
    add(item.size);
    add(item.editRevision);
    add(item.favorite ? 1 : 0);
    add(item.rating || 0);
    add(item.duration);
    add(item.liveVideoId);
    add("\u001e");
  }
  return `${items.length}:${(hash >>> 0).toString(36)}`;
}

function ordinaryContentView() {
  if (
    state.copyTarget ||
    state.select ||
    state.edit ||
    state.filmstrip ||
    state.photoWall ||
    state.albumMapOpen
  ) {
    return null;
  }
  const isLibrary = state.activeId === "library";
  const isAlbum =
    Number.isInteger(state.activeId) && state.album?.id === state.activeId;
  if (!isLibrary && !isAlbum) return null;
  const extensionFilter =
    state.extensionFilter == null
      ? "*"
      : [...state.extensionFilter].sort().join(",");
  return {
    key: JSON.stringify([
      "content-v2",
      activeRootCacheKey(),
      isLibrary ? "library" : `album:${state.activeId}`,
      state.revision,
      state.coverEpoch,
      itemViewSignature(state.items),
      state.filterKind,
      state.typeKind,
      state.deviceKind,
      state.locationFilter,
      extensionFilter,
      state.itemSort,
      state.photoZoom,
      currentPhotoStyle(),
      isOriginalRatio(),
      photoLayoutMode,
      isLibrary ? state.libraryTimelineMode : "",
    ]),
  };
}

function trimContentCache() {
  while (contentViewCache.size > CONTENT_VIEW_CACHE_LIMIT) {
    contentViewCache.delete(contentViewCache.keys().next().value);
  }
}

function cacheCurrentContentView() {
  const content = $("#content");
  const descriptor = renderedContentView;
  if (
    hasIncompleteProgressivePhotoGrid() ||
    content?.querySelectorAll(".tile[data-index]").length >
      CONTENT_VIEW_CACHE_MAX_TILES
  ) {
    cancelProgressivePhotoGridFill();
    content?.replaceChildren();
    renderedContentView = null;
    return;
  }
  if (!content || !descriptor?.key) {
    content?.replaceChildren();
    renderedContentView = null;
    return;
  }
  const fragment = document.createDocumentFragment();
  while (content.firstChild) fragment.append(content.firstChild);
  contentViewCache.delete(descriptor.key);
  contentViewCache.set(descriptor.key, { fragment });
  trimContentCache();
  renderedContentView = null;
}

function restoreCachedContentView(descriptor) {
  const entry = descriptor?.key ? contentViewCache.get(descriptor.key) : null;
  if (!entry) return false;
  contentViewCache.delete(descriptor.key);
  $("#content").replaceChildren(entry.fragment);
  trimContentCache();
  return true;
}

function promoteCachedContentView(descriptor) {
  if (!descriptor?.key || !contentViewCache.has(descriptor.key)) return;
  const entry = contentViewCache.get(descriptor.key);
  contentViewCache.delete(descriptor.key);
  contentViewCache.set(descriptor.key, entry);
}

function collectionDataCacheKey(kind, id = "") {
  return `${activeRootCacheKey()}:${kind}:${String(id)}@${String(lastRev)}`;
}

function cachedCollectionData(kind, id = "") {
  const key = collectionDataCacheKey(kind, id);
  const data = collectionDataCache.get(key);
  if (!data) return null;
  collectionDataCache.delete(key);
  collectionDataCache.set(key, data);
  return data;
}

function cacheCollectionData(kind, id, data) {
  const key = collectionDataCacheKey(kind, id);
  collectionDataCache.delete(key);
  collectionDataCache.set(key, data);
  while (collectionDataCache.size > COLLECTION_DATA_CACHE_LIMIT) {
    collectionDataCache.delete(collectionDataCache.keys().next().value);
  }
  return data;
}

function invalidateCollectionData(kind, id = "") {
  const prefix = `${activeRootCacheKey()}:${kind}:${String(id)}@`;
  for (const key of collectionDataCache.keys()) {
    if (key.startsWith(prefix)) collectionDataCache.delete(key);
  }
}

function render({
  keepContextMenu = false,
  chrome = true,
  holdReveal = false,
} = {}) {
  /* 照片墙打开期间，原页面需要作为真实背景留在 DOM 中；
     外部刷新先挂起，等墙面退场后再同步。 */
  if (photoWallDomFrozen) return;
  resetGalleryImageWindow();
  /* 换页时先把媒体压住，等 revealRightContent() 真正建立入场动画后
     再放开。这样即使缩略图已经缓存、首帧立即可画，也不会在载入动画
     启动前先完整闪出一张照片。 */
  if (holdReveal) holdContentReveal();
  cancelAlbumWheelScroll();
  cancelAlbumGridDragScroll();
  cancelAlbumCardReveal();
  /* 收藏已经清空时，收回收藏相簿等同于用户点击「图库」。 */
  if (state.activeId === "favorites" && state.favoriteCount === 0) {
    navigateFromEmptyFavorites();
    return;
  }
  if (contextMenuOpen && !keepContextMenu) closeItemContextMenu(true);
  cancelGalleryZoomMotion();
  /* 「未归档」没有项目或设置关闭时自动消失；
     如果正停在这个虚拟相簿里，回到所有相簿，不留下空页面。 */
  if (
    state.activeId !== "all" &&
    state.activeId !== "trash" &&
    state.activeId !== "hidden"
  ) {
    const active = albumById(state.activeId);
    if (isUnfiledAlbum(active) && (!showUnfiledCard || active.count === 0)) {
      fallbackToAllAlbums();
    }
  }
  if (chrome) {
    renderSidebar();
    /* 「添加到相簿」和左下角「移动项目」都让整条侧栏退成模糊背景，
       不能切换相簿，也不能被 Tab 或读屏选中。 */
    syncSidebarModalBlur();
  }
  const ctx = toolbarContext();
  const {
    isTrash,
    isLibrary,
    isFavorites,
    isAll,
    isPhotoWall,
    isLocations,
    isAlbumMap,
    album,
  } = ctx;
  document.documentElement.classList.toggle(
    "no-root-directory",
    state.roots.length === 0,
  );
  document.documentElement.classList.toggle(
    "toolbar-selecting",
    state.select && !state.copyTarget,
  );
  document.documentElement.classList.toggle(
    "toolbar-editing",
    state.edit && !state.copyTarget && !state.select && (!!album || isAll),
  );
  document.documentElement.classList.toggle(
    "toolbar-photo-wall-selecting",
    anyWallSelectionActive() &&
      isPhotoWall &&
      !state.photoWallAlbumId &&
      !state.masonryWallAlbumId &&
      !state.filmrollWallAlbumId &&
      !state.mosaicWallAlbumId,
  );
  document.documentElement.classList.toggle(
    "locations-map-titlebar-hidden",
    (isLocations && state.locationSubview === "map") || isAlbumMap,
  );
  document.documentElement.classList.toggle(
    "photo-wall-library-titlebar-hidden",
    isPhotoWall &&
      !state.photoWall &&
      !state.photoWallAlbumId &&
      !state.masonryWallAlbumId &&
      !state.filmrollWallAlbumId &&
      !state.mosaicWallAlbumId,
  );
  document.body.classList.toggle("photo-wall-library-active", isPhotoWall);
  syncSidebarRailButtonState();
  if (chrome) syncToolbarForState(ctx);

  const photoWallVisible =
    state.photoWall &&
    !state.copyTarget &&
    !isTrash &&
    Boolean(state.photoWallPlayback);
  const albumMapVisible = isAlbumMap;
  const locationsMapVisible = isLocations && state.locationSubview === "map";
  const filmstripVisible =
    state.filmstrip &&
    !state.copyTarget &&
    !state.select &&
    !photoWallVisible &&
    !locationsMapVisible &&
    !albumMapVisible &&
    state.items.length > 0;
  /* 视图模式必须在内容进入 DOM 前落到外壳上。胶片预览依赖 body 级
     样式把工具栏变成不占高度的透明浮层；若等到 syncFilmstripView
     之后才加类，任何同步刷新异常都会留下一条实色顶栏。 */
  $("#content").classList.toggle("filmstrip-view-mode", filmstripVisible);
  document.body.classList.toggle("filmstrip-view-mode", filmstripVisible);
  const nextContentView =
    albumMapVisible || locationsMapVisible ? null : ordinaryContentView();
  const content = $("#content");
  let reusedContentView = Boolean(
    nextContentView && renderedContentView?.key === nextContentView.key,
  );
  let nextProgressiveGridBatch = null;
  if (!reusedContentView) {
    promoteCachedContentView(nextContentView);
    cacheCurrentContentView();
    reusedContentView = restoreCachedContentView(nextContentView);
    if (!reusedContentView) {
      let html = "";
      const progressiveBuild = {
        seq: ++progressivePhotoGridSeq,
        grids: [],
        gridIndex: 0,
        initialRemaining: PROGRESSIVE_PHOTO_GRID_INITIAL_ITEMS,
      };
      progressivePhotoGridBuilder = progressiveBuild;
      try {
        if (!albumMapVisible) {
          if (state.copyTarget) html = renderCopyTargetAlbums();
          else if (filmstripVisible) html = renderFilmstripView();
          else if (photoWallVisible) html = renderPhotoWallView();
          else if (isTrash) html = renderTrashView();
          else if (isPhotoWall) {
            html =
              state.photoWallAlbumId ||
              state.masonryWallAlbumId ||
              state.filmrollWallAlbumId ||
              state.mosaicWallAlbumId
                ? renderPhotoWallAlbumView()
                : renderPhotoWallLibraryView();
          } else if (isLocations) {
            html = locationsMapVisible ? "" : renderLocationItemsView();
          } else if (isLibrary) html = renderLibraryView();
          else if (isFavorites) html = renderFavoritesView();
          else html = album ? renderAlbumView(album) : renderAlbumCards();
        }
      } finally {
        progressivePhotoGridBuilder = null;
      }
      content.innerHTML = html;
      nextProgressiveGridBatch = progressiveBuild.grids.length
        ? progressiveBuild
        : null;
    }
  }
  hydrateCurveLoaders();
  if (nextProgressiveGridBatch) {
    progressivePhotoGridBatch = nextProgressiveGridBatch;
  }
  renderedContentView = nextContentView;
  if (filmstripVisible) syncFilmstripView();
  else applyPhotoGridLayouts();
  $("#content").classList.toggle(
    "library-timeline-mode",
    isLibrary && state.libraryTimelineMode !== "all",
  );
  syncLibraryTimelineScrubber({ rebuildTicks: true });
  $("#content").classList.toggle(
    "location-grid-view",
    isLocations && !locationsMapVisible,
  );
  if (locationsMapVisible) showLocationsMapView();
  else hideLocationsMapView();
  if (albumMapVisible) showAlbumMapView();
  else hideAlbumMapView();
  $("#content").hidden = locationsMapVisible || albumMapVisible;
  document.body.classList.toggle("album-map-view-mode", albumMapVisible);
  document.body.classList.toggle(
    "location-assign-mode",
    albumMapVisible && state.albumMapAssignMode,
  );
  $("#content").classList.toggle("photo-wall-mode", photoWallVisible);
  document.body.classList.toggle("photo-wall-mode", photoWallVisible);
  if (photoWallVisible) mountPhotoWallApp();
  else unmountPhotoWallApp();
  if (canZoomGallery() && !photoWallVisible) {
    setGalleryImageQuality(photoLayoutGrids(), state.photoZoom);
  }
  observeGalleryImageTiles(photoLayoutGrids());
  scheduleProgressivePhotoGridFill();
  $("#content").classList.remove("edit-leaving");
  $("#content").classList.toggle(
    "edit-mode",
    state.edit && !state.copyTarget && (!!album || isAll),
  );
  $("#content").classList.toggle(
    "select-mode",
    state.select && !state.copyTarget,
  );
  $("#content").classList.toggle(
    "photo-wall-album-select-mode",
    anyWallSelectionActive() &&
      isPhotoWall &&
      !state.photoWallAlbumId &&
      !state.masonryWallAlbumId &&
      !state.filmrollWallAlbumId &&
      !state.mosaicWallAlbumId,
  );
  $("#content").classList.toggle(
    "masonry-wall-album-select-mode",
    masonryWallAlbumSelectionActive(),
  );
  $("#content").classList.toggle(
    "filmroll-wall-album-select-mode",
    filmrollWallAlbumSelectionActive(),
  );
  $("#content").classList.toggle(
    "mosaic-wall-album-select-mode",
    mosaicWallAlbumSelectionActive(),
  );
  $("#content").classList.toggle(
    "wall-select-tile",
    Boolean(state.photoWallSelectMode),
  );
  $("#content").classList.toggle(
    "wall-select-masonry",
    Boolean(state.masonryWallSelectMode),
  );
  $("#content").classList.toggle(
    "wall-select-filmroll",
    Boolean(state.filmrollWallSelectMode),
  );
  $("#content").classList.toggle(
    "wall-select-mosaic",
    Boolean(state.mosaicWallSelectMode),
  );
  syncSelectionBar();
  syncSelbar();
  if (!state.select) {
    if (menuKind !== "settings") closeMenu();
    hidePickerNow({ syncChrome: chrome });
  }
  paintKeyboardFocus();
  renderStatus();
  applySettledAlbumHover();
  syncAlbumGridSpacing();
  $("#content").classList.toggle(
    "is-content-crossfade-active",
    Boolean(contentCrossfadeMotion?.snapshot?.isConnected),
  );
  scheduleVisibleContextMapPreviews();
}

function syncSelectionBar() {
  const bar = $("#selbar");
  const visible = state.select && !state.copyTarget;
  bar.inert = !visible;
  bar.setAttribute("aria-hidden", String(!visible));
  if (!visible) {
    bar.classList.add("is-collapsed");
    return;
  }
  if (!bar.classList.contains("is-collapsed")) return;
  /* 先让折叠态产生一次布局，再在下一帧展开，height 过渡才会真正播放。 */
  bar.getBoundingClientRect();
  requestAnimationFrame(() => {
    if (state.select && !state.copyTarget) bar.classList.remove("is-collapsed");
  });
}

/* ------------------------------ 交互 ------------------------------ */

async function loadAlbum(albumId, { request = null } = {}) {
  /* 相簿内容来自本地索引，切换相簿时静默读取，不占底栏、不推挤内容。 */
  const cached = request ? null : cachedCollectionData("album", albumId);
  const data =
    cached ||
    (await (request || api(`/api/albums/${albumId}/items?limit=100000`)));
  if (!cached) cacheCollectionData("album", albumId, data);
  state.album = data.album;
  state.albumItemsRaw = Array.isArray(data.items) ? data.items : [];
  state.albumItems = sortAlbumItems(state.albumItemsRaw, state.itemSort);
  state.items = visibleAlbumItems();
  state.busy = "";
}

async function loadLibrary() {
  const cached = cachedCollectionData("library");
  const data = cached || (await api("/api/library/items"));
  if (!cached) cacheCollectionData("library", "", data);
  state.album = null;
  state.albumItemsRaw = Array.isArray(data.items) ? data.items : [];
  state.albumItems = sortLibraryAlbumItems();
  state.items = visibleAlbumItems();
  state.busy = "";
}

async function loadFavorites() {
  const data = await api("/api/favorites/items");
  state.album = null;
  state.albumItemsRaw = Array.isArray(data.items) ? data.items : [];
  state.albumItems = sortAlbumItems(state.albumItemsRaw, state.itemSort);
  state.items = visibleAlbumItems();
  state.busy = "";
}

async function loadPhotoWallAlbums() {
  state.wallLibraryKind = normalizeWallLibraryKind(state.wallLibraryKind);
  mosaicWallDataCache.clear();
  mosaicWallDataRequests.clear();
  mosaicWallWarmQueue = [];
  mosaicWallWarmThumbs.clear();
  const data = await api("/api/walls/albums");
  state.photoWallAlbums = Array.isArray(data.photoWall) ? data.photoWall : [];
  state.masonryWallAlbums = Array.isArray(data.masonry) ? data.masonry : [];
  state.filmrollWallAlbums = Array.isArray(data.filmroll) ? data.filmroll : [];
  state.mosaicWallAlbums = Array.isArray(data.mosaic) ? data.mosaic : [];
  state.photoWallAlbumId = null;
  state.masonryWallAlbumId = null;
  state.filmrollWallAlbumId = null;
  state.mosaicWallAlbumId = null;
  state.album = null;
  state.albumItemsRaw = [];
  state.albumItems = [];
  state.items = [];
  state.busy = "";
}

async function openPhotoWallAlbum(albumId) {
  const nextId = Number(albumId);
  setWallLibraryKind("tile");
  const seq = ++photoWallAlbumOpenSeq;
  const request = api(`/api/albums/${nextId}/items?limit=100000`);
  request.catch(() => {});
  const contentExitFade = beginContentExitFade();
  const contentExit = beginAlbumContentExit(nextId);
  let data;
  try {
    data = await request;
  } catch (err) {
    cancelContentExitFade(contentExitFade);
    cancelAlbumContentExit(contentExit);
    alert(err.message);
    return;
  }
  if (seq !== photoWallAlbumOpenSeq) {
    cancelContentExitFade(contentExitFade);
    cancelAlbumContentExit(contentExit);
    return;
  }
  state.photoWallAlbumId = nextId;
  state.masonryWallAlbumId = null;
  state.filmrollWallAlbumId = null;
  state.mosaicWallAlbumId = null;
  state.album = albumById(nextId);
  state.albumItemsRaw = Array.isArray(data.items) ? data.items : [];
  state.albumItems = state.albumItemsRaw.filter(isPhotoWallCandidate);
  state.items = state.albumItems;
  closeMenu();
  if (contentExit) {
    playContentExitFade(contentExitFade);
    render({ chrome: false, holdReveal: true });
    $("#content").scrollTop = 0;
    const dissolved = await finishAlbumContentExit(contentExit);
    if (!dissolved || seq !== photoWallAlbumOpenSeq) {
      cancelContentExitFade(contentExitFade);
      cancelAlbumContentExit(contentExit);
      return;
    }
    cancelAlbumContentExit(contentExit);
    flushPendingUpdate();
    syncToolbarForState();
    return;
  }
  $("#content").scrollTop = 0;
  playContentExitFade(contentExitFade);
  render({ holdReveal: true });
  /* 照片墙资料库里的相簿和普通相簿共用同一段照片入场：先占好格子、
     等首屏缩略图就绪，再按距离错峰落入，不再在读取完成后整片弹出。 */
  revealRightContent();
}

