function closePhotoWallAlbum() {
  closeMasonryCropPopup();
  state.photoWallAlbumId = null;
  state.masonryWallAlbumId = null;
  state.filmrollWallAlbumId = null;
  state.mosaicWallAlbumId = null;
  state.album = null;
  state.albumItemsRaw = [];
  state.albumItems = [];
  state.items = [];
  $("#content").scrollTop = 0;
  render({ holdReveal: true });
  /* 和从别处点击「所有相簿」使用同一段入场：资料库相簿先占位，
     再按首屏距离错峰落下、淡入，而不是在退场后整片直接出现。 */
  revealRightContent();
}

function closeMasonryWallAlbum() {
  closePhotoWallAlbum();
}

function closeFilmrollWallAlbum() {
  closePhotoWallAlbum();
}

function closeMosaicWallAlbum() {
  closePhotoWallAlbum();
}

async function reloadActiveCollection() {
  if (state.activeId === "library") return loadLibrary();
  if (state.activeId === "locations") {
    const keptIds = new Set(state.items.map((item) => Number(item.id)));
    await loadLocationItems({ force: true });
    if (state.locationSubview === "group") {
      state.items = sortedLocationItems().filter((item) =>
        keptIds.has(Number(item.id)),
      );
    } else {
      state.items = sortedLocationItems();
    }
    return;
  }
  if (state.activeId === "favorites") {
    await loadFavorites();
    return navigateFromEmptyFavorites();
  }
  if (state.activeId === "photoWall") return loadPhotoWallAlbums();
  if (state.activeId !== "all" && state.activeId !== "trash") {
    return loadAlbum(state.activeId);
  }
  return false;
}

function updateAlbumItems(mutate, { blurReveal = false } = {}) {
  const update = () => {
    mutate();
    if (state.activeId === "library") {
      state.albumItems = sortLibraryAlbumItems();
    }
    state.items = visibleAlbumItems();
    state.cursor = -1;
    state.cursorVisible = false;
    clearSelection();
    render({ holdReveal: blurReveal });
    $("#content").scrollTop = 0;
    if (blurReveal) revealRightContent();
  };

  if (
    typeof document.startViewTransition === "function" &&
    !blurReveal &&
    !window.matchMedia("(prefers-reduced-motion: reduce)").matches
  ) {
    document.startViewTransition(update);
  } else {
    update();
  }
}

function applyAlbumFilter(kind) {
  if (!ALBUM_FILTERS.some(([value]) => value === kind)) return;
  if (state.filterKind === kind) return;
  updateAlbumItems(() => {
    state.filterKind = kind;
    state.extensionFilter = null;
  });
}

function applyLocationFilter(kind) {
  if (kind !== "all" && !LOCATION_FILTERS.some(([value]) => value === kind)) {
    return;
  }
  if (state.locationFilter === kind) return;
  updateAlbumItems(() => {
    state.locationFilter = kind;
    state.extensionFilter = null;
  });
}

function applyAlbumType(kind) {
  if (!availableAlbumTypes().some(([value]) => value === kind)) return;
  if (state.typeKind === kind) return;
  updateAlbumItems(() => {
    state.typeKind = kind;
    state.extensionFilter = null;
  });
}

function applyAlbumDevice(kind) {
  if (!availableAlbumDevices().some(([value]) => value === kind)) return;
  if (state.deviceKind === kind) return;
  updateAlbumItems(() => {
    state.deviceKind = kind;
    state.extensionFilter = null;
  });
}

function applyExtensionFilter(selected) {
  const choices = availableFileExtensions();
  const allSelected =
    choices.length > 0 && choices.every((key) => selected.has(key));
  updateAlbumItems(() => {
    state.extensionFilter = allSelected ? null : new Set(selected);
  });
}

function applyAlbumSort(kind) {
  if (!ALBUM_SORTS.some(([value]) => value === kind)) return;
  if (state.itemSort === kind) return;
  updateAlbumItems(
    () => {
      state.itemSort = kind;
      persistItemSort(kind);
      state.albumItems = sortAlbumItems(state.albumItemsRaw, kind);
    },
    { blurReveal: true },
  );
}

/* 与 Folia 的 PosterWall / LatticePoster 入场波一致：
   从左上角按格距每格约 30ms 出发，最晚 340ms。
   弹簧参数为 stiffness 360、damping 24；Framer 在这组阈值下的
   位置收尾约 583ms，缩放约 400ms，透明度约 240ms。 */
const ALBUM_PHOTO_REVEAL_MS = 583;
const ALBUM_PHOTO_REVEAL_WAIT_MS = 80;
const PHOTO_WALL_ENTER_MS = 583;
const PHOTO_WALL_STAGGER_MS = 30;
const PHOTO_WALL_MAX_DELAY_MS = 340;
const PHOTO_WALL_SCALE_MS = 400;
const PHOTO_WALL_OPACITY_MS = 240;
const PHOTO_WALL_ENTRANCE_LIFT = 68;
const PHOTO_WALL_EXIT_FADE_MS = 180;

function closePhotoWallFocus({ immediate = false, restoreSource = true } = {}) {
  const focus = photoWallFocus;
  if (!focus) return;
  photoWallFocus = null;
  photoWallFocusSeq += 1;
  const finish = () => {
    focus.layer.remove();
    if (restoreSource && focus.sourceTile?.isConnected) {
      focus.sourceTile.classList.remove("is-wall-focus-source");
    }
    document
      .querySelector(".photo-wall-shell")
      ?.classList.remove("has-photo-wall-focus");
  };
  if (
    immediate ||
    !focus.sourceTile?.isConnected ||
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  ) {
    finish();
    return;
  }
  const main = $(".main");
  const source = focus.sourceTile.getBoundingClientRect();
  const mainRect = main.getBoundingClientRect();
  const current = focus.card.getBoundingClientRect();
  const animation = focus.card.animate(
    [
      {
        left: `${current.left - mainRect.left}px`,
        top: `${current.top - mainRect.top}px`,
        width: `${current.width}px`,
        height: `${current.height}px`,
        borderRadius: "4px",
      },
      {
        left: `${source.left - mainRect.left}px`,
        top: `${source.top - mainRect.top}px`,
        width: `${source.width}px`,
        height: `${source.height}px`,
        borderRadius: "4px",
      },
    ],
    {
      duration: 330,
      easing: "cubic-bezier(0.4, 0, 0.2, 1)",
      fill: "forwards",
    },
  );
  focus.scrim.animate([{ opacity: 1 }, { opacity: 0 }], {
    duration: 220,
    easing: "ease-out",
    fill: "forwards",
  });
  animation.finished.then(finish).catch(finish);
}

function openPhotoWallFocus(index, sourceTile) {
  if (!state.photoWall || !Number.isInteger(index)) return;
  const item = state.items[index];
  const main = $(".main");
  const content = $("#content");
  if (!item || !main || !content) return;
  closePhotoWallFocus({ immediate: true });
  const seq = ++photoWallFocusSeq;
  const mainRect = main.getBoundingClientRect();
  const contentRect = content.getBoundingClientRect();
  const sourceRect = sourceTile.getBoundingClientRect();
  const size = Math.max(
    240,
    Math.min(760, contentRect.width * 0.54, contentRect.height * 0.76),
  );
  const from = {
    x: sourceRect.left - mainRect.left,
    y: sourceRect.top - mainRect.top,
    width: sourceRect.width,
    height: sourceRect.height,
  };
  const to = {
    x: contentRect.left - mainRect.left + (contentRect.width - size) / 2,
    y: contentRect.top - mainRect.top + (contentRect.height - size) / 2,
    width: size,
    height: size,
  };
  const layer = document.createElement("div");
  layer.className = "photo-wall-focus-layer";
  layer.innerHTML = `
    <div class="photo-wall-focus-scrim" data-photo-wall-focus-scrim></div>
    <article class="photo-wall-focus-card" role="dialog" aria-modal="true"
      aria-label="${esc(item.name || "照片")}" style="
        left:${from.x}px;top:${from.y}px;width:${from.width}px;height:${from.height}px">
      <img src="${
        item.kind === "video" ? itemThumbUrl(item, 900, "cover") : fileUrl(item)
      }" alt="" draggable="false">
      <span class="photo-wall-focus-shade" aria-hidden="true"></span>
      <div class="photo-wall-focus-caption">${esc(item.name || "照片")}</div>
      <div class="photo-wall-focus-actions">
        <button type="button" data-photo-wall-focus-open aria-label="打开照片">
          <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.7"
            stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <path d="M7 13 13 7M8 7h5v5"/></svg>
        </button>
      </div>
    </article>`;
  main.append(layer);
  const card = layer.querySelector(".photo-wall-focus-card");
  const scrim = layer.querySelector(".photo-wall-focus-scrim");
  photoWallFocus = { index, sourceTile, layer, card, scrim };
  card.classList.add("is-expanded");
  sourceTile.classList.add("is-wall-focus-source");
  document
    .querySelector(".photo-wall-shell")
    ?.classList.add("has-photo-wall-focus");

  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduced) {
    Object.assign(card.style, {
      left: `${to.x}px`,
      top: `${to.y}px`,
      width: `${to.width}px`,
      height: `${to.height}px`,
    });
  } else {
    scrim.animate([{ opacity: 0 }, { opacity: 1 }], {
      duration: 220,
      easing: "ease-out",
      fill: "both",
    });
    const motion = card.animate(
      [
        {
          left: `${from.x}px`,
          top: `${from.y}px`,
          width: `${from.width}px`,
          height: `${from.height}px`,
          borderRadius: "4px",
        },
        {
          left: `${to.x}px`,
          top: `${to.y}px`,
          width: `${to.width}px`,
          height: `${to.height}px`,
          borderRadius: "4px",
        },
      ],
      {
        duration: 420,
        easing: "cubic-bezier(0.22, 1, 0.36, 1)",
        fill: "forwards",
      },
    );
    motion.finished
      .then(() => {
        if (seq !== photoWallFocusSeq || !card.isConnected) return;
        motion.cancel();
        Object.assign(card.style, {
          left: `${to.x}px`,
          top: `${to.y}px`,
          width: `${to.width}px`,
          height: `${to.height}px`,
        });
      })
      .catch(() => {});
  }

  layer.addEventListener("click", (event) => {
    if (!event.target.closest(".photo-wall-focus-card")) closePhotoWallFocus();
  });
  layer
    .querySelector("[data-photo-wall-focus-open]")
    .addEventListener("click", (event) => {
      event.stopPropagation();
      closePhotoWallFocus({ immediate: true });
      openViewer(index);
    });
}

const PHOTO_WALL_BACKDROP_MS = 520;
const PHOTO_WALL_BACKDROP_RESTORE_DELAY_MS = 100;
/* 子应用会把超大首屏的入场延迟压到 900ms 以内；
   退出倒序沿用同一范围，淡出和缩退同步在 240ms 内完成； */
const PHOTO_WALL_EXIT_MAX_DELAY_MS = 600;
const PHOTO_WALL_EXIT_MOTION_MS = 200;
const PHOTO_WALL_EXIT_BUFFER_MS = 100;
const PHOTO_WALL_EXIT_FALLBACK_MS =
  PHOTO_WALL_EXIT_MAX_DELAY_MS +
  PHOTO_WALL_EXIT_MOTION_MS +
  PHOTO_WALL_EXIT_BUFFER_MS;

function moveNodePreservingState(parent, node, before = null) {
  /* Chromium 的 moveBefore 会保留节点现有渲染状态；remove + append
     则会让已经显示出来的 fixed 按钮重建合成层，退场时闪跳一帧。 */
  if (typeof parent.moveBefore === "function") {
    parent.moveBefore(node, before);
  } else {
    parent.insertBefore(node, before);
  }
}

function detachSidebarRailForPhotoWall() {
  const button = $("#sidebarRailBtn");
  const app = $(".app");
  if (!button || !app || photoWallSidebarRailMarker || !app.contains(button))
    return;
  const marker = document.createComment("photo-wall-sidebar-rail-origin");
  button.before(marker);
  moveNodePreservingState(document.body, button);
  photoWallSidebarRailMarker = marker;
}

function restoreSidebarRailAfterPhotoWall() {
  const marker = photoWallSidebarRailMarker;
  const button = $("#sidebarRailBtn");
  photoWallSidebarRailMarker = null;
  if (!marker?.isConnected) return;
  if (button) moveNodePreservingState(marker.parentNode, button, marker);
  marker.remove();
}

function preparePhotoWallBackdrop() {
  const app = $(".app");
  if (!app || photoWallDomFrozen) return;
  photoWallDomFrozen = true;
  photoWallAppWasInert = app.inert;
  photoWallAppAriaHidden = app.getAttribute("aria-hidden");
  detachSidebarRailForPhotoWall();
  app.inert = true;
  app.setAttribute("aria-hidden", "true");
  document.body.classList.add("photo-wall-active");
  app.classList.add("photo-wall-backdrop-animating");
  /* 先让缩放 / 模糊的起始态生效，再在下一帧落到目标态。 */
  void app.offsetWidth;
  requestAnimationFrame(() => {
    if (photoWallDomFrozen) app.classList.add("photo-wall-backdrop");
  });
}

async function restorePhotoWallBackdrop() {
  const app = $(".app");
  if (!app) return;
  app.classList.add("photo-wall-backdrop-restoring");
  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduced) {
    app.classList.remove("photo-wall-backdrop");
    return;
  }
  /* 先让照片开始反向退场，背景保持原模糊度，再启动清晰化。 */
  await new Promise((resolve) =>
    setTimeout(resolve, PHOTO_WALL_BACKDROP_RESTORE_DELAY_MS),
  );
  void app.offsetWidth;
  app.classList.remove("photo-wall-backdrop");
  await new Promise((resolve) =>
    setTimeout(resolve, PHOTO_WALL_BACKDROP_MS + 30),
  );
}

function releasePhotoWallBackdrop() {
  const app = $(".app");
  if (app) {
    app.classList.remove(
      "photo-wall-backdrop",
      "photo-wall-backdrop-animating",
      "photo-wall-backdrop-restoring",
    );
    app.inert = photoWallAppWasInert;
    if (photoWallAppAriaHidden == null) app.removeAttribute("aria-hidden");
    else app.setAttribute("aria-hidden", photoWallAppAriaHidden);
  }
  document.body.classList.remove("photo-wall-active", "photo-wall-exiting");
  restoreSidebarRailAfterPhotoWall();
  photoWallDomFrozen = false;
  photoWallAppAriaHidden = null;
}

function waitForPhotoWallExitAnimation() {
  if (!photoWallFrame?.contentWindow || !photoWallReady) {
    return Promise.resolve();
  }
  return new Promise((resolve) => {
    let timer = 0;
    const finish = () => {
      clearTimeout(timer);
      if (photoWallExitResolver === finish) photoWallExitResolver = null;
      resolve();
    };
    photoWallExitResolver = finish;
    photoWallFrame.contentWindow.postMessage(
      { type: "photo-wall:exit-animation" },
      window.location.origin,
    );
    timer = setTimeout(
      finish,
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
        ? 0
        : PHOTO_WALL_EXIT_FALLBACK_MS,
    );
  });
}

async function leavePhotoWallMode() {
  /* 子应用已经挂载时，即使状态切换期间 photoWall 标志暂时落回 false，
     也必须完成退场并卸载 iframe，避免留下无法关闭的透明墙层。 */
  if (
    photoWallTransition === "exiting" ||
    (!state.photoWall && !photoWallFrame)
  )
    return;
  clearPhotoWallEnterTimeout();
  clearPhotoWallLoadWatchdog();
  clearPhotoWallPendingEntry();
  hidePhotoWallLoading({ immediate: true });
  photoWallPlaybackOpenSeq += 1;
  document.body.classList.add("photo-wall-exiting");
  photoWallTransition = "exiting";
  photoWallFrame?.classList.add("is-exiting");
  const childExit = waitForPhotoWallExitAnimation();
  const backdropExit = restorePhotoWallBackdrop();
  await childExit;
  unmountPhotoWallApp();
  /* 墙面已经退净，原页面继续以少量模糊停留，再完成最后一段清晰化。 */
  await backdropExit;
  releasePhotoWallBackdrop();
  state.photoWall = false;
  state.photoWallPlayback = null;
  if (photoWallPan) {
    photoWallPan.viewport.classList.remove("is-dragging", "is-moving");
    try {
      photoWallPan.viewport.releasePointerCapture(photoWallPan.pointerId);
    } catch {}
    photoWallPan = null;
  }
  cancelPhotoWallMotion();
  cancelPhotoWallWheel();
  closePhotoWallFocus({ immediate: true });
  photoWallTransition = "idle";
  flushPendingUpdate();
}

function setPhotoWall(enabled) {
  if (!enabled) {
    void leavePhotoWallMode();
    return;
  }
  if (state.photoWall || photoWallTransition !== "idle") return;
  document.body.classList.remove("photo-wall-exiting");
  state.filmstrip = false;
  if (!state.photoWallPlayback) {
    const photos = photoWallCandidates();
    if (!photos.length) {
      clearPhotoWallPendingEntry();
      closeMenu();
      toast("这个相簿里还没有可显示的照片");
      return;
    }
    const album = state.album;
    state.photoWallPlayback = {
      mode: "photos",
      albums: album
        ? [
            {
              id: album.id,
              displayName: albumDisplayName(album),
              photoCount: photos.length,
            },
          ]
        : [],
      photos,
      seed: randomPhotoWallSeed(),
      currentAlbumId: null,
    };
  }

  rememberPhotoWallPendingEntry("wall");
  state.photoWall = true;
  state.edit = false;
  state.select = false;
  clearSelection();
  resetPhotoWallCamera();
  closeMenu({ duration: 0, endScale: 1 });
  $("#popMenu").hidden = true;
  photoWallTransition = "entering";
  photoWallInitRetryAttempted = false;
  showPhotoWallLoading();
  armPhotoWallEnterTimeout();
  armPhotoWallLoadWatchdog();
  preparePhotoWallBackdrop();
  mountPhotoWallApp();
}

function startCurrentPhotoWallAlbumPlayback() {
  const albumId = Number(state.photoWallAlbumId ?? state.activeId);
  if (!Number.isInteger(albumId)) return false;
  const album =
    state.photoWallAlbums.find((entry) => entry.id === albumId) ||
    (state.album?.id === albumId ? state.album : albumById(albumId));
  const photos = photoWallCandidates(
    state.albumItems.length ? state.albumItems : state.items,
  );
  if (!photos.length) {
    closeMenu();
    toast("这个相簿里还没有可显示的照片");
    return false;
  }

  /* 单相簿播放使用的是进入相簿时已经读到的照片，不再请求"全部照片"
     或重新打开播放方式菜单。退出照片墙后仍停留在当前相簿网格。 */
  photoWallPlaybackOpenSeq += 1;
  state.photoWallPlayback = {
    mode: "photos",
    albums: album ? [album] : [],
    photos,
    basePhotos: photos,
    seed: randomPhotoWallSeed(),
    currentAlbumId: null,
  };
  warmMosaicWallThumbnails(photos);
  closeMenu({ duration: 0 });
  setPhotoWall(true);
  return true;
}

function randomPhotoWallSeed() {
  try {
    const words = new Uint32Array(1);
    crypto.getRandomValues(words);
    return words[0] || Date.now();
  } catch {
    return (Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0;
  }
}

async function startCurrentMasonryWall() {
  const libraryMode = state.activeId === "library";
  const album = libraryMode ? null : albumById(state.activeId);
  if (!libraryMode && (!album || kidsOf(album.id).length)) return false;
  let photos = [];
  try {
    photos = album
      ? (await api(`/api/masonry-wall/photos?albums=${album.id}`)).items || []
      : (await api("/api/masonry-wall/photos")).items || [];
    photos = photos.filter((item) => item.kind === "photo");
  } catch (err) {
    closeMenu();
    alert(err.message);
    return false;
  }
  if (!photos.length) {
    closeMenu();
    toast("这个相簿里还没有可显示的照片");
    return false;
  }

  photoWallPlaybackOpenSeq += 1;
  state.photoWallPlayback = {
    wallKind: "masonry",
    mode: "masonry",
    albumId: album?.id ?? null,
    albums: album ? [album] : [],
    photos,
    basePhotos: photos,
    seed: randomPhotoWallSeed(),
    currentAlbumId: null,
  };
  closeMenu({ duration: 0 });
  setPhotoWall(true);
  return true;
}

