/* 新建相簿 / 文件夹的名称输入。用应用自己的居中卡片，文案里的名词跟着
   菜单项变化；输入为空时「存储」保持不可用。 */
let nameDialogOpen = false;
let nameDialogDone = null;
let nameDialogReturnFocus = null;
let nameDialogAnims = [];

function updateNameSubmitState() {
  $("#nameSubmit").disabled = !$("#nameInput").value.trim();
}

function askAlbumName({ title, message, value = "" }) {
  const dialog = $("#nameDialog");
  const card = $("#nameCard");
  const dim = dialog.querySelector(".name-dim");
  const input = $("#nameInput");

  if (nameDialogOpen) closeNameDialog(null);
  nameDialogReturnFocus =
    document.activeElement instanceof HTMLElement
      ? document.activeElement
      : null;
  $("#nameTitle").textContent = title;
  $("#nameMessage").textContent = message;
  input.value = value;
  updateNameSubmitState();
  dialog.hidden = false;
  nameDialogOpen = true;

  nameDialogAnims.forEach((anim) => anim.cancel());
  nameDialogAnims = [
    card.animate(
      [
        { opacity: 0, transform: "scale(0.92)" },
        { opacity: 1, transform: "scale(1.004)", offset: 0.72 },
        { opacity: 1, transform: "scale(1)" },
      ],
      { duration: 190, easing: "cubic-bezier(0.32, 0.72, 0.42, 1)" },
    ),
    dim.animate([{ opacity: 0 }, { opacity: 1 }], {
      duration: 190,
      easing: "ease-out",
    }),
  ];

  requestAnimationFrame(() => {
    if (!nameDialogOpen) return;
    input.focus({ preventScroll: true });
    if (value) input.select();
  });
  return new Promise((resolve) => {
    nameDialogDone = resolve;
  });
}

function askNewAlbumName(kind = "album") {
  const noun = kind === "folder" ? "文件夹" : "相簿";
  return askAlbumName({
    title: `新建${noun}`,
    message: `请为此${noun}输入名称。`,
  });
}

function closeNameDialog(value) {
  if (!nameDialogOpen) return;
  nameDialogOpen = false;
  const card = $("#nameCard");
  const dialog = $("#nameDialog");
  const dim = dialog.querySelector(".name-dim");
  const done = nameDialogDone;
  const back = nameDialogReturnFocus;
  nameDialogDone = null;
  nameDialogReturnFocus = null;

  nameDialogAnims = animateDialogPairOut(card, dim, nameDialogAnims);
  const out = nameDialogAnims[0];
  out.onfinish = () => {
    if (nameDialogOpen) return;
    nameDialogAnims.forEach((anim) => anim.cancel());
    nameDialogAnims = [];
    dialog.hidden = true;
  };

  if (done) done(value);
  if (back && document.contains(back)) back.focus({ preventScroll: true });
}

$("#nameInput").addEventListener("input", updateNameSubmitState);
$("#nameForm").addEventListener("submit", (e) => {
  e.preventDefault();
  const name = $("#nameInput").value.trim();
  if (name) closeNameDialog(name);
});
$("#nameCancel").addEventListener("click", () => closeNameDialog(null));
$("#nameDialog").addEventListener("click", (e) => {
  if (e.target.closest("#nameCard")) return;
  e.stopPropagation();
  closeNameDialog(null);
});

/* 位置信息编辑：只保存到“照片”覆盖层，不写回磁盘原文件。 */
let metadataLocationOpen = false;
let metadataLocationDone = null;
let metadataLocationReturnFocus = null;
let metadataLocationAnims = [];
let metadataLocationItems = [];
let metadataMapRevealed = false;
let metadataMapInitTimer = 0;
let metadataMapConfirming = false;
let metadataLocationReadOnly = false;
let metadataMapMode = "";
let metadataLocationSearchQuery = "";

const metadataMapFrame = $("#metadataLocationMapFrame");

function metadataMapPoints(items) {
  const seen = new Set();
  const points = [];
  for (const item of items) {
    const lat = item?.gps_lat == null ? NaN : Number(item.gps_lat);
    const lon = item?.gps_lon == null ? NaN : Number(item.gps_lon);
    if (
      !Number.isFinite(lat) ||
      !Number.isFinite(lon) ||
      lat < -90 ||
      lat > 90 ||
      lon < -180 ||
      lon > 180
    )
      continue;
    const key = `${lat.toFixed(7)},${lon.toFixed(7)}`;
    if (seen.has(key)) continue;
    seen.add(key);
    points.push({
      lat,
      lon,
      label: String(item?.location_name || "").trim(),
    });
  }
  return points;
}

function metadataMapCoordinateText(lat, lon) {
  const latText = `${Math.abs(lat).toFixed(4)}°${lat < 0 ? "S" : "N"}`;
  const lonText = `${Math.abs(lon).toFixed(4)}°${lon < 0 ? "W" : "E"}`;
  return `${latText}  ${lonText}`;
}

function metadataMapSummary(points) {
  if (points.length === 1) {
    return metadataMapCoordinateText(points[0].lat, points[0].lon);
  }
  if (points.length > 1) return `${points.length} 个不同位置`;
  return "可以搜索或直接点击地图";
}

function postToMetadataMap(message) {
  const target = metadataMapFrame?.contentWindow;
  if (!target) return false;
  target.postMessage(message, window.location.origin);
  return true;
}

function syncMetadataMap(items = metadataLocationItems) {
  const points = metadataMapPoints(items);
  $("#metadataLocationMapCoords").textContent = metadataMapSummary(points);
  postToMetadataMap({
    type: "metadata-map:set-network",
    enabled: mapNetworkEnabled,
  });
  postToMetadataMap({
    type: "metadata-map:set-tile-provider",
    provider: mapTileProvider,
  });
  postToMetadataMap({
    type: "metadata-map:set-location",
    payload: { points },
  });
}

function syncMetadataMapSearch() {
  postToMetadataMap({
    type: "metadata-map:set-search-query",
    query: metadataLocationSearchQuery,
  });
}

function requestMetadataMapStatus() {
  postToMetadataMap({ type: "metadata-map:hello" });
}

function revealMetadataMap() {
  window.clearTimeout(metadataMapInitTimer);
  metadataMapInitTimer = 0;
  metadataMapRevealed = true;
  const card = $("#metadataLocationCard");
  const loading = $("#metadataLocationMapLoading");
  card.classList.remove("has-map-error");
  card.classList.add("has-map-first-frame");
  loading.classList.add("is-settled");
  loading.setAttribute("aria-hidden", "true");
  $("#metadataLocationMapRetry").hidden = true;
}

function failMetadataMap(message = "") {
  window.clearTimeout(metadataMapInitTimer);
  metadataMapInitTimer = 0;
  metadataMapRevealed = false;
  const card = $("#metadataLocationCard");
  const loading = $("#metadataLocationMapLoading");
  card.classList.remove("has-map-first-frame");
  card.classList.add("has-map-error");
  loading.classList.remove("is-settled");
  loading.removeAttribute("aria-hidden");
  $("#metadataLocationMapStatus").textContent = "地图暂时无法显示";
  $("#metadataLocationMapCoords").textContent =
    message || "可以稍后重试，或继续使用离线世界底图";
  $("#metadataLocationMapRetry").hidden = false;
}

function metadataMapSrc(mode, items) {
  const params = new URLSearchParams({
    mode,
    network: mapNetworkEnabled ? "1" : "0",
    provider: mapTileProvider,
  });
  if (mode === "view") {
    const points = metadataMapPoints(items);
    if (points.length === 1) {
      params.set("lat", String(points[0].lat));
      params.set("lon", String(points[0].lon));
    }
  }
  return `/map/index.html?${params.toString()}`;
}

function prepareMetadataMap(items) {
  window.clearTimeout(metadataMapInitTimer);
  const card = $("#metadataLocationCard");
  const loading = $("#metadataLocationMapLoading");
  const points = metadataMapPoints(items);
  $("#metadataLocationMapCoords").textContent = metadataMapSummary(points);
  $("#metadataLocationMapRetry").hidden = true;
  card.classList.remove("has-map-error");
  const nextMode = metadataLocationReadOnly ? "view" : "edit";
  if (metadataMapMode !== nextMode || !metadataMapFrame.getAttribute("src")) {
    metadataMapMode = nextMode;
    metadataMapRevealed = false;
    metadataMapFrame.src = metadataMapSrc(nextMode, items);
  }
  if (metadataMapRevealed) {
    card.classList.add("has-map-first-frame");
    loading.classList.add("is-settled");
    loading.setAttribute("aria-hidden", "true");
  } else {
    card.classList.remove("has-map-first-frame");
    loading.classList.remove("is-settled");
    loading.removeAttribute("aria-hidden");
    $("#metadataLocationMapStatus").textContent = "正在定位";
    metadataMapInitTimer = window.setTimeout(() => {
      failMetadataMap("地图加载时间较长，可以重试或继续使用离线底图");
    }, 4800);
  }

  requestAnimationFrame(() => {
    requestMetadataMapStatus();
    syncMetadataMap(items);
    syncMetadataMapSearch();
  });
}

function retryMetadataMap() {
  metadataMapRevealed = false;
  const card = $("#metadataLocationCard");
  const loading = $("#metadataLocationMapLoading");
  card.classList.remove("has-map-first-frame", "has-map-error");
  loading.classList.remove("is-settled");
  loading.removeAttribute("aria-hidden");
  $("#metadataLocationMapStatus").textContent = "正在定位";
  $("#metadataLocationMapCoords").textContent = metadataMapSummary(
    metadataMapPoints(metadataLocationItems),
  );
  $("#metadataLocationMapRetry").hidden = true;
  metadataMapFrame.src =
    metadataMapSrc(metadataMapMode || "edit", metadataLocationItems) +
    `&retry=${Date.now()}`;
  window.clearTimeout(metadataMapInitTimer);
  metadataMapInitTimer = window.setTimeout(() => {
    failMetadataMap("仍无法载入地图，请稍后重试");
  }, 4800);
}

metadataMapFrame?.addEventListener("load", () => {
  requestMetadataMapStatus();
  if (metadataLocationOpen) {
    syncMetadataMap();
    syncMetadataMapSearch();
  }
});

window.addEventListener("message", (event) => {
  if (
    event.origin !== window.location.origin ||
    event.source !== metadataMapFrame?.contentWindow
  )
    return;
  const message = event.data;
  if (!message || typeof message.type !== "string") return;
  if (message.type === "metadata-map:ready") {
    if (metadataLocationOpen) {
      syncMetadataMap();
      syncMetadataMapSearch();
    }
    return;
  }
  if (message.type === "metadata-map:first-frame") {
    revealMetadataMap();
    return;
  }
  if (message.type === "metadata-map:error") {
    failMetadataMap(String(message.message || "地图载入失败"));
    return;
  }
  if (message.type === "metadata-map:cancel") {
    closeMetadataLocation(null);
    return;
  }
  if (message.type === "metadata-map:confirm") {
    if (metadataLocationReadOnly) return;
    void saveMetadataMapLocation(
      message.lat,
      message.lon,
      message.locationName,
    );
    return;
  }
  if (message.type === "metadata-map:search-query-changed") {
    if (!metadataLocationOpen) return;
    metadataLocationSearchQuery = String(message.query || "").slice(0, 200);
    return;
  }
  if (message.type !== "metadata-map:location-change" || !metadataLocationOpen)
    return;
  const lat = Number(message.lat);
  const lon = Number(message.lon);
  if (
    !Number.isFinite(lat) ||
    !Number.isFinite(lon) ||
    lat < -90 ||
    lat > 90 ||
    lon < -180 ||
    lon > 180
  )
    return;
  $("#metadataLocationMapCoords").textContent = metadataMapCoordinateText(
    lat,
    lon,
  );
});

$("#metadataLocationMapRetry").addEventListener("click", retryMetadataMap);
document.addEventListener(
  "keydown",
  (event) => {
    if (
      event.key !== "Escape" ||
      !metadataLocationOpen ||
      metadataMapConfirming
    )
      return;
    event.preventDefault();
    event.stopPropagation();
    closeMetadataLocation(null);
  },
  true,
);

function askMetadataLocation(items, { readOnly = false } = {}) {
  const dialog = $("#metadataLocationDialog");
  const card = $("#metadataLocationCard");
  const dim = dialog.querySelector(".name-dim");
  const picked = Array.isArray(items) ? items.filter(Boolean) : [];
  const list = picked.filter(
    (item) => item.kind === "photo" || item.kind === "video",
  );
  if (!list.length) {
    toast("没有可调整位置的项目");
    return Promise.resolve(null);
  }
  if (metadataLocationOpen) closeMetadataLocation(null);

  metadataLocationReadOnly = Boolean(readOnly);
  const allVideos = list.every((item) => item.kind === "video");
  const allPhotos = list.every((item) => item.kind === "photo");
  const locationType = allVideos ? "视频" : allPhotos ? "照片" : "项目";
  $("#metadataLocationTitle").textContent = readOnly
    ? `${locationType}位置`
    : list.length > 1
      ? `调整 ${list.length} ${selectionUnit(list)}的位置`
      : `调整${locationType}位置`;
  $("#metadataLocationMessage").textContent = readOnly
    ? "只读查看照片在地图上的位置。"
    : "在地图上选择位置。点击打勾后只保存到“照片”，不会修改磁盘原文件。";
  metadataLocationReturnFocus =
    document.activeElement instanceof HTMLElement
      ? document.activeElement
      : null;
  metadataLocationItems = [...list];
  metadataMapConfirming = false;
  document.documentElement.classList.add("metadata-location-open");
  dialog.hidden = false;
  metadataLocationOpen = true;
  prepareMetadataMap(metadataLocationItems);

  metadataLocationAnims.forEach((anim) => anim.cancel());
  metadataLocationAnims = [
    card.animate(
      [
        { opacity: 0, transform: "scale(0.92)" },
        { opacity: 1, transform: "scale(1.004)", offset: 0.72 },
        { opacity: 1, transform: "scale(1)" },
      ],
      { duration: 190, easing: "cubic-bezier(0.32, 0.72, 0.42, 1)" },
    ),
    dim.animate([{ opacity: 0 }, { opacity: 1 }], {
      duration: 190,
      easing: "ease-out",
    }),
  ];
  requestAnimationFrame(() => {
    if (metadataLocationOpen) {
      metadataMapFrame.focus({ preventScroll: true });
    }
  });
  return new Promise((resolve) => {
    metadataLocationDone = resolve;
  });
}

function closeMetadataLocation(value) {
  if (!metadataLocationOpen) return;
  if (metadataMapConfirming) return;
  metadataLocationOpen = false;
  document.documentElement.classList.remove("metadata-location-open");
  const card = $("#metadataLocationCard");
  const dialog = $("#metadataLocationDialog");
  const dim = dialog.querySelector(".name-dim");
  const done = metadataLocationDone;
  const back = metadataLocationReturnFocus;
  metadataLocationDone = null;
  metadataLocationReturnFocus = null;
  metadataLocationItems = [];
  metadataMapConfirming = false;
  metadataLocationReadOnly = false;
  metadataLocationSearchQuery = "";
  metadataLocationAnims = animateDialogPairOut(
    card,
    dim,
    metadataLocationAnims,
  );
  const out = metadataLocationAnims[0];
  out.onfinish = () => {
    if (metadataLocationOpen) return;
    metadataLocationAnims.forEach((anim) => anim.cancel());
    metadataLocationAnims = [];
    dialog.hidden = true;
  };
  if (done) done(value);
  if (back && document.contains(back)) back.focus({ preventScroll: true });
}

async function saveMetadataMapLocation(rawLat, rawLon, rawLocationName = "") {
  if (
    !metadataLocationOpen ||
    metadataMapConfirming ||
    metadataLocationReadOnly
  )
    return false;
  const lat = Number(rawLat);
  const lon = Number(rawLon);
  if (
    !Number.isFinite(lat) ||
    !Number.isFinite(lon) ||
    lat < -90 ||
    lat > 90 ||
    lon < -180 ||
    lon > 180
  ) {
    postToMetadataMap({ type: "metadata-map:confirm-failed" });
    return false;
  }
  const items = [...metadataLocationItems];
  const ids = [
    ...new Set(
      items
        .map((item) => Number(item.id))
        .filter((id) => Number.isInteger(id) && id > 0),
    ),
  ];
  if (!ids.length) {
    postToMetadataMap({ type: "metadata-map:confirm-failed" });
    return false;
  }

  metadataMapConfirming = true;
  quietUntil = Date.now() + 4000;
  try {
    const res = await api("/api/items/location", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ids,
        lat,
        lon,
        locationName: String(rawLocationName || "")
          .trim()
          .slice(0, 200),
      }),
    });
    applyState(res.state);
    await reloadActiveCollection();
    if (state.select) exitSelection();
    else render();
    for (const id of ids) refreshOpenItemInfo(id);
    try {
      lastRev = (await api("/api/revision")).rev;
    } catch {}
    metadataMapConfirming = false;
    closeMetadataLocation(null);
    const failed = Array.isArray(res.failed) ? res.failed.length : 0;
    toast(
      failed
        ? `已更新 ${ids.length - failed} 张照片位置，${failed} 张失败`
        : "已更新位置",
    );
    return true;
  } catch (err) {
    postToMetadataMap({ type: "metadata-map:confirm-failed" });
    alert(`保存照片位置失败：${err.message}`);
    return false;
  } finally {
    metadataMapConfirming = false;
  }
}

$("#metadataLocationDialog").addEventListener("click", (event) => {
  if (event.target.closest("#metadataLocationCard")) return;
  event.stopPropagation();
  closeMetadataLocation(null);
});

/* 从「＋」菜单里新建软件相簿；只写软件数据，不创建磁盘文件夹。 */
async function createAlbum(kind = "album") {
  const isAll = state.activeId === "all";
  const album = isAll ? null : albumById(state.activeId);
  const root = isAll ? activeRootEntry() : null;
  if (!album && !root) return;
  const name = await askNewAlbumName(kind);
  if (name === null) return;
  try {
    const endpoint = isAll
      ? `/api/roots/${root.id}/create`
      : `/api/albums/${album.id}/create`;
    const res = await api(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, kind }),
    });

    /* 新建会让服务端换封面版本号。先把新版本的封面解码好，再换 DOM，
       否则整页封面会先空一帧，看起来像闪了一下。 */
    const created =
      res.state.albums.find((item) => item.id === Number(res.album?.id)) ||
      res.state.albums.find(
        (item) =>
          item.path.toLowerCase() === String(res.folder || "").toLowerCase(),
      );
    const beforeCards = captureAlbumCardLayout();
    const scrollTop = $("#content").scrollTop;
    await preloadCoverThumbs(res.state);
    await animateEditModeOutForCreate();

    applyState(res.state);
    if (album) await loadAlbum(album.id, { quiet: true });
    state.busy = "";
    state.edit = false;
    /* 这次界面更新已经包含了自己刚建出来的相簿，记下版本号，
       免得两秒后的自动刷新又整页重绘一次。 */
    try {
      lastRev = (await api("/api/revision")).rev;
    } catch {}
    /* 新建文件夹仍然留在当前层；新建相簿则直接进入刚建好的空相簿。 */
    if (kind === "album" && created) {
      if (album) state.expanded.add(album.id);
      await select(String(created.id));
      return;
    }
    render();
    $("#content").scrollTop = scrollTop;
    animateAlbumCardReflow(beforeCards, created?.id);
  } catch (err) {
    alert(err.message);
  } finally {
    state.busy = "";
    renderStatus();
  }
}

let folderPromptBusy = false;
let folderPromptTimer = 0;

/* 自动检测到新磁盘文件夹时只询问一次；导入的是接受时的快照。 */
async function promptFolderImports() {
  if (folderPromptBusy || !state.folderPrompts.length || !state.roots.length)
    return;
  if (askOpen || state.busy) {
    clearTimeout(folderPromptTimer);
    folderPromptTimer = setTimeout(promptFolderImports, 500);
    return;
  }
  folderPromptBusy = true;
  try {
    while (state.folderPrompts.length) {
      const prompt = state.folderPrompts[0];
      const ok = await askConfirm($("#sidebarOptionsBtn"), {
        title: `检测到新文件夹「${prompt.name}」`,
        message: "要把它此刻的内容导入为软件相簿吗？",
        note: "只导入现在的照片；之后放进这个文件夹的新照片会进入“未归档”。选择取消后，本次导入不再询问。",
        actionText: "导入为相簿",
      });
      const action = ok ? "import" : "dismiss";
      const res = await api(`/api/roots/${prompt.rootId}/folders/${action}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: prompt.path }),
      });
      await preloadCoverThumbs(res.state);
      applyState(res.state);
      render();
      lastRev = (await api("/api/revision")).rev;
    }
  } catch (err) {
    toast(err.message);
  } finally {
    folderPromptBusy = false;
  }
}

async function renameAlbumTo(albumId, name) {
  const album = albumById(albumId);
  if (!album) return false;
  const next = String(name || "").trim();
  if (!next) return false;
  if (next === album.name) {
    closeMenu();
    return true;
  }
  try {
    const res = await api(`/api/albums/${albumId}/rename`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: next }),
    });
    await preloadCoverThumbs(res.state);
    applyState(res.state);
    if (state.activeId === albumId) await loadAlbum(albumId);
    /* 行内重命名完成时，菜单停在原地等文件系统写完，普通关闭的 130ms
       快速收尾会显得像突然消失。这里先启动一次更平缓的淡出，再刷新页面；
       render() 随后看到 menuOpen 已是 false，不会再覆盖这段动画。 */
    if (menuOpen && albumSubmenu === "rename") {
      closeMenu({
        duration: 220,
        easing: "cubic-bezier(0.22, 0.72, 0.3, 1)",
        endScale: 0.985,
      });
    }
    state.busy = "";
    render();
    try {
      lastRev = (await api("/api/revision")).rev;
    } catch {}
    return true;
  } catch (err) {
    state.busy = "";
    renderStatus();
    alert(err.message);
    return false;
  }
}

/* 在相簿里点「删除相簿」：原地解散并提升子相簿；
   当前正在看的相簿消失后回到它的上一层。 */
async function deleteCurrentAlbum(albumId) {
  const album = albumById(albumId);
  if (!album) return;
  if (album.isRoot) {
    alert("这是根文件夹本身，不能删除；换文件夹请点「选择文件夹」");
    return;
  }
  const parentId = album.parentId;
  quietUntil = Date.now() + 5000;
  try {
    const res = await api(`/api/albums/${albumId}/trash`, { method: "POST" });
    await preloadCoverThumbs(res.state);
    applyState(res.state);
    state.busy = "";
    try {
      lastRev = (await api("/api/revision")).rev;
    } catch {}
    if (parentId != null) await select(String(parentId));
    else await select("all");
  } catch (err) {
    state.busy = "";
    renderStatus();
    alert(err.message);
  }
}

let libraryPickerOpen = false;
let libraryPickerTargetAlbumId = null;
let libraryPickerMode = "library";
let libraryPickerAlbumId = null;
let libraryPickerItems = [];
let libraryPickerLibraryItems = [];
let libraryPickerLibraryLoaded = false;
let libraryPickerItemsById = new Map();
let libraryPickerSelected = new Set();
let libraryPickerRequest = 0;
let libraryPickerAdding = false;
let libraryPickerCloseTimer = null;
let libraryPickerReturnFocus = null;

function rememberLibraryPickerItems(items) {
  for (const item of items) libraryPickerItemsById.set(item.id, item);
}

function libraryPickerAlbumsAtLevel() {
  const albums =
    libraryPickerAlbumId == null
      ? state.roots.flatMap((root) => topAlbumsOf(root.id))
      : childrenOf(libraryPickerAlbumId);
  return albums.filter(
    (album) =>
      !isUnfiledAlbum(album) && album.id !== libraryPickerTargetAlbumId,
  );
}

function libraryPickerAlbumCardHTML(album) {
  /* 相簿来源沿用主界面的相簿卡片：方形封面在上，名称和数量在下。 */
  const count = album.count || album.childCount;
  return `<div class="album-card library-picker-album-card" role="button"
    tabindex="0" data-library-picker-album="${album.id}">
    <div class="cover-frame">${coverHTML(album, true)}</div>
    <div class="card-meta">
      <div class="card-title">${esc(albumDisplayName(album))}</div>
      ${count ? `<div class="card-count">${count}</div>` : ""}
    </div>
  </div>`;
}

function libraryPickerAlbumPath() {
  const names = [];
  let current =
    libraryPickerAlbumId == null ? null : albumById(libraryPickerAlbumId);
  let guard = 0;
  while (current && guard < 30) {
    names.unshift(albumDisplayName(current));
    current = current.parentId == null ? null : albumById(current.parentId);
    guard += 1;
  }
  return names.join(" / ");
}

function renderLibraryPickerAlbumBrowser() {
  const browser = $("#libraryPickerAlbumBrowser");
  const visible = libraryPickerMode === "album";
  browser.hidden = !visible;
  if (!visible) return;
  const atRoot = libraryPickerAlbumId == null;
  $("#libraryPickerBrowseHead").hidden = atRoot;
  $("#libraryPickerAlbumBack").hidden = atRoot;
  const pathLabel = $("#libraryPickerAlbumPath");
  pathLabel.textContent = libraryPickerAlbumPath();
  pathLabel.hidden = atRoot;
  const albums = libraryPickerAlbumsAtLevel();
  const list = $("#libraryPickerAlbumList");
  list.innerHTML = albums.map(libraryPickerAlbumCardHTML).join("");
  list.hidden = albums.length === 0;
  return albums.length;
}

function syncLibraryPickerModeUI() {
  const libraryName = interfaceDisplayName("library");
  $("#libraryPickerSource").textContent =
    libraryPickerMode === "album" ? "相簿" : libraryName;
  const libraryTab = document.querySelector(
    '[data-library-picker-mode="library"]',
  );
  if (libraryTab) libraryTab.textContent = libraryName;
  for (const tab of document.querySelectorAll("[data-library-picker-mode]")) {
    const current = tab.dataset.libraryPickerMode === libraryPickerMode;
    tab.classList.toggle("is-current", current);
    tab.setAttribute("aria-selected", String(current));
  }
  renderLibraryPickerAlbumBrowser();
}

function libraryPickerItemHTML(item) {
  const selected = libraryPickerSelected.has(item.id);
  const ar = item.width && item.height ? item.width / item.height : 1;
  const coverScale = ar >= 1 ? ar : 1 / ar;
  const label = formatDuration(item.duration);
  const thumb =
    itemThumbUrl(item, 600, "inside") +
    (item.kind === "video" ? "&picker=1" : "");
  const media =
    item.kind === "video"
      ? `<img loading="lazy" src="${thumb}" alt="" draggable="false"
         onload="syncTileAspect(this)"
         onerror="handleGalleryThumbError(this, 'failed-video')">
       ${label ? `<span class="tile-badge">${label}</span>` : ""}`
      : `<img loading="lazy" src="${thumb}" alt="" draggable="false"
         onload="syncTileAspect(this)"
         onerror="handleGalleryThumbError(this)">`;
  return `<div class="tile${item.kind === "video" ? " is-video" : ""}${selected ? " is-selected" : ""}"
    data-library-picker-item="${item.id}" role="checkbox"
    aria-checked="${selected}" aria-label="${esc(item.name || "项目")}"
    tabindex="0" style="--ar:${ar.toFixed(4)};--cs:${coverScale.toFixed(4)}">
    <div class="shot"><span class="crop">${media}</span>
      ${item.favorite ? `<span class="tile-heart">${ICON_FAVORITES}</span>` : ""}
      <span class="tile-check">${ICON_CHECK}</span>
    </div>
  </div>`;
}

function syncLibraryPickerSelection() {
  const count = libraryPickerSelected.size;
  const confirm = $("#libraryPickerConfirm");
  const actions = $("#libraryPickerHeadActions");
  actions.classList.toggle("has-selection", count > 0);
  confirm.disabled = !count || libraryPickerAdding;
  confirm.setAttribute("aria-hidden", String(count === 0));
  for (const tile of document.querySelectorAll("[data-library-picker-item]")) {
    const selected = libraryPickerSelected.has(
      Number(tile.dataset.libraryPickerItem),
    );
    tile.classList.toggle("is-selected", selected);
    tile.setAttribute("aria-checked", String(selected));
  }
}

function renderLibraryPicker() {
  const grid = $("#libraryPickerGrid");
  const message = $("#libraryPickerMessage");
  syncLibraryPickerModeUI();
  if (libraryPickerMode === "album" && libraryPickerAlbumId == null) {
    grid.hidden = true;
    grid.innerHTML = "";
    const albumCount = $("#libraryPickerAlbumList").children.length;
    message.hidden = albumCount > 0;
    message.textContent = albumCount > 0 ? "" : "还没有可选择的相簿";
    syncLibraryPickerSelection();
    return;
  }
  if (!libraryPickerItems.length) {
    grid.hidden = true;
    grid.innerHTML = "";
    message.hidden = false;
    message.textContent =
      libraryPickerMode === "album"
        ? "这个相簿里还没有照片或视频"
        : "图库里还没有照片或视频";
  } else {
    message.hidden = true;
    grid.innerHTML = libraryPickerItems.map(libraryPickerItemHTML).join("");
    grid.hidden = false;
  }
  syncLibraryPickerSelection();
}

function finalizeLibraryPickerClose() {
  if (libraryPickerCloseTimer) {
    clearTimeout(libraryPickerCloseTimer);
    libraryPickerCloseTimer = null;
  }
  const dialog = $("#libraryPicker");
  dialog.hidden = true;
  dialog.classList.remove("is-open", "is-closing");
  $("#libraryPickerHeadActions").classList.remove("has-selection");
  libraryPickerItems = [];
  libraryPickerLibraryItems = [];
  libraryPickerLibraryLoaded = false;
  libraryPickerItemsById = new Map();
  libraryPickerSelected = new Set();
  libraryPickerTargetAlbumId = null;
  libraryPickerMode = "library";
  libraryPickerAlbumId = null;
  const returnFocus = libraryPickerReturnFocus;
  libraryPickerReturnFocus = null;
  if (returnFocus?.isConnected) returnFocus.focus();
}

function closeLibraryPicker(immediate = false) {
  if (!libraryPickerOpen || libraryPickerAdding) return;
  libraryPickerOpen = false;
  libraryPickerRequest += 1;
  const dialog = $("#libraryPicker");
  dialog.classList.remove("is-open");
  dialog.classList.add("is-closing");
  if (immediate) {
    finalizeLibraryPickerClose();
    return;
  }
  libraryPickerCloseTimer = setTimeout(finalizeLibraryPickerClose, 190);
}

async function loadLibraryPickerLibrary(request = ++libraryPickerRequest) {
  const message = $("#libraryPickerMessage");
  const grid = $("#libraryPickerGrid");
  message.textContent = "正在载入图库…";
  message.hidden = false;
  grid.hidden = true;
  grid.innerHTML = "";
  try {
    const data = await api("/api/library/items");
    if (
      !libraryPickerOpen ||
      request !== libraryPickerRequest ||
      libraryPickerMode !== "library"
    )
      return;
    libraryPickerLibraryItems = sortAlbumItems(
      data.items || [],
      state.itemSort,
    );
    libraryPickerLibraryLoaded = true;
    rememberLibraryPickerItems(libraryPickerLibraryItems);
    libraryPickerItems = libraryPickerLibraryItems;
    renderLibraryPicker();
    requestAnimationFrame(() => {
      $("#libraryPickerGrid [data-library-picker-item]")?.focus();
    });
  } catch (err) {
    if (
      !libraryPickerOpen ||
      request !== libraryPickerRequest ||
      libraryPickerMode !== "library"
    )
      return;
    message.hidden = false;
    message.textContent = err.message;
  }
}

function setLibraryPickerMode(mode) {
  if (libraryPickerAdding || (mode !== "library" && mode !== "album")) return;
  if (libraryPickerMode === mode) return;
  libraryPickerMode = mode;
  libraryPickerAlbumId = null;
  libraryPickerItems = [];
  libraryPickerRequest += 1;
  syncLibraryPickerModeUI();
  if (mode === "library" && libraryPickerLibraryLoaded) {
    libraryPickerItems = libraryPickerLibraryItems;
    renderLibraryPicker();
    return;
  }
  if (mode === "library") {
    void loadLibraryPickerLibrary();
    return;
  }
  renderLibraryPicker();
}

async function openLibraryPickerAlbum(albumId) {
  const album = albumById(albumId);
  if (!album || libraryPickerAdding) return;
  const request = ++libraryPickerRequest;
  libraryPickerMode = "album";
  libraryPickerAlbumId = album.id;
  libraryPickerItems = [];
  syncLibraryPickerModeUI();
  const grid = $("#libraryPickerGrid");
  const message = $("#libraryPickerMessage");
  grid.hidden = true;
  grid.innerHTML = "";
  message.hidden = false;
  message.textContent = "正在载入相簿…";
  try {
    const data = await api(`/api/albums/${album.id}/items?limit=100000`);
    if (
      !libraryPickerOpen ||
      request !== libraryPickerRequest ||
      libraryPickerMode !== "album" ||
      libraryPickerAlbumId !== album.id
    )
      return;
    libraryPickerItems = sortAlbumItems(data.items || [], state.itemSort);
    rememberLibraryPickerItems(libraryPickerItems);
    renderLibraryPicker();
    requestAnimationFrame(() => {
      $("#libraryPickerGrid [data-library-picker-item]")?.focus();
    });
  } catch (err) {
    if (
      !libraryPickerOpen ||
      request !== libraryPickerRequest ||
      libraryPickerMode !== "album" ||
      libraryPickerAlbumId !== album.id
    )
      return;
    message.hidden = false;
    message.textContent = err.message;
  }
}

function leaveLibraryPickerAlbum() {
  const album =
    libraryPickerAlbumId == null ? null : albumById(libraryPickerAlbumId);
  if (album?.parentId != null) {
    void openLibraryPickerAlbum(album.parentId);
    return;
  }
  libraryPickerRequest += 1;
  libraryPickerAlbumId = null;
  libraryPickerItems = [];
  renderLibraryPicker();
}

async function openLibraryPicker(albumId) {
  const album = albumById(albumId);
  if (!album || libraryPickerOpen) return;
  libraryPickerOpen = true;
  libraryPickerAdding = false;
  libraryPickerTargetAlbumId = album.id;
  libraryPickerMode = "library";
  libraryPickerAlbumId = null;
  libraryPickerItems = [];
  libraryPickerLibraryItems = [];
  libraryPickerLibraryLoaded = false;
  libraryPickerItemsById = new Map();
  libraryPickerSelected = new Set();
  libraryPickerReturnFocus = document.activeElement;
  const request = ++libraryPickerRequest;
  const dialog = $("#libraryPicker");
  if (libraryPickerCloseTimer) {
    clearTimeout(libraryPickerCloseTimer);
    libraryPickerCloseTimer = null;
  }
  $("#libraryPickerConfirm").disabled = true;
  $("#libraryPickerConfirm").setAttribute("aria-hidden", "true");
  $("#libraryPickerHeadActions").classList.remove("has-selection");
  syncLibraryPickerModeUI();
  dialog.hidden = false;
  dialog.classList.remove("is-closing");
  requestAnimationFrame(() => {
    if (libraryPickerOpen && request === libraryPickerRequest) {
      dialog.classList.add("is-open");
    }
  });
  $("#libraryPickerClose").focus();
  void loadLibraryPickerLibrary(request);
}

function toggleLibraryPickerItem(itemId, tile) {
  if (libraryPickerAdding) return;
  if (libraryPickerSelected.has(itemId)) libraryPickerSelected.delete(itemId);
  else libraryPickerSelected.add(itemId);
  tile.classList.toggle("is-selected", libraryPickerSelected.has(itemId));
  tile.setAttribute("aria-checked", String(libraryPickerSelected.has(itemId)));
  syncLibraryPickerSelection();
}

async function addLibraryPickerSelection() {
  if (libraryPickerAdding || !libraryPickerSelected.size) return;
  const albumId = libraryPickerTargetAlbumId;
  const album = albumById(albumId);
  const ids = [...libraryPickerSelected];
  if (!album || !ids.length) return;
  libraryPickerAdding = true;
  syncLibraryPickerSelection();
  try {
    const beforeAlbums = state.albums;
    const actionIds = itemActionIds(
      ids.map((id) => libraryPickerItemsById.get(id)).filter(Boolean),
    );
    const res = await api("/api/items/add-to-album", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ids: actionIds, albumId }),
    });
    applyState(res.state);
    invalidateCollectionData("album", albumId);
    await loadAlbum(albumId);
    await preloadChangedCoverThumbs(beforeAlbums, res.state);
    libraryPickerAdding = false;
    closeLibraryPicker(true);
    render({ holdReveal: true });
    revealRightContent();
    lastRev = (await api("/api/revision")).rev;
    flushPendingUpdate();
    const added = res.result?.added || 0;
    const skipped = res.result?.skipped || 0;
    toast(
      added
        ? `已添加到「${album.name}」${added} 个项目${skipped ? `，${skipped} 项已存在` : ""}`
        : "这些项目已经在相簿里",
    );
  } catch (err) {
    libraryPickerAdding = false;
    syncLibraryPickerSelection();
    alert(err.message);
  }
}

$("#libraryPickerGrid").addEventListener("click", (event) => {
  const tile = event.target.closest("[data-library-picker-item]");
  if (!tile) return;
  toggleLibraryPickerItem(Number(tile.dataset.libraryPickerItem), tile);
});
$("#libraryPickerGrid").addEventListener("keydown", (event) => {
  if (event.key !== "Enter" && event.key !== " ") return;
  const tile = event.target.closest("[data-library-picker-item]");
  if (!tile) return;
  event.preventDefault();
  toggleLibraryPickerItem(Number(tile.dataset.libraryPickerItem), tile);
});
for (const tab of document.querySelectorAll("[data-library-picker-mode]")) {
  tab.addEventListener("click", () => {
    setLibraryPickerMode(tab.dataset.libraryPickerMode);
  });
}
$("#libraryPickerAlbumList").addEventListener("click", (event) => {
  const card = event.target.closest("[data-library-picker-album]");
  if (!card) return;
  void openLibraryPickerAlbum(Number(card.dataset.libraryPickerAlbum));
});
$("#libraryPickerAlbumList").addEventListener("keydown", (event) => {
  if (event.key !== "Enter" && event.key !== " ") return;
  const card = event.target.closest("[data-library-picker-album]");
  if (!card) return;
  event.preventDefault();
  void openLibraryPickerAlbum(Number(card.dataset.libraryPickerAlbum));
});
$("#libraryPickerAlbumBack").addEventListener("click", leaveLibraryPickerAlbum);
$("#libraryPickerDim").addEventListener("click", () => closeLibraryPicker());
$("#libraryPickerClose").addEventListener("click", () => closeLibraryPicker());
$("#libraryPickerConfirm").addEventListener("click", addLibraryPickerSelection);

$("#createBtn").addEventListener("click", (e) => {
  e.stopPropagation();
  toggleMenu($("#createBtn"), "create", { focusFirst: e.detail === 0 });
});

async function trashAlbum(albumId) {
  const album = albumById(albumId);
  if (!album) return;
  /* 直接删除时先把被删这张的摆动停下来。真正离场要等新状态和封面都准备好，
     避免删失败后闪一下。 */
  markAlbumDeleting(albumId);
  /* 删除过程保持静默：不弹底部「正在删除…」，避免内容区高度先缩再长。 */
  quietUntil = Date.now() + 5000;
  /* 网络请求回来之前先记下每张相簿的位置。重绘后留下来的相簿
     从旧位置滑到新槽位，与删除照片后的连续补位一致。 */
  const beforeCards = captureAlbumCardLayout();
  const beforeSidebar = captureSidebarAlbumLayout();
  const beforeAlbums = state.albums;
  const scrollTop = $("#content").scrollTop;
  const sidebarScrollTop = $("#sidebarList").scrollTop;
  beginAlbumDeletePreview(albumId);
  try {
    const res = await api(`/api/albums/${albumId}/trash`, { method: "POST" });
    /* 删除会让服务端换封面版本号。先把新版本封面解码好，再换 DOM，
       否则卡片会先空一帧再出现，看起来像闪了一下。 */
    await preloadChangedCoverThumbs(beforeAlbums, res.state);
    applyState(res.state);
    if (state.activeId !== "all") await loadAlbum(state.activeId);
    state.busy = "";
    const exitTargets = detachAlbumDeleteTargets(albumId);
    render();
    $("#content").scrollTop = scrollTop;
    $("#sidebarList").scrollTop = sidebarScrollTop;
    animateAlbumCardReflow(beforeCards);
    animateSidebarReflow(beforeSidebar, SIDEBAR_REFLOW_MS);
    animateAlbumDeleteTargets(exitTargets);
    albumDeletePreviews.delete(albumId);
    /* 这次重绘已经包含删除后的状态，记下版本号，免得轮询再整页刷一次。 */
    try {
      lastRev = (await api("/api/revision")).rev;
    } catch {}
  } catch (err) {
    clearAlbumDeleting(albumId);
    state.busy = "";
    renderStatus();
    alert(err.message);
  }
}

/* 「未归档」的红减号：它没有独立文件夹，实际是把根目录和带子目录的
   父目录中所有未归档移到最近删除，保留各层相簿与子相簿。 */
async function trashUnfiledAlbum(albumId) {
  const album = albumById(albumId);
  if (!isUnfiledAlbum(album)) return;
  markAlbumDeleting(albumId);
  quietUntil = Date.now() + 5000;
  const beforeCards = captureAlbumCardLayout();
  const beforeSidebar = captureSidebarAlbumLayout();
  const beforeAlbums = state.albums;
  const scrollTop = $("#content").scrollTop;
  const sidebarScrollTop = $("#sidebarList").scrollTop;
  beginAlbumDeletePreview(albumId);
  try {
    const data = await api(`/api/albums/${albumId}/items?limit=100000`);
    const ids = itemActionIds(data.items || []);
    if (!ids.length) {
      clearAlbumDeleting(albumId);
      return;
    }
    const res = await api("/api/items/trash", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ids }),
    });
    await preloadChangedCoverThumbs(beforeAlbums, res.state);
    applyState(res.state);
    if (state.activeId === albumId) fallbackToAllAlbums();
    state.busy = "";
    const exitTargets = detachAlbumDeleteTargets(albumId);
    render();
    $("#content").scrollTop = scrollTop;
    $("#sidebarList").scrollTop = sidebarScrollTop;
    animateAlbumCardReflow(beforeCards);
    animateSidebarReflow(beforeSidebar, SIDEBAR_REFLOW_MS);
    animateAlbumDeleteTargets(exitTargets);
    albumDeletePreviews.delete(albumId);
    try {
      lastRev = (await api("/api/revision")).rev;
    } catch {}
  } catch (err) {
    clearAlbumDeleting(albumId);
    state.busy = "";
    renderStatus();
    alert(err.message);
  }
}

let sidebarRailCollapsed = false;
let railMotion = null;
let railLayoutCache = null;
let railRememberedHoverId = null;
let sidebarHoverPeekOpen = false;
let sidebarHoverPeekSuppressed = false;
let sidebarHoverOpenTimer = 0;
let sidebarHoverCloseTimer = 0;
let sidebarHoverPointerFrame = 0;
let sidebarHoverPointerX = Number.NaN;
let sidebarHoverPointerY = Number.NaN;

const SIDEBAR_HOVER_OPEN_DELAY_MS = 150;
const SIDEBAR_HOVER_CLOSE_DELAY_MS = 250;
const SIDEBAR_MAP_HOVER_SAFE_ZONE_WIDTH = 96;
const SIDEBAR_MAP_HOVER_SAFE_ZONE_BOTTOM = 112;

function photoWallLibraryRailIsLocked() {
  return (
    state.activeId === "photoWall" &&
    !state.photoWall &&
    !state.photoWallAlbumId &&
    !state.masonryWallAlbumId &&
    !state.filmrollWallAlbumId &&
    !state.mosaicWallAlbumId
  );
}

function syncSidebarRailButtonState() {
  const button = $("#sidebarRailBtn");
  if (!button) return;
  const locked = photoWallLibraryRailIsLocked();
  const hoverModeDisabled = hoverExpandSidebar;
  button.disabled = locked;
  button.classList.toggle("is-context-disabled", locked || hoverModeDisabled);
  button.setAttribute("aria-disabled", String(locked || hoverModeDisabled));
  if (locked) {
    button.setAttribute("aria-label", "照片墙页面中不能收起相簿栏");
    return;
  }
  const collapsed = $("#sidebar").classList.contains("is-rail-collapsed");
  button.setAttribute(
    "aria-expanded",
    String(!collapsed || sidebarHoverPeekOpen),
  );
  if (hoverModeDisabled) {
    button.setAttribute(
      "aria-label",
      "相簿栏由鼠标靠近展开，或使用键盘聚焦左侧感应区展开",
    );
    return;
  }
  button.setAttribute(
    "aria-label",
    sidebarHoverPeekOpen
      ? "固定展开相簿栏"
      : collapsed
        ? "展开相簿栏"
        : "收起相簿栏",
  );
}

function syncSidebarRailInteractionState() {
  const sidebar = $("#sidebar");
  const button = $("#sidebarRailBtn");
  const list = $("#sidebarList");
  const foot = sidebar.querySelector(".sidebar-foot");
  const actions = document.getElementById("headActions");
  const title = $("#sidebarTitle");
  const back = $("#backBtn");
  const exposed = !sidebarRailCollapsed || sidebarHoverPeekOpen;
  list.inert = !exposed;
  foot.inert = !exposed;
  const actionsCollapsed =
    sidebarRailCollapsed &&
    !sidebarHoverPeekOpen &&
    actions?.parentElement === sidebar.querySelector(".sidebar-head");
  if (actions) actions.inert = actionsCollapsed;
  list.setAttribute("aria-hidden", String(!exposed));
  foot.setAttribute("aria-hidden", String(!exposed));
  actions?.setAttribute("aria-hidden", String(actionsCollapsed));
  title.setAttribute("aria-hidden", String(!exposed));
  /* 主内容里的返回键与浮层不属于同一交互层：浮层展开时它仍保持收起态。 */
  back.inert = sidebarRailCollapsed;
  back.setAttribute("aria-hidden", String(sidebarRailCollapsed));
  button.setAttribute(
    "aria-hidden",
    String(hoverExpandSidebar && sidebarRailCollapsed && !sidebarHoverPeekOpen),
  );
  syncSidebarRailButtonState();
}

function sidebarHoverPeekFocusInside() {
  const sidebar = $("#sidebar");
  const button = $("#sidebarRailBtn");
  const edge = $("#sidebarHoverEdge");
  const active = document.activeElement;
  return Boolean(
    active &&
    (active === button ||
      active === edge ||
      sidebar.contains(active) ||
      button?.contains(active)),
  );
}

function sidebarHoverPeekSettingsOpen() {
  return menuOpen && menuKind === "settings";
}

function sidebarHoverPointerInMapSafeZone(x, y) {
  return (
    document.documentElement.classList.contains(
      "locations-map-titlebar-hidden",
    ) &&
    sidebarRailCollapsed &&
    Number.isFinite(x) &&
    Number.isFinite(y) &&
    x >= 0 &&
    x <= SIDEBAR_MAP_HOVER_SAFE_ZONE_WIDTH &&
    y >= 0 &&
    y < SIDEBAR_MAP_HOVER_SAFE_ZONE_BOTTOM
  );
}

function sidebarHoverPeekPointerNear(
  x = sidebarHoverPointerX,
  y = sidebarHoverPointerY,
) {
  if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
  if (sidebarHoverPointerInMapSafeZone(x, y)) return false;
  if (x <= 40) return true;
  const button = $("#sidebarRailBtn");
  if (button) {
    const rect = button.getBoundingClientRect();
    if (
      x >= rect.left - 5 &&
      x <= rect.right + 5 &&
      y >= rect.top - 5 &&
      y <= rect.bottom + 5
    ) {
      return true;
    }
  }
  if (!sidebarHoverPeekOpen) return false;
  const sidebar = $("#sidebar").getBoundingClientRect();
  return (
    x >= sidebar.left &&
    x <= sidebar.right &&
    y >= sidebar.top &&
    y <= sidebar.bottom
  );
}

function sidebarHoverPeekInteractionAllowed() {
  return (
    hoverExpandSidebar &&
    sidebarRailCollapsed &&
    !askOpen &&
    !pickerOpen &&
    !nameDialogOpen &&
    !metadataLocationOpen &&
    !photoEditorOpen &&
    !contextMenuOpen &&
    $("#viewer")?.hidden !== false
  );
}

function clearSidebarHoverPeekTimers() {
  window.clearTimeout(sidebarHoverOpenTimer);
  window.clearTimeout(sidebarHoverCloseTimer);
  sidebarHoverOpenTimer = 0;
  sidebarHoverCloseTimer = 0;
}

function openSidebarHoverPeek() {
  clearSidebarHoverPeekTimers();
  if (!sidebarHoverPeekInteractionAllowed()) return false;
  const sidebar = $("#sidebar");
  sidebarHoverPeekOpen = true;
  document.documentElement.classList.add("sidebar-hover-peek-open");
  sidebar.classList.add("is-rail-hover-peek-ready", "is-rail-hover-peek-open");
  syncSidebarRailInteractionState();
  syncSidebarHoverPeekMode();
  return true;
}

function closeSidebarHoverPeek({ immediate = false } = {}) {
  clearSidebarHoverPeekTimers();
  if (!sidebarHoverPeekOpen) return;
  sidebarHoverPeekOpen = false;
  document.documentElement.classList.remove("sidebar-hover-peek-open");
  $("#sidebar").classList.remove("is-rail-hover-peek-open");
  syncSidebarRailInteractionState();
  if (immediate) $("#sidebar").classList.remove("is-rail-hover-peek-ready");
}

function scheduleSidebarHoverPeekOpen() {
  if (
    sidebarHoverOpenTimer ||
    sidebarHoverPeekOpen ||
    sidebarHoverPeekSuppressed ||
    !sidebarHoverPeekInteractionAllowed()
  ) {
    return;
  }
  window.clearTimeout(sidebarHoverCloseTimer);
  sidebarHoverCloseTimer = 0;
  sidebarHoverOpenTimer = window.setTimeout(() => {
    sidebarHoverOpenTimer = 0;
    if (sidebarHoverPeekPointerNear() || sidebarHoverPeekFocusInside()) {
      openSidebarHoverPeek();
    }
  }, SIDEBAR_HOVER_OPEN_DELAY_MS);
}

function scheduleSidebarHoverPeekClose() {
  window.clearTimeout(sidebarHoverOpenTimer);
  sidebarHoverOpenTimer = 0;
  if (!sidebarHoverPeekOpen || sidebarHoverCloseTimer) return;
  sidebarHoverCloseTimer = window.setTimeout(() => {
    sidebarHoverCloseTimer = 0;
    if (
      sidebarHoverPeekSettingsOpen() ||
      sidebarHoverPeekFocusInside() ||
      sidebarHoverPeekPointerNear() ||
      !sidebarHoverPeekInteractionAllowed()
    ) {
      return;
    }
    closeSidebarHoverPeek();
  }, SIDEBAR_HOVER_CLOSE_DELAY_MS);
}

function syncSidebarHoverPeekMode() {
  const sidebar = $("#sidebar");
  const edge = $("#sidebarHoverEdge");
  const ready =
    hoverExpandSidebar &&
    sidebarRailCollapsed;
  if (!ready) closeSidebarHoverPeek({ immediate: true });
  document.documentElement.classList.toggle(
    "sidebar-hover-peek-open",
    ready && sidebarHoverPeekOpen,
  );
  sidebar.classList.toggle("is-rail-hover-peek-ready", ready);
  edge?.classList.toggle(
    "is-disabled",
    !ready || !sidebarHoverPeekInteractionAllowed(),
  );
  if (edge) {
    edge.tabIndex = ready ? 0 : -1;
    edge.setAttribute("aria-hidden", String(!ready));
    edge.setAttribute(
      "aria-label",
      sidebarHoverPeekOpen ? "相簿栏已展开" : "展开相簿栏",
    );
  }
  syncSidebarRailButtonState();
}

function applySidebarRailHoverMemory() {
  document
    .querySelectorAll(
      "#sidebarList .nav-item.rail-hover-memory, #trashNavBtn.rail-hover-memory",
    )
    .forEach((row) => row.classList.remove("rail-hover-memory"));
  if (railRememberedHoverId == null) return;
  if (railRememberedHoverId === "trash") {
    $("#trashNavBtn").classList.add("rail-hover-memory");
    return;
  }
  document
    .querySelector(
      `#sidebarList .nav-item[data-id="${String(railRememberedHoverId)}"]`,
    )
    ?.classList.add("rail-hover-memory");
}

$("#sidebarList").addEventListener(
  "pointermove",
  (event) => {
    const row =
      event.target instanceof Element
        ? event.target.closest(".nav-item[data-id]")
        : null;
    const nextId = row?.dataset.id ?? null;
    if (nextId === railRememberedHoverId) return;
    railRememberedHoverId = nextId;
    applySidebarRailHoverMemory();
  },
  { passive: true },
);
$("#trashNavBtn").addEventListener(
  "pointermove",
  () => {
    if (railRememberedHoverId === "trash") return;
    railRememberedHoverId = "trash";
    applySidebarRailHoverMemory();
  },
  { passive: true },
);
const RAIL_GRID_SELECTOR = "#content .album-grid, #content .photo-grid";
const RAIL_ITEM_SELECTOR = "#content .album-grid > *, #content .photo-grid > *";
const RAIL_ITEM_MARGIN = 320;

function captureContentLayout() {
  const map = new Map();
  const margin = 240;
  for (const el of document.querySelectorAll(
    "#content .album-card, #content .tile[data-index]",
  )) {
    const r = el.getBoundingClientRect();
    if (r.bottom < -margin || r.top > window.innerHeight + margin) continue;
    const key = el.dataset.album
      ? `album:${el.dataset.album}`
      : `tile:${el.dataset.index}`;
    map.set(key, {
      left: r.left,
      top: r.top,
      width: r.width,
      height: r.height,
    });
  }
  return map;
}

function animateContentReflow(before, duration = 280) {
  if (
    !before.size ||
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  )
    return;
  const margin = 240;
  for (const el of document.querySelectorAll(
    "#content .album-card, #content .tile[data-index]",
  )) {
    const key = el.dataset.album
      ? `album:${el.dataset.album}`
      : `tile:${el.dataset.index}`;
    const old = before.get(key);
    if (!old) continue;
    const now = el.getBoundingClientRect();
    if (now.bottom < -margin || now.top > window.innerHeight + margin) continue;
    const dx = old.left - now.left;
    const dy = old.top - now.top;
    const sx = old.width / now.width;
    const sy = old.height / now.height;
    if (
      Math.abs(dx) < 0.5 &&
      Math.abs(dy) < 0.5 &&
      Math.abs(sx - 1) < 0.002 &&
      Math.abs(sy - 1) < 0.002
    )
      continue;
    el.animate(
      [
        {
          transform: `translate3d(${dx}px, ${dy}px, 0) scale(${sx}, ${sy})`,
          transformOrigin: "top left",
        },
        {
          transform: "translate3d(0, 0, 0) scale(1, 1)",
          transformOrigin: "top left",
        },
      ],
      {
        duration,
        easing: "cubic-bezier(0.22, 0.72, 0.24, 1)",
      },
    );
  }
}

function railItemKey(el, fallbackIndex) {
  if (el.dataset.album != null) return `album:${el.dataset.album}`;
  if (el.dataset.index != null) return `tile:${el.dataset.index}`;
  if (el.dataset.trashAlbum != null)
    return `trash-album:${el.dataset.trashAlbum}`;
  return `grid-item:${fallbackIndex}`;
}

function captureRailItems() {
  const items = new Map();
  const content = $("#content");
  const contentRect = content.getBoundingClientRect();
  const contentPaddingLeft =
    Number.parseFloat(getComputedStyle(content).paddingLeft) || 0;
  let fallbackIndex = 0;
  for (const el of document.querySelectorAll(RAIL_ITEM_SELECTOR)) {
    const key = railItemKey(el, fallbackIndex++);
    const rect = el.getBoundingClientRect();
    if (
      rect.bottom < -RAIL_ITEM_MARGIN ||
      rect.top > window.innerHeight + RAIL_ITEM_MARGIN
    ) {
      continue;
    }
    items.set(key, {
      el,
      left: rect.left,
      top: rect.top,
      width: rect.width,
      height: rect.height,
    });
  }
  return {
    items,
    contentLeft: contentRect.left,
    contentTop: contentRect.top,
    contentOriginLeft: contentRect.left + contentPaddingLeft,
  };
}

/* 先量出栏体到位后的最终网格。量完马上恢复，真正可见的仍从原位置起步。 */
function measureRailTarget(collapsed) {
  const sidebar = $("#sidebar");
  const wasCollapsed = sidebar.classList.contains("is-rail-collapsed");
  sidebar.classList.add("is-rail-measuring");
  sidebar.classList.toggle("is-rail-collapsed", collapsed);
  void sidebar.offsetWidth;
  /* 等高成行 / 等宽成列的照片是绝对定位，不会像相册卡片那样
     随 CSS Grid 自动重排。这里必须先把两端的成列坐标都算好，
     否则收起动画只拿到了旧坐标；随后 ResizeObserver 会在栏体
     移动的每一帧改写照片尺寸，看起来就是部分照片在闪。 */
  syncAlbumGridSpacing();
  applyPhotoGridLayouts({ preserveViewport: false });
  const target = captureRailItems();
  sidebar.classList.toggle("is-rail-collapsed", wasCollapsed);
  void sidebar.offsetWidth;
  syncAlbumGridSpacing();
  applyPhotoGridLayouts({ preserveViewport: false });
  sidebar.classList.remove("is-rail-measuring");
  return target;
}

/* 动画期间把网格钉在当前槽位。内容区左缘仍跟相簿栏一起移动，
   卡片在网格内部则一次性飞向已经量好的最终槽位。 */
function freezeRailGrids() {
  const grids = [];
  for (const grid of document.querySelectorAll(RAIL_GRID_SELECTOR)) {
    const style = getComputedStyle(grid);
    if (!style.gridTemplateColumns || style.gridTemplateColumns === "none")
      continue;
    grids.push({
      grid,
      template: grid.style.gridTemplateColumns,
      justify: grid.style.justifyContent,
      columnGap: grid.style.columnGap,
      rowGap: grid.style.rowGap,
    });
    grid.style.gridTemplateColumns = style.gridTemplateColumns;
    grid.style.justifyContent = "start";
    grid.style.columnGap = style.columnGap;
    grid.style.rowGap = style.rowGap;
  }
  return grids;
}

function restoreRailGrids(grids) {
  for (const grid of grids) {
    if (!grid.grid.isConnected) continue;
    grid.grid.style.gridTemplateColumns = grid.template;
    grid.grid.style.justifyContent = grid.justify;
    grid.grid.style.columnGap = grid.columnGap;
    grid.grid.style.rowGap = grid.rowGap;
  }
}

function animateRailItems(start, base, target, duration) {
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return [];
  const animations = [];
  const contentDx = target.contentOriginLeft - base.contentOriginLeft;
  const contentDy = target.contentTop - base.contentTop;

  for (const [key, from] of start.items) {
    const pinned = base.items.get(key);
    const to = target.items.get(key);
    if (!pinned || !to || !from.el.isConnected || pinned.el !== from.el)
      continue;

    const fromX = from.left - pinned.left;
    const fromY = from.top - pinned.top;
    const toX = to.left - (pinned.left + contentDx);
    const toY = to.top - (pinned.top + contentDy);
    const fromScaleX = pinned.width ? from.width / pinned.width : 1;
    const fromScaleY = pinned.height ? from.height / pinned.height : 1;
    const toScaleX = pinned.width ? to.width / pinned.width : 1;
    const toScaleY = pinned.height ? to.height / pinned.height : 1;

    if (
      Math.max(
        Math.abs(fromX - toX),
        Math.abs(fromY - toY),
        Math.abs(fromScaleX - toScaleX),
        Math.abs(fromScaleY - toScaleY),
      ) < 0.002
    ) {
      continue;
    }

    /* 与「所有相簿」的树展开 / 收回共用同一条慢快慢曲线。 */
    const animation = pinned.el.animate(
      [
        {
          translate: `${fromX}px ${fromY}px`,
          scale: `${fromScaleX} ${fromScaleY}`,
          transformOrigin: "top left",
        },
        {
          translate: `${toX}px ${toY}px`,
          scale: `${toScaleX} ${toScaleY}`,
          transformOrigin: "top left",
        },
      ],
      {
        duration,
        easing: NAV_EASE,
        fill: "both",
      },
    );
    animations.push(animation);
  }
  return animations;
}

function finishRailMotion({ settlePhotoGrid = true } = {}) {
  if (!railMotion) return;
  const motion = railMotion;
  railMotion = null;
  clearTimeout(motion.timer);
  for (const animation of motion.animations) animation.cancel();
  restoreRailGrids(motion.grids);
  if (photoGridLayoutFrame) {
    cancelAnimationFrame(photoGridLayoutFrame);
    photoGridLayoutFrame = 0;
  }
  photoGridLayoutSuspended = false;
  albumGridSpacingSuspended = false;
  syncAlbumGridSpacing();
  if (settlePhotoGrid) {
    applyPhotoGridLayouts({ preserveViewport: false });
    photoGridLastWidth = photoLayoutGrids()[0]?.clientWidth ?? -1;
    const content = $("#content");
    if (content) content.scrollTop = motion.scrollTop;
  }
  document.documentElement.classList.remove("sidebar-rail-motion-active");
}

/* 整个相簿栏向左收到只剩切换图标；列表、标题和底栏一起淡出。
   栏体宽度负责推 / 拉，主内容区自然补上腾出来的空间。 */
function setSidebarRailCollapsed(collapsed, { animate = true } = {}) {
  const sidebar = $("#sidebar");
  const initialContentScrollTop = $("#content").scrollTop;
  document.documentElement.classList.remove("sidebar-rail-motion-active");
  const reducedMotion =
    !animate || window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (!collapsed) {
    clearSidebarHoverPeekTimers();
    sidebarHoverPeekOpen = false;
    sidebar.classList.remove(
      "is-rail-hover-peek-open",
      "is-rail-hover-peek-ready",
    );
  }
  if (collapsed) sidebarHoverPeekSuppressed = true;
  const syncMapRailStates = (motion = false) => {
    syncLocationsMapRailState(sidebarRailCollapsed);
    syncAlbumMapRailState(sidebarRailCollapsed, { motion });
  };
  /* 收起前把鼠标停留过的相簿行固定为悬浮态，随后跟列表一起慢速淡出。 */
  if (!collapsed && railRememberedHoverId != null)
    applySidebarRailHoverMemory();
  const interrupted = !!railMotion;
  const visualStart = interrupted ? captureRailItems() : null;
  finishRailMotion({ settlePhotoGrid: reducedMotion });
  sidebarRailCollapsed = !!collapsed;
  albumGridSpacingSuspended = !reducedMotion;
  /* 先同步相簿地图内部画布的目标位置和移动时长，再切换父页面侧栏；
     两侧从同一个绘制帧启动，地图与侧栏边缘保持连续。 */
  syncMapRailStates(!reducedMotion);
  document.documentElement.classList.toggle(
    "sidebar-rail-is-collapsed",
    sidebarRailCollapsed,
  );
  /* 地图里的“显示地图按钮”关闭后，只有相簿栏已经收起时，
     左上角切换按钮才进入靠近显示模式；相簿栏展开时必须始终可点。 */
  syncLocationsMapRailVisibility();
  if (sidebarRailCollapsed && !showLocationMapButtons) {
    hideLocationsMapRail();
  }
  if (!reducedMotion) {
    startAlbumMapRailMotion(sidebarRailCollapsed, NAV_MOVE_MS);
  }
  /* 地图图层和关闭键保持同一组过渡时长；下一帧再写一次相同目标，
     确保嵌入页与父页从同一帧开始执行动画。 */
  requestAnimationFrame(() => syncMapRailStates(!reducedMotion));

  if (reducedMotion) {
    railLayoutCache = null;
    sidebar.classList.toggle("is-rail-collapsed", sidebarRailCollapsed);
    sidebar.classList.remove("is-rail-animating");
    syncAlbumGridSpacing();
    photoGridLastWidth = -1;
    applyPhotoGridLayouts();
    syncMapRailStates();
  } else {
    let start;
    let target;
    if (interrupted && railLayoutCache) {
      /* 连点时不能再量一次目标：那会把栏体宽度临时归零，产生闪跳。
         直接复用上一次已经量好的两端布局，并从当前可见位置接着走。 */
      start = visualStart;
      target = railLayoutCache[sidebarRailCollapsed ? "collapsed" : "expanded"];
    } else {
      start = captureRailItems();
      target = measureRailTarget(sidebarRailCollapsed);
      railLayoutCache = {
        [sidebarRailCollapsed ? "expanded" : "collapsed"]: start,
        [sidebarRailCollapsed ? "collapsed" : "expanded"]: target,
      };
    }
    /* 成列坐标已经写成绝对定位。动画期间先暂停 ResizeObserver 的
       逐帧重算，让 Web Animations 把它们连续送到刚量好的目标；
       动画结束后再落到同一份最终布局，避免最后一帧回弹。 */
    photoGridLayoutSuspended = true;
    const grids = freezeRailGrids();
    const base = captureRailItems();

    sidebar.classList.toggle("is-rail-collapsed", sidebarRailCollapsed);
    /* 收 / 推的整段时间里先停用分界线，避免它跟着右边缘扫过
       左上角切换图标，也避免动画中途误抓到宽度。 */
    sidebar.classList.add("is-rail-animating");
    document.documentElement.classList.add("sidebar-rail-motion-active");
    /* 外壳、淡变和卡片补位保持同一段时长，连点时也能从当前帧连续接上。 */
    const duration = NAV_MOVE_MS;
    const animations = animateRailItems(start, base, target, duration);
    railMotion = {
      animations,
      grids,
      scrollTop: initialContentScrollTop,
      timer: setTimeout(() => {
        finishRailMotion();
        sidebar.classList.remove("is-rail-animating");
        cancelAlbumMapRailMotion();
        syncMapRailStates();
        syncSidebarHoverPeekMode();
      }, duration + 30),
    };
  }
  if (reducedMotion) syncSidebarHoverPeekMode();
  syncSidebarRailInteractionState();
  syncSidebarRailButtonState();
}

function toggleSidebarRail() {
  if (contextMenuOpen || !$("#viewer").hidden) return;
  if (photoWallLibraryRailIsLocked() || hoverExpandSidebar) {
    syncSidebarRailButtonState();
    return;
  }
  /* 以界面上的实际状态为准，避免热刷新或中断动画后变量与 DOM 不同步，
     导致点击像是在“收起”但实际又把状态算回展开。 */
  const currentlyCollapsed =
    $("#sidebar").classList.contains("is-rail-collapsed");
  const nextCollapsed = !currentlyCollapsed;
  setSidebarRailCollapsed(nextCollapsed);
  writeSidebarRailCollapsed(nextCollapsed);
}

let sidebarRailPressHandled = false;

function handleSidebarRailPress(event) {
  if (event.button !== 0) return;
  const button =
    event.target instanceof Element
      ? event.target.closest("#sidebarRailBtn")
      : null;
  if (!button) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (sidebarRailPressHandled) return;
  sidebarRailPressHandled = true;
  toggleSidebarRail();
  setTimeout(() => {
    sidebarRailPressHandled = false;
  }, 0);
}

/* pointerdown 和 mousedown 都监听：前者更及时，后者兜底旧版 Chromium /
   窗口拖动层只派发鼠标事件的情况。随后产生的 click 不再重复切换。 */
document.addEventListener("pointerdown", handleSidebarRailPress, true);
document.addEventListener("mousedown", handleSidebarRailPress, true);
$("#sidebarRailBtn").addEventListener("click", (event) => {
  if (event.detail !== 0) return;
  event.preventDefault();
  event.stopPropagation();
  toggleSidebarRail();
});

document.addEventListener(
  "pointermove",
  (event) => {
    sidebarHoverPointerX = event.clientX;
    sidebarHoverPointerY = event.clientY;
    if (!hoverExpandSidebar || !sidebarRailCollapsed) return;
    if (sidebarHoverPointerFrame) return;
    sidebarHoverPointerFrame = requestAnimationFrame(() => {
      sidebarHoverPointerFrame = 0;
      if (!hoverExpandSidebar || !sidebarRailCollapsed) return;
      const near = sidebarHoverPeekPointerNear();
      if (!near) sidebarHoverPeekSuppressed = false;
      if (!sidebarHoverPeekInteractionAllowed()) {
        scheduleSidebarHoverPeekClose();
        return;
      }
      if (near && !sidebarHoverPeekSuppressed) {
        scheduleSidebarHoverPeekOpen();
      } else {
        scheduleSidebarHoverPeekClose();
      }
    });
  },
  { passive: true },
);

document.addEventListener("pointerleave", () => {
  scheduleSidebarHoverPeekClose();
});
$("#sidebar").addEventListener("pointerleave", (event) => {
  if (!sidebarHoverPeekOpen) return;
  const next = event.relatedTarget;
  if (
    next instanceof Element &&
    next.closest("#sidebarRailBtn, .sidebar-hover-edge")
  ) {
    return;
  }
  /* 指针直接进入地图等 iframe 时，父页面收不到后续 pointermove。
     清掉旧坐标，让离开计时器能够正常完成收起。 */
  sidebarHoverPointerX = Number.NaN;
  sidebarHoverPointerY = Number.NaN;
  scheduleSidebarHoverPeekClose();
});
window.addEventListener("blur", () => {
  scheduleSidebarHoverPeekClose();
});

function handleSidebarHoverPeekFocus(target) {
  if (
    !(target instanceof Element) ||
    (!target.closest("#sidebar") &&
      target !== $("#sidebarRailBtn") &&
      target !== $("#sidebarHoverEdge"))
  ) {
    return;
  }
  if (!sidebarHoverPeekInteractionAllowed()) return;
  window.clearTimeout(sidebarHoverCloseTimer);
  sidebarHoverCloseTimer = 0;
  openSidebarHoverPeek();
}

document.addEventListener("focusin", (event) => {
  handleSidebarHoverPeekFocus(event.target);
});
document.addEventListener("focusout", (event) => {
  if (
    !(event.target instanceof Element) ||
    (!event.target.closest("#sidebar") &&
      event.target !== $("#sidebarRailBtn") &&
      event.target !== $("#sidebarHoverEdge"))
  ) {
    return;
  }
  requestAnimationFrame(() => {
    if (!sidebarHoverPeekFocusInside()) scheduleSidebarHoverPeekClose();
  });
});

$("#sidebarHoverEdge").addEventListener("keydown", (event) => {
  if (event.key !== "Enter" && event.key !== " ") return;
  event.preventDefault();
  if (!openSidebarHoverPeek()) return;
  requestAnimationFrame(() => {
    $("#sidebarOptionsBtn").focus({ preventScroll: true });
  });
});

/* 拖动分界线调侧边栏宽度，右边网格会自动重排 */
(function initResizer() {
  const bar = $("#sidebar");
  const handle = $("#sidebarResizer");
  const MIN = 228;
  const MAX = () => Math.min(560, Math.round(window.innerWidth * 0.6));
  let frozenGrids = [];
  const setSidebarVisibleWidth = (width) => {
    document.documentElement.style.setProperty(
      "--sidebar-visible-width",
      `${width}px`,
    );
    syncLocationsMapRailState();
    syncAlbumMapRailState();
  };
  /* 每次打开相簿都从最窄宽度开始；拖动只改变这次打开时的宽度，不再记住上次的尺寸 */
  bar.style.setProperty("--sidebar-current", `${MIN}px`);
  setSidebarVisibleWidth(MIN);
  localStorage.removeItem("album-sidebar-width");

  const albumCardGrids = () =>
    document.querySelectorAll("#content .album-grid");

  /* 相簿卡片会随列宽伸缩；拖动时先把列宽钉住，避免边拖边缩放。
     照片网格则故意不冻结：拖动过程中它要跟着可用宽度实时伸缩、换列。 */
  const freezeContentGrids = () => {
    frozenGrids = [...albumCardGrids()].map((grid) => ({
      grid,
      previous: grid.style.gridTemplateColumns,
    }));
    for (const { grid } of frozenGrids) {
      const columns = getComputedStyle(grid).gridTemplateColumns;
      if (columns && columns !== "none")
        grid.style.gridTemplateColumns = columns;
    }
  };

  const releaseContentGrids = () => {
    if (!frozenGrids.length) return;
    const before = captureContentLayout();
    for (const { grid, previous } of frozenGrids) {
      grid.style.gridTemplateColumns = previous;
    }
    frozenGrids = [];
    animateContentReflow(before);
  };

  const apply = (px) => {
    const width = Math.max(MIN, Math.min(MAX(), Math.round(px)));
    bar.style.setProperty("--sidebar-current", `${width}px`);
    setSidebarVisibleWidth(width);
    return width;
  };

  handle.addEventListener("pointerdown", (e) => {
    /* 顶栏与侧栏表头的分界线以上不参与宽度调整；
        拖动热区本身也从这条线下方开始。 */
    if (e.clientY < $(".toolbar").getBoundingClientRect().bottom) return;
    e.preventDefault();
    handle.setPointerCapture(e.pointerId);
    freezeContentGrids();
    document.body.classList.add("resizing");
    const onMove = (ev) => apply(ev.clientX - bar.getBoundingClientRect().left);
    const onUp = (ev) => {
      handle.removeEventListener("pointermove", onMove);
      handle.removeEventListener("pointerup", onUp);
      handle.removeEventListener("pointercancel", onUp);
      document.body.classList.remove("resizing");
      releaseContentGrids();
      ev.preventDefault();
    };
    handle.addEventListener("pointermove", onMove);
    handle.addEventListener("pointerup", onUp);
    handle.addEventListener("pointercancel", onUp);
  });
})();

/* --------------------------- 选文件夹 / 扫描 --------------------------- */

async function refreshState() {
  const data = await api("/api/state");
  applyState(data);
  return data;
}

const COVER_PRELOAD_CONCURRENCY = 8;

async function preloadImageUrls(
  urls,
  { timeout = 5000, concurrency = 8 } = {},
) {
  const queue = [...new Set(urls || [])];
  if (!queue.length) return;
  let next = 0;
  const workerCount = Math.min(
    queue.length,
    Math.max(1, Math.min(COVER_PRELOAD_CONCURRENCY, Number(concurrency) || 1)),
  );
  const loadOne = (url) =>
    new Promise((resolve) => {
      const img = new Image();
      let settled = false;
      let timer = null;
      const done = () => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        resolve();
      };
      img.onload = () => {
        /* onload 只代表资源到了；decode 完再换界面，插入时才是已经能画的图。 */
        if (img.decode) img.decode().then(done, done);
        else done();
      };
      img.onerror = done;
      img.src = url;
      timer = setTimeout(done, timeout);
    });
  await Promise.all(
    Array.from({ length: workerCount }, async () => {
      while (next < queue.length) await loadOne(queue[next++]);
    }),
  );
}

/* 后台刷新完成后，先把新封面装进浏览器缓存，再换界面。
   这样从「上次的封面」切到「当前封面」时不会经过一排空白格。 */
async function preloadCoverThumbs(payload) {
  const version = payload.coverEpoch || payload.scan?.finishedAt || 0;
  const urls = (payload.albums || []).flatMap((album) =>
    (album.coverIds || []).flatMap((id) => {
      const coverVersion = album.coverVersions?.[id] || version;
      return [
        thumbUrlAt(id, 200, "cover", coverVersion),
        thumbUrlAt(id, 400, "cover", coverVersion),
      ];
    }),
  );
  await preloadImageUrls(urls, { timeout: 5000 });
}

const coverKeyOf = (album) =>
  (album?.coverIds || [])
    .map((id) => `${id}:${album.coverVersions?.[id] || ""}`)
    .join("|");

/* 移动、复制、添加项目后，只有封面真的换了的相簿需要重新等图。
   先把新封面装进浏览器缓存，再换 DOM，侧栏和相簿卡片就不会闪空。 */
async function preloadChangedCoverThumbs(beforeAlbums, payload) {
  const before = new Map(
    (beforeAlbums || []).map((album) => [album.id, coverKeyOf(album)]),
  );
  const urls = new Set();
  for (const album of payload?.albums || []) {
    if (before.get(album.id) === coverKeyOf(album)) continue;
    for (const id of album.coverIds || []) {
      const version = album.coverVersions?.[id] || payload.coverEpoch || 0;
      urls.add(thumbUrlAt(id, 200, "cover", version));
      urls.add(thumbUrlAt(id, 400, "cover", version));
    }
  }
  if (!urls.size) return;
  await preloadImageUrls(urls, { timeout: 1200 });
}

const ROOT_IMPORT_POLL_MS = 400;

async function waitForRootImport(rootId, requestedAt, statusText) {
  while (true) {
    const scan = await api(`/api/scan?rootId=${encodeURIComponent(rootId)}`);
    if (scan.running) {
      /* 扫描阶段仍在后台更新，但导入期间只展示用户选中的文件夹路径，
         不再切换成“读取磁盘”“读取拍摄信息”等阶段文字。 */
      if (state.busy !== statusText) {
        state.busy = statusText;
        renderStatus();
      }
    } else if (
      scan.phase === "done" &&
      Number(scan.finishedAt) >= Number(requestedAt)
    ) {
      await new Promise((resolve) =>
        window.setTimeout(resolve, ROOT_IMPORT_POLL_MS),
      );
      return api("/api/state");
    } else if (
      scan.phase === "error" &&
      Number(scan.finishedAt) >= Number(requestedAt)
    ) {
      throw new Error(scan.message || "导入图库失败");
    }
    await new Promise((resolve) =>
      window.setTimeout(resolve, ROOT_IMPORT_POLL_MS),
    );
  }
}

let rootImportInProgress = false;

async function pickFolder() {
  if (rootImportInProgress) {
    toast("正在导入图库，请等待当前任务完成");
    return;
  }
  rootImportInProgress = true;
  try {
    const picked = await api("/api/pick-folder", { method: "POST" });
    if (!picked.path) return;
    state.busy = `正在导入 ${picked.path}`;
    renderStatus();
    const requestedAt = Date.now();
    const res = await api("/api/roots", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: picked.path, background: true }),
    });
    const finalState = res.background
      ? await waitForRootImport(
          res.root.id,
          requestedAt,
          `正在导入 ${picked.path}`,
        )
      : res.state;
    await preloadCoverThumbs(finalState);
    applyState(finalState);
    resetPhotoWallLibraryState();
    invalidateLocationItems();
    state.activeId = "library";
    await loadLibrary();
    rememberActiveView();
    lastRev = Number(finalState.revision) || lastRev;
    state.busy = "";
    render();
  } catch (err) {
    state.busy = "";
    renderStatus();
    alert(err.message);
  } finally {
    rootImportInProgress = false;
  }
}

async function switchRoot(rootId) {
  if (Number(rootId) === Number(state.activeRootId)) return true;
  const root = state.roots.find((entry) => Number(entry.id) === Number(rootId));
  if (!root) return false;
  if (root.available === false) {
    toast("这个根目录暂时无法访问");
    return false;
  }
  const contentCrossfade = beginContentCrossfade();
  closeMenu({ duration: 120 });
  state.busy = `正在切换到 ${root.name || root.path}`;
  renderStatus();
  try {
    const res = await api(`/api/roots/${root.id}/activate`, { method: "POST" });
    state.select = false;
    clearSelection();
    state.cursor = -1;
    state.cursorVisible = false;
    state.photoWall = false;
    state.photoWallPlayback = null;
    state.copyTarget = false;
    state.copyTargetParentId = null;
    state.edit = false;
    await preloadCoverThumbs(res.state);
    applyState(res.state);
    resetPhotoWallLibraryState();
    invalidateLocationItems();
    state.activeId = "library";
    state.album = null;
    state.items = [];
    state.albumItems = [];
    state.albumItemsRaw = [];
    state.expanded.clear();
    /* 新根目录从自己的 revision 开始取列表，避免仍以旧图库的版本号建缓存。 */
    lastRev = Number(res.state.revision) || 0;
    await loadLibrary();
    rememberActiveView();
    state.busy = "";
    playContentCrossfade(contentCrossfade);
    render();
    startContentCrossfadeFade(
      contentCrossfade,
      ".photo-grid .tile, .album-card",
    );
    void promptFolderImports();
    return true;
  } catch (err) {
    cancelContentCrossfade(contentCrossfade);
    state.busy = "";
    renderStatus();
    toast(err.message);
    return false;
  }
}

async function switchToNextRoot() {
  const roots = state.roots.filter((root) => root.available !== false);
  if (!roots.length) {
    toast("未导入文件夹");
    return false;
  }
  if (roots.length === 1) {
    toast("只有一个可用图库");
    return false;
  }
  const currentIndex = roots.findIndex(
    (root) => Number(root.id) === Number(state.activeRootId),
  );
  const next = roots[(currentIndex + 1) % roots.length];
  return switchRoot(next.id);
}

/* ------------------- 自动更新（磁盘一变，界面自己刷） ------------------- */

let lastRev = null;
let pendingUpdate = false; /* 正在选择 / 看大图时先攒着，退出来再刷 */
const POLL_MS = 2000;

async function pollRevision() {
  let info;
  try {
    info = await api("/api/revision");
  } catch {
    return; /* 服务没起来就先不管，下一轮再说 */
  }
  if (lastRev === null) {
    lastRev = info.rev;
    if (
      state.activeId === "locations" &&
      state.locationItemsRevision === null
    ) {
      state.locationItemsRevision = info.rev;
    }
    return;
  }
  if (info.rev === lastRev) return;
  lastRev = info.rev;
  await applyExternalUpdate();
}

async function applyExternalUpdate() {
  /* 选择模式、查看器或正拖着相簿时先别动，否则列表一换就对不上了 */
  if (
    state.select ||
    !$("#viewer").hidden ||
    galleryZoomBusy ||
    albumGesture ||
    albumSettling ||
    state.photoWall ||
    window.albumSlideshow?.isOpen()
  ) {
    pendingUpdate = true;
    return;
  }
  const scrollTop = $("#content").scrollTop;
  state.busy = "文件夹有更新，正在刷新…";
  renderStatus();
  try {
    const data = await api("/api/state");
    await preloadChangedCoverThumbs(state.albums, data);
    applyState(data);
    if (state.activeId === "locations") {
      await reloadActiveCollection();
    } else if (state.activeId === "trash") {
      await loadTrash();
    } else if (state.activeId === "library") {
      await loadLibrary();
    } else if (state.activeId === "photoWall") {
      await loadPhotoWallAlbums();
    } else if (state.activeId === "favorites") {
      await loadFavorites();
    } else if (state.activeId !== "all" && albumById(state.activeId)) {
      await loadAlbum(state.activeId);
    } else if (state.activeId !== "all") {
      /* 当前这个相簿在磁盘上被删掉了 */
      fallbackToAllAlbums();
    }
  } catch {
    /* 读失败就保持原样，等下一轮 */
  }
  state.busy = "";
  render();
  $("#content").scrollTop = scrollTop; /* 别把人家的浏览位置顶回去 */
  void promptFolderImports();
}

function flushPendingUpdate() {
  if (!pendingUpdate) return;
  pendingUpdate = false;
  return applyExternalUpdate();
}

let undoing = false;

async function undoLast() {
  if (undoing) return;
  undoing = true;
  if (!$("#viewer").hidden) closeViewer();
  closeMenu();
  hidePickerNow();
  /* 撤销完全静默：状态条出现会让内容区高度先缩再长，产生一次跳闪。 */
  state.busy = "";
  renderStatus();
  quietUntil = Date.now() + 4000;
  const beforeCards = captureAlbumCardLayout();
  const beforeSidebar = captureSidebarAlbumLayout();
  const contentScrollTop = $("#content").scrollTop;
  const sidebarScrollTop = $("#sidebarList").scrollTop;

  try {
    const res = await api("/api/undo", { method: "POST" });
    /* 先把恢复后的封面解码好，再替换 DOM；否则新卡片会先空一帧。 */
    await preloadCoverThumbs(res.state);
    applyState(res.state);

    /* 撤销可能把当前相簿整个收掉（比如撤销新建），那就回「所有相簿」 */
    state.select = false;
    clearSelection();
    state.cursor = -1;
    state.cursorVisible = false;
    if (state.activeId === "locations") {
      await reloadActiveCollection();
    } else if (state.activeId === "trash") {
      await loadTrash();
    } else if (state.activeId === "library") {
      await loadLibrary();
    } else if (state.activeId === "favorites") {
      await loadFavorites();
    } else if (state.activeId !== "all" && albumById(state.activeId)) {
      await loadAlbum(state.activeId);
    } else if (state.activeId !== "all") {
      fallbackToAllAlbums();
    }

    if (res.kind === "location") {
      locationAssignTarget = null;
      const refreshed = new Map(
        [...state.items, ...state.albumItemsRaw, ...state.locationItemsRaw].map(
          (item) => [Number(item.id), item],
        ),
      );
      state.albumMapItems = state.albumMapItems.map(
        (item) => refreshed.get(Number(item.id)) || item,
      );
    }
    state.busy = "";
    render();
    $("#content").scrollTop = contentScrollTop;
    $("#sidebarList").scrollTop = sidebarScrollTop;
    if (res.kind === "trash-album") {
      const restoredPaths = new Set(
        (res.result?.items || [])
          .map((item) => String(item.path || "").toLowerCase())
          .filter(Boolean),
      );
      const restoredIds = state.albums
        .filter((album) => restoredPaths.has(String(album.path).toLowerCase()))
        .map((album) => album.id);
      animateRestoredAlbum(restoredIds, beforeCards, beforeSidebar);
    }
    lastRev = (await api("/api/revision")).rev;
  } catch (err) {
    state.busy = "";
    renderStatus();
    toast(err.message);
  } finally {
    undoing = false;
  }
}

async function removeRoot(rootId, { confirmRemoval = true } = {}) {
  const root = state.roots.find((r) => r.id === rootId);
  if (!root) return false;
  if (confirmRemoval) {
    const confirmed = await askConfirm($("#librarySwitchBtn"), {
      title: `从 Fotora 中移除“${root.name || root.path}”？`,
      message: `文件夹：${root.path}`,
      note: "此操作不可撤销",
      actionText: "移除",
      centered: true,
    });
    if (!confirmed) return false;
  }
  const removedActive = Number(rootId) === Number(state.activeRootId);
  closeMenu({ duration: 0, endScale: 1 });
  state.busy = `正在移除 ${root.name || root.path}`;
  renderStatus();
  try {
    const res = await api(`/api/roots/${rootId}`, { method: "DELETE" });
    state.select = false;
    clearSelection();
    applyState(res.state);
    invalidateLocationItems();
    if (!state.roots.length) {
      state.activeId = "library";
      state.album = null;
      state.items = [];
      state.albumItems = [];
      state.albumItemsRaw = [];
      state.trashAlbums = [];
      state.folderPrompts = [];
      state.expanded.clear();
      state.selected.clear();
      state.selectedTrashAlbums.clear();
      state.photoWall = false;
      state.photoWallPlayback = null;
      state.photoWallAlbumId = null;
      state.photoWallSelectMode = null;
      state.copyTarget = false;
      state.copyTargetParentId = null;
      state.edit = false;
      state.select = false;
      rememberActiveView();
    } else if (removedActive) {
      state.activeId = "library";
      state.album = null;
      state.items = [];
      state.albumItems = [];
      state.albumItemsRaw = [];
      state.expanded.clear();
      state.photoWall = false;
      state.photoWallPlayback = null;
      state.copyTarget = false;
      state.copyTargetParentId = null;
      resetPhotoWallLibraryState();
      await loadLibrary();
      rememberActiveView();
    } else if (state.activeId !== "all" && !albumById(state.activeId)) {
      fallbackToAllAlbums();
    }
    lastRev = Number(res.state.revision) || 0;
    state.busy = "";
    render();
    return true;
  } catch (err) {
    state.busy = "";
    renderStatus();
    toast(err.message);
    return false;
  }
}

/* ------------------------------ 查看器 ------------------------------ */

function formatSize(bytes) {
  if (!bytes) return "";
  const mb = bytes / 1024 / 1024;
  return mb >= 1 ? `${mb.toFixed(1)} MB` : `${Math.round(bytes / 1024)} KB`;
}

function formatDate(ms) {
  if (!ms) return "没有拍摄时间";
  const d = new Date(ms);
  const p = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日 ${p(d.getHours())}:${p(d.getMinutes())}`;
}

function formatInfoDate(ms) {
  if (!ms) return "没有拍摄时间";
  const d = new Date(ms);
  const p = (n) => String(n).padStart(2, "0");
  return (
    `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日 ` +
    `${MENU_WEEKDAYS[d.getDay()]} ${p(d.getHours())}:${p(d.getMinutes())}`
  );
}

function infoHTML(item) {
  const params = [
    item.focal ? `${Math.round(item.focal)}mm` : "",
    item.f_number ? `f/${item.f_number}` : "",
    item.exposure ? `1/${Math.round(1 / item.exposure)}s` : "",
    item.iso ? `ISO ${item.iso}` : "",
  ]
    .filter(Boolean)
    .join("  ");
  const rows = [
    ["日期", formatDate(item.taken_at)],
    ["尺寸", item.width && item.height ? `${item.width} × ${item.height}` : ""],
    ["相机", cameraDisplayName(item.camera) || ""],
    ["镜头", item.lens || ""],
    ["参数", params],
    ["实况", isLivePhoto(item) ? "照片 + 伴随视频" : ""],
    ["大小", formatSize(item.size)],
    ["文件", item.path],
  ].filter(([, v]) => v);
  return rows
    .map(
      ([k, v]) =>
        `<div class="info-row"><span>${k}</span><b>${esc(v)}</b></div>`,
    )
    .join("");
}

