/* 很多视频的第 0 帧本来就是黑场（片头淡入、黑底标题卡）。
   等播放推进到这里再揭开封面，交接时露出的就不是那帧黑画面。 */
const VIDEO_CONTENT_START = 0.2;
const VIDEO_SINGLE_CLICK_DELAY = 200;
const VIDEO_FLIGHT_MS = 380;
/* 等封面飞入结束再接入视频源。解码器如果和第一帧飞行动画同时初始化，
   会在点击后 0.1 秒左右抢一次合成，表现为打开瞬间掉一帧。 */
const VIDEO_SOURCE_DELAY = VIDEO_FLIGHT_MS;
const VIDEO_CONTROLS_IDLE_MS = 2000;
let viewerCloseClone = null;
let viewerCloseTimer = null;
let lastPointerX = 0;
let lastPointerY = 0;

function rememberViewerPointer(e) {
  lastPointerX = e.clientX;
  lastPointerY = e.clientY;
}
document.addEventListener("pointermove", rememberViewerPointer, {
  passive: true,
});
document.addEventListener("pointerdown", rememberViewerPointer, {
  passive: true,
});

/* RAW 由接口判定是否带内嵌预览；其余动画/多帧格式在服务端检查后隐藏入口。
   这里只排除无需发请求的 GIF。 */
const NON_EDITABLE_PHOTO_EXT = new Set([".gif"]);
const extensionOfPath = (value) => {
  const match = /(?:^|[\\/])([^\\/]+)$/.exec(String(value || ""));
  const name = match ? match[1] : String(value || "");
  const dot = name.lastIndexOf(".");
  return dot >= 0 ? name.slice(dot).toLowerCase() : "";
};
let viewerEditEligible = false;
let viewerEditCheckToken = 0;
let photoEditorOpen = false;
const viewerEditRecipes = new Map();

function viewerEditMaybeAvailable(item) {
  if (!item) return false;
  if (item.kind === "video") return true;
  if (item.kind !== "photo") return false;
  return !NON_EDITABLE_PHOTO_EXT.has(
    String(item.ext || extensionOfPath(item.path)).toLowerCase(),
  );
}

function syncViewerEditVisibility() {
  const zone = $("#viewerEditZone");
  const button = $("#viewerEditButton");
  if (!zone || !button) return;
  const available =
    viewerEditEligible &&
    !$("#viewer").hidden &&
    !photoEditorOpen &&
    !viewerInfoOpen &&
    !viewerDateOpen;
  if (!available) {
    zone.classList.remove("is-visible");
    button.tabIndex = -1;
    button.setAttribute("aria-hidden", "true");
    return;
  }
  button.setAttribute(
    "aria-label",
    state.items[viewerIndex]?.kind === "video" ? "裁剪视频" : "编辑照片",
  );
  if (!viewerEditHoverOnly) {
    zone.classList.add("is-visible");
    button.tabIndex = 0;
    button.setAttribute("aria-hidden", "false");
    return;
  }
  const rect = zone.getBoundingClientRect();
  const near =
    lastPointerX >= rect.left - 12 &&
    lastPointerX <= rect.right + 12 &&
    lastPointerY >= rect.top - 12 &&
    lastPointerY <= rect.bottom + 12;
  const visible = near || document.activeElement === button;
  zone.classList.toggle("is-visible", visible);
  button.tabIndex = visible ? 0 : -1;
  button.setAttribute("aria-hidden", String(!visible));
}

async function refreshViewerEditButton(item = state.items[viewerIndex]) {
  const token = ++viewerEditCheckToken;
  viewerEditEligible = viewerEditMaybeAvailable(item);
  syncViewerEditVisibility();
  if (!viewerEditEligible) return;
  try {
    const response = await fetch(`/api/edit/${item.id}`, { cache: "no-store" });
    const payload = await response.json().catch(() => ({}));
    if (
      token !== viewerEditCheckToken ||
      state.items[viewerIndex]?.id !== item.id
    )
      return;
    viewerEditEligible = response.ok && payload.editable === true;
    if (response.ok && payload.recipe) {
      viewerEditRecipes.set(Number(item.id), payload.recipe);
      item.editRecipe = payload.recipe;
      if (
        item.kind === "video" &&
        state.items[viewerIndex]?.id === item.id &&
        !photoEditorOpen
      ) {
        const video = $("#viewerStage > video");
        if (video) {
          fitViewerVideoToStage(video);
          if (videoControlsVideo && !$("#videoControls").hidden) {
            placeVideoControls(video);
          }
        }
      }
    }
    syncViewerEditVisibility();
  } catch {
    if (token === viewerEditCheckToken) {
      viewerEditEligible = false;
      syncViewerEditVisibility();
    }
  }
}

async function waitForViewerImageReady(image) {
  if (!image) return null;
  if (image.complete && !image.naturalWidth) {
    throw new Error("最终预览加载失败");
  }
  if (!image.complete) {
    await new Promise((resolve, reject) => {
      const finish = () => {
        image.removeEventListener("load", finish);
        image.removeEventListener("error", fail);
        resolve();
      };
      const fail = () => {
        image.removeEventListener("load", finish);
        image.removeEventListener("error", fail);
        reject(new Error("最终预览加载失败"));
      };
      image.addEventListener("load", finish, { once: true });
      image.addEventListener("error", fail, { once: true });
    });
  }
  await image.decode?.().catch(() => {});
  await new Promise((resolve) =>
    requestAnimationFrame(() => requestAnimationFrame(resolve)),
  );
  return image.isConnected && image.getBoundingClientRect().width > 0
    ? rectSnapshot(image.getBoundingClientRect())
    : null;
}

async function refreshViewerAfterEdit(
  item,
  { reload = true, recipe = null } = {},
) {
  if (!item) return;
  if (recipe) {
    viewerEditRecipes.set(Number(item.id), recipe);
    item.editRecipe = recipe;
  }
  for (const album of state.albums) {
    if (Array.isArray(album.coverIds) && album.coverIds.includes(item.id)) {
      if (!album.coverVersions || typeof album.coverVersions !== "object") {
        album.coverVersions = {};
      }
      album.coverVersions[item.id] = itemThumbVersion(item);
    }
  }
  for (const album of state.photoWallAlbums) {
    if (Number(album.coverItemId) === Number(item.id)) {
      album.coverEditRevision = Number(item.editRevision) || 0;
    }
  }
  const itemIndex = state.items.findIndex(
    (entry) => Number(entry.id) === Number(item.id),
  );
  const currentTile = itemIndex >= 0 ? tileAt(itemIndex) : null;
  const tileImage = currentTile?.querySelector("img");
  if (tileImage) tileImage.src = itemThumbUrl(item, 600, "inside");
  let viewerRect = null;
  if (state.items[viewerIndex]?.id === item.id) {
    const viewerVideo = $("#viewerStage > video");
    const viewerImage = $("#viewerPhoto > img");
    if (viewerVideo) {
      viewerRect = null;
    } else if (viewerImage) {
      viewerImage.src = viewItemUrl(item);
      viewerRect = await waitForViewerImageReady(viewerImage);
    }
  }
  const thumbPath = `/api/thumb/${item.id}`;
  const wallPath = `/api/photo-wall/thumb/${item.id}`;
  document.querySelectorAll("img[src]").forEach((img) => {
    let pathname = "";
    try {
      pathname = new URL(img.getAttribute("src"), location.href).pathname;
    } catch {}
    if (pathname === thumbPath) {
      const parsed = new URL(img.src, location.href);
      img.src = itemThumbUrl(
        item,
        Number(parsed.searchParams.get("size")) || 400,
        parsed.searchParams.get("fit") || "inside",
      );
    } else if (pathname === wallPath) {
      const parsed = new URL(img.src, location.href);
      img.src = photoWallThumbUrl(
        item,
        Number(parsed.searchParams.get("size")) || 600,
      );
    }
  });
  if (state.items[viewerIndex]?.id === item.id && reload && !photoEditorOpen) {
    showViewerItem({ autoplay: false });
  }
  refreshViewerEditButton(item);
  return viewerRect;
}

async function openPhotoEditor() {
  const item = state.items[viewerIndex];
  if (
    !item ||
    !viewerEditEligible ||
    photoEditorOpen ||
    !window.PhotoEditor?.open
  )
    return;
  const viewerImage = $("#viewerPhoto > img");
  const imageRect = viewerImage?.getBoundingClientRect();
  const viewerVideo = $("#viewerStage > video");
  const previewTime =
    viewerVideo && Number.isFinite(viewerVideo.currentTime)
      ? viewerVideo.currentTime
      : null;
  if (viewerVideo && !viewerVideo.paused) viewerVideo.pause();
  const stageRect = $("#viewerStage").getBoundingClientRect();
  const transition =
    viewerImage && imageRect?.width > 0 && imageRect?.height > 0
      ? {
          src: viewerImage.currentSrc || viewerImage.src,
          rect: {
            left: imageRect.left,
            top: imageRect.top,
            width: imageRect.width,
            height: imageRect.height,
          },
          clipRect: {
            left: stageRect.left,
            top: stageRect.top,
            right: stageRect.right,
            bottom: stageRect.bottom,
          },
        }
      : null;
  photoEditorOpen = true;
  stopLiveMotion();
  syncViewerEditVisibility();
  syncViewerFilmstrip();
  syncViewerRating();
  closeViewerInfo({ immediate: true });
  closeViewerDate({ immediate: true });
  try {
    await window.PhotoEditor.open(item, {
      transition,
      previewTime,
      onBeforeExit: () => {
        const surface = viewerZoomSurface();
        if (surface) surface.style.transition = "none";
        viewerRotation = 0;
        resetViewerZoom();
        scheduleViewerLiveButtonPosition();
        if (surface) {
          requestAnimationFrame(() =>
            surface.style.removeProperty("transition"),
          );
        }
      },
      onSaved: async ({ item: changedItem, recipe }) => {
        const rect = await refreshViewerAfterEdit(changedItem, {
          reload: false,
          recipe,
        });
        const stageRect = $("#viewerStage").getBoundingClientRect();
        return {
          rect,
          clipRect: {
            left: stageRect.left,
            top: stageRect.top,
            right: stageRect.right,
            bottom: stageRect.bottom,
          },
        };
      },
      onExit: ({ action, item: changedItem }) => {
        photoEditorOpen = false;
        syncViewerFilmstrip();
        syncViewerRating();
        scheduleViewerLiveButtonPosition();
        syncViewerEditVisibility();
        if (
          action === "done" &&
          changedItem.kind === "video" &&
          state.items[viewerIndex]?.id === changedItem.id
        ) {
          requestAnimationFrame(() => {
            if (!$("#viewer").hidden) showViewerItem({ autoplay: false });
          });
        }
      },
    });
  } catch (err) {
    photoEditorOpen = false;
    viewerEditEligible = false;
    syncViewerEditVisibility();
    syncViewerRating();
    toast(err?.message || "这个项目暂时不能编辑");
  }
}

$("#viewerEditButton")?.addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  void openPhotoEditor();
});
$("#viewerEditButton")?.addEventListener("focus", syncViewerEditVisibility);
$("#viewerEditButton")?.addEventListener("blur", () => {
  requestAnimationFrame(syncViewerEditVisibility);
});
document.addEventListener(
  "pointermove",
  () => {
    if ($("#viewer").hidden || !viewerEditHoverOnly) return;
    syncViewerEditVisibility();
  },
  { passive: true },
);
document.addEventListener(
  "pointerdown",
  () => {
    if ($("#viewer").hidden || !viewerEditHoverOnly) return;
    syncViewerEditVisibility();
  },
  { passive: true },
);

function pointerOverTileRect(tile) {
  if (!tile?.isConnected) return false;
  const rect = tile.getBoundingClientRect();
  return (
    lastPointerX >= rect.left &&
    lastPointerX <= rect.right &&
    lastPointerY >= rect.top &&
    lastPointerY <= rect.bottom
  );
}

function finishViewerCloseHover(tile, itemId) {
  if (!tile?.isConnected || itemId == null) {
    clearPinnedHover();
    return;
  }
  if (pointerOverTileRect(tile)) pinTileHover(tile, itemId);
  else clearPinnedHover();
}

/* 退出查看器时鼠标往往还停在右下角的 ✕ 上，并不在照片上。
   先让刚才那张照片沿用悬停样式；鼠标一动就撤掉，
   之后仍由浏览器正常的 :hover 决定哪一张浮起来。 */
function clearPinnedHover() {
  state.hoverPinId = null;
  document.body.classList.remove("viewer-hover-pinned");
  document
    .querySelectorAll(".photo-grid .tile.is-hover-pinned")
    .forEach((tile) => {
      tile.classList.remove("is-hover-pinned");
    });
  if (hoverPinRelease) {
    document.removeEventListener("pointermove", hoverPinRelease, true);
    document.removeEventListener("pointerdown", hoverPinRelease, true);
    hoverPinRelease = null;
  }
}

function clearViewerSourceTile() {
  document
    .querySelectorAll(".photo-grid .tile.is-viewer-source")
    .forEach((tile) => tile.classList.remove("is-viewer-source"));
}

/* 从打开查看器的那一刻就把悬停样式挂到照片上，而不是等退出后再挂。
   这样查看期间状态一直存在，退出时不会重新播一遍阴影过渡。
   查看器里翻到别的照片时，也跟着把这一张换过去。 */
function setPinnedHover(itemId) {
  if (itemId == null) return;
  state.hoverPinId = itemId;
  document.body.classList.add("viewer-hover-pinned");
  clearViewerSourceTile();
  document
    .querySelectorAll(".photo-grid .tile.is-hover-pinned")
    .forEach((tile) => {
      const index = Number(tile.dataset.index);
      if (state.items[index]?.id !== itemId)
        tile.classList.remove("is-hover-pinned");
    });
  const tile = tileAt(viewerIndex);
  if (tile && state.items[viewerIndex]?.id === itemId) {
    tile.classList.add("is-hover-pinned");
    tile.classList.add("is-viewer-source");
  }
}

function armPinnedHoverRelease() {
  if (hoverPinRelease) return;
  hoverPinRelease = () => clearPinnedHover();
  document.addEventListener("pointermove", hoverPinRelease, true);
  document.addEventListener("pointerdown", hoverPinRelease, true);
}

function viewerZoomSurface() {
  return $("#viewerPhoto") || $("#viewerStage video");
}

/* 横图转成竖图后，原来的显示尺寸已经装不进舞台。
   这里只在 90° / 270° 时补一个适配缩放，避免画面上下或左右被裁掉。 */
function viewerRotationFit(surface = viewerZoomSurface()) {
  if (!surface || viewerRotation % 180 === 0) return 1;
  /* 照片的缩放作用在铺满舞台的外层，旋转适配要按里面真正有画面的
     图片尺寸来算；拿外层尺寸会把四周留白也算进去，画面会缩得过小。 */
  const content = surface.matches("video")
    ? surface
    : surface.querySelector("img") || surface;
  const crop = content.matches("video") ? viewerVideoCrop(content) : null;
  const width = content.offsetWidth * (crop?.w || 1);
  const height = content.offsetHeight * (crop?.h || 1);
  const stage = $("#viewerStage").getBoundingClientRect();
  if (!width || !height || !stage.width || !stage.height) return 1;
  return Math.min(1, stage.width / height, stage.height / width);
}

function applyViewerZoom() {
  const stage = $("#viewerStage");
  const surface = viewerZoomSurface();
  if (!surface) {
    stage.classList.remove("is-zoomed");
    return;
  }
  stage.classList.toggle("is-zoomed", viewerZoom > 1.001);
  /* 保留连续角度，不要每圈归零。否则 270° → 0° 会被 CSS 当成
     反方向转 270°，第四次按键看起来就会倒转一圈。 */
  const rotation = viewerRotation;
  const scale = viewerZoom * viewerRotationFit(surface);
  const transform = [];
  if (viewerPanX !== 0 || viewerPanY !== 0) {
    transform.push(`translate3d(${viewerPanX}px, ${viewerPanY}px, 0)`);
  }
  if (rotation !== 0) transform.push(`rotate(${rotation}deg)`);
  if (Math.abs(scale - 1) > 0.0001) transform.push(`scale(${scale})`);
  surface.style.transform = transform.join(" ");
  if (videoControlsVideo && !$("#videoControls").hidden) {
    placeVideoControls();
    followVideoControls(videoControlsVideo);
  }
  scheduleViewerLiveButtonPosition();
}

function resetViewerZoom() {
  viewerZoom = 1;
  viewerPanX = 0;
  viewerPanY = 0;
  viewerDrag = null;
  const surface = viewerZoomSurface();
  if (surface) {
    surface.classList.remove("is-panning");
    surface.style.transform = "";
  }
  $("#viewerStage").classList.remove("is-zoomed");
  applyViewerZoom();
}

function rememberViewerStageSize() {
  const rect = $("#viewerStage").getBoundingClientRect();
  viewerStageSize =
    rect.width > 0 && rect.height > 0
      ? { width: rect.width, height: rect.height }
      : null;
}

/* 查看器里已经放大并拖动过时，窗口尺寸变了要按比例挪回原来的画面位置；
   否则照片虽然还是同一个缩放倍数，眼前看到的内容会突然偏掉。 */
function preserveViewerPanOnResize() {
  const rect = $("#viewerStage").getBoundingClientRect();
  if (!rect.width || !rect.height) {
    viewerStageSize = null;
    return;
  }
  const previous = viewerStageSize;
  viewerStageSize = { width: rect.width, height: rect.height };
  if (!previous || viewerZoom <= 1.001) return;
  const ratio = Math.min(
    rect.width / previous.width,
    rect.height / previous.height,
  );
  if (!Number.isFinite(ratio) || ratio <= 0 || Math.abs(ratio - 1) < 0.001)
    return;
  viewerPanX *= ratio;
  viewerPanY *= ratio;
  applyViewerZoom();
}

function viewerResizeSurface() {
  const stage = $("#viewerStage");
  return stage.querySelector(".viewer-photo img, video");
}

/* 全屏切换时照片的布局尺寸会从窗口尺寸直接换成屏幕尺寸。
   先记住旧画面，切换后让它从旧尺寸平滑长到新尺寸，避免硬跳一格。 */
document.addEventListener("album:fullscreen-will-change", () => {
  if (viewerResizeFrame) cancelAnimationFrame(viewerResizeFrame);
  viewerResizeFrame = 0;
  const surface = viewerResizeSurface();
  const rect = surface?.getBoundingClientRect();
  viewerResizeFrom =
    rect && rect.width > 0 && rect.height > 0
      ? {
          x: rect.x,
          y: rect.y,
          width: rect.width,
          height: rect.height,
          surface,
        }
      : null;
});

document.addEventListener("album:fullscreen-changed", () => {
  const from = viewerResizeFrom;
  viewerResizeFrom = null;
  if (!from || !from.surface.isConnected || $("#viewer").hidden) return;
  if (viewerResizeFrame) cancelAnimationFrame(viewerResizeFrame);
  /* 原生窗口事件可能早于渲染器完成新尺寸布局一拍到达；
     等两帧再量终点，避免把旧尺寸当成新尺寸而跳过接续动画。 */
  viewerResizeFrame = requestAnimationFrame(() => {
    viewerResizeFrame = requestAnimationFrame(() => {
      viewerResizeFrame = 0;
      if (!from.surface.isConnected || $("#viewer").hidden) return;
      fitViewerImageToStage();
      fitViewerVideoToStage();
      const rect = from.surface.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      const reduced = window.matchMedia(
        "(prefers-reduced-motion: reduce)",
      ).matches;
      if (reduced) return;
      const scaleX = from.width / rect.width;
      const scaleY = from.height / rect.height;
      if (Math.abs(scaleX - 1) < 0.001 && Math.abs(scaleY - 1) < 0.001) return;
      from.surface.animate(
        [
          {
            transform: `translate(${from.x - rect.x}px, ${from.y - rect.y}px) scale(${scaleX}, ${scaleY})`,
            transformOrigin: "left top",
          },
          {
            transform: "translate(0, 0) scale(1)",
            transformOrigin: "left top",
          },
        ],
        {
          duration: 180,
          easing: "cubic-bezier(0.22, 0.72, 0.24, 1)",
        },
      );
    });
  });
});

function setViewerZoom(value) {
  if (!viewerZoomSurface()) return;
  /* 所有项目都可以在适配尺寸基础上继续缩小，最小到 25%。
     地图查看器和普通查看器共用这条范围，避免同类操作表现不一致。 */
  viewerZoom = Math.max(VIEWER_MIN_ZOOM, Math.min(VIEWER_MAX_ZOOM, value));
  if (viewerZoom <= 1) {
    viewerPanX = 0;
    viewerPanY = 0;
  }
  applyViewerZoom();
}

function rotateViewer(delta) {
  const surface = viewerZoomSurface();
  if (!surface) return;
  viewerRotation += delta;
  viewerPanX = 0;
  viewerPanY = 0;
  viewerDrag?.surface?.classList.remove("is-panning");
  viewerDrag = null;
  applyViewerZoom();
}

function rectSnapshot(rect) {
  return {
    left: rect.left,
    top: rect.top,
    width: rect.width,
    height: rect.height,
  };
}

/* 照片视口就是查看器舞台的完整内容框。按原始宽高取 contain 尺寸；
   只有启用「等比适配」时才允许超过原始像素尺寸，让较长的一维贴住舞台。 */
function viewerContainBox(
  sourceWidth,
  sourceHeight,
  containerWidth,
  containerHeight,
  { allowUpscale = true } = {},
) {
  if (
    ![sourceWidth, sourceHeight, containerWidth, containerHeight].every(
      (value) => Number.isFinite(value) && value > 0,
    )
  )
    return null;
  let scale = Math.min(
    containerWidth / sourceWidth,
    containerHeight / sourceHeight,
  );
  if (!allowUpscale) scale = Math.min(1, scale);
  const width = sourceWidth * scale;
  const height = sourceHeight * scale;
  return {
    left: (containerWidth - width) / 2,
    top: (containerHeight - height) / 2,
    width,
    height,
  };
}

function fitViewerImageToStage(image = $("#viewerPhoto > img")) {
  if (
    !image?.matches?.("img") ||
    !image.isConnected ||
    !image.naturalWidth ||
    !image.naturalHeight
  )
    return null;
  const stage = $("#viewerStage").getBoundingClientRect();
  if (!stage.width || !stage.height) return null;
  const box = viewerContainBox(
    image.naturalWidth,
    image.naturalHeight,
    stage.width,
    stage.height,
    {
      allowUpscale:
        viewerFitEnabled ||
        document.documentElement.classList.contains("is-fullscreen"),
    },
  );
  if (!box) return null;
  /* 启用等比适配后显式写出最大展示尺寸；关闭时仍允许大图等比缩小，
     但不会把低分辨率原图强制放大到舞台边缘。 */
  image.style.width = `${box.width}px`;
  image.style.height = `${box.height}px`;
  image.style.removeProperty("position");
  image.style.removeProperty("left");
  return box;
}

function viewerVideoCrop(video = $("#viewerStage > video")) {
  /* 能直接解码原视频时，在查看器里按编辑参数裁出可见区域即可。
     原文件保持只读，也不会为了看一眼裁剪区域先编码整段视频。 */
  if (video?.dataset.viewerVideoSource !== "original-crop") {
    return { x: 0, y: 0, w: 1, h: 1 };
  }
  const item = state.items[viewerIndex];
  const recipe = item?.editRecipe || viewerEditRecipes.get(Number(item?.id));
  const crop = recipe?.geometry?.crop;
  if (!crop) return { x: 0, y: 0, w: 1, h: 1 };
  const x = Math.min(1, Math.max(0, Number(crop.x) || 0));
  const y = Math.min(1, Math.max(0, Number(crop.y) || 0));
  return {
    x,
    y,
    w: Math.min(1 - x, Math.max(0.02, Number(crop.w) || 1)),
    h: Math.min(1 - y, Math.max(0.02, Number(crop.h) || 1)),
  };
}

function fitViewerVideoToStage(video = $("#viewerStage > video")) {
  if (
    !video?.matches?.("video") ||
    !video.isConnected ||
    !video.videoWidth ||
    !video.videoHeight
  )
    return null;
  const stage = $("#viewerStage").getBoundingClientRect();
  if (!stage.width || !stage.height) return null;
  const crop = viewerVideoCrop(video);
  const cropWidth = Math.max(2, video.videoWidth * crop.w);
  const cropHeight = Math.max(2, video.videoHeight * crop.h);
  const box = viewerContainBox(
    cropWidth,
    cropHeight,
    stage.width,
    stage.height,
  );
  if (!box) return null;
  const videoWidth = box.width / crop.w;
  const videoHeight = box.height / crop.h;
  const hasClientCrop =
    crop.x > 0.0005 || crop.y > 0.0005 || crop.w < 0.9995 || crop.h < 0.9995;
  video.style.position = "absolute";
  /* 查看器的通用样式把视频限制在舞台 100% 内。裁剪显示需要先把完整
     源视频铺到可比舞台更大的画布上，再由 clip-path 截出居中区域。 */
  video.style.maxWidth = hasClientCrop ? "none" : "";
  video.style.maxHeight = hasClientCrop ? "none" : "";
  video.style.width = `${videoWidth}px`;
  video.style.height = `${videoHeight}px`;
  video.style.left = `${box.left - crop.x * videoWidth}px`;
  video.style.top = `${box.top - crop.y * videoHeight}px`;
  video.style.objectFit = hasClientCrop ? "fill" : "contain";
  video.style.clipPath = hasClientCrop
    ? `inset(${crop.y * 100}% ${(1 - crop.x - crop.w) * 100}% ` +
      `${(1 - crop.y - crop.h) * 100}% ${crop.x * 100}%)`
    : "none";
  video.style.transformOrigin =
    `${(crop.x + crop.w / 2) * videoWidth}px ` +
    `${(crop.y + crop.h / 2) * videoHeight}px`;
  return {
    left: stage.left + box.left,
    top: stage.top + box.top,
    width: box.width,
    height: box.height,
  };
}

function viewerVideoVisibleRect(video = $("#viewerStage > video")) {
  if (!video?.isConnected) return null;
  const stage = $("#viewerStage").getBoundingClientRect();
  const rect = video.getBoundingClientRect();
  const crop = viewerVideoCrop(video);
  const left = Math.max(stage.left, rect.left + rect.width * crop.x);
  const top = Math.max(stage.top, rect.top + rect.height * crop.y);
  const right = Math.min(
    stage.right,
    rect.left + rect.width * (crop.x + crop.w),
  );
  const bottom = Math.min(
    stage.bottom,
    rect.top + rect.height * (crop.y + crop.h),
  );
  if (right - left < 1 || bottom - top < 1) return null;
  return { left, top, right, bottom };
}

function tileMorphRect(tile) {
  if (!tile) return null;
  const img = tile.querySelector("img");
  const source = isOriginalRatio() && img && img.naturalWidth ? img : tile;
  return rectSnapshot(source.getBoundingClientRect());
}

function centerContentTile(tile) {
  const content = $("#content");
  if (!tile?.isConnected || !content) return;
  const tileRect = tile.getBoundingClientRect();
  const contentRect = content.getBoundingClientRect();
  if (!tileRect.width || !tileRect.height || !contentRect.height) return;
  const tileCenter = tileRect.top + tileRect.height / 2;
  const contentCenter = contentRect.top + contentRect.height / 2;
  content.scrollTop += tileCenter - contentCenter;
}

function contentTileIsVisible(tile) {
  const content = $("#content");
  if (!tile?.isConnected || !content) return false;
  const tileRect = tile.getBoundingClientRect();
  const contentRect = content.getBoundingClientRect();
  if (!tileRect.width || !tileRect.height || !contentRect.height) return false;
  const centerX = tileRect.left + tileRect.width / 2;
  const centerY = tileRect.top + tileRect.height / 2;
  return (
    centerX >= contentRect.left &&
    centerX <= contentRect.right &&
    centerY >= contentRect.top &&
    centerY <= contentRect.bottom
  );
}

function viewerPhotoTargetRect(item, tile) {
  const stage = $("#viewerStage").getBoundingClientRect();
  const img = tile?.querySelector("img");
  /* 裁剪后的视频缩略图已经带有最终画面比例。优先使用它，
     避免进场时先按磁盘原视频的宽高铺开，再跳成裁剪后的尺寸。 */
  const knownVideoSize =
    item.kind === "video" && item.width > 0 && item.height > 0;
  const thumbnailVideoSize =
    item.kind === "video" && img?.naturalWidth > 0 && img?.naturalHeight > 0;
  /* 缩略图已经按 EXIF 方向转正，宽高比就是浏览器里最终看到的比例。
     元数据在 HEIC / RAW 和少数带镜像方向位的照片上不一定和实际显示一致，
     拿它来算落点会让过渡层在最后一刻露出尺寸差。 */
  const sourceWidth =
    (thumbnailVideoSize
      ? img.naturalWidth
      : knownVideoSize
        ? item.width
        : img?.naturalWidth) || (item.width > 0 ? item.width : stage.width);
  const sourceHeight =
    (thumbnailVideoSize
      ? img.naturalHeight
      : knownVideoSize
        ? item.height
        : img?.naturalHeight) || (item.height > 0 ? item.height : stage.height);
  /* 视频始终使用舞台内的最大等比尺寸；照片是否允许放大由「等比适配」控制。 */
  const box = viewerContainBox(
    sourceWidth,
    sourceHeight,
    stage.width,
    stage.height,
    { allowUpscale: item.kind === "video" || viewerFitEnabled },
  );
  const width = box?.width || stage.width;
  const height = box?.height || stage.height;
  return {
    left: stage.left + (box?.left ?? (stage.width - width) / 2),
    top: stage.top + (box?.top ?? (stage.height - height) / 2),
    width,
    height,
  };
}

function morphRectMatches(rect, target, epsilon = 0.75) {
  return (
    !!rect &&
    Math.abs(rect.left - target.left) <= epsilon &&
    Math.abs(rect.top - target.top) <= epsilon &&
    Math.abs(rect.width - target.width) <= epsilon &&
    Math.abs(rect.height - target.height) <= epsilon
  );
}

function createMorphClone(
  src,
  rect,
  back = false,
  fullSrc = "",
  sourceImg = null,
) {
  const clone = document.createElement("div");
  clone.className = `viewer-zoom-clone${back ? " is-back" : ""}`;
  clone.style.left = `${rect.left}px`;
  clone.style.top = `${rect.top}px`;
  clone.style.width = `${rect.width}px`;
  clone.style.height = `${rect.height}px`;
  /* 格子里已经画出来的缩略图优先复用：同一张解码结果可以直接上屏，
     不必等新 <img> 再解码一帧，短画面打开时不会先闪一条空底。 */
  const img =
    sourceImg?.complete && sourceImg.naturalWidth
      ? sourceImg.cloneNode(false)
      : document.createElement("img");
  if (!img.getAttribute("src")) img.src = src;
  /* 格子里的 onerror 只负责处理网格占位；交接层失败时应保留背景、
     由下一帧换图，不能去引用一个已经不存在的 .tile。 */
  img.removeAttribute("onerror");
  img.loading = "eager";
  img.decoding = "sync";
  img.alt = "";
  img.draggable = false;
  clone.appendChild(img);
  if (fullSrc) {
    const full = document.createElement("img");
    full.className = "morph-full";
    full.src = fullSrc;
    full.loading = "eager";
    full.decoding = "sync";
    full.alt = "";
    full.draggable = false;
    clone.appendChild(full);
    const showFull = () => {
      full.style.opacity = "1";
    };
    if (full.complete && full.naturalWidth) showFull();
    else full.addEventListener("load", showFull, { once: true });
    /* 原图偶尔加载失败时别让飞行动画一直等它；撤掉这层后，
       600px 缩略图仍能顶着，原图就绪后再交接。 */
    full.addEventListener("error", () => full.remove(), { once: true });
  }
  return clone;
}

/* 放大、旋转或拖动后的查看器画面需要连裁切、缩放和角度一起带走。
   外层从查看器舞台缩到格子，内层同时把 rotate / translate / scale 归零。 */
function createViewerStateCloseClone(stage, targetRect) {
  const stageRect = stage.getBoundingClientRect();
  const sourcePhoto = stage.querySelector(".viewer-photo");
  if (!sourcePhoto || !stageRect.width || !stageRect.height) return null;
  const wrapper = document.createElement("div");
  wrapper.className = "viewer-state-close";
  wrapper.style.left = `${stageRect.left}px`;
  wrapper.style.top = `${stageRect.top}px`;
  wrapper.style.width = `${stageRect.width}px`;
  wrapper.style.height = `${stageRect.height}px`;
  const photo = sourcePhoto.cloneNode(true);
  photo.removeAttribute("id");
  const transform = getComputedStyle(sourcePhoto).transform;
  photo.style.transform = transform;
  const targetImage = document.createElement("img");
  targetImage.className = "viewer-state-target";
  targetImage.src =
    photo.querySelector("img")?.currentSrc ||
    photo.querySelector("img")?.src ||
    "";
  targetImage.alt = "";
  targetImage.draggable = false;
  wrapper.append(photo, targetImage);
  document.body.append(wrapper);
  void wrapper.offsetWidth;
  return {
    wrapper,
    photo,
    targetImage,
    targetRect: rectSnapshot(targetRect),
    stageRect: rectSnapshot(stageRect),
  };
}

/* 视频退出不能直接克隆 <video>：媒体源释放后会黑屏，旋转后的
   getBoundingClientRect() 也只是外接矩形，拿它抓帧会把画面拉变形。
   这里抓未旋转的布局画面，再在退出层里复现查看器的 transform。 */
function createViewerVideoStateCloseClone(
  stage,
  video,
  targetRect,
  snapshotSrc,
  item,
) {
  const stageRect = stage.getBoundingClientRect();
  const width = video.offsetWidth;
  const height = video.offsetHeight;
  if (!stageRect.width || !stageRect.height || !width || !height || !item)
    return null;
  const wrapper = document.createElement("div");
  wrapper.className = "viewer-state-close is-video-state-back";
  wrapper.style.left = `${stageRect.left}px`;
  wrapper.style.top = `${stageRect.top}px`;
  wrapper.style.width = `${stageRect.width}px`;
  wrapper.style.height = `${stageRect.height}px`;
  const photo = document.createElement("div");
  photo.className = "viewer-photo";
  photo.style.transform = getComputedStyle(video).transform;
  const snapshot = document.createElement("img");
  snapshot.className = "viewer-state-frame";
  snapshot.src = snapshotSrc || openingPosterUrl(item);
  snapshot.alt = "";
  snapshot.draggable = false;
  snapshot.style.width = `${width}px`;
  snapshot.style.height = `${height}px`;
  photo.appendChild(snapshot);
  const targetImage = document.createElement("img");
  targetImage.className = "viewer-state-target";
  targetImage.src = itemThumbUrl(item, 600, "inside");
  targetImage.alt = "";
  targetImage.draggable = false;
  wrapper.append(photo, targetImage);
  addVideoChrome(wrapper, item);
  document.body.append(wrapper);
  void wrapper.offsetWidth;
  return {
    wrapper,
    photo,
    snapshot,
    targetImage,
    targetRect: rectSnapshot(targetRect),
    stageRect: rectSnapshot(stageRect),
  };
}

function placeMorphClone(clone, rect) {
  clone.style.left = `${rect.left}px`;
  clone.style.top = `${rect.top}px`;
  clone.style.width = `${rect.width}px`;
  clone.style.height = `${rect.height}px`;
}

function clearViewerVideoTimers() {
  for (const id of viewerVideoTimers) clearTimeout(id);
  viewerVideoTimers = [];
}

/* 离开视频时把媒体源也断掉。只 pause() 或移除 <video> 元素时，
   浏览器和本地服务可能还保留着视频请求，Windows 会因此锁住原文件。 */
function releaseViewerVideo(video) {
  if (!video) return;
  clearPendingVideoToggle();
  hideVideoControls();
  try {
    video.pause();
    video.removeAttribute("src");
    video.load();
  } catch {}
}

function viewerOriginalVideoUrl(item) {
  const version =
    `${Number(item?.mtime) || 0}-${Number(item?.size) || 0}-` +
    `${Number(item?.editRevision) || 0}`;
  return `/api/edit/video-source/${item.id}?v=${version}`;
}

async function loadViewerVideoSource(
  video,
  item,
  { editedPreview = false, sourceOverride = "" } = {},
) {
  if (!video?.isConnected || !item) return false;
  const hasEdit = !sourceOverride && Number(item.editRevision) > 0;
  if (hasEdit && !editedPreview && !item.editRecipe) {
    await refreshViewerEditButton(item);
    if (!video.isConnected || state.items[viewerIndex]?.id !== item.id) {
      return false;
    }
    /* 拿不到裁剪参数时不能把原视频当成未裁剪视频播放。 */
    if (!item.editRecipe) editedPreview = true;
  }
  const sourceMode = sourceOverride
    ? "compatible"
    : hasEdit && !editedPreview
      ? "original-crop"
      : "direct";
  const src =
    sourceOverride ||
    (sourceMode === "original-crop"
      ? viewerOriginalVideoUrl(item)
      : fileUrl(item));
  if (video.getAttribute("src") === src) {
    if (video.readyState >= 1 && video.videoWidth > 0) {
      fitViewerVideoToStage(video);
      applyViewerZoom();
      return true;
    }
    return false;
  }
  video.dataset.viewerVideoSource = sourceMode;
  const fit = () => {
    if (!video.isConnected || video.getAttribute("src") !== src) return;
    fitViewerVideoToStage(video);
    applyViewerZoom();
  };
  const ready = await new Promise((resolve) => {
    let settled = false;
    const finish = (ok) => {
      if (settled) return;
      settled = true;
      video.removeEventListener("loadedmetadata", onMetadata);
      video.removeEventListener("error", onError);
      resolve(ok);
    };
    const onMetadata = () => finish(true);
    const onError = () => finish(false);
    video.addEventListener("loadedmetadata", onMetadata, { once: true });
    video.addEventListener("error", onError, { once: true });
    video.preload = "auto";
    video.setAttribute("src", src);
    video.load();
  });
  if (
    ready &&
    video.isConnected &&
    video.getAttribute("src") === src &&
    state.items[viewerIndex]?.id === item.id
  ) {
    fit();
    return true;
  }
  return false;
}

async function loadCompatibleViewerVideo(
  video,
  item,
  stage,
  { autoplay = true } = {},
) {
  if (!video?.isConnected || !item || !stage) return false;
  video.classList.add("is-video-waiting");
  try {
    while (
      video.isConnected &&
      stage.isConnected &&
      state.items[viewerIndex]?.id === item.id
    ) {
      const result = await api(`/api/video/compatibility/${item.id}`);
      if (
        !video.isConnected ||
        !stage.isConnected ||
        state.items[viewerIndex]?.id !== item.id
      ) {
        return false;
      }
      if (result.status === "failed") {
        throw new Error("这个视频暂时无法生成兼容预览");
      }
      if (result.status === "ready" && result.url) {
        const loaded = await loadViewerVideoSource(video, item, {
          sourceOverride: result.url,
        });
        if (
          !loaded ||
          !video.isConnected ||
          state.items[viewerIndex]?.id !== item.id
        ) {
          return false;
        }
        const cover = stage.querySelector(".viewer-video-cover");
        if (autoplay) {
          revealViewerVideoWhenPlaying(video, cover);
        } else {
          video.classList.remove("is-video-waiting");
          cover?.remove();
        }
        return true;
      }
      await new Promise((resolve) => setTimeout(resolve, 650));
    }
  } catch (err) {
    if (
      video.isConnected &&
      stage.isConnected &&
      state.items[viewerIndex]?.id === item.id
    ) {
      hideVideoControls();
      resetVideoCursorState();
      clearViewerMorph();
      stage.innerHTML = `<div class="viewer-fallback">
        <p>这个视频暂时无法播放</p>
        <button class="primary-btn" onclick="openInSystem(${item.id})">用系统播放器打开</button>
      </div>`;
    }
  }
  return false;
}

function formatPlaybackTime(seconds, roundUp = false) {
  const value = Number(seconds);
  if (!Number.isFinite(value) || value < 0) return "0:00";
  const whole = roundUp ? Math.ceil(value) : Math.floor(value);
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

function placeVideoControls(video = videoControlsVideo) {
  const controls = $("#videoControls");
  if (controls.hidden || !video?.isConnected) return;
  const visible = viewerVideoVisibleRect(video);
  if (!visible) return;
  const { left, right, top, bottom } = visible;
  const height = Math.min(46, bottom - top);
  controls.style.left = `${Math.round(left)}px`;
  controls.style.width = `${Math.round(right - left)}px`;
  controls.style.top = `${Math.round(bottom - height)}px`;
  controls.style.height = `${Math.round(height)}px`;
}

/* 视频的 transform 有 0.38s 过渡，而控件是独立定位层。
   过渡期间逐帧读取视频当前可见边缘，进度条才不会先跳到终点。 */
function stopVideoControlsFollow() {
  if (!videoControlsFollowFrame) return;
  cancelAnimationFrame(videoControlsFollowFrame);
  videoControlsFollowFrame = 0;
}

function followVideoControls(video, duration = 460) {
  if (!video || video !== videoControlsVideo) return;
  stopVideoControlsFollow();
  const deadline = performance.now() + duration;
  const tick = () => {
    videoControlsFollowFrame = 0;
    if (
      !videoControlsVideo ||
      videoControlsVideo !== video ||
      $("#videoControls").hidden ||
      !video.isConnected
    )
      return;
    placeVideoControls(video);
    if (performance.now() >= deadline) return;
    videoControlsFollowFrame = requestAnimationFrame(tick);
  };
  videoControlsFollowFrame = requestAnimationFrame(tick);
}

function syncVideoControls(video = videoControlsVideo) {
  if (!video || video !== videoControlsVideo || !video.isConnected) return;
  const duration = Number.isFinite(video.duration) ? video.duration : 0;
  const current = Math.min(
    Number(video.currentTime) || 0,
    duration || Infinity,
  );
  const seek = $("#videoSeek");
  $("#videoTime").textContent =
    `${formatPlaybackTime(current)} / ${formatPlaybackTime(duration, true)}`;
  seek.max = String(duration || 0);
  seek.disabled = !duration;
  if (document.activeElement !== seek) seek.value = String(current);
  placeVideoControls(video);
}

function bindVideoControls(video) {
  video.controls = false;
  video.disablePictureInPicture = true;
  video.disableRemotePlayback = true;
  for (const eventName of [
    "loadedmetadata",
    "durationchange",
    "timeupdate",
    "play",
    "pause",
    "seeked",
  ]) {
    video.addEventListener(eventName, () => syncVideoControls(video));
  }
  video.addEventListener("ended", () => {
    if (
      !autoPlayNextVideoEnabled ||
      $("#viewer").hidden ||
      $("#viewer").classList.contains("is-closing") ||
      video !== $("#viewerStage video")
    ) {
      return;
    }
    const nextIndex = state.items.findIndex(
      (item, index) => index > viewerIndex && item?.kind === "video",
    );
    if (nextIndex >= 0) showViewerAt(nextIndex);
  });
  /* 这里只绑定事件。进度条尚未显示时，videoControlsVideo 必须保持 null，
     否则第一次鼠标移动会误判成“已经显示”，永远不会真正打开控件。 */
  if (videoControlsVideo === video) syncVideoControls(video);
}

function clearVideoControlsHideTimer() {
  if (!videoControlsHideTimer) return;
  clearTimeout(videoControlsHideTimer);
  videoControlsHideTimer = 0;
}

function scheduleVideoControlsHide(delay = VIDEO_CONTROLS_IDLE_MS) {
  clearVideoControlsHideTimer();
  if (videoControlsHeld) return;
  videoControlsHideTimer = setTimeout(() => {
    videoControlsHideTimer = 0;
    if (!videoControlsHeld) hideVideoControls();
  }, delay);
}

function clearVideoCursorIdleTimer() {
  if (!videoCursorIdleTimer) return;
  clearTimeout(videoCursorIdleTimer);
  videoCursorIdleTimer = 0;
}

function scheduleVideoCursorIdleHide() {
  clearVideoCursorIdleTimer();
  const viewer = $("#viewer");
  if (viewerDateOpen || viewerInfoOpen) {
    viewer.classList.remove("video-cursor-hidden");
    return;
  }
  if (
    viewer.hidden ||
    viewer.classList.contains("is-closing") ||
    videoControlsVideo
  )
    return;
  videoCursorIdleTimer = setTimeout(() => {
    videoCursorIdleTimer = 0;
    if (!videoControlsVideo && !viewer.hidden) {
      viewer.classList.add("video-cursor-hidden");
    }
  }, VIDEO_CONTROLS_IDLE_MS);
}

function resetVideoCursorState() {
  clearVideoCursorIdleTimer();
  videoCursorActivated = false;
  $("#viewer").classList.remove("video-cursor-hidden");
}

function hideVideoControls() {
  clearVideoControlsHideTimer();
  clearVideoCursorIdleTimer();
  videoControlsHeld = false;
  stopVideoControlsFollow();
  if (videoControlsFrame) {
    cancelAnimationFrame(videoControlsFrame);
    videoControlsFrame = 0;
  }
  videoControlsVideo = null;
  const controls = $("#videoControls");
  controls.hidden = true;
  const viewer = $("#viewer");
  if (
    videoCursorActivated &&
    !viewerDateOpen &&
    !viewerInfoOpen &&
    !viewer.hidden &&
    !viewer.classList.contains("is-closing")
  ) {
    viewer.classList.add("video-cursor-hidden");
  }
}

function showVideoControls(video, hideAfter = VIDEO_CONTROLS_IDLE_MS) {
  if (!video?.isConnected) return;
  clearVideoCursorIdleTimer();
  videoCursorActivated = true;
  $("#viewer").classList.remove("video-cursor-hidden");
  videoControlsVideo = video;
  $("#videoControls").hidden = false;
  syncVideoControls(video);
  if (videoControlsFrame) cancelAnimationFrame(videoControlsFrame);
  videoControlsFrame = requestAnimationFrame(() => {
    videoControlsFrame = 0;
    syncVideoControls(video);
  });
  scheduleVideoControlsHide(hideAfter);
}

function viewerVideoAtPoint(clientX, clientY) {
  const viewer = $("#viewer");
  if (viewer.hidden || viewer.classList.contains("is-closing")) return null;
  if (state.items[viewerIndex]?.kind !== "video") return null;
  /* 信息卡是视频上方的可交互层。鼠标压在卡片上时不能穿透到视频，
     即使卡片当前正好盖在视频画面内。 */
  if (viewerInfoOpen) {
    const popup = $("#viewerInfoPopover");
    const popupRect = popup.getBoundingClientRect();
    const overInfo =
      !popup.hidden &&
      clientX >= popupRect.left &&
      clientX <= popupRect.right &&
      clientY >= popupRect.top &&
      clientY <= popupRect.bottom;
    if (overInfo) return null;
  }
  const video = $("#viewerStage video");
  if (
    !video?.isConnected ||
    video.classList.contains("is-video-waiting") ||
    viewerMorphClone
  ) {
    return null;
  }
  const visible = viewerVideoVisibleRect(video);
  if (!visible) return null;
  const { left, top, right, bottom } = visible;
  const inside =
    clientX >= left && clientX <= right && clientY >= top && clientY <= bottom;
  return inside ? video : null;
}

function updateVideoControlsForPointer(clientX, clientY) {
  if (videoControlsHeld) return;
  /* 拖信息卡期间只处理卡片位移。鼠标即使经过视频，也仍被卡片捕获，
     不能因此唤出进度条。 */
  if (viewerInfoDrag) {
    if (videoControlsVideo) hideVideoControls();
    return;
  }
  const video = viewerVideoAtPoint(clientX, clientY);
  if (!video) {
    if (videoControlsVideo) hideVideoControls();
    return;
  }
  if (videoControlsVideo !== video) showVideoControls(video);
  else scheduleVideoControlsHide();
}

function toggleVideoPlayback(video) {
  if (!video?.isConnected) return;
  if (video.paused) {
    playViewerVideo(video);
  } else {
    video.pause();
  }
}

function makeViewerVideoAudible(video) {
  if (!video) return;
  video.muted = false;
  video.volume = 1;
}

function clearPendingVideoToggle() {
  if (!videoClickToggleTimer) return;
  clearTimeout(videoClickToggleTimer);
  videoClickToggleTimer = 0;
}

function scheduleVideoPlaybackToggle(video) {
  clearPendingVideoToggle();
  const paused = video.paused;
  videoClickToggleTimer = setTimeout(() => {
    videoClickToggleTimer = 0;
    if (!video.isConnected || video.paused !== paused) return;
    toggleVideoPlayback(video);
  }, VIDEO_SINGLE_CLICK_DELAY);
}

function playViewerVideo(video) {
  if (!video?.isConnected) return;
  makeViewerVideoAudible(video);
  const attempt = video.play();
  if (!attempt?.catch) return;
  attempt.catch(() => {});
}

function restartViewerVideoWithAudio(video) {
  if (!video?.isConnected) return;
  try {
    video.pause();
    video.currentTime = 0;
  } catch {}
  makeViewerVideoAudible(video);
  video.play().catch(() => {});
}

function setLiveInfoBreathing(root, playing) {
  root?.querySelectorAll?.(".viewer-info-live-icon").forEach((icon) => {
    icon.classList.toggle("is-breathing", playing);
  });
}

function setViewerLivePlaying(playing) {
  const button = $("#viewerLiveButton");
  const photo = $("#viewerPhoto");
  const video = photo?.querySelector(".viewer-live-video");
  button?.classList.toggle("is-playing", playing);
  button?.setAttribute("aria-pressed", String(playing));
  button?.setAttribute(
    "aria-label",
    playing ? "停止播放实况照片" : "播放实况照片",
  );
  photo?.classList.toggle("is-live-playing", playing);
  video?.classList.toggle("is-playing", playing);
  $("#viewerInfoLiveIcon")?.classList.toggle("is-breathing", playing);
}

function stopLiveMotion({ reveal = true } = {}) {
  viewerLivePlayRequest += 1;
  if (viewerLiveHoverTimer) {
    clearTimeout(viewerLiveHoverTimer);
    viewerLiveHoverTimer = 0;
  }
  if (viewerLiveLeaveTimer) {
    clearTimeout(viewerLiveLeaveTimer);
    viewerLiveLeaveTimer = 0;
  }
  const video = $("#viewerPhoto .viewer-live-video");
  if (!video) {
    setViewerLivePlaying(false);
    return;
  }
  video.pause();
  video.muted = true;
  setViewerLivePlaying(false);
  if (reveal) {
    const image = $("#viewerPhoto img");
    if (image) image.style.removeProperty("opacity");
  }
}

function waitForViewerLiveFrame(video, request) {
  return new Promise((resolve) => {
    if (!video?.isConnected) {
      resolve(false);
      return;
    }
    let settled = false;
    let frameHandle = null;
    let fallbackFrame = 0;
    const live = () =>
      request === viewerLivePlayRequest && video.isConnected && !video.paused;
    const finish = (ready) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (fallbackFrame) cancelAnimationFrame(fallbackFrame);
      if (frameHandle != null && video.cancelVideoFrameCallback) {
        try {
          video.cancelVideoFrameCallback(frameHandle);
        } catch {}
      }
      video.removeEventListener("playing", onPlaying);
      resolve(ready && live());
    };
    const onPlaying = () => {
      if (!live()) return finish(false);
      requestAnimationFrame(() => {
        fallbackFrame = requestAnimationFrame(() => finish(live()));
      });
    };
    if (typeof video.requestVideoFrameCallback === "function") {
      frameHandle = video.requestVideoFrameCallback(() => {
        frameHandle = null;
        finish(live());
      });
    } else {
      video.addEventListener("playing", onPlaying, { once: true });
    }
    const timer = setTimeout(() => finish(false), 1800);
  });
}

function playLiveMotion() {
  const item = state.items[viewerIndex];
  const video = $("#viewerPhoto .viewer-live-video");
  if (!item || !isLivePhoto(item) || !video?.isConnected) return;
  placeViewerLiveVideo();
  const request = ++viewerLivePlayRequest;
  const beginCrossfade = () => {
    if (request !== viewerLivePlayRequest || !video.isConnected || video.paused)
      return;
    setViewerLivePlaying(true);
    /* 首帧已经可以显示时再开声音，不让音轨先于动态画面出现。 */
    makeViewerVideoAudible(video);
  };
  video.pause();
  video.muted = true;
  video.volume = 1;
  try {
    video.currentTime = 0;
  } catch {}
  /* 首帧回调必须在 play() 之前排好，避免视频已经出画而错过交接点。 */
  const firstFrame = waitForViewerLiveFrame(video, request);
  const attempt = video.play();
  let waiting = false;
  const waitForHandoff = () => {
    if (waiting) return;
    waiting = true;
    firstFrame.then((ready) => {
      if (ready) {
        beginCrossfade();
      } else if (request === viewerLivePlayRequest) {
        stopLiveMotion();
        toast("这段实况视频暂时没有可显示的画面");
      }
    });
  };
  if (!attempt?.catch) {
    waitForHandoff();
    return;
  }
  attempt.then(waitForHandoff).catch(() => {
    if (request !== viewerLivePlayRequest || !video.isConnected) return;
    stopLiveMotion();
    toast("这段实况视频暂时无法播放");
  });
}

function placeViewerLiveButton() {
  const button = $("#viewerLiveButton");
  if (!button?.isConnected || button.hidden) return;
  const image = $("#viewerPhoto img");
  if (!image?.isConnected || image.offsetWidth < 1 || image.offsetHeight < 1)
    return;
  /* 标记和照片处在同一个变换层里。使用未受 transform 影响的布局坐标，
     缩放、拖动和旋转就会由外层统一带动，舞台边缘也自然负责裁切。 */
  const inset = 8;
  button.style.left = `${image.offsetLeft + image.offsetWidth - inset - button.offsetWidth}px`;
  button.style.right = "auto";
  button.style.top = `${image.offsetTop + inset}px`;
}

function placeViewerLiveVideo() {
  const image = $("#viewerPhoto img");
  const video = $("#viewerPhoto .viewer-live-video");
  if (
    !image?.isConnected ||
    !video?.isConnected ||
    image.offsetWidth < 1 ||
    image.offsetHeight < 1
  )
    return;
  /* 静态图按自身尺寸居中，不再强制铺满查看器。视频使用同一组布局坐标，
     播放时只替换画面内容，不改变打开项目后的显示大小和位置。 */
  video.style.left = `${image.offsetLeft}px`;
  video.style.top = `${image.offsetTop}px`;
  video.style.width = `${image.offsetWidth}px`;
  video.style.height = `${image.offsetHeight}px`;
  video.style.objectFit = "fill";
  video.style.transform = "";
  video.style.transformOrigin = "center center";
  const item = state.items[viewerIndex];
  const recipe = item?.editRecipe || viewerEditRecipes.get(Number(item?.id));
  const crop = recipe?.geometry?.crop;
  if (
    crop &&
    (crop.x > 0.0005 || crop.y > 0.0005 || crop.w < 0.9995 || crop.h < 0.9995)
  ) {
    const width = image.offsetWidth / Math.max(0.02, crop.w);
    const height = image.offsetHeight / Math.max(0.02, crop.h);
    video.style.width = `${width}px`;
    video.style.height = `${height}px`;
    video.style.left = `${image.offsetLeft - crop.x * width}px`;
    video.style.top = `${image.offsetTop - crop.y * height}px`;
  }
  if (recipe?.geometry?.mirrorX) {
    video.style.transform = "scaleX(-1)";
  }
}

function scheduleViewerLiveButtonPosition() {
  if (viewerLiveButtonFrame) return;
  viewerLiveButtonFrame = requestAnimationFrame(() => {
    viewerLiveButtonFrame = 0;
    placeViewerLiveVideo();
    placeViewerLiveButton();
  });
}

function livePhotoGlyphHTML() {
  return `<svg viewBox="0 0 18 18">
      <circle cx="9" cy="9" r="2.8" fill="none" stroke="currentColor"
              stroke-width="2.15"/>
      <circle cx="9" cy="9" r="5.35" fill="none" stroke="currentColor"
              stroke-width="0.82"/>
      <circle cx="9" cy="9" r="7.35" fill="none" stroke="currentColor"
              stroke-width="1.08" stroke-linecap="round"
              stroke-dasharray="0.01 1.9"/>
    </svg>`;
}

function viewerLiveMarkHTML() {
  return `<span class="viewer-live-mark" aria-hidden="true">
    ${livePhotoGlyphHTML()}
  </span>`;
}

/* 翻页 / 键盘打开视频时没有共享元素封面，用一张封面图先顶住，
   等视频真的播过开场黑帧再淡出。飞入路径由 startVideoFlight 自己接管。 */
function revealViewerVideoWhenPlaying(video, cover) {
  const started = performance.now();
  let done = false;
  let coverPainted = !cover;
  const coverImg = cover?.querySelector("img");
  if (coverImg) {
    if (coverImg.complete && coverImg.naturalWidth) coverPainted = true;
    else {
      coverImg.addEventListener(
        "load",
        () => {
          coverPainted = true;
        },
        { once: true },
      );
      coverImg.addEventListener(
        "error",
        () => {
          coverPainted = true;
        },
        { once: true },
      );
    }
  }
  const finish = () => {
    if (done || !video.isConnected) return;
    done = true;
    video.classList.remove("is-video-waiting");
    /* 先让视频在封面下面完整露出来，等它真的画上一帧再淡封面。
       直接同时改两层透明度，中间会透出背后的磨砂，看着像闪一下。 */
    requestAnimationFrame(() =>
      requestAnimationFrame(() => {
        scheduleVideoCursorIdleHide();
        /* 封面退场时从同一媒体时间点同时开始画面和声音。 */
        restartViewerVideoWithAudio(video);
        if (!cover?.isConnected) return;
        cover.classList.add("is-arrived");
        setTimeout(() => cover.remove(), 240);
      }),
    );
  };
  const tick = () => {
    if (done || !video.isConnected) return;
    if (
      (video.readyState >= 2 && coverPainted) ||
      performance.now() - started > 2200
    ) {
      finish();
      return;
    }
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

function clearViewerMorph() {
  viewerMorphClone?.remove();
  viewerMorphClone = null;
  clearViewerVideoTimers();
  const stage = $("#viewerStage");
  stage.classList.remove("is-morphing");
  /* 封面层被强行打断（按 X 看信息、翻页等）时，让底下等着的视频直接露面，
     别留下一个透明的空位。 */
  const video = stage.querySelector("video");
  if (video?.classList.contains("is-video-waiting")) {
    video.classList.remove("is-video-waiting");
    playViewerVideo(video);
  }
}

function cancelViewerClose() {
  if (viewerCloseTimer) {
    clearTimeout(viewerCloseTimer);
    viewerCloseTimer = null;
  }
  const viewer = $("#viewer");
  if (!viewer.hidden) document.body.classList.add("viewer-open");
  viewer.classList.remove("is-closing", "is-video-closing");
  viewer.style.removeProperty("--video-close-fade");
  document.body.classList.remove("viewer-returning");
  viewerCloseClone?.remove();
  viewerCloseClone = null;
}

let viewerFilmstripScrollFrame = 0;

function viewerFilmstripThumbHTML(item, index) {
  const selected = index === viewerIndex;
  const duration = item.kind === "video" ? formatDuration(item.duration) : "";
  const aspect = photoAspect(item).toFixed(4);
  return `<button class="filmstrip-thumb viewer-filmstrip-thumb${
    selected ? " is-current" : ""
  }" type="button"
    data-viewer-filmstrip-thumb="${index}"
    style="--filmstrip-thumb-ar:${aspect}"
    aria-label="${esc(item.name || `项目 ${index + 1}`)}"
    aria-current="${selected ? "true" : "false"}"
    tabindex="${selected ? 0 : -1}">
    <img src="${itemThumbUrl(item, 240, "inside")}" alt="" loading="lazy"
      draggable="false">
    ${duration ? `<span class="filmstrip-thumb-duration">${duration}</span>` : ""}
  </button>`;
}

function scrollViewerFilmstripSelection({
  behavior = "smooth",
  immediate = false,
} = {}) {
  const track = $("#viewerFilmstripTrack");
  const thumb = track?.querySelector(".viewer-filmstrip-thumb.is-current");
  if (!track || !thumb) return;
  track.classList.toggle("is-short", track.scrollWidth <= track.clientWidth);
  if (track.scrollWidth <= track.clientWidth) return;
  const left = thumb.offsetLeft - (track.clientWidth - thumb.offsetWidth) / 2;
  if (immediate) {
    const previousBehavior = track.style.scrollBehavior;
    track.style.scrollBehavior = "auto";
    track.scrollLeft = Math.max(0, left);
    void track.offsetWidth;
    track.style.scrollBehavior = previousBehavior;
    return;
  }
  track.scrollTo({
    left: Math.max(0, left),
    behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
      ? "auto"
      : behavior,
  });
}

function scheduleViewerFilmstripSelectionScroll(options = {}) {
  cancelAnimationFrame(viewerFilmstripScrollFrame);
  viewerFilmstripScrollFrame = requestAnimationFrame(() => {
    viewerFilmstripScrollFrame = 0;
    scrollViewerFilmstripSelection(options);
  });
}

function syncViewerFilmstrip({
  scroll = false,
  resetScroll = false,
  instant = false,
} = {}) {
  const viewer = $("#viewer");
  const bar = $("#viewerFilmstrip");
  const track = $("#viewerFilmstripTrack");
  if (!viewer || !bar || !track) return;
  const filmstripEnabled =
    viewerFilmstripMode === "group" ||
    (viewerFilmstripMode !== "hidden" && viewerFilmstripEnabled);
  const visible =
    filmstripEnabled &&
    !state.ratingMode &&
    !viewer.hidden &&
    !viewer.classList.contains("is-closing") &&
    !photoEditorOpen &&
    !photoWallCropSession &&
    state.items.length > 0;
  bar.hidden = !visible;
  if (!visible) {
    cancelAnimationFrame(viewerFilmstripScrollFrame);
    viewerFilmstripScrollFrame = 0;
    return;
  }

  const first = state.items[0];
  const last = state.items[state.items.length - 1];
  const signature = `${state.items.length}:${first?.id ?? ""}:${last?.id ?? ""}`;
  if (track.dataset.itemsSignature !== signature) {
    track.innerHTML = state.items
      .map((item, index) => viewerFilmstripThumbHTML(item, index))
      .join("");
    track.dataset.itemsSignature = signature;
    track.scrollLeft = 0;
    if (instant) scrollViewerFilmstripSelection({ immediate: true });
    else scheduleViewerFilmstripSelectionScroll({ behavior: "auto" });
    return;
  }

  const thumbs = track.querySelectorAll(".viewer-filmstrip-thumb");
  thumbs.forEach((thumb, index) => {
    const selected = index === viewerIndex;
    thumb.classList.toggle("is-current", selected);
    thumb.setAttribute("aria-current", selected ? "true" : "false");
    thumb.tabIndex = selected ? 0 : -1;
  });
  if (resetScroll) {
    track.scrollLeft = 0;
    scheduleViewerFilmstripSelectionScroll({ behavior: "auto" });
  } else if (scroll) {
    if (instant) {
      cancelAnimationFrame(viewerFilmstripScrollFrame);
      viewerFilmstripScrollFrame = 0;
      scrollViewerFilmstripSelection({ immediate: true });
    } else {
      scheduleViewerFilmstripSelectionScroll();
    }
  }
}

function openViewer(index, options = {}) {
  if (!state.items.length) return;
  clearViewerPhotoSwitchLayers();
  const openingItem = state.items[index];
  photoWallCropSession =
    state.activeId === "photoWall" &&
    !state.photoWall &&
    openingItem?.kind === "photo";
  photoWallCropEntry = options.cropEntry || "viewer";
  photoWallCropConfirmed = false;
  cancelViewerClose();
  clearPinnedHover();
  clearViewerMorph();
  viewerIndex = index;
  viewerOpenedItemId = openingItem?.id == null ? null : Number(openingItem.id);
  state.cursor = index;
  const item = state.items[index];
  if (item) state.zoomAnchorId = item.id;
  const tile = tileAt(index);
  const startRect = tileMorphRect(tile);
  const thumbImg = tile?.querySelector("img");
  const thumbSrc =
    thumbImg?.currentSrc || thumbImg?.src || itemThumbUrl(item, 600, "inside");
  const viewer = $("#viewer");
  /* 相册开场动画的 fill: both 会在格子上留下一层带滤镜的合成结果。
     开始放大前把它收掉，避免查看器首帧还叠着原位置的旧画面。 */
  tile
    ?.querySelector(".shot")
    ?.getAnimations()
    .forEach((animation) => animation.cancel());
  document.body.classList.add("viewer-open");
  viewer.hidden = false;
  requestAnimationFrame(() => {
    if (!viewer.hidden) viewer.focus({ preventScroll: true });
  });
  /* 视频要等封面飞到落点附近再起播，所以这里先别自动播放 */
  const autoplay = !(item.kind === "video" && startRect && startRect.width > 0);
  showViewerItem({
    autoplay,
    deferVideoSource: !autoplay,
    liveDuringMorph: !!(startRect && startRect.width > 0),
    instantFilmstrip: true,
  });
  rememberViewerStageSize();
  viewer.classList.toggle("has-multi", state.items.length > 1);
  viewer.classList.remove("is-opening");
  void viewer.offsetWidth;
  viewer.classList.add("is-opening");
  setTimeout(() => viewer.classList.remove("is-opening"), 320);

  if (startRect && startRect.width > 0 && item.kind !== "video") {
    const stage = $("#viewerStage");
    const targetRect = viewerPhotoTargetRect(item, tile);
    stage.classList.add("is-morphing");
    const actualImg = $("#viewerPhoto img");
    const fullSrc = actualImg?.src || "";
    const clone = createMorphClone(
      thumbSrc,
      startRect,
      false,
      fullSrc,
      thumbImg,
    );
    if (isLivePhoto(item)) {
      const liveMark = document.createElement("span");
      liveMark.className = "viewer-live-button viewer-live-flight-mark";
      liveMark.innerHTML = viewerLiveMarkHTML();
      clone.appendChild(liveMark);
    }
    viewerMorphClone = clone;
    viewer.appendChild(clone);
    const morphFull = clone.querySelector(".morph-full");
    void clone.offsetWidth;
    placeMorphClone(clone, targetRect);
    clone.style.borderRadius = "0px";
    /* CSS 过渡和 setTimeout 是两个独立的时钟：过渡实际会在样式提交后的下一帧
       才开始，固定等 380ms 时经常还差最后一小段。那一下会露出过渡层和原图之间
       的一圈错位。这里改成逐帧等它真的落到目标位置，再把画面交给原图。 */
    let goal = targetRect;
    let syncedToImage = false;
    let stableFrames = 0;
    const started = performance.now();
    const reveal = () => {
      if (viewerMorphClone !== clone) return;
      stage.classList.remove("is-morphing");
      /* 先让真正的原图在同一位置画出来，两帧后再撤掉过渡层。
         这时两层尺寸已经完全一致，直接交接不会有残影；再做透明度淡出
         反而会让浏览器在中途按低分辨率重绘原图，看起来像柔焦闪一下。 */
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          if (viewerMorphClone !== clone) return;
          clone.remove();
          viewerMorphClone = null;
        });
      });
    };
    const tick = () => {
      if (viewerMorphClone !== clone) return;
      const ready =
        !!actualImg && actualImg.complete && actualImg.naturalWidth > 0;
      /* 过渡层里除了 600px 缩略图，还叠了一张原图；原图没接上就撤层，
         会先露出缩略图的柔焦，再变清楚，看起来就是最后闪一下。
         两层都就绪后再交接。 */
      const fullReady =
        !morphFull ||
        !morphFull.isConnected ||
        (morphFull.complete &&
          morphFull.naturalWidth > 0 &&
          morphFull.style.opacity === "1");
      if (ready && !syncedToImage) {
        const rect = actualImg.getBoundingClientRect();
        if (rect.width > 0) {
          const exact = rectSnapshot(rect);
          if (!morphRectMatches(exact, targetRect, 1)) {
            goal = exact;
            placeMorphClone(clone, goal);
          }
          syncedToImage = true;
        }
      }
      const settled = morphRectMatches(clone.getBoundingClientRect(), goal);
      stableFrames = settled ? stableFrames + 1 : 0;
      if (
        (ready && fullReady && stableFrames >= 2) ||
        performance.now() - started > 2500
      ) {
        reveal();
        return;
      }
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }

  if (startRect && startRect.width > 0 && item.kind === "video") {
    startVideoFlight(item, tile, startRect, thumbSrc);
  }
}

function hidePhotoWallCrop() {
  photoWallCropSession = false;
  photoWallCropDrag = null;
  photoWallCropImageRect = null;
  photoWallCropConfirmed = false;
  photoWallCropConfirmAnim?.cancel();
  photoWallCropConfirmAnim = null;
  if (photoWallCropPositionFrame) {
    cancelAnimationFrame(photoWallCropPositionFrame);
    photoWallCropPositionFrame = 0;
  }
  const layer = $("#photoWallCropLayer");
  const frame = $("#photoWallCropFrame");
  layer?.setAttribute("hidden", "");
  layer?.setAttribute("aria-hidden", "true");
  frame?.classList.remove("is-visible", "is-confirming");
  $("#viewer").classList.remove("is-photo-wall-cropping");
}

function hidePhotoWallCropLater() {
  /* 等共享元素放大交接完成后再撤掉裁剪框，避免退出时先露出一个空框。 */
  const frame = $("#photoWallCropFrame");
  frame?.classList.remove("is-visible");
  $("#photoWallCropLayer")?.setAttribute("aria-hidden", "true");
  setTimeout(hidePhotoWallCrop, 240);
}

function layoutPhotoWallCropFrame() {
  photoWallCropPositionFrame = 0;
  if (!photoWallCropSession) return;
  const image = $("#viewerPhoto > img");
  const layer = $("#photoWallCropLayer");
  const frame = $("#photoWallCropFrame");
  if (!image || !layer || !frame || image.hidden) return;
  const imageRect = image.getBoundingClientRect();
  const layerRect = layer.getBoundingClientRect();
  if (
    imageRect.width < 2 ||
    imageRect.height < 2 ||
    layerRect.width < 2 ||
    layerRect.height < 2
  )
    return;
  const width = Math.min(imageRect.width, imageRect.height);
  const side = Math.min(
    width,
    Math.max(width * 0.5, width * photoWallCropFrameState.size),
  );
  const leftLimit = imageRect.left - layerRect.left;
  const topLimit = imageRect.top - layerRect.top;
  let centerX = leftLimit + photoWallCropFrameState.x * imageRect.width;
  let centerY = topLimit + photoWallCropFrameState.y * imageRect.height;
  centerX = Math.min(
    leftLimit + imageRect.width - side / 2,
    Math.max(leftLimit + side / 2, centerX),
  );
  centerY = Math.min(
    topLimit + imageRect.height - side / 2,
    Math.max(topLimit + side / 2, centerY),
  );
  const left = centerX - side / 2;
  const top = centerY - side / 2;
  frame.style.left = `${left}px`;
  frame.style.top = `${top}px`;
  frame.style.width = `${side}px`;
  frame.style.height = `${side}px`;
  photoWallCropFrameState = {
    ...photoWallCropFrameState,
    x: (centerX - leftLimit) / imageRect.width,
    y: (centerY - topLimit) / imageRect.height,
    size: side / width,
  };
  photoWallCropImageRect = {
    left: leftLimit,
    top: topLimit,
    width: imageRect.width,
    height: imageRect.height,
  };
}

function schedulePhotoWallCropLayout() {
  if (!photoWallCropSession) return;
  if (photoWallCropPositionFrame)
    cancelAnimationFrame(photoWallCropPositionFrame);
  photoWallCropPositionFrame = requestAnimationFrame(() => {
    layoutPhotoWallCropFrame();
    requestAnimationFrame(layoutPhotoWallCropFrame);
  });
}

function animateCropConfirmation(frame) {
  if (!frame) return null;
  const left = frame.offsetLeft;
  const top = frame.offsetTop;
  const width = frame.offsetWidth;
  const height = frame.offsetHeight;
  const barWidth = Math.min(44, Math.max(30, width * 0.24));
  const barHeight = 3;
  const targetLeft = left + (width - barWidth) / 2;
  const targetTop = top + (height - barHeight) / 2;
  const dotWidth = 18;
  const dotLeft = left + (width - dotWidth) / 2;
  frame.classList.add("is-confirming");
  return frame.animate(
    [
      {
        left: `${left}px`,
        top: `${top}px`,
        width: `${width}px`,
        height: `${height}px`,
        opacity: 1,
        borderRadius: "0px",
        offset: 0,
      },
      {
        left: `${targetLeft}px`,
        top: `${targetTop}px`,
        width: `${barWidth}px`,
        height: `${barHeight}px`,
        opacity: 0.9,
        borderRadius: "2px",
        offset: 0.62,
      },
      {
        left: `${dotLeft}px`,
        top: `${targetTop}px`,
        width: `${dotWidth}px`,
        height: "2px",
        opacity: 0.65,
        borderRadius: "1px",
        offset: 0.8,
      },
      {
        left: `${dotLeft}px`,
        top: `${targetTop}px`,
        width: `${dotWidth}px`,
        height: "2px",
        opacity: 0,
        borderRadius: "1px",
        offset: 1,
      },
    ],
    {
      duration: window.matchMedia("(prefers-reduced-motion: reduce)").matches
        ? 1
        : 460,
      easing: "cubic-bezier(0.22, 0.72, 0.24, 1)",
      fill: "forwards",
    },
  );
}

function showPhotoWallCrop(item) {
  if (!photoWallCropSession || item?.kind !== "photo") {
    hidePhotoWallCrop();
    return;
  }
  photoWallCropConfirmed = false;
  photoWallCropConfirmAnim?.cancel();
  photoWallCropConfirmAnim = null;
  photoWallCropFrameState = photoWallCropForItem(item);
  photoWallCropOriginalState = { ...photoWallCropFrameState };
  const layer = $("#photoWallCropLayer");
  const frame = $("#photoWallCropFrame");
  $("#viewer").classList.add("is-photo-wall-cropping");
  layer.hidden = false;
  layer.setAttribute("aria-hidden", "false");
  frame.classList.remove("is-visible", "is-confirming");
  const image = $("#viewerPhoto > img");
  const reveal = () => {
    schedulePhotoWallCropLayout();
    setTimeout(() => {
      if (photoWallCropSession && $("#viewerPhoto > img") === image) {
        schedulePhotoWallCropLayout();
        frame.classList.add("is-visible");
      }
    }, 360);
  };
  if (image?.complete && image.naturalWidth > 0) reveal();
  else image?.addEventListener("load", reveal, { once: true });
}

async function savePhotoWallCrop(confirmation = null) {
  const item = state.items[viewerIndex];
  if (!item || item.kind !== "photo") return;
  try {
    const request = api("/api/photo-wall/crop", {
      method: "POST",
      body: JSON.stringify({
        itemId: item.id,
        x: photoWallCropFrameState.x,
        y: photoWallCropFrameState.y,
        size: photoWallCropFrameState.size,
      }),
    });
    const [result] = await Promise.all([
      request,
      confirmation?.finished.catch(() => {}),
    ]);
    item.photoWallCropX = result.crop.x;
    item.photoWallCropY = result.crop.y;
    item.photoWallCropSize = result.crop.size;
    item.photoWallCropUpdatedAt = result.crop.updatedAt;
    const tile = tileAt(viewerIndex);
    const image = tile?.querySelector("img");
    if (image) image.src = photoWallThumbUrl(item, 800);
    for (const album of state.photoWallAlbums) {
      if (album.coverItemId === item.id) {
        album.coverCrop = result.crop;
        const cardImage = document.querySelector(
          `.photo-wall-library-card[data-photo-wall-album="${album.id}"] img`,
        );
        if (cardImage) cardImage.src = photoWallAlbumCoverUrl(album, 400);
      }
    }
    photoWallCropConfirmed = true;
    photoWallCropFrameState = { ...result.crop };
    photoWallCropOriginalState = { ...result.crop };
    if (photoWallCropEntry === "context") {
      closeViewer();
    } else {
      const layer = $("#photoWallCropLayer");
      const frame = $("#photoWallCropFrame");
      photoWallCropConfirmAnim?.cancel();
      photoWallCropConfirmAnim = null;
      frame?.classList.remove("is-visible", "is-confirming");
      if (layer) layer.hidden = true;
      layer?.setAttribute("aria-hidden", "true");
    }
  } catch (err) {
    photoWallCropConfirmAnim?.cancel();
    photoWallCropConfirmAnim = null;
    const frame = $("#photoWallCropFrame");
    frame?.classList.remove("is-confirming");
    frame?.classList.add("is-visible");
    layoutPhotoWallCropFrame();
    alert(err.message);
  }
}

const photoWallCropFrameEl = $("#photoWallCropFrame");
const photoWallCropLayerEl = $("#photoWallCropLayer");

photoWallCropFrameEl?.addEventListener("click", (event) => {
  event.stopPropagation();
});

photoWallCropLayerEl?.addEventListener("click", (event) => {
  if (!photoWallCropSession) return;
  if (event.target.closest("#photoWallCropFrame")) return;
  const image = photoWallCropImageRect;
  const layerRect = photoWallCropLayerEl.getBoundingClientRect();
  const x = event.clientX - layerRect.left;
  const y = event.clientY - layerRect.top;
  if (
    !image ||
    x < image.left ||
    y < image.top ||
    x > image.left + image.width ||
    y > image.top + image.height
  ) {
    event.stopPropagation();
    closeViewer();
    return;
  }
  event.stopPropagation();
});

photoWallCropFrameEl?.addEventListener("pointerdown", (event) => {
  if (
    !photoWallCropSession ||
    event.button !== 0 ||
    photoWallCropFrameEl.classList.contains("is-confirming") ||
    event.target.closest(".photo-wall-crop-action")
  )
    return;
  event.preventDefault();
  const image = $("#viewerPhoto > img");
  if (!image) return;
  const rect = image.getBoundingClientRect();
  const layerRect = photoWallCropLayerEl.getBoundingClientRect();
  photoWallCropDrag = {
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    x: photoWallCropFrameState.x,
    y: photoWallCropFrameState.y,
    imageLeft: rect.left - layerRect.left,
    imageTop: rect.top - layerRect.top,
    imageWidth: rect.width,
    imageHeight: rect.height,
    side:
      parseFloat(photoWallCropFrameEl.style.width) ||
      Math.min(rect.width, rect.height),
  };
  event.currentTarget.setPointerCapture?.(event.pointerId);
  photoWallCropFrameEl.classList.add("is-dragging");
});

photoWallCropFrameEl?.addEventListener("pointermove", (event) => {
  const drag = photoWallCropDrag;
  if (!drag || drag.pointerId !== event.pointerId) return;
  const dx = event.clientX - drag.startX;
  const dy = event.clientY - drag.startY;
  const half = drag.side / 2;
  const x = Math.min(
    (drag.imageWidth - half) / drag.imageWidth,
    Math.max(half / drag.imageWidth, drag.x + dx / drag.imageWidth),
  );
  const y = Math.min(
    (drag.imageHeight - half) / drag.imageHeight,
    Math.max(half / drag.imageHeight, drag.y + dy / drag.imageHeight),
  );
  photoWallCropFrameState = { ...photoWallCropFrameState, x, y };
  photoWallCropConfirmed = false;
  layoutPhotoWallCropFrame();
});

const endPhotoWallCropDrag = (event) => {
  if (!photoWallCropDrag || photoWallCropDrag.pointerId !== event.pointerId)
    return;
  try {
    photoWallCropFrameEl.releasePointerCapture?.(event.pointerId);
  } catch {}
  photoWallCropDrag = null;
  photoWallCropFrameEl.classList.remove("is-dragging");
};
photoWallCropFrameEl?.addEventListener("pointerup", endPhotoWallCropDrag);
photoWallCropFrameEl?.addEventListener("pointercancel", endPhotoWallCropDrag);

photoWallCropLayerEl?.addEventListener(
  "wheel",
  (event) => {
    if (!photoWallCropSession || !photoWallCropImageRect) return;
    const layerRect = photoWallCropLayerEl.getBoundingClientRect();
    const x = event.clientX - layerRect.left;
    const y = event.clientY - layerRect.top;
    const image = photoWallCropImageRect;
    if (
      x < image.left ||
      y < image.top ||
      x > image.left + image.width ||
      y > image.top + image.height
    )
      return;
    event.preventDefault();
    event.stopPropagation();
    const shortEdge = Math.min(image.width, image.height);
    const current = photoWallCropFrameState.size * shortEdge;
    const next = Math.min(
      shortEdge,
      Math.max(shortEdge * 0.5, current * Math.exp(-event.deltaY * 0.0015)),
    );
    photoWallCropFrameState = {
      ...photoWallCropFrameState,
      size: next / shortEdge,
    };
    photoWallCropConfirmed = false;
    layoutPhotoWallCropFrame();
  },
  { passive: false },
);

$("#photoWallCropReset")?.addEventListener("click", (event) => {
  event.stopPropagation();
  photoWallCropFrameState = { x: 0.5, y: 0.5, size: 1 };
  photoWallCropConfirmed = false;
  layoutPhotoWallCropFrame();
});
$("#photoWallCropCurrent")?.addEventListener("click", (event) => {
  event.stopPropagation();
  photoWallCropFrameState = { ...photoWallCropOriginalState };
  photoWallCropConfirmed = false;
  layoutPhotoWallCropFrame();
});
$("#photoWallCropConfirm")?.addEventListener("click", (event) => {
  event.stopPropagation();
  photoWallCropConfirmAnim = animateCropConfirmation(photoWallCropFrameEl);
  void savePhotoWallCrop(photoWallCropConfirmAnim);
});
$("#photoWallCropCancel")?.addEventListener("click", (event) => {
  event.stopPropagation();
  closeViewer();
});
window.addEventListener("resize", schedulePhotoWallCropLayout);

function viewerRatingHTML(item) {
  if (item?.kind !== "photo") return "";
  const rating = normalizeItemRating(item.rating);
  return Array.from({ length: 5 }, (_, index) => {
    const value = index + 1;
    return `<button class="viewer-rating-star${value <= rating ? " is-filled" : ""}"
          type="button" data-viewer-rating="${value}"
          aria-label="设为 ${value} 星" aria-pressed="${value <= rating}">${ICON_STAR}</button>`;
  }).join("");
}

function syncViewerRating(
  item = state.items[viewerIndex],
  { pop = false } = {},
) {
  const rating = $("#viewerRating");
  if (!rating) return;
  const enabled =
    state.ratingMode &&
    item?.kind === "photo" &&
    !photoEditorOpen &&
    !photoWallCropSession;
  rating.hidden = !enabled;
  if (!enabled) {
    rating.innerHTML = "";
    delete rating.dataset.ratingSignature;
    return;
  }
  const value = normalizeItemRating(item.rating);
  const signature = `${item.id}:${value}`;
  if (rating.dataset.ratingSignature !== signature) {
    rating.innerHTML = viewerRatingHTML(item);
    rating.dataset.ratingSignature = signature;
  }
  rating.setAttribute("aria-label", `照片分类评级，当前 ${value} 星`);
  for (const button of rating.querySelectorAll("[data-viewer-rating]")) {
    const filled = Number(button.dataset.viewerRating) <= value;
    button.classList.toggle("is-filled", filled);
    button.setAttribute("aria-pressed", String(filled));
  }
  if (pop) {
    rating.classList.remove("is-just-rated");
    void rating.offsetWidth;
    rating.classList.add("is-just-rated");
  }
}

function updateRatingTile(tile, item) {
  if (!tile || !item) return;
  const rating = state.ratingMode ? normalizeItemRating(item.rating) : 0;
  tile.classList.toggle("has-rating", rating > 0);
  const shot = tile.querySelector(".shot");
  if (!shot) return;
  let badge = shot.querySelector(".tile-rating");
  if (!rating) {
    badge?.remove();
    return;
  }
  if (!badge) {
    badge = document.createElement("span");
    badge.className = "tile-rating";
    badge.setAttribute("role", "img");
    shot.insertBefore(badge, shot.querySelector(".tile-check"));
  }
  badge.innerHTML = ratingStarsMarkup(rating);
  badge.setAttribute("aria-label", `评分 ${rating} 星`);
}

function syncRatingTile(item, index = viewerIndex) {
  updateRatingTile(tileAt(index), item);
}

function syncRenderedRatingTiles() {
  for (const tile of document.querySelectorAll(
    "#content .photo-grid .tile[data-index]",
  )) {
    updateRatingTile(tile, state.items[Number(tile.dataset.index)]);
  }
}

async function saveFilmstripRating(value) {
  if (ratingInFlight) return;
  const index = filmstripCurrentIndex();
  const item = state.items[index];
  if (!state.filmstrip || !state.ratingMode || item?.kind !== "photo") {
    return;
  }
  const nextRating = normalizeItemRating(value);
  const previousRating = normalizeItemRating(item.rating);
  ratingInFlight = true;
  applyRatingState([item.id], nextRating);
  syncFilmstripRating(item, { pop: true });
  try {
    const savedRating = await saveItemRating([item.id], nextRating);
    applyRatingState([item.id], savedRating);
    if (filmstripCurrentItem()?.id === item.id) {
      syncFilmstripRating(item);
    }
  } catch (err) {
    applyRatingState([item.id], previousRating);
    if (filmstripCurrentItem()?.id === item.id) {
      syncFilmstripRating(item);
    }
    alert(err.message);
  } finally {
    ratingInFlight = false;
  }
}

async function saveViewerRating(value) {
  if (ratingInFlight) return;
  const item = state.items[viewerIndex];
  const viewer = $("#viewer");
  if (
    !item ||
    item.kind !== "photo" ||
    viewer.hidden ||
    viewer.classList.contains("is-closing")
  )
    return;
  const nextRating = normalizeItemRating(value);
  const previousRating = normalizeItemRating(item.rating);
  ratingInFlight = true;
  applyRatingState([item.id], nextRating);
  syncViewerRating(item, { pop: true });
  syncRatingTile(item);
  try {
    const savedRating = await saveItemRating([item.id], nextRating);
    applyRatingState([item.id], savedRating);
    syncViewerRating(item);
    syncRatingTile(item);
  } catch (err) {
    applyRatingState([item.id], previousRating);
    syncViewerRating(item);
    syncRatingTile(item);
    alert(err.message);
  } finally {
    ratingInFlight = false;
  }
}

function bindViewerRating(container) {
  if (!container || container.dataset.bound === "true") return;
  container.dataset.bound = "true";
  container.addEventListener("pointerdown", (event) => {
    event.stopPropagation();
  });
  container.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    const button = event.target.closest("[data-viewer-rating]");
    if (!button) return;
    void saveViewerRating(Number(button.dataset.viewerRating));
  });
  container.addEventListener("dblclick", (event) => {
    event.preventDefault();
    event.stopPropagation();
  });
  container.addEventListener(
    "wheel",
    (event) => {
      event.stopPropagation();
    },
    { passive: true },
  );
  container.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
  });
}

bindViewerRating($("#viewerRating"));

function showViewerItem(opts = {}) {
  const item = state.items[viewerIndex];
  if (!item) return;
  stopLiveMotion();
  if (viewerDateOpen) closeViewerDate({ immediate: true });
  if (viewerInfoOpen) closeViewerInfo({ immediate: true });
  const stage = $("#viewerStage");
  resetVideoCursorState();
  hideVideoControls();
  clearViewerVideoTimers();
  releaseViewerVideo(stage.querySelector("video"));
  if (item.kind === "video") {
    /* 视频一插进来就藏在封面下面。飞行打开时由 startVideoFlight 接管；
       翻页或键盘打开时用一张封面图顶住，等播过开场黑帧再交接。 */
    const cover = `<div class="viewer-photo viewer-video-cover">
      <img src="${openingPosterUrl(item)}" alt="" draggable="false"></div>`;
    stage.innerHTML = `<video class="is-video-waiting" preload="none"
      playsinline disablepictureinpicture disableremoteplayback
      controlslist="nodownload noplaybackrate noremoteplayback"></video>${cover}`;
    const video = stage.querySelector("video");
    video.loop = videoLoopEnabled && !autoPlayNextVideoEnabled;
    bindVideoControls(video);
    video.addEventListener("error", () => {
      if (
        !video.isConnected ||
        !stage.isConnected ||
        state.items[viewerIndex]?.id !== item.id
      ) {
        return;
      }
      if (
        video.dataset.viewerVideoSource === "original-crop" &&
        Number(item.editRevision) > 0
      ) {
        video.classList.add("is-video-waiting");
        void loadViewerVideoSource(video, item, { editedPreview: true }).then(
          (loaded) => {
            if (!loaded || !video.isConnected) return;
            stage.querySelector(".viewer-video-cover")?.remove();
            playViewerVideo(video);
          },
        );
        return;
      }
      if (
        video.dataset.viewerVideoSource !== "compatible" &&
        video.dataset.compatibilityAttempted !== String(item.id)
      ) {
        video.dataset.compatibilityAttempted = String(item.id);
        void loadCompatibleViewerVideo(video, item, stage, {
          autoplay: true,
        });
        return;
      }
      if (video.dataset.viewerVideoSource === "compatible") {
        hideVideoControls();
        resetVideoCursorState();
        clearViewerMorph();
        stage.innerHTML = `<div class="viewer-fallback">
          <p>这个视频暂时无法播放</p>
          <button class="primary-btn" onclick="openInSystem(${item.id})">用系统播放器打开</button>
        </div>`;
      }
    });
    const beginVideo = async () => {
      const loaded = await loadViewerVideoSource(video, item);
      if (
        !loaded ||
        !video.isConnected ||
        state.items[viewerIndex]?.id !== item.id
      )
        return;
      if (opts.autoplay !== false) {
        revealViewerVideoWhenPlaying(
          video,
          stage.querySelector(".viewer-video-cover"),
        );
      }
    };
    if (opts.deferVideoSource !== true) void beginVideo();
    if (opts.autoplay === false) {
      const coverNode = stage.querySelector(".viewer-video-cover");
      video.addEventListener(
        "loadeddata",
        () => {
          if (!video.isConnected || state.items[viewerIndex]?.id !== item.id)
            return;
          video.classList.remove("is-video-waiting");
          coverNode?.remove();
        },
        { once: true },
      );
    }
  } else {
    const liveVideo = liveVideoId(item);
    const liveButton = liveVideo
      ? `<button class="viewer-live-button"
      id="viewerLiveButton" type="button" aria-label="播放实况照片"
      aria-pressed="false">${viewerLiveMarkHTML()}</button>`
      : "";
    stage.innerHTML = `<div class="viewer-photo" id="viewerPhoto">
      <img src="${viewItemUrl(item)}" alt="">
      ${
        liveVideo
          ? `<video class="viewer-live-video" src="${fileUrl(liveVideo)}"
        preload="auto" playsinline disablepictureinpicture disableremoteplayback></video>`
          : ""
      }
      ${liveButton}
    </div>`;
    bindViewerLiveButton(stage.querySelector("#viewerLiveButton"));
    const motion = stage.querySelector(".viewer-live-video");
    if (motion) {
      /* 打开静态图时就把伴生视频装进缓存，悬停后只等首帧绘制，不临时整段加载。 */
      motion.load();
      motion.addEventListener("ended", () => stopLiveMotion());
      motion.addEventListener(
        "error",
        () => {
          stopLiveMotion();
          toast("这段实况视频的编码暂时无法播放");
        },
        { once: true },
      );
    }
    const image = stage.querySelector("#viewerPhoto > img");
    const fitImage = () => {
      if (!image?.isConnected || state.items[viewerIndex]?.id !== item.id)
        return;
      fitViewerImageToStage(image);
      scheduleViewerLiveButtonPosition();
    };
    if (image?.complete && image.naturalWidth > 0) fitImage();
    else image?.addEventListener("load", fitImage, { once: true });
  }
  const liveButton = stage.querySelector("#viewerLiveButton");
  if (liveButton) {
    liveButton.hidden = !isLivePhoto(item);
    liveButton.classList.remove("is-visible");
    liveButton.classList.remove("is-playing");
    liveButton.setAttribute("aria-pressed", "false");
    liveButton.setAttribute("aria-label", "播放实况照片");
  }
  if (viewerLivePlaceTimer) {
    clearTimeout(viewerLivePlaceTimer);
    viewerLivePlaceTimer = 0;
  }
  if (viewerLiveRevealTimer) {
    clearTimeout(viewerLiveRevealTimer);
    viewerLiveRevealTimer = 0;
  }
  if (liveButton && !liveButton.hidden) {
    const image = $("#viewerPhoto img");
    image?.addEventListener("load", scheduleViewerLiveButtonPosition, {
      once: true,
    });
    scheduleViewerLiveButtonPosition();
    /* 共享元素飞入结束后图片的实际落点才稳定，再补一次精确定位。 */
    const itemId = item.id;
    viewerLivePlaceTimer = setTimeout(() => {
      viewerLivePlaceTimer = 0;
      if (state.items[viewerIndex]?.id === itemId)
        scheduleViewerLiveButtonPosition();
    }, 430);
    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    if (opts.liveDuringMorph && !reduced) {
      /* 真正的标记在飞行层下面同步就位，等共享元素交接时它已经完全显现。 */
      liveButton.classList.add("is-visible", "is-entry-synced");
    } else {
      viewerLiveRevealTimer = setTimeout(
        () => {
          viewerLiveRevealTimer = 0;
          if (
            state.items[viewerIndex]?.id !== itemId ||
            !liveButton.isConnected
          )
            return;
          placeViewerLiveButton();
          requestAnimationFrame(() => {
            if (liveButton.isConnected && !liveButton.hidden) {
              liveButton.classList.add("is-visible");
            }
          });
        },
        reduced ? 0 : 180,
      );
    }
  }
  $("#viewerTitle").textContent = item.name;
  $("#viewerInfo").innerHTML = infoHTML(item);
  $("#viewerCounter").textContent =
    `${viewerIndex + 1} / ${state.items.length}`;
  syncViewerFavorite(item);
  syncViewerRating(item);
  $("#viewer").classList.toggle("has-multi", state.items.length > 1);
  viewerRotation = 0;
  resetViewerZoom();
  setPinnedHover(item.id);
  syncViewerFilmstrip({
    scroll: true,
    instant: opts.instantFilmstrip === true,
  });
  if (viewerMapRestoreItems) {
    if (viewerMapContext === "locations") syncLocationsMapSelection(item.id);
    else if (viewerMapContext === "album") syncAlbumMapSelection(item.id);
  }
  if (photoWallCropSession && item.kind === "photo") {
    showPhotoWallCrop(item);
  }
  void refreshViewerEditButton(item);
}

/* 视频封面层上的两样小东西：底部暗角和时长；不再生成播放三角。
   进场时先原样贴住卡片，再快速淡掉；退场时反过来，落回卡片前淡回来。 */
function addVideoChrome(clone, item) {
  const scrim = document.createElement("span");
  scrim.className = "flight-scrim";
  clone.appendChild(scrim);

  const duration = formatDuration(item.duration);
  if (duration) {
    const time = document.createElement("span");
    time.className = "tile-badge flight-chrome";
    time.textContent = duration;
    clone.appendChild(time);
  }
}

/* 退出瞬间把当前视频帧抓成快照。退出时用它直接缩回卡片，
   避免「当前帧 → 封面」的交叉淡化在点击那一刻闪一下。 */
function captureVideoFrame(video) {
  try {
    if (
      !video ||
      video.readyState < 2 ||
      !video.videoWidth ||
      !video.videoHeight
    )
      return "";
    const crop = viewerVideoCrop(video);
    /* offsetWidth / offsetHeight 不包含 CSS transform，正是退出层要复现的
       视频画面尺寸。旋转 90° 时 getBoundingClientRect() 的宽高已经互换，
       用它做画布会让抓到的画面横纵比例错误。 */
    const sourceWidth = Math.max(1, Math.round(video.offsetWidth * crop.w));
    const sourceHeight = Math.max(1, Math.round(video.offsetHeight * crop.h));
    /* 只用于缩回动画，不必保留 4K 尺寸；限制长边峰值，避免抓帧编码拖慢点击。 */
    const limit = Math.min(1, 1600 / Math.max(sourceWidth, sourceHeight));
    const width = Math.max(1, Math.round(sourceWidth * limit));
    const height = Math.max(1, Math.round(sourceHeight * limit));
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    if (!ctx) return "";
    /* 快照只保留查看器真正显示的裁剪区域，退场时不会先闪出完整视频。 */
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, width, height);
    const sourceCropX = video.videoWidth * crop.x;
    const sourceCropY = video.videoHeight * crop.y;
    const sourceCropWidth = video.videoWidth * crop.w;
    const sourceCropHeight = video.videoHeight * crop.h;
    ctx.drawImage(
      video,
      sourceCropX,
      sourceCropY,
      sourceCropWidth,
      sourceCropHeight,
      0,
      0,
      width,
      height,
    );
    return canvas.toDataURL("image/jpeg", 0.8);
  } catch {
    return "";
  }
}

/* 视频的进场：封面层照照片那套从缩略图飞到落点，真正的 <video> 在底下
   安静地加载；飞到约 3/4 路程时起播，等首帧真的画出来再让封面淡出。
   这样飞行途中看不到黑块，落位时也不会「点完愣一下」才动。 */
function startVideoFlight(item, tile, startRect, thumbSrc) {
  const viewer = $("#viewer");
  const stage = $("#viewerStage");
  const video = stage.querySelector("video");
  if (!video) return;

  const targetRect = viewerPhotoTargetRect(item, tile);
  stage.classList.add("is-morphing");
  video.classList.add("is-video-waiting");

  /* 落点处用视频真正开始播放的那一帧当封面；还没回来时 600 缩略图先顶着。
     两张图内容一致，交接时不会从 1 秒处的封面跳到开场画面。 */
  const clone = createMorphClone(
    thumbSrc,
    startRect,
    false,
    openingPosterUrl(item),
    tile?.querySelector("img"),
  );
  const openingPoster = clone.querySelector(".morph-full");
  clone.classList.add("is-video-flight");
  addVideoChrome(clone, item);
  viewerMorphClone = clone;
  viewer.appendChild(clone);
  void clone.offsetWidth;
  /* 先让「还在缩略图原位」的这一帧真正画出来，下一帧再启动放大。
     否则首帧偶尔会已经落在半路上，看起来像从卡片直接跳到了大图。 */
  requestAnimationFrame(() => {
    if (viewerMorphClone !== clone) return;
    placeMorphClone(clone, targetRect);
    clone.style.borderRadius = "0px";
  });

  /* 先让封面独自飞完，再装入视频源并起播，避开首帧解码和合成动画抢线程。 */
  viewerVideoTimers.push(
    setTimeout(() => {
      if (viewerMorphClone !== clone) return;
      void loadViewerVideoSource(video, item);
    }, VIDEO_SOURCE_DELAY),
  );

  let goal = targetRect;
  let synced = false;
  let stableFrames = 0;
  let bufferingShown = false;
  let openingReadyAt = 0;
  const started = performance.now();
  if (!openingPoster || openingPoster.complete) {
    openingReadyAt = performance.now();
  } else {
    const markOpeningReady = () => {
      openingReadyAt = performance.now();
    };
    openingPoster.addEventListener("load", markOpeningReady, { once: true });
    openingPoster.addEventListener("error", markOpeningReady, { once: true });
  }

  const reveal = () => {
    if (viewerMorphClone !== clone) return;
    stage.classList.remove("is-morphing");
    video.classList.remove("is-video-waiting");
    /* 视频先在仍然不透明的封面下面露出来；确认画上一帧后，
       再单独把封面淡掉。这样既不会在终点提前看到播放器，也不会闪白。 */
    requestAnimationFrame(() =>
      requestAnimationFrame(() => {
        if (viewerMorphClone !== clone) return;
        /* 与封面淡出同一帧重新对齐画面和声音；不要只解除静音。 */
        restartViewerVideoWithAudio(video);
        clone.classList.add("is-video-arrived");
        setTimeout(() => {
          if (viewerMorphClone !== clone) return;
          clone.remove();
          viewerMorphClone = null;
          scheduleVideoCursorIdleHide();
        }, 220);
      }),
    );
  };

  const tick = () => {
    if (viewerMorphClone !== clone) return;
    /* 以真正视频元素的落点为准：封面层和它差一点点都会在交接时露边 */
    if (!synced) {
      const rect = video.getBoundingClientRect();
      if (rect.width > 0 && video.readyState >= 1) {
        const exact = rectSnapshot(rect);
        if (!morphRectMatches(exact, targetRect, 1)) {
          goal = exact;
          placeMorphClone(clone, goal);
        }
        synced = true;
      }
    }
    const settled = morphRectMatches(clone.getBoundingClientRect(), goal);
    stableFrames = settled ? stableFrames + 1 : 0;
    const elapsed = performance.now() - started;
    /* 不能只等“第一帧画出来”：第 0 帧常常是黑的。等播放推进过开场，
       再淡掉封面，避免交接时整块画面先黑一下。 */
    const openingPainted =
      openingReadyAt > 0 && performance.now() - openingReadyAt > 90;
    if (stableFrames >= 2 && video.readyState >= 2 && openingPainted) {
      reveal();
      return;
    }
    /* 已经落位但视频还没出画：封面继续顶着，过一会儿给个加载提示 */
    if (stableFrames >= 2 && elapsed > 900 && !bufferingShown) {
      bufferingShown = true;
      const loader = document.createElement("span");
      loader.className = "viewer-buffer-loader";
      loader.setAttribute("aria-hidden", "true");
      loader.innerHTML = curveLoaderMarkup("circle");
      clone.appendChild(loader);
      hydrateCircleCurveLoaders();
      clone.classList.add("is-video-buffering");
    }
    /* 编码不支持等极端情况别一直卡着封面，交还原生控件让用户看到反馈 */
    if (elapsed > 2400) {
      reveal();
      return;
    }
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

function flashViewerSwitch() {
  const viewer = $("#viewer");
  viewer.classList.remove("is-switching");
  void viewer.offsetWidth;
  viewer.classList.add("is-switching");
  setTimeout(() => viewer.classList.remove("is-switching"), 260);
}

const VIEWER_PHOTO_SWITCH_MS = 200;
const VIEWER_REDUCED_PHOTO_SWITCH_MS = 80;
const VIEWER_PHOTO_SWITCH_EASING = "cubic-bezier(0.22, 0.72, 0.24, 1)";

function captureViewerPhotoSwitchLayer(nextItem) {
  const currentItem = state.items[viewerIndex];
  if (currentItem?.kind !== "photo" || nextItem?.kind !== "photo") return null;
  const photo = $("#viewerPhoto");
  const stage = $("#viewerStage");
  if (!photo || !stage) return null;
  const stageRect = stage.getBoundingClientRect();
  if (stageRect.width < 1 || stageRect.height < 1) return null;
  const layer = photo.cloneNode(true);
  layer.removeAttribute("id");
  layer
    .querySelectorAll(".viewer-live-video, .viewer-live-button")
    .forEach((node) => node.remove());
  layer.classList.add("viewer-photo-switch-out");
  layer.classList.remove("is-live-playing", "is-panning");
  layer.style.position = "fixed";
  layer.style.left = `${stageRect.left}px`;
  layer.style.top = `${stageRect.top}px`;
  layer.style.width = `${stageRect.width}px`;
  layer.style.height = `${stageRect.height}px`;
  layer.style.margin = "0";
  const currentStyle = getComputedStyle(photo);
  layer.style.opacity = currentStyle.opacity;
  layer.style.transform = currentStyle.transform;
  layer.style.transformOrigin = currentStyle.transformOrigin;
  layer.style.transition = "none";
  $("#viewer").appendChild(layer);
  return layer;
}

function clearViewerPhotoSwitchLayers() {
  document
    .querySelectorAll(".viewer-photo-switch-out")
    .forEach((layer) => layer.remove());
}

function ensureContentTileRendered(index) {
  const existing = tileAt(index);
  if (existing) return existing;
  const batch = progressivePhotoGridBatch;
  if (!batch) return null;
  for (const spec of batch.grids) {
    const position = spec.entries.findIndex(
      (entry) => entry.index === Number(index),
    );
    if (position < 0) continue;
    while (spec.next <= position) {
      if (!appendProgressivePhotoGridChunk(spec)) return null;
    }
    return tileAt(index);
  }
  return null;
}

function crossfadeViewerPhotoSwitch(outgoing) {
  const incoming = $("#viewerPhoto");
  if (!outgoing) return false;
  if (!incoming) {
    outgoing.remove();
    return false;
  }
  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const duration = reduced
    ? VIEWER_REDUCED_PHOTO_SWITCH_MS
    : VIEWER_PHOTO_SWITCH_MS;
  const startOpacity = Number(getComputedStyle(outgoing).opacity);
  const outgoingAnimation = outgoing.animate(
    [
      { opacity: Number.isFinite(startOpacity) ? startOpacity : 1 },
      { opacity: 0 },
    ],
    {
      duration,
      easing: VIEWER_PHOTO_SWITCH_EASING,
      fill: "forwards",
    },
  );
  const incomingAnimation = incoming.animate([{ opacity: 0 }, { opacity: 1 }], {
    duration,
    easing: VIEWER_PHOTO_SWITCH_EASING,
    fill: "both",
  });
  Promise.allSettled([
    outgoingAnimation.finished,
    incomingAnimation.finished,
  ]).then(() => {
    outgoing.remove();
    incomingAnimation.cancel();
  });
  return true;
}

function transitionViewerItem(next, { anchorZoom = false } = {}) {
  $("#viewer").classList.remove("is-switching");
  clearViewerPhotoSwitchLayers();
  const outgoing = captureViewerPhotoSwitchLayer(state.items[next]);
  clearViewerMorph();
  viewerIndex = next;
  state.cursor = next;
  const item = state.items[next];
  if (anchorZoom && item) state.zoomAnchorId = item.id;
  showViewerItem();
  if (!crossfadeViewerPhotoSwitch(outgoing)) flashViewerSwitch();
}

function stepViewer(delta) {
  const count = state.items.length;
  if (count < 2) return;
  const current = viewerIndex >= 0 && viewerIndex < count ? viewerIndex : 0;
  const next = (current + delta + count) % count;
  transitionViewerItem(next);
}

function syncViewerFavorite(
  item = state.items[viewerIndex],
  { pop = false } = {},
) {
  const el = $("#viewerFavorite");
  if (!el) return;
  el.hidden = !item?.favorite;
  if (item?.favorite && !el.firstElementChild)
    el.innerHTML = ICON_FAVORITE_LINE;
  if (!pop) return;
  el.classList.remove("is-just-toggled");
  void el.offsetWidth;
  el.classList.add("is-just-toggled");
}

/* 大图里改了收藏，背后的网格也立刻换掉这颗爱心；不用整页重绘，
   以免破坏正在播放的视频和查看器位置。 */
function syncFavoriteTile(item, index = viewerIndex) {
  const tile = tileAt(index);
  if (!tile) return;
  tile.classList.toggle("is-favorite", !!item.favorite);
  const shot = tile.querySelector(".shot");
  if (!shot) return;
  let heart = shot.querySelector(".tile-heart");
  if (!item.favorite) {
    heart?.remove();
    return;
  }
  if (heart) return;
  heart = document.createElement("span");
  heart.className = "tile-heart";
  heart.innerHTML = ICON_FAVORITES;
  shot.insertBefore(heart, shot.querySelector(".tile-check"));
}

let viewerNeedsFavoritesRefresh = false;
async function refreshFavoritesAfterViewer() {
  if (!viewerNeedsFavoritesRefresh) return;
  viewerNeedsFavoritesRefresh = false;
  try {
    await loadFavorites();
    if (await navigateFromEmptyFavorites()) return;
    render();
  } catch {}
}

async function toggleViewerFavorite() {
  if (favoriteInFlight) return;
  const item = state.items[viewerIndex];
  const viewer = $("#viewer");
  if (!item || viewer.hidden || viewer.classList.contains("is-closing")) return;
  const makeFavorite = !item.favorite;
  favoriteInFlight = true;
  try {
    const changed = await saveFavorite([item.id], makeFavorite);
    syncViewerFavorite(item, { pop: true });
    syncFavoriteTile(item);
    if (state.activeId === "favorites" && !makeFavorite && changed.size) {
      viewerNeedsFavoritesRefresh = true;
    }
  } catch (err) {
    alert(err.message);
  } finally {
    favoriteInFlight = false;
  }
}

function showViewerAt(index) {
  if (index < 0 || index >= state.items.length) return;
  transitionViewerItem(index, { anchorZoom: true });
  if (state.filmstrip) syncFilmstripView();
}

function closeViewerWithBackgroundAnimation() {
  closeViewer();
}

function closeViewer({ immediate = false } = {}) {
  if (photoEditorOpen) return;
  const viewer = $("#viewer");
  if (viewer.hidden || viewer.classList.contains("is-closing")) return;
  const openedItemId = viewerOpenedItemId;
  viewerOpenedItemId = null;
  $("#viewerFilmstrip").hidden = true;
  viewerEditEligible = false;
  viewerEditCheckToken += 1;
  syncViewerEditVisibility();
  if (photoWallCropSession) hidePhotoWallCropLater();
  stopLiveMotion();
  closeViewerDate({ immediate: true });
  closeViewerInfo({ immediate: true });
  resetVideoCursorState();
  const lastItem = state.items[viewerIndex];
  const switchedItem =
    !viewerMapContext &&
    openedItemId != null &&
    lastItem?.id != null &&
    Number(lastItem.id) !== openedItemId;
  const tile = switchedItem
    ? ensureContentTileRendered(viewerIndex)
    : tileAt(viewerIndex);
  if (switchedItem && !contentTileIsVisible(tile)) centerContentTile(tile);
  if (immediate) {
    cancelViewerClose();
    clearViewerMorph();
    releaseViewerVideo($("#viewerStage video"));
    $("#viewerStage").innerHTML = "";
    resetViewerZoom();
    viewer.hidden = true;
    finishAlbumMapViewerContext();
    document.body.classList.remove("viewer-open", "viewer-returning");
    clearViewerSourceTile();
    viewer.classList.remove(
      "show-info",
      "is-opening",
      "is-switching",
      "is-closing",
      "is-video-closing",
      "has-multi",
    );
    viewer.style.removeProperty("--video-close-fade");
    void refreshFavoritesAfterViewer();
    return;
  }
  const image = $("#viewerPhoto img");
  const video = $("#viewerStage video");
  const activeMorph = viewerMorphClone;
  const morphImage = activeMorph?.querySelector("img");
  const targetRect = tileMorphRect(tile);

  /* 视频已经落位：先暂停并抓当前帧快照，用快照直接缩回缩略图。
     不在点击瞬间切封面，避免两层画面交叉时闪一下。 */
  if (lastItem?.kind === "video" && video && !activeMorph) {
    const fromRect = rectSnapshot(video.getBoundingClientRect());
    const hasVideoTransform =
      viewerZoom > 1.001 ||
      viewerRotation % 360 !== 0 ||
      Math.abs(viewerPanX) > 0.01 ||
      Math.abs(viewerPanY) > 0.01;
    const canFly =
      !hasVideoTransform &&
      fromRect.width > 0 &&
      !!targetRect &&
      targetRect.width > 0;
    clearViewerVideoTimers();
    video.pause();
    /* 优先用当前帧快照直接缩回；抓不到时再退回封面交叉淡化。 */
    const snapshotSrc = captureVideoFrame(video);
    const stateClose =
      hasVideoTransform && targetRect?.width > 0
        ? createViewerVideoStateCloseClone(
            $("#viewerStage"),
            video,
            targetRect,
            snapshotSrc,
            lastItem,
          )
        : null;
    if (!stateClose) releaseViewerVideo(video);
    const handoffMs = snapshotSrc ? 0 : 80;
    const morphMs = VIDEO_FLIGHT_MS;
    const closeFadeMs = handoffMs + morphMs;
    viewer.classList.remove("show-info", "is-opening", "is-switching");
    viewer.classList.add("is-closing", "is-video-closing");
    viewer.style.setProperty("--video-close-fade", `${closeFadeMs}ms`);
    paintKeyboardFocus();
    flushPendingUpdate();
    if (stateClose) {
      finishViewerCloseHover(tile, lastItem.id);
      viewerCloseClone = stateClose.wrapper;
      const started = performance.now();
      let stableFrames = 0;
      let targetRevealed = false;
      const beginClose = () => {
        if (viewerCloseClone !== stateClose.wrapper) return;
        /* 快照已经上屏后再撤掉真实播放器，避免两套图层交接时闪白。 */
        releaseViewerVideo(video);
        $("#viewerStage").innerHTML = "";
        resetViewerZoom();
        requestAnimationFrame(() => {
          if (viewerCloseClone !== stateClose.wrapper) return;
          placeMorphClone(stateClose.wrapper, stateClose.targetRect);
          stateClose.wrapper.style.borderRadius = "4px";
          stateClose.photo.style.transform = "none";
        });
      };
      const finishStateClose = () => {
        if (viewerCloseClone !== stateClose.wrapper) return;
        if (viewerCloseTimer) {
          clearTimeout(viewerCloseTimer);
          viewerCloseTimer = null;
        }
        stateClose.wrapper.remove();
        viewerCloseClone = null;
        viewer.hidden = true;
        finishAlbumMapViewerContext();
        document.body.classList.remove("viewer-open");
        clearViewerSourceTile();
        viewer.classList.remove("is-closing", "is-video-closing", "has-multi");
        viewer.style.removeProperty("--video-close-fade");
        refreshFavoritesAfterViewer();
      };
      const tickStateClose = () => {
        if (viewerCloseClone !== stateClose.wrapper) return;
        const settled = morphRectMatches(
          stateClose.wrapper.getBoundingClientRect(),
          stateClose.targetRect,
        );
        stableFrames = settled ? stableFrames + 1 : 0;
        if (!targetRevealed && performance.now() - started >= 220) {
          targetRevealed = true;
          stateClose.targetImage.style.opacity = "1";
        }
        const transform = getComputedStyle(stateClose.photo).transform;
        const transformDone =
          transform === "none" || transform === "matrix(1, 0, 0, 1, 0, 0)";
        if (
          (stableFrames >= 2 && transformDone) ||
          performance.now() - started > 1000
        ) {
          finishStateClose();
          return;
        }
        requestAnimationFrame(tickStateClose);
      };
      viewerCloseTimer = setTimeout(finishStateClose, 1400);
      const startWhenPainted = () => {
        if (!stateClose.snapshot.isConnected) return;
        beginClose();
        requestAnimationFrame(tickStateClose);
      };
      if (stateClose.snapshot.complete && stateClose.snapshot.naturalWidth) {
        requestAnimationFrame(startWhenPainted);
      } else {
        stateClose.snapshot.addEventListener("load", startWhenPainted, {
          once: true,
        });
        stateClose.snapshot.addEventListener("error", startWhenPainted, {
          once: true,
        });
      }
      return;
    }
    resetViewerZoom();
    viewerCloseTimer = setTimeout(() => {
      viewer.hidden = true;
      finishAlbumMapViewerContext();
      document.body.classList.remove("viewer-open");
      clearViewerSourceTile();
      finishViewerCloseHover(tile, lastItem?.id);
      viewer.classList.remove("is-closing", "is-video-closing", "has-multi");
      viewer.style.removeProperty("--video-close-fade");
      viewerCloseTimer = null;
      refreshFavoritesAfterViewer();
    }, closeFadeMs + 80);
    if (canFly) {
      const clone = createMorphClone(
        snapshotSrc || itemThumbUrl(lastItem, 600, "inside"),
        fromRect,
        true,
        snapshotSrc ? "" : itemThumbUrl(lastItem, 1600, "inside"),
      );
      clone.classList.add("is-video-back");
      addVideoChrome(clone, lastItem);
      if (!snapshotSrc) clone.style.opacity = "0";
      document.body.appendChild(clone);
      viewerCloseClone = clone;
      void clone.offsetWidth;

      let shrinkStarted = false;
      const startShrink = () => {
        if (shrinkStarted || viewerCloseClone !== clone) return;
        shrinkStarted = true;
        $("#viewerStage").innerHTML = "";
        /* 当前帧快照从视频原位缩回缩略图；落位后淡出，露出真正的卡片封面。 */
        placeMorphClone(clone, targetRect);
        clone.style.borderRadius = "4px";
        const started = performance.now();
        let stableFrames = 0;
        const arrive = () => {
          clone.classList.add("is-arrived");
          setTimeout(() => {
            clone.remove();
            if (viewerCloseClone === clone) viewerCloseClone = null;
          }, 150);
        };
        const tick = () => {
          if (!clone.isConnected) return;
          stableFrames = morphRectMatches(
            clone.getBoundingClientRect(),
            targetRect,
          )
            ? stableFrames + 1
            : 0;
          if (stableFrames >= 2 || performance.now() - started > 1000) {
            arrive();
            return;
          }
          requestAnimationFrame(tick);
        };
        requestAnimationFrame(tick);
      };

      if (snapshotSrc) {
        const snapshot = clone.querySelector("img");
        clone.style.opacity = "1";
        const begin = () => requestAnimationFrame(startShrink);
        if (snapshot.complete && snapshot.naturalWidth) begin();
        else {
          snapshot.addEventListener("load", begin, { once: true });
          snapshot.addEventListener("error", begin, { once: true });
        }
      } else {
        /* 快照抓取失败时退回原来的冻帧 → 封面交叉淡化。 */
        clone.style.opacity = "1";
        video.style.transition = `opacity ${handoffMs}ms linear`;
        video.style.opacity = "0";
        setTimeout(startShrink, handoffMs);
      }
    } else {
      $("#viewerStage").innerHTML = "";
    }
    return;
  }

  const fromRect = activeMorph
    ? rectSnapshot(activeMorph.getBoundingClientRect())
    : image
      ? rectSnapshot(image.getBoundingClientRect())
      : null;
  const canMorph =
    viewerRotation % 360 === 0 &&
    !!lastItem &&
    viewerZoom <= 1.001 &&
    !!fromRect &&
    fromRect.width > 0 &&
    !!targetRect &&
    targetRect.width > 0;
  const morphSrc =
    lastItem?.kind === "video"
      ? itemThumbUrl(lastItem, 1600, "inside")
      : activeMorph
        ? morphImage?.src
        : image
          ? image.currentSrc || image.src
          : "";
  const hasViewerTransform =
    viewerZoom > 1.001 ||
    viewerRotation % 360 !== 0 ||
    Math.abs(viewerPanX) > 0.01 ||
    Math.abs(viewerPanY) > 0.01;
  const stateMorph =
    !canMorph &&
    hasViewerTransform &&
    !!image &&
    !!targetRect &&
    targetRect.width > 0;
  const keepStageUntilHidden = !canMorph && !stateMorph;
  /* 原格子要一直藏到飞回的过渡层真正落到它的位置。
     查看器背景 220ms 就会退完，但照片收缩约 380ms 才结束；
     如果那时直接恢复原格子，最后几十毫秒会有两张图叠在原位置。 */
  const holdSourceForFlight = canMorph && !!morphSrc;
  if (holdSourceForFlight) document.body.classList.add("viewer-returning");
  if (stateMorph || keepStageUntilHidden) {
    /* 原格子仍被 viewer-open 遮住，此时先把退出后的悬停状态定下来，
       避免它真正现身时再播放一次亮度 / 阴影过渡。 */
    finishViewerCloseHover(tile, lastItem?.id);
  }
  const stateClose = stateMorph
    ? createViewerStateCloseClone($("#viewerStage"), targetRect)
    : null;
  if (lastItem?.kind === "video") releaseViewerVideo(video);
  clearViewerMorph();
  viewer.classList.remove("show-info", "is-opening", "is-switching");
  viewer.classList.add("is-closing");
  if (stateClose) {
    viewerCloseClone = stateClose.wrapper;
    $("#viewerStage").innerHTML = "";
    resetViewerZoom();
    paintKeyboardFocus();
    flushPendingUpdate();
    const started = performance.now();
    let stableFrames = 0;
    let targetRevealed = false;
    requestAnimationFrame(() => {
      if (viewerCloseClone !== stateClose.wrapper) return;
      placeMorphClone(stateClose.wrapper, stateClose.targetRect);
      stateClose.wrapper.style.borderRadius = "4px";
      stateClose.photo.style.transform = "none";
    });
    const finishStateClose = () => {
      if (viewerCloseClone !== stateClose.wrapper) return;
      if (viewerCloseTimer) {
        clearTimeout(viewerCloseTimer);
        viewerCloseTimer = null;
      }
      stateClose.wrapper.remove();
      viewerCloseClone = null;
      viewer.hidden = true;
      finishAlbumMapViewerContext();
      document.body.classList.remove("viewer-open");
      clearViewerSourceTile();
      viewer.classList.remove("is-closing", "has-multi");
      refreshFavoritesAfterViewer();
    };
    viewerCloseTimer = setTimeout(finishStateClose, 1200);
    const tickStateClose = () => {
      if (viewerCloseClone !== stateClose.wrapper) return;
      const settled = morphRectMatches(
        stateClose.wrapper.getBoundingClientRect(),
        stateClose.targetRect,
      );
      stableFrames = settled ? stableFrames + 1 : 0;
      if (!targetRevealed && performance.now() - started >= 220) {
        targetRevealed = true;
        stateClose.targetImage.style.opacity = "1";
      }
      const transform = getComputedStyle(stateClose.photo).transform;
      const transformDone =
        transform === "none" || transform === "matrix(1, 0, 0, 1, 0, 0)";
      if (
        (stableFrames >= 2 && transformDone) ||
        performance.now() - started > 900
      ) {
        finishStateClose();
        return;
      }
      requestAnimationFrame(tickStateClose);
    };
    requestAnimationFrame(tickStateClose);
    return;
  }
  if (!keepStageUntilHidden) {
    $("#viewerStage").innerHTML = "";
    resetViewerZoom();
  }
  paintKeyboardFocus();
  flushPendingUpdate();
  /* 背景用 0.2s 淡出；查看器等这段走完再隐藏，收缩层继续留在页面上。 */
  viewerCloseTimer = setTimeout(() => {
    viewer.hidden = true;
    finishAlbumMapViewerContext();
    if (keepStageUntilHidden) resetViewerZoom();
    document.body.classList.remove("viewer-open");
    if (!holdSourceForFlight) clearViewerSourceTile();
    if (!keepStageUntilHidden) finishViewerCloseHover(tile, lastItem?.id);
    viewer.classList.remove("is-closing", "has-multi");
    viewerCloseTimer = null;
    refreshFavoritesAfterViewer();
  }, 220);
  if (canMorph && morphSrc) {
    const clone = createMorphClone(morphSrc, fromRect, true);
    document.body.appendChild(clone);
    viewerCloseClone = clone;
    void clone.offsetWidth;
    placeMorphClone(clone, targetRect);
    clone.style.borderRadius = "4px";
    /* 和打开时一样，等它真的缩回缩略图的位置再淡出。
       否则 280ms 就开始透明时，过渡层还在半路上，最后会跳一下。 */
    const started = performance.now();
    let stableFrames = 0;
    const arrive = () => {
      /* 飞行层已经和目标格子逐像素重合，这时才恢复原图；两者在同一帧交换，
         不会在照片仍在半路时提前露出下面的缩略图。 */
      document.body.classList.remove("viewer-returning");
      clearViewerSourceTile();
      clone.classList.add("is-arrived");
      setTimeout(() => {
        clone.remove();
        if (viewerCloseClone === clone) viewerCloseClone = null;
      }, 150);
    };
    const tick = () => {
      if (!clone.isConnected) return;
      stableFrames = morphRectMatches(clone.getBoundingClientRect(), targetRect)
        ? stableFrames + 1
        : 0;
      if (stableFrames >= 2 || performance.now() - started > 900) {
        arrive();
        return;
      }
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }
}

function setViewerInfo(open) {
  if (open) {
    closeViewerDate();
    closeViewerInfo();
  }
  $("#viewer").classList.toggle("show-info", open);
}

/* 应用窗口按固定像素排版：225px 相簿卡片、固定侧栏和顶栏。
   Chromium 默认会把 Ctrl + 滚轮当成整页缩放，触控板捏合也会带 ctrlKey；
   整页缩放会让这套版式偏离设计尺寸，所以在窗口捕获阶段一律截住。
   查看器的照片缩放不受影响，仍由下面的 viewerStage 监听处理。 */
window.addEventListener(
  "wheel",
  (e) => {
    if (e.ctrlKey || e.metaKey) e.preventDefault();
  },
  { passive: false, capture: true },
);

/* 滚轮缩放；拖动画布；双击已放大的画面恢复原始大小。 */
let viewerWheelSwitchLockedUntil = 0;
$("#viewerStage").addEventListener(
  "wheel",
  (e) => {
    if (!viewerZoomSurface()) return;
    e.preventDefault();
    const switchWithWheel =
      viewerWheelMode === "navigate"
        ? !e.ctrlKey
        : viewerWheelMode === "zoom-navigate" && e.ctrlKey;
    if (switchWithWheel) {
      if (Math.abs(e.deltaY) <= Math.abs(e.deltaX)) return;
      const now = performance.now();
      if (now < viewerWheelSwitchLockedUntil) return;
      if (state.items.length < 2) return;
      viewerWheelSwitchLockedUntil = now + 140;
      stepViewer(e.deltaY > 0 ? 1 : -1);
      return;
    }
    setViewerZoom(viewerZoom * (e.deltaY < 0 ? 1.12 : 0.89));
  },
  { passive: false },
);

$("#viewerStage").addEventListener("pointerdown", (e) => {
  if (e.target.closest(".viewer-live-button")) return;
  const surface = e.target.closest(".viewer-photo, video");
  if (!surface || viewerZoom <= 1 || e.button !== 0) return;
  e.preventDefault();
  viewerDragged = false;
  viewerDrag = {
    pointerId: e.pointerId,
    x: e.clientX,
    y: e.clientY,
    panX: viewerPanX,
    panY: viewerPanY,
    surface,
    captureEl: e.target.closest("img, video") || surface,
  };
  surface.classList.add("is-panning");
  try {
    viewerDrag.captureEl.setPointerCapture(e.pointerId);
  } catch {}
});

$("#viewerStage").addEventListener("pointermove", (e) => {
  const drag = viewerDrag;
  if (!drag || drag.pointerId !== e.pointerId) return;
  const dx = e.clientX - drag.x;
  const dy = e.clientY - drag.y;
  if (Math.hypot(dx, dy) > 3) viewerDragged = true;
  viewerPanX = drag.panX + dx;
  viewerPanY = drag.panY + dy;
  applyViewerZoom();
});

function endViewerDrag(e) {
  const drag = viewerDrag;
  if (!drag || (e.pointerId != null && e.pointerId !== drag.pointerId)) return;
  drag.surface?.classList.remove("is-panning");
  try {
    drag.captureEl?.releasePointerCapture(drag.pointerId);
  } catch {}
  viewerDrag = null;
  if (viewerDragged)
    setTimeout(() => {
      viewerDragged = false;
    }, 0);
}
$("#viewerStage").addEventListener("pointerup", endViewerDrag);
$("#viewerStage").addEventListener("pointercancel", endViewerDrag);
$("#viewerStage").addEventListener("lostpointercapture", endViewerDrag);

$("#viewerStage").addEventListener("dblclick", (e) => {
  if (e.target.closest(".viewer-live-button")) return;
  const video = e.target.closest("video:not(.viewer-live-video)");
  if (
    e.target.closest("#videoControls") ||
    (!video && !e.target.closest(".viewer-photo"))
  )
    return;
  e.preventDefault();
  clearPendingVideoToggle();
  if (video && viewerZoom < 0.999) {
    setViewerZoom(1);
    return;
  }
  if (viewerZoom > 1.001) setViewerZoom(1);
});

let viewerFilmstripDrag = null;
let viewerFilmstripClickGuardUntil = 0;

$("#viewerFilmstrip").addEventListener("click", (event) => {
  if (performance.now() < viewerFilmstripClickGuardUntil) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  const thumb = event.target.closest("[data-viewer-filmstrip-thumb]");
  if (!thumb) {
    event.stopPropagation();
    return;
  }
  event.preventDefault();
  event.stopPropagation();
  showViewerAt(Number(thumb.dataset.viewerFilmstripThumb));
});

const viewerFilmstripTrack = $("#viewerFilmstripTrack");

viewerFilmstripTrack.addEventListener("pointerdown", (event) => {
  if (
    (event.button != null && event.button !== 0) ||
    !event.target.closest(".viewer-filmstrip-thumb")
  )
    return;
  stopHorizontalFilmstripWheelMotion(viewerFilmstripTrack);
  stopHorizontalFilmstripScrollMotion(viewerFilmstripTrack);
  const scrollBehavior = viewerFilmstripTrack.style.scrollBehavior;
  viewerFilmstripTrack.style.scrollBehavior = "auto";
  viewerFilmstripDrag = {
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    scrollLeft: viewerFilmstripTrack.scrollLeft,
    scrollBehavior,
    lastX: event.clientX,
    lastTime: performance.now(),
    velocity: 0,
    moved: false,
  };
});

viewerFilmstripTrack.addEventListener("pointermove", (event) => {
  const drag = viewerFilmstripDrag;
  if (!drag || event.pointerId !== drag.pointerId) return;
  const dx = event.clientX - drag.startX;
  const dy = event.clientY - drag.startY;
  const now = performance.now();
  const elapsed = now - drag.lastTime;
  if (elapsed > 0) {
    const sample =
      (-(event.clientX - drag.lastX) / Math.max(1, elapsed)) * 1000;
    drag.velocity += (sample - drag.velocity) * 0.55;
  }
  drag.lastX = event.clientX;
  drag.lastTime = now;
  if (!drag.moved && Math.abs(dx) > 5 && Math.abs(dx) > Math.abs(dy)) {
    drag.moved = true;
    viewerFilmstripTrack.classList.add("is-dragging");
    try {
      viewerFilmstripTrack.setPointerCapture(event.pointerId);
    } catch {}
  }
  if (!drag.moved) return;
  event.preventDefault();
  const before = viewerFilmstripTrack.scrollLeft;
  viewerFilmstripTrack.scrollLeft = drag.scrollLeft - dx;
  if (Math.abs(viewerFilmstripTrack.scrollLeft - before) < 0.01) {
    drag.velocity = 0;
  }
});

function endViewerFilmstripDrag(event) {
  const drag = viewerFilmstripDrag;
  if (!drag || (event.pointerId != null && event.pointerId !== drag.pointerId))
    return;
  viewerFilmstripDrag = null;
  viewerFilmstripTrack.classList.remove("is-dragging");
  viewerFilmstripTrack.style.scrollBehavior = drag.scrollBehavior;
  try {
    viewerFilmstripTrack.releasePointerCapture?.(drag.pointerId);
  } catch {}
  if (drag.moved) {
    const now = performance.now();
    const stale = now - drag.lastTime > PHOTO_WALL_INERTIA.staleReleaseMs;
    viewerFilmstripClickGuardUntil =
      now + (event.type === "pointercancel" || stale ? 180 : 280);
    startHorizontalFilmstripScrollInertia(
      viewerFilmstripTrack,
      stale || event.type === "pointercancel" ? 0 : drag.velocity,
      drag.scrollBehavior,
    );
  } else {
    viewerFilmstripTrack.style.scrollBehavior = drag.scrollBehavior;
  }
}

document.addEventListener("pointerup", endViewerFilmstripDrag);
document.addEventListener("pointercancel", endViewerFilmstripDrag);
viewerFilmstripTrack.addEventListener(
  "lostpointercapture",
  endViewerFilmstripDrag,
);

viewerFilmstripTrack.addEventListener(
  "wheel",
  (event) => {
    event.preventDefault();
    event.stopPropagation();
    const track = event.currentTarget;
    const delta =
      Math.abs(event.deltaX) > Math.abs(event.deltaY)
        ? event.deltaX
        : event.deltaY;
    const unit =
      event.deltaMode === 1
        ? ALBUM_WHEEL_SMOOTHING.lineHeightPx
        : event.deltaMode === 2
          ? track.clientWidth
          : 1;
    scrollHorizontalFilmstripByWheel(track, delta * unit);
  },
  { passive: false },
);

$("#videoControls").addEventListener("click", (e) => e.stopPropagation());
$("#videoControls").addEventListener("pointerdown", () => {
  videoControlsHeld = true;
  clearVideoControlsHideTimer();
});
$("#videoSeek").addEventListener("input", () => {
  const video = videoControlsVideo;
  if (!video?.isConnected || !Number.isFinite(video.duration)) return;
  video.currentTime = Number($("#videoSeek").value) || 0;
});
window.addEventListener("resize", () => {
  fitViewerImageToStage();
  fitViewerVideoToStage();
  preserveViewerPanOnResize();
  scheduleViewerLiveButtonPosition();
  scrollViewerFilmstripSelection({ behavior: "auto" });
  if (viewerDateOpen) clampViewerDatePosition();
  if (viewerInfoOpen) clampViewerInfoPosition();
  if (videoControlsVideo && !$("#videoControls").hidden) syncVideoControls();
});
document.addEventListener(
  "pointermove",
  (e) => {
    /* 窗口尺寸变化、视频展开等布局变化可能补发同坐标的 pointermove；
     只有坐标真的发生了变化，才算用户实际移动了鼠标。 */
    if (
      videoPointerLast &&
      videoPointerLast.x === e.clientX &&
      videoPointerLast.y === e.clientY
    )
      return;
    videoPointerLast = { x: e.clientX, y: e.clientY };
    clearVideoCursorIdleTimer();
    $("#viewer").classList.remove("video-cursor-hidden");
    updateVideoControlsForPointer(e.clientX, e.clientY);
    scheduleVideoCursorIdleHide();
  },
  { passive: true },
);
document.addEventListener("pointerup", (e) => {
  if (!videoControlsHeld) return;
  videoControlsHeld = false;
  updateVideoControlsForPointer(e.clientX, e.clientY);
});
document.addEventListener("pointercancel", () => {
  if (!videoControlsHeld) return;
  videoControlsHeld = false;
  if (videoControlsVideo) scheduleVideoControlsHide();
});
$("#viewer").addEventListener("pointerleave", () => {
  stopLiveMotion();
  if (videoControlsVideo) hideVideoControls();
  $("#viewerEditZone")?.classList.remove("is-visible");
});
window.addEventListener("blur", () => {
  stopLiveMotion();
  if (videoControlsVideo) hideVideoControls();
  $("#viewerEditZone")?.classList.remove("is-visible");
});

/* 点照片本身收起信息面板；点照片外的空白处退出查看器，和微信一致。 */
$("#viewerStage").addEventListener("click", (e) => {
  if (viewerTopDragging || performance.now() < viewerTopClickSuppressedUntil) {
    e.preventDefault();
    e.stopPropagation();
    return;
  }
  if (viewerDragged) {
    viewerDragged = false;
    return;
  }
  if (viewerDateOpen) {
    closeViewerDate();
    return;
  }
  if (viewerInfoOpen) {
    closeViewerInfo();
    return;
  }
  const video = e.target.closest("video");
  if (video) {
    setViewerInfo(false);
    if (e.detail > 1) clearPendingVideoToggle();
    else scheduleVideoPlaybackToggle(video);
    return;
  }
  if (e.target.closest("img, video, .viewer-photo")) {
    const liveVideo = e.target
      .closest(".viewer-photo")
      ?.querySelector(".viewer-live-video");
    if (liveVideo && !liveVideo.paused) {
      stopLiveMotion();
      return;
    }
    setViewerInfo(false);
    return;
  }
  if ($("#viewer").classList.contains("show-info")) {
    setViewerInfo(false);
    return;
  }
  closeViewerWithBackgroundAnimation();
});

function bindViewerLiveButton(button) {
  if (!button || button.dataset.bound === "true") return;
  button.dataset.bound = "true";
  button.addEventListener("pointerenter", (e) => {
    if (e.pointerType === "touch") return;
    if (viewerLiveLeaveTimer) {
      clearTimeout(viewerLiveLeaveTimer);
      viewerLiveLeaveTimer = 0;
    }
    const video = $("#viewerPhoto .viewer-live-video");
    if (video && !video.paused) return;
    if (viewerLiveHoverTimer) clearTimeout(viewerLiveHoverTimer);
    viewerLiveHoverTimer = setTimeout(() => {
      viewerLiveHoverTimer = 0;
      if (!button.isConnected || !button.matches(":hover")) return;
      playLiveMotion();
    }, 320);
  });
  button.addEventListener("pointerleave", () => {
    if (viewerLiveHoverTimer) {
      clearTimeout(viewerLiveHoverTimer);
      viewerLiveHoverTimer = 0;
    }
    const video = $("#viewerPhoto .viewer-live-video");
    if (!video || video.paused) {
      stopLiveMotion();
      return;
    }
    if (viewerLiveLeaveTimer) clearTimeout(viewerLiveLeaveTimer);
    viewerLiveLeaveTimer = setTimeout(() => {
      viewerLiveLeaveTimer = 0;
      if (!button.isConnected || button.matches(":hover")) return;
      stopLiveMotion();
    }, 260);
  });
  button.addEventListener(
    "wheel",
    (event) => {
      /* LIVE 是独立覆盖控件。滚轮停在按钮上时不再冒泡给查看器，
       避免按钮命中区把本应停留在控件上的滚轮解释成项目缩放。 */
      event.stopPropagation();
    },
    { passive: true },
  );
  button.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
  });
}

let viewerTopDragging = false;
let viewerTopClickSuppressedUntil = 0;

/* 原生拖动区会吞掉单击。这里用同一套识别同时支持：
   单击、双击最大化、按住拖动窗口。查看器顶部、窗口控制栏和整个顶栏共用。
   全屏或最大化里第一次产生拖动位移时先恢复普通窗口，再接着拖动。 */
function bindWindowDragSurface(
  surface,
  {
    onClick,
    onDragStart,
    onDragEnd,
    exitMaximized = false,
    isIgnoredTarget = () => false,
  } = {},
) {
  if (!surface) return;
  const isTopChrome = surface.matches?.(
    "#windowControls, #windowTopGrab, .toolbar",
  );
  const viewerOwnsBorderClick = () => {
    if (!isTopChrome) return false;
    const viewer = document.getElementById("viewer");
    return Boolean(
      viewer && !viewer.hidden && !viewer.classList.contains("is-closing"),
    );
  };
  const isFullscreen = () =>
    document.documentElement.classList.contains("is-fullscreen");
  const isMaximized = () =>
    document.documentElement.classList.contains("is-maximized");
  const toggleFullscreenForDrag = async () => {
    if (!window.albumWindow?.toggleFullscreen) {
      await toggleAppWindow();
      return !isFullscreen();
    }
    document.dispatchEvent(new CustomEvent("album:fullscreen-will-change"));
    let fullscreen = isFullscreen();
    try {
      const result = await window.albumWindow.toggleFullscreen();
      fullscreen = Boolean(result && result.fullscreen);
      document.documentElement.classList.toggle("is-fullscreen", fullscreen);
    } finally {
      document.dispatchEvent(
        new CustomEvent("album:fullscreen-changed", {
          detail: { fullscreen },
        }),
      );
    }
    return fullscreen;
  };
  const restoreMaximizedForDrag = async () => {
    if (!window.albumWindow?.toggleMaximize) return false;
    try {
      let maximized = isMaximized();
      const nativeMaximized = await Promise.resolve(
        window.albumWindow.isMaximized?.(),
      ).catch(() => null);
      if (typeof nativeMaximized === "boolean") maximized = nativeMaximized;
      document.documentElement.classList.toggle("is-maximized", maximized);
      if (!maximized) return true;
      const result = await window.albumWindow.toggleMaximize();
      maximized = Boolean(result && result.maximized);
      document.documentElement.classList.toggle("is-maximized", maximized);
      return !maximized;
    } catch {
      return false;
    }
  };
  let press = null;
  let dragging = false;
  let clickTimer = null;
  let suppressedUntil = 0;

  const cancelClick = () => {
    if (!clickTimer) return;
    clearTimeout(clickTimer);
    clickTimer = null;
  };
  const resetPress = () => {
    if (press?.frame) cancelAnimationFrame(press.frame);
    press = null;
    dragging = false;
    setWindowDragState(false);
  };
  const endPress = (e) => {
    if (!press) return;
    const wasDragging = dragging;
    resetPress();
    window.albumWindow?.endWindowMove?.();
    try {
      surface.releasePointerCapture(e.pointerId);
    } catch {}
    if (!wasDragging) return;
    suppressedUntil = performance.now() + 350;
    onDragEnd?.();
    e.stopPropagation();
    e.preventDefault();
  };

  surface.addEventListener("pointerdown", (e) => {
    if (e.target.closest?.("#sidebarRailBtn")) return;
    if (viewerOwnsBorderClick()) return;
    if (e.button !== 0 || isIgnoredTarget(e.target)) return;
    e.stopPropagation();
    cancelClick();
    const fullscreen = isFullscreen();
    const next = {
      x: e.screenX,
      y: e.screenY,
      pos: null,
      pending: null,
      frame: 0,
      fullscreen,
      maximized: exitMaximized && !fullscreen && isMaximized(),
      exitingFullscreen: false,
      exitingMaximized: false,
      lastX: e.screenX,
      lastY: e.screenY,
    };
    press = next;
    dragging = false;
    if (!next.fullscreen && !next.maximized)
      window.albumWindow?.beginWindowMove?.();
    if (window.albumWindow?.getWindowPosition) {
      window.albumWindow
        .getWindowPosition()
        .then(([x, y]) => {
          next.pos = [x, y];
        })
        .catch(() => {});
    }
    try {
      surface.setPointerCapture(e.pointerId);
    } catch {}
  });

  const continueMoveAfterWindowFit = async (activePress) => {
    if (press !== activePress || !dragging) return;
    window.albumWindow?.beginWindowMove?.();
    const position = await Promise.resolve(
      window.albumWindow?.getWindowPosition?.(),
    ).catch(() => null);
    if (press !== activePress || !dragging || !Array.isArray(position)) return;
    activePress.pos = position;
    activePress.pending = [
      position[0] + activePress.lastX - activePress.x,
      position[1] + activePress.lastY - activePress.y,
    ];
    if (activePress.frame) return;
    activePress.frame = requestAnimationFrame(() => {
      activePress.frame = 0;
      if (press !== activePress || !dragging || !activePress.pending) return;
      window.albumWindow?.moveWindow?.(
        activePress.pending[0],
        activePress.pending[1],
      );
    });
  };

  surface.addEventListener("pointermove", (e) => {
    if (!press || e.buttons === 0) return;
    press.lastX = e.screenX;
    press.lastY = e.screenY;
    if (!dragging) {
      if (Math.hypot(e.screenX - press.x, e.screenY - press.y) < 4) return;
      dragging = true;
      setWindowDragState(true);
      cancelClick();
      onDragStart?.();
      if (press.fullscreen) {
        press.exitingFullscreen = true;
        const activePress = press;
        void toggleFullscreenForDrag().then(async (fullscreen) => {
          if (fullscreen) return;
          const restored = await restoreMaximizedForDrag();
          if (restored) void continueMoveAfterWindowFit(activePress);
        });
        return;
      }
      if (press.maximized) {
        press.exitingMaximized = true;
        const activePress = press;
        void restoreMaximizedForDrag().then((restored) => {
          if (restored) void continueMoveAfterWindowFit(activePress);
        });
        return;
      }
    }
    if (press.exitingFullscreen || press.exitingMaximized) return;
    if (!window.albumWindow?.moveWindow) return;
    if (!press.pos || !window.albumWindow?.moveWindow) return;
    press.pending = [
      press.pos[0] + e.screenX - press.x,
      press.pos[1] + e.screenY - press.y,
    ];
    if (press.frame) return;
    press.frame = requestAnimationFrame(() => {
      press.frame = 0;
      if (press === null || !dragging || !press.pending) return;
      window.albumWindow.moveWindow(press.pending[0], press.pending[1]);
    });
  });

  /* 窗口移动时 pointer capture 可能丢失，所以在 document 捕获阶段也收一次。 */
  document.addEventListener("pointerup", endPress, true);
  document.addEventListener("pointercancel", endPress, true);
  window.addEventListener("blur", () => {
    if (!press) return;
    const wasDragging = dragging;
    resetPress();
    window.albumWindow?.endWindowMove?.();
    if (wasDragging) {
      suppressedUntil = performance.now() + 350;
      onDragEnd?.();
    }
  });

  surface.addEventListener("click", (e) => {
    if (e.target.closest?.("#sidebarRailBtn")) return;
    if (viewerOwnsBorderClick()) return;
    if (isIgnoredTarget(e.target)) return;
    e.stopPropagation();
    if (dragging || performance.now() < suppressedUntil) {
      e.preventDefault();
      return;
    }
    cancelClick();
    clickTimer = setTimeout(() => {
      clickTimer = null;
      onClick?.(e);
    }, 300);
  });

  surface.addEventListener("dblclick", (e) => {
    if (e.target.closest?.("#sidebarRailBtn")) return;
    if (viewerOwnsBorderClick()) return;
    if (isIgnoredTarget(e.target)) return;
    e.preventDefault();
    e.stopPropagation();
    cancelClick();
    if (state.photoWall) return;
    if (isFullscreen()) return;
    if (window.albumWindow?.toggleMaximize) window.albumWindow.toggleMaximize();
    else toggleAppWindow();
  });
}

bindWindowDragSurface($("#viewerTopClose"), {
  onClick: () => {
    if (
      !$("#viewer").hidden &&
      !$("#viewer").classList.contains("is-closing")
    ) {
      closeViewer();
    }
  },
  onDragStart: () => {
    viewerTopDragging = true;
  },
  onDragEnd: () => {
    viewerTopDragging = false;
    viewerTopClickSuppressedUntil = performance.now() + 350;
  },
});

function scrollProjectAreaTo(edge) {
  const content = $("#content");
  if (!content) return;
  const behavior = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    ? "auto"
    : "smooth";
  content.scrollTo({
    top: edge === "bottom" ? content.scrollHeight : 0,
    behavior,
  });
}

const isToolbarControl = (target) =>
  target instanceof Element &&
  !!target.closest(
    'button, a[href], input, textarea, select, [contenteditable="true"]',
  );

bindWindowDragSurface($("#windowControls"), {
  exitMaximized: true,
  isIgnoredTarget: isToolbarControl,
});

bindWindowDragSurface($("#windowTopGrab"), {
  exitMaximized: true,
});

bindWindowDragSurface($(".toolbar"), {
  exitMaximized: true,
  onClick: (event) => {
    /* 指针捕获可能把 click 的目标改写成整个工具栏；按松开位置重新命中。 */
    const target =
      document.elementFromPoint(event.clientX, event.clientY) ||
      (event.target instanceof Element ? event.target : null);
    if (target?.closest("#toolbarLeftZone")) {
      scrollProjectAreaTo("top");
    } else if (target?.closest("#toolbarRightZone")) {
      scrollProjectAreaTo("bottom");
    }
  },
  isIgnoredTarget: isToolbarControl,
});

$("#viewer").addEventListener("click", (e) => {
  if (viewerTopDragging || performance.now() < viewerTopClickSuppressedUntil) {
    e.preventDefault();
    e.stopPropagation();
    return;
  }
  if (
    e.target.closest(
      ".viewer-stage, .viewer-filmstrip, .viewer-meta, .viewer-panel, " +
        ".viewer-date-popover, .viewer-info-popover",
    )
  ) {
    return;
  }
  closeViewerWithBackgroundAnimation();
});

$("#viewer").addEventListener("contextmenu", (event) => {
  const viewer = $("#viewer");
  if (viewer.hidden || viewer.classList.contains("is-closing")) return;
  event.preventDefault();
  event.stopPropagation();
  if (photoWallCropSession) return;
  if (
    event.target instanceof Element &&
    event.target.closest("#viewerInfoPopover")
  )
    return;
  if (!viewerInfoOpen) openViewerInfo();
});

/* 查看器四周那圈 Acrylic 玻璃边在 .viewer 外面，不属于任何可见的内容层。
   记下按下时的位置，只有从玻璃边开始、也在玻璃边结束的点击才退出，
   免得把照片拖到边上松手当成一次“点外面”。 */
let viewerBorderPress = false;
document.addEventListener(
  "pointerdown",
  (e) => {
    const viewer = $("#viewer");
    if (viewer.hidden || viewer.classList.contains("is-closing")) {
      viewerBorderPress = false;
      return;
    }
    if (e.target instanceof Element && e.target.closest(".photo-editor")) {
      viewerBorderPress = false;
      return;
    }
    viewerBorderPress = !(
      e.target instanceof Element && e.target.closest("#viewer")
    );
  },
  true,
);
document.addEventListener("click", (e) => {
  const fromBorder = viewerBorderPress;
  viewerBorderPress = false;
  if (!fromBorder) return;
  const viewer = $("#viewer");
  if (viewer.hidden || viewer.classList.contains("is-closing")) return;
  if (e.target instanceof Element && e.target.closest(".photo-editor")) return;
  if (e.target instanceof Element && e.target.closest("#viewer")) return;
  closeViewerWithBackgroundAnimation();
});

/* ------------------------- 项目右键 / Ctrl 右键菜单 ------------------------- */

let contextItemIndex = -1;
let contextTile = null;
let contextCloseTimer = null;
let contextSourceAnim = null;
let contextMenuAnim = null;
let contextSourceStart = null;
let contextSourceTarget = null;
let contextMenuTargetPlacement = null;
let contextMenuStartPlacement = null;
let contextMotionToken = 0;
let contextSourceImg = null;
let contextSourceVideo = null;
let contextPointerX = 0;
let contextPointerY = 0;
let contextCropSession = false;
let contextCropDrag = null;
let contextCropSaving = false;
let contextCropPositionFrame = 0;
let contextCropCloseAnim = null;
let contextCropFrameState = { x: 0.5, y: 0.5, size: 1 };
let contextCropOriginalState = { x: 0.5, y: 0.5, size: 1 };
let contextCropConfirmAnim = null;
let contextCropImageRect = null;

function trackContextPointer(e) {
  if (!contextMenuOpen && !contextCloseTimer) return;
  contextPointerX = e.clientX;
  contextPointerY = e.clientY;
}

document.addEventListener("pointermove", trackContextPointer, {
  passive: true,
});
document.addEventListener("pointerdown", trackContextPointer, {
  passive: true,
});

const CONTEXT_PREVIEW_MOTION_MS = 380;
const CONTEXT_PREVIEW_EASING = "cubic-bezier(0.4, 0, 0.2, 1)";
const CONTEXT_BACKDROP_BLUR_MAX_ITEMS = 1200;

function invalidateContextMotion() {
  contextMotionToken += 1;
}

function contextRectTransform(from, to) {
  const scaleX = Number(from.width) / Math.max(1, Number(to.width) || 1);
  const scaleY = Number(from.height) / Math.max(1, Number(to.height) || 1);
  const translateX = Number(from.left) - Number(to.left);
  const translateY = Number(from.top) - Number(to.top);
  return (
    `translate3d(${translateX.toFixed(2)}px, ${translateY.toFixed(2)}px, 0) ` +
    `scale(${scaleX.toFixed(5)}, ${scaleY.toFixed(5)})`
  );
}

function contextMenuTransform(from, to, scale) {
  const translateX = Number(from.left) - Number(to.left);
  const translateY = Number(from.top) - Number(to.top);
  return (
    `translate3d(${translateX.toFixed(2)}px, ${translateY.toFixed(2)}px, 0) ` +
    `scale(${scale.toFixed(5)})`
  );
}

/* 预览框自身会从缩略图的方形逐步展开成照片原始比例。图片始终按
   object-fit: cover 铺满当前预览框，由外框尺寸变化完成裁切过渡；不能
   跟着外框做非等比 transform，否则横竖缩放比例不同会把照片压扁。 */
function layoutContextSourceImage() {
  const img = contextSourceImg;
  const source = $("#contextSource");
  if (!img?.isConnected || !source) return;
  img.style.width = "100%";
  img.style.height = "100%";
  img.style.objectFit = "cover";
  img.style.transform = "none";
}

/* 宽照片的原格子可能比收窄后的菜单还宽。菜单始终从略小尺寸展开，
   避免出现“起始比例大于 1”导致展开时缩小、退出时反而放大。 */
function contextMenuStartScale(startWidth, finalWidth) {
  const ratio = Number(startWidth) / Math.max(1, Number(finalWidth) || 1);
  return Math.min(0.92, Math.max(0.05, Number.isFinite(ratio) ? ratio : 0.92));
}

function hideContextCrop() {
  contextCropSession = false;
  contextCropDrag = null;
  contextCropImageRect = null;
  contextCropConfirmAnim?.cancel();
  contextCropConfirmAnim = null;
  contextCropCloseAnim?.cancel();
  contextCropCloseAnim = null;
  if (contextCropPositionFrame) {
    cancelAnimationFrame(contextCropPositionFrame);
    contextCropPositionFrame = 0;
  }
  $("#contextCropLayer")?.setAttribute("hidden", "");
  $("#contextCropLayer")?.setAttribute("aria-hidden", "true");
  $("#contextCropFrame")?.classList.remove(
    "is-visible",
    "is-dragging",
    "is-confirming",
  );
}

function animateContextCropClose(target) {
  const scene = $("#contextScene");
  const frame = $("#contextCropFrame");
  if (!contextCropSession || !scene || !frame || !target) return null;
  const sceneRect = scene.getBoundingClientRect();
  const liveRect = frame.getBoundingClientRect();
  const shortEdge = Math.min(target.width, target.height);
  const targetSide = shortEdge * contextCropFrameState.size;
  const targetLeft =
    target.left + contextCropFrameState.x * target.width - targetSide / 2;
  const targetTop =
    target.top + contextCropFrameState.y * target.height - targetSide / 2;
  contextCropCloseAnim?.cancel();
  contextCropCloseAnim = frame.animate(
    [
      {
        left: `${liveRect.left - sceneRect.left}px`,
        top: `${liveRect.top - sceneRect.top}px`,
        width: `${liveRect.width}px`,
        height: `${liveRect.height}px`,
        opacity: 1,
      },
      {
        left: `${targetLeft}px`,
        top: `${targetTop}px`,
        width: `${targetSide}px`,
        height: `${targetSide}px`,
        opacity: 0,
      },
    ],
    {
      duration: 380,
      easing: "cubic-bezier(0.4, 0, 0.2, 1)",
      fill: "forwards",
    },
  );
  return contextCropCloseAnim;
}

function layoutContextCropFrame() {
  contextCropPositionFrame = 0;
  if (!contextCropSession) return;
  const scene = $("#contextScene");
  const source = $("#contextSource");
  const frame = $("#contextCropFrame");
  if (!scene || !source || !frame) return;
  const sceneRect = scene.getBoundingClientRect();
  const sourceRect = source.getBoundingClientRect();
  if (sourceRect.width < 2 || sourceRect.height < 2) return;

  const imageRect = {
    left: sourceRect.left - sceneRect.left,
    top: sourceRect.top - sceneRect.top,
    width: sourceRect.width,
    height: sourceRect.height,
  };
  const shortEdge = Math.min(imageRect.width, imageRect.height);
  const side = Math.min(
    shortEdge,
    Math.max(shortEdge * 0.5, shortEdge * contextCropFrameState.size),
  );
  let centerX = imageRect.left + contextCropFrameState.x * imageRect.width;
  let centerY = imageRect.top + contextCropFrameState.y * imageRect.height;
  centerX = Math.min(
    imageRect.left + imageRect.width - side / 2,
    Math.max(imageRect.left + side / 2, centerX),
  );
  centerY = Math.min(
    imageRect.top + imageRect.height - side / 2,
    Math.max(imageRect.top + side / 2, centerY),
  );

  frame.style.left = `${centerX - side / 2}px`;
  frame.style.top = `${centerY - side / 2}px`;
  frame.style.width = `${side}px`;
  frame.style.height = `${side}px`;
  contextCropFrameState = {
    x: (centerX - imageRect.left) / imageRect.width,
    y: (centerY - imageRect.top) / imageRect.height,
    size: side / shortEdge,
  };
  contextCropImageRect = imageRect;
}

function showContextCrop(item) {
  if (!contextMenuOpen || !item || item.kind !== "photo") return;
  contextCropSession = true;
  contextCropConfirmAnim?.cancel();
  contextCropConfirmAnim = null;
  contextCropFrameState = photoWallCropForItem(item);
  contextCropOriginalState = { ...contextCropFrameState };
  const layer = $("#contextCropLayer");
  const frame = $("#contextCropFrame");
  if (!layer || !frame) return;
  layer.hidden = false;
  layer.setAttribute("aria-hidden", "false");
  frame.classList.remove("is-visible", "is-confirming");
  requestAnimationFrame(() => {
    if (!contextCropSession) return;
    layoutContextCropFrame();
    requestAnimationFrame(() => {
      if (!contextCropSession) return;
      layoutContextCropFrame();
      frame.classList.add("is-visible");
    });
  });
}

function updateContextCropVisuals(item, crop) {
  item.photoWallCropX = crop.x;
  item.photoWallCropY = crop.y;
  item.photoWallCropSize = crop.size;
  item.photoWallCropUpdatedAt = crop.updatedAt;
  const image = contextTile?.querySelector("img");
  if (image) image.src = photoWallThumbUrl(item, 800);
  for (const album of state.photoWallAlbums) {
    if (album.coverItemId !== item.id) continue;
    album.coverCrop = crop;
    const cardImage = document.querySelector(
      `.photo-wall-library-card[data-photo-wall-album="${album.id}"] img`,
    );
    if (cardImage) cardImage.src = photoWallAlbumCoverUrl(album, 400);
  }
}

async function saveContextCrop(confirmation = null) {
  const item = state.items[contextItemIndex];
  if (!item || item.kind !== "photo" || contextCropSaving) return;
  contextCropSaving = true;
  try {
    const request = api("/api/photo-wall/crop", {
      method: "POST",
      body: JSON.stringify({
        itemId: item.id,
        x: contextCropFrameState.x,
        y: contextCropFrameState.y,
        size: contextCropFrameState.size,
      }),
    });
    const [result] = await Promise.all([
      request,
      confirmation?.finished.catch(() => {}),
    ]);
    updateContextCropVisuals(item, result.crop);
    closeItemContextMenu();
  } catch (err) {
    contextCropConfirmAnim?.cancel();
    contextCropConfirmAnim = null;
    const frame = $("#contextCropFrame");
    frame?.classList.remove("is-confirming");
    frame?.classList.add("is-visible");
    layoutContextCropFrame();
    alert(err.message);
  } finally {
    contextCropSaving = false;
  }
}

let contextAddToAlbumPending = false;

function contextMenuRows(item) {
  const activeAlbum =
    typeof state.activeId === "number" ? albumById(state.activeId) : null;
  const unfiled = isUnfiledAlbum(activeAlbum);
  const rows = [
    [
      item.favorite ? "取消收藏" : "收藏项目",
      item.favorite ? "favFilled" : "fav",
      "favorite",
    ],
    ["拷贝项目", "copy", "copy"],
    ["显示图库", "allItems", "show-library"],
  ];
  if (activeAlbum && !unfiled) rows.push(["设为封面", "photo", "cover"]);
  rows.push(
    unfiled
      ? ["移动到相簿", "move", "add-album"]
      : ["加入相簿", "album", "add-album"],
  );
  if (activeAlbum && !unfiled) rows.push(["移出相簿", "remove", "remove"]);
  const deleteLabel = item?.kind === "video" ? "删除视频" : "删除照片";
  return (
    rows
      .map(
        ([label, icon, action]) =>
          `<button class="context-row" role="menuitem" tabindex="-1" data-context-action="${action}">
      <span>${label}</span>${MENU_ICONS[icon]}
    </button>`,
      )
      .join("") +
    `
    <div class="context-separator" role="separator"></div>
    <button class="context-row danger" role="menuitem" tabindex="-1" data-context-action="delete">
      <span>${deleteLabel}</span>${MENU_ICONS.remove}
    </button>`
  );
}

let contextDetailOpen = false;
let contextDetailAnim = null;
let contextDetailContentAnim = null;
let contextDetailRevealAnims = [];
let contextDetailDrag = null;
let contextDateOpen = false;
let contextDateAnim = null;
let contextDateDrag = null;
const CONTEXT_DETAIL_GAP = 20;
const CONTEXT_DETAIL_EDGE = 20;
const CONTEXT_INFO_CARD_WIDTH = 320;

const CONTEXT_MAP_PREVIEW_WIDTH = 324;
const CONTEXT_MAP_PREVIEW_HEIGHT = 176;
const CONTEXT_MAP_PREVIEW_CACHE_LIMIT = 64;
const contextMapPreviewCache = new Map();
const contextMapPreviewTasks = new Map();
const contextMapPrewarmQueue = [];
const contextMapPrewarmFrameWaiters = new Set();
let contextMapPrewarmRunning = false;
let contextMapPrewarmFrameReady = false;
let contextMapPrewarmSuspended = false;
let contextMapPrewarmRequestSeq = 0;
let contextMapPrewarmRequest = null;
let contextMapPreviewScheduleTimer = 0;

function contextMapLocation(item) {
  if (!item) return null;
  const lat = Number(item.gps_lat);
  const lon = Number(item.gps_lon);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  if (lat < -90 || lat > 90 || lon < -180 || lon > 180) return null;
  return { lat, lon };
}

function contextMapPreviewKey(item) {
  const location = contextMapLocation(item);
  if (!location) return "";
  return [
    Number(item.id),
    location.lat.toFixed(6),
    location.lon.toFixed(6),
    mapNetworkEnabled ? "network" : "offline",
  ].join(":");
}

function contextMapPrewarmFrame() {
  return $("#contextMapPrewarmFrame");
}

function releaseContextMapPrewarmWork() {
  window.clearTimeout(contextMapPreviewScheduleTimer);
  contextMapPreviewScheduleTimer = 0;
  contextMapPrewarmQueue.length = 0;
  for (const task of contextMapPreviewTasks.values()) task.resolve("");
  contextMapPreviewTasks.clear();
  contextMapPrewarmRequest?.finish(false);
  contextMapPrewarmRequest = null;
  contextMapPrewarmFrameReady = false;
  for (const resolve of contextMapPrewarmFrameWaiters) resolve(false);
  contextMapPrewarmFrameWaiters.clear();
}

function setContextMapPrewarmSuspended(suspended) {
  const next = suspended === true;
  if (contextMapPrewarmSuspended === next) return;
  contextMapPrewarmSuspended = next;
  releaseContextMapPrewarmWork();
  const frame = contextMapPrewarmFrame();
  if (!frame) return;
  if (next) {
    frame.loading = "lazy";
    frame.src = "about:blank";
    return;
  }
  frame.loading = "eager";
  frame.src =
    "/map/index.html" +
    `?mode=preview&network=${mapNetworkEnabled ? "1" : "0"}` +
    `&revision=${Date.now()}`;
  scheduleVisibleContextMapPreviews();
}

function resumeContextMapPrewarmIfPossible() {
  if (state.albumMapOpen) return;
  if (state.activeId === "locations" && state.locationSubview === "map") return;
  setContextMapPrewarmSuspended(false);
}

function markContextMapPrewarmFrameReady() {
  contextMapPrewarmFrameReady = true;
  for (const resolve of contextMapPrewarmFrameWaiters) resolve(true);
  contextMapPrewarmFrameWaiters.clear();
  queueMicrotask(runContextMapPrewarmQueue);
}

function waitForContextMapPrewarmFrame() {
  if (contextMapPrewarmFrameReady) return Promise.resolve(true);
  return new Promise((resolve) => {
    let settled = false;
    const finish = (ready) => {
      if (settled) return;
      settled = true;
      contextMapPrewarmFrameWaiters.delete(finish);
      window.clearTimeout(timer);
      resolve(ready);
    };
    const timer = window.setTimeout(() => finish(false), 4500);
    contextMapPrewarmFrameWaiters.add(finish);
  });
}

function ensureContextMapPrewarmFrame() {
  if (contextMapPrewarmSuspended) return null;
  const frame = contextMapPrewarmFrame();
  if (!frame) return null;
  const src = frame.getAttribute("src");
  if (!src || src === "about:blank") {
    contextMapPrewarmFrameReady = false;
    frame.loading = "eager";
    frame.src =
      "/map/index.html" +
      `?mode=preview&network=${mapNetworkEnabled ? "1" : "0"}`;
  }
  return frame;
}

function rememberContextMapPreview(key, src) {
  if (!key || !src) return;
  if (contextMapPreviewCache.has(key)) contextMapPreviewCache.delete(key);
  contextMapPreviewCache.set(key, src);
  while (contextMapPreviewCache.size > CONTEXT_MAP_PREVIEW_CACHE_LIMIT) {
    contextMapPreviewCache.delete(contextMapPreviewCache.keys().next().value);
  }
}

function settleContextMapPreviewTask(task, src = "") {
  if (!task || contextMapPreviewTasks.get(task.key) !== task) return;
  if (src) rememberContextMapPreview(task.key, src);
  contextMapPreviewTasks.delete(task.key);
  task.resolve(src || "");
}

function enqueueContextMapPreview(item, { priority = false } = {}) {
  const key = contextMapPreviewKey(item);
  if (!key) return Promise.resolve("");
  const cached = contextMapPreviewCache.get(key);
  if (cached) {
    rememberContextMapPreview(key, cached);
    return Promise.resolve(cached);
  }
  const existing = contextMapPreviewTasks.get(key);
  if (existing) {
    if (priority) {
      const index = contextMapPrewarmQueue.indexOf(existing);
      if (index > 0) {
        contextMapPrewarmQueue.splice(index, 1);
        contextMapPrewarmQueue.unshift(existing);
      }
    }
    return existing.promise;
  }
  const location = contextMapLocation(item);
  let resolve;
  const promise = new Promise((done) => {
    resolve = done;
  });
  const task = {
    key,
    itemId: Number(item.id),
    lat: location.lat,
    lon: location.lon,
    resolve,
    promise,
  };
  contextMapPreviewTasks.set(key, task);
  if (priority) contextMapPrewarmQueue.unshift(task);
  else contextMapPrewarmQueue.push(task);
  queueMicrotask(runContextMapPrewarmQueue);
  return promise;
}

function composeContextMapPreview(canvas) {
  const snapshot = document.createElement("canvas");
  snapshot.width = CONTEXT_MAP_PREVIEW_WIDTH;
  snapshot.height = CONTEXT_MAP_PREVIEW_HEIGHT;
  const context = snapshot.getContext("2d");
  const scale = Math.max(
    snapshot.width / canvas.width,
    snapshot.height / canvas.height,
  );
  const width = canvas.width * scale;
  const height = canvas.height * scale;
  context.drawImage(
    canvas,
    (snapshot.width - width) / 2,
    (snapshot.height - height) / 2,
    width,
    height,
  );
  return snapshot.toDataURL("image/png");
}

async function captureContextMapPreview(frame, task) {
  const requestId = `context-map-${++contextMapPrewarmRequestSeq}`;
  const positioned = await new Promise((resolve) => {
    let settled = false;
    const finish = (ready) => {
      if (settled) return;
      settled = true;
      window.clearTimeout(timer);
      contextMapPrewarmRequest = null;
      resolve(ready);
    };
    const timer = window.setTimeout(() => finish(false), 4500);
    contextMapPrewarmRequest = { requestId, finish };
    frame.contentWindow.postMessage(
      {
        type: "metadata-map:set-preview-point",
        requestId,
        lat: task.lat,
        lon: task.lon,
      },
      window.location.origin,
    );
  });
  if (!positioned || !frame.isConnected) return "";
  try {
    const canvas = frame.contentDocument?.querySelector(".maplibregl-canvas");
    if (!canvas || canvas.width <= 1 || canvas.height <= 1) return "";
    return composeContextMapPreview(canvas);
  } catch {
    return "";
  }
}

async function runContextMapPrewarmQueue() {
  if (contextMapPrewarmRunning || !contextMapPrewarmQueue.length) return;
  contextMapPrewarmRunning = true;
  try {
    while (contextMapPrewarmQueue.length) {
      const frame = ensureContextMapPrewarmFrame();
      if (!frame || !(await waitForContextMapPrewarmFrame())) break;
      const task = contextMapPrewarmQueue.shift();
      if (contextMapPreviewTasks.get(task.key) !== task) continue;
      const src = await captureContextMapPreview(frame, task);
      settleContextMapPreviewTask(task, src);
    }
  } finally {
    contextMapPrewarmRunning = false;
    if (contextMapPrewarmQueue.length && contextMapPrewarmFrameReady) {
      window.setTimeout(runContextMapPrewarmQueue, 0);
    }
  }
}

function resetContextMapPreviewCache() {
  for (const task of contextMapPreviewTasks.values()) task.resolve("");
  contextMapPreviewTasks.clear();
  contextMapPrewarmQueue.length = 0;
  contextMapPreviewCache.clear();
  contextMapPrewarmRequest?.finish(false);
  contextMapPrewarmRequest = null;
  contextMapPrewarmFrameReady = false;
  for (const resolve of contextMapPrewarmFrameWaiters) resolve(false);
  contextMapPrewarmFrameWaiters.clear();
  const frame = contextMapPrewarmFrame();
  if (frame) {
    frame.src = contextMapPrewarmSuspended
      ? "about:blank"
      : "/map/index.html" +
        `?mode=preview&network=${mapNetworkEnabled ? "1" : "0"}` +
        `&revision=${Date.now()}`;
  }
  scheduleVisibleContextMapPreviews();
}

function setContextMapPreviewImage(holder, src) {
  if (!holder?.isConnected || !src) return;
  const image = holder.querySelector(".context-info-map-image");
  if (!image) return;
  image.src = src;
  image.classList.add("is-ready");
}

function bindContextMapPreview(root) {
  const holder = root?.querySelector("[data-context-location-preview]");
  if (!holder) return;
  const itemId = Number(holder.dataset.contextMapItemId);
  const item = state.items.find((entry) => Number(entry.id) === itemId);
  const key = contextMapPreviewKey(item);
  if (!key) return;
  holder.dataset.contextMapPreviewKey = key;
  const cached = contextMapPreviewCache.get(key);
  if (cached) {
    setContextMapPreviewImage(holder, cached);
    return;
  }
  void enqueueContextMapPreview(item, { priority: true }).then((src) => {
    if (holder.dataset.contextMapPreviewKey !== key) return;
    setContextMapPreviewImage(holder, src);
  });
}

function scheduleVisibleContextMapPreviews() {
  window.clearTimeout(contextMapPreviewScheduleTimer);
  if (contextMapPrewarmSuspended) return;
  contextMapPreviewScheduleTimer = window.setTimeout(() => {
    const content = $("#content");
    if (!content || state.copyTarget) return;
    const contentRect = content.getBoundingClientRect();
    const centerY = contentRect.top + contentRect.height / 2;
    const candidates = [
      ...content.querySelectorAll(".photo-grid .tile[data-index]"),
    ]
      .map((tile) => {
        const item = state.items[Number(tile.dataset.index)];
        if (!contextMapLocation(item)) return null;
        const rect = tile.getBoundingClientRect();
        if (rect.bottom < contentRect.top || rect.top > contentRect.bottom)
          return null;
        return {
          item,
          distance: Math.abs(rect.top + rect.height / 2 - centerY),
        };
      })
      .filter(Boolean)
      .sort((a, b) => a.distance - b.distance)
      .slice(0, 24);
    for (const { item } of candidates) void enqueueContextMapPreview(item);
  }, 0);
}

async function waitForContextMapPreviewBeforeOpen(item) {
  if (!contextMapLocation(item)) return;
  const key = contextMapPreviewKey(item);
  if (contextMapPreviewCache.has(key)) return;
  await Promise.race([
    enqueueContextMapPreview(item, { priority: true }),
    new Promise((resolve) => window.setTimeout(resolve, 1800)),
  ]);
}

window.addEventListener("message", (event) => {
  const frame = contextMapPrewarmFrame();
  if (
    !frame ||
    event.origin !== window.location.origin ||
    event.source !== frame.contentWindow
  )
    return;
  const message = event.data || {};
  if (message.type === "metadata-map:ready") {
    markContextMapPrewarmFrameReady();
    return;
  }
  if (
    message.type === "metadata-map:preview-ready" &&
    message.requestId === contextMapPrewarmRequest?.requestId
  ) {
    contextMapPrewarmRequest.finish(true);
  }
});

function contextItemInfoHTML(item) {
  updateViewerInfoPopover(item);
  const view = document.createElement("div");
  view.className = "context-detail-view";
  const hasLocation =
    item.gps_lat != null &&
    item.gps_lon != null &&
    Number.isFinite(Number(item.gps_lat)) &&
    Number.isFinite(Number(item.gps_lon));
  for (const source of [...$("#viewerInfoPopover").children]) {
    if (source.classList.contains("viewer-info-location")) continue;
    const clone = source.cloneNode(true);
    if (clone.id) clone.removeAttribute("id");
    clone
      .querySelectorAll("[id]")
      .forEach((node) => node.removeAttribute("id"));
    const adjust = clone.querySelector(".viewer-info-adjust");
    if (adjust) adjust.dataset.contextDetailAdjust = "";
    if (clone.classList.contains("viewer-info-map") && !hasLocation) {
      clone.classList.add("has-context-location-add");
      const addLocation = document.createElement("button");
      addLocation.type = "button";
      addLocation.className = "context-info-location-add";
      addLocation.dataset.contextLocationAdd = "";
      addLocation.textContent = "添加位置…";
      clone.replaceChildren(addLocation);
    }
    if (clone.classList.contains("viewer-info-map") && hasLocation) {
      clone.classList.add("has-map");
      clone.dataset.contextLocationPreview = "";
      clone.tabIndex = 0;
      clone.setAttribute("role", "button");
      clone.setAttribute("aria-label", "查看项目位置地图");
      const lat = Number(item.gps_lat);
      const lon = Number(item.gps_lon);
      const image = document.createElement("img");
      image.className = "context-info-map-image";
      image.alt = "";
      image.draggable = false;
      const previewKey = contextMapPreviewKey(item);
      clone.dataset.contextMapItemId = String(item.id);
      clone.dataset.contextMapPreviewKey = previewKey;
      const cachedPreview = contextMapPreviewCache.get(previewKey);
      if (cachedPreview) {
        image.src = cachedPreview;
        image.classList.add("is-ready");
      }
      const pin = document.createElementNS("http://www.w3.org/2000/svg", "svg");
      pin.classList.add("context-info-map-pin");
      pin.setAttribute("viewBox", "0 0 26 36");
      pin.setAttribute("aria-hidden", "true");
      pin.innerHTML = window.AlbumMapPinIcon.innerHTML("context-info-map-pin");
      const footer = document.createElement("div");
      footer.className = "context-info-map-footer";
      footer.dataset.contextLocationAdjust = "";
      footer.title = "调整项目位置";
      const label = document.createElement("span");
      label.className = "context-info-map-label";
      label.textContent =
        String(item.location_name || "").trim() ||
        metadataMapCoordinateText(lat, lon);
      const chevron = document.createElementNS(
        "http://www.w3.org/2000/svg",
        "svg",
      );
      chevron.classList.add("context-info-map-chevron");
      chevron.setAttribute("viewBox", "0 0 8 14");
      chevron.setAttribute("aria-hidden", "true");
      const chevronPath = document.createElementNS(
        "http://www.w3.org/2000/svg",
        "path",
      );
      chevronPath.setAttribute("d", "m1 1 6 6-6 6");
      chevron.append(chevronPath);
      const adjust = document.createElement("button");
      adjust.type = "button";
      adjust.className = "context-info-map-adjust";
      adjust.dataset.contextLocationAdjust = "";
      adjust.textContent = "调整";
      footer.append(label, chevron, adjust);
      clone.replaceChildren(image, pin, footer);
    }
    view.append(clone);
  }
  const liveMotion = contextSourceVideo;
  if (
    isLivePhoto(item) &&
    liveMotion &&
    !liveMotion.paused &&
    !liveMotion.ended
  ) {
    setLiveInfoBreathing(view, true);
  }
  return view.outerHTML;
}

function bindContextDetailAdjustButton(root = $("#contextMenu")) {
  const button = root?.querySelector?.(
    ".context-detail-view [data-context-detail-adjust]",
  );
  if (!button || button.dataset.dateAdjustBound === "true") return;
  button.dataset.dateAdjustBound = "true";
  button.addEventListener("pointerdown", (event) => {
    /* “调整”是文字按钮，不属于信息卡顶部的拖动区域。 */
    event.stopPropagation();
  });
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openContextDate({ anchorRect: button.getBoundingClientRect() });
  });
}

function closeContextDate({ immediate = false } = {}) {
  const popup = $("#contextDatePopover");
  if (!contextDateOpen) {
    popup.hidden = true;
    return;
  }
  contextDateOpen = false;
  contextDateDrag = null;
  const startFrame = captureVisualFrame(popup);
  popup
    .getAnimations({ subtree: true })
    .forEach((animation) => animation.cancel());
  contextDateAnim = null;
  const finish = () => {
    if (contextDateOpen) return;
    popup.hidden = true;
    popup.innerHTML = "";
    popup.classList.remove("menu-date-editor", "is-closing", "is-dragging");
  };
  if (immediate) {
    finish();
    return;
  }
  popup.classList.add("is-closing");
  const endScale = Math.min(0.97, visualScaleOf(startFrame));
  const anim = popup.animate(
    [startFrame, { opacity: 0, transform: `scale(${endScale})` }],
    { duration: VIEWER_DATE_CLOSE_MS, easing: UI_EASE_OUT },
  );
  contextDateAnim = anim;
  anim.onfinish = () => {
    if (contextDateOpen || contextDateAnim !== anim) return;
    contextDateAnim = null;
    finish();
  };
}

async function saveContextItemDate(ms, item) {
  if (!item) return false;
  const editedId = item.id;
  const scrollTop = $("#content").scrollTop;
  quietUntil = Date.now() + 6000;
  state.busy = "正在写入拍摄时间…";
  renderStatus();
  try {
    const res = await api("/api/items/date", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ids: itemActionIds([item]), takenAt: ms }),
    });
    applyState(res.state);
    closeContextDate({ immediate: true });
    await reloadActiveCollection();
    const nextIndex = state.items.findIndex((entry) => entry.id === editedId);
    if (nextIndex >= 0) {
      state.cursor = nextIndex;
      state.zoomAnchorId = editedId;
      contextItemIndex = nextIndex;
    }
    state.select = false;
    state.selected.clear();
    render({ keepContextMenu: true });
    if (contextMenuOpen) {
      const shown = state.items[contextItemIndex];
      const nextTile = document.querySelector(
        `.photo-grid .tile[data-index="${contextItemIndex}"]`,
      );
      if (shown && nextTile) {
        contextTile = nextTile;
        nextTile.classList.add("is-context-origin");
        const sceneRect = $("#contextScene").getBoundingClientRect();
        const nextRect =
          tileMorphRect(nextTile) || nextTile.getBoundingClientRect();
        contextSourceStart = {
          left: nextRect.left - sceneRect.left,
          top: nextRect.top - sceneRect.top,
          width: nextRect.width,
          height: nextRect.height,
        };
      }
    }
    refreshOpenItemInfo(editedId);
    $("#content").scrollTop = scrollTop;
    lastRev = (await api("/api/revision")).rev;
    return !(res.failed || []).length;
  } catch (err) {
    alert(err.message);
    return false;
  } finally {
    state.busy = "";
    renderStatus();
  }
}

function openContextDate({ anchorRect = null } = {}) {
  const item = state.items[contextItemIndex];
  const menu = $("#contextMenu");
  const scene = $("#contextScene");
  if (
    !item ||
    scene.hidden ||
    scene.classList.contains("is-closing") ||
    !menu.classList.contains("is-item-detail")
  )
    return;
  closeContextDate({ immediate: true });
  const popup = $("#contextDatePopover");
  const anchor =
    anchorRect ??
    menu.querySelector(".viewer-info-adjust")?.getBoundingClientRect();
  if (!anchor) return;
  popup.style.left = "";
  popup.style.top = "";
  popup.style.right = "";
  popup.classList.add("menu-date-editor");
  popup.innerHTML = menuDateEditorHTML(itemTime(item), { showHint: false });
  popup.hidden = false;

  const sceneRect = $("#contextScene").getBoundingClientRect();
  const contentRect = $("#content").getBoundingClientRect();
  popup.style.left = "0px";
  popup.style.top = "0px";
  popup.style.right = "auto";
  const popupRect = popup.getBoundingClientRect();
  const inset = 14;
  const contentLeft = contentRect.left - sceneRect.left;
  const contentTop = contentRect.top - sceneRect.top;
  const contentRight = contentRect.right - sceneRect.left;
  const contentBottom = contentRect.bottom - sceneRect.top;
  const menuRect = menu.getBoundingClientRect();
  let left =
    menuRect.left - sceneRect.left + (menuRect.width - popupRect.width) / 2;
  /* 时间窗口替换信息卡时沿用信息卡顶边，不从“调整”按钮下方再展开，
     避免画面出现一次不必要的向下跳位。 */
  const infoTop = menuRect.top - sceneRect.top;
  let top = infoTop;
  if (top + popupRect.height > contentBottom - inset) {
    top = contentBottom - inset - popupRect.height;
  }
  left = Math.min(
    Math.max(contentLeft + inset, left),
    Math.max(contentLeft + inset, contentRight - inset - popupRect.width),
  );
  top = Math.min(
    Math.max(contentTop + inset, top),
    Math.max(contentTop + inset, contentBottom - inset - popupRect.height),
  );
  popup.style.left = `${left}px`;
  popup.style.top = `${top}px`;
  popup.style.transformOrigin =
    `${anchor.left + anchor.width / 2 - sceneRect.left - left}px ` +
    `${anchor.top + anchor.height / 2 - sceneRect.top - top}px`;
  contextDateOpen = true;
  bindDateEditorControls(popup, {
    items: [item],
    save: async (nextMs, items) => {
      const ok = await saveContextItemDate(nextMs, items[0]);
      return ok;
    },
    onClose: () => closeContextDate(),
    onDismiss: () => closeContextDate(),
    showSavingStatus: false,
  });
  popup.classList.remove("is-closing", "is-dragging");
  contextDateAnim = popup.animate(
    [
      { opacity: 0, transform: "scale(0.92) translateY(-4px)" },
      { opacity: 1, transform: "scale(1.005)", offset: 0.72 },
      { opacity: 1, transform: "scale(1)" },
    ],
    { duration: 210, easing: "cubic-bezier(0.32, 0.72, 0.42, 1)" },
  );
  revealMenuDate(popup);
}

function clampContextDatePosition() {
  const popup = $("#contextDatePopover");
  if (!contextDateOpen || !popup.style.left) return;
  const sceneRect = $("#contextScene").getBoundingClientRect();
  const contentRect = $("#content").getBoundingClientRect();
  const inset = 14;
  const minLeft = contentRect.left - sceneRect.left + inset;
  const minTop = contentRect.top - sceneRect.top + inset;
  const maxLeft = Math.max(
    minLeft,
    contentRect.right - sceneRect.left - inset - popup.offsetWidth,
  );
  const maxTop = Math.max(
    minTop,
    contentRect.bottom - sceneRect.top - inset - popup.offsetHeight,
  );
  popup.style.left = `${Math.min(
    Math.max(minLeft, parseFloat(popup.style.left) || minLeft),
    maxLeft,
  )}px`;
  popup.style.top = `${Math.min(
    Math.max(minTop, parseFloat(popup.style.top) || minTop),
    maxTop,
  )}px`;
  popup.style.right = "auto";
}

function endContextDateDrag(event) {
  const drag = contextDateDrag;
  if (!drag || (event.pointerId != null && event.pointerId !== drag.pointerId))
    return;
  contextDateDrag = null;
  $("#contextDatePopover").classList.remove("is-dragging");
  try {
    drag.handle.releasePointerCapture(drag.pointerId);
  } catch {}
  clampContextDatePosition();
}

function bindContextDateDrag() {
  const popup = $("#contextDatePopover");
  popup.addEventListener("pointerdown", (event) => {
    const handle = event.target.closest?.(".menu-date-head");
    if (
      !handle ||
      event.button !== 0 ||
      event.isPrimary === false ||
      event.target.closest("button, input, textarea, select, .menu-date-year")
    )
      return;
    const sceneRect = $("#contextScene").getBoundingClientRect();
    const popupRect = popup.getBoundingClientRect();
    contextDateDrag = {
      pointerId: event.pointerId,
      handle,
      startX: event.clientX,
      startY: event.clientY,
      left: popupRect.left - sceneRect.left,
      top: popupRect.top - sceneRect.top,
    };
    popup.style.left = `${contextDateDrag.left}px`;
    popup.style.top = `${contextDateDrag.top}px`;
    popup.style.right = "auto";
    popup.classList.add("is-dragging");
    try {
      handle.setPointerCapture(event.pointerId);
    } catch {}
    event.preventDefault();
    event.stopPropagation();
  });
  popup.addEventListener("pointermove", (event) => {
    const drag = contextDateDrag;
    if (!drag || event.pointerId !== drag.pointerId) return;
    popup.style.left = `${drag.left + event.clientX - drag.startX}px`;
    popup.style.top = `${drag.top + event.clientY - drag.startY}px`;
    clampContextDatePosition();
    event.preventDefault();
  });
  popup.addEventListener("pointerup", endContextDateDrag);
  popup.addEventListener("pointercancel", endContextDateDrag);
  popup.addEventListener("lostpointercapture", endContextDateDrag, true);
}

bindContextDateDrag();

/* 信息卡初次展开时和放大的项目是同一浮层里的两个对象：卡片可以左右并排，
   也可以在空间不足时改到项目上方 / 下方，但初始位置不能压住项目。
   横向并排时与项目边缘保持和普通操作菜单相同的 20px 间距。
   展开后由用户拖动时可自由经过项目，只受项目区边界限制。 */
function placeContextDetailCard(
  sourceRect,
  cardWidth,
  cardHeight,
  contentRect,
  sceneRect,
  { preferredSide = "", trackSourceTop = false } = {},
) {
  const gap = CONTEXT_DETAIL_GAP;
  const edge = CONTEXT_DETAIL_EDGE;
  const contentLeft = contentRect.left - sceneRect.left;
  const contentRight = contentRect.right - sceneRect.left;
  const contentTop = contentRect.top - sceneRect.top;
  const contentBottom = contentRect.bottom - sceneRect.top;
  const source = {
    left: sourceRect.left - sceneRect.left,
    top: sourceRect.top - sceneRect.top,
    right: sourceRect.right - sceneRect.left,
    bottom: sourceRect.bottom - sceneRect.top,
  };
  const minLeft = contentLeft + edge;
  const maxLeft = Math.max(minLeft, contentRight - edge - cardWidth);
  const minTop = contentTop;
  const maxTop = Math.max(minTop, contentBottom - cardHeight);
  const clampLeft = (left) => Math.min(Math.max(left, minLeft), maxLeft);
  const clampTop = (top) => Math.min(Math.max(top, minTop), maxTop);
  const sourceCenterX = (source.left + source.right) / 2;
  const sourceCenterY = (source.top + source.bottom) / 2;
  const contentCenterX = (contentLeft + contentRight) / 2;
  const contentCenterY = (contentTop + contentBottom) / 2;

  const horizontal = (side) => {
    const left =
      side === "right" ? source.right + gap : source.left - gap - cardWidth;
    return {
      side,
      left,
      top: trackSourceTop ? source.top : clampTop(source.top),
      fits: left >= minLeft && left <= maxLeft,
    };
  };
  const vertical = (side) => {
    const top =
      side === "bottom" ? source.bottom + gap : source.top - gap - cardHeight;
    return {
      side: "",
      left: clampLeft(sourceCenterX - cardWidth / 2),
      top,
      fits: top >= minTop && top <= maxTop,
    };
  };

  const preferred =
    preferredSide === "left" || preferredSide === "right" ? preferredSide : "";
  const sideCandidates = [
    horizontal(preferred === "left" ? "left" : "right"),
    horizontal(preferred === "left" ? "right" : "left"),
    vertical(sourceCenterY < contentCenterY ? "bottom" : "top"),
    vertical(sourceCenterY < contentCenterY ? "top" : "bottom"),
  ];

  const preferredHorizontal =
    preferred || (sourceCenterX < contentCenterX ? "right" : "left");
  const first = horizontal(preferredHorizontal);
  const second = horizontal(preferredHorizontal === "right" ? "left" : "right");
  if (first.fits) return first;
  if (second.fits) return second;

  const fits = sideCandidates.filter((candidate) => candidate.fits);
  if (!fits.length) {
    /* 极窄窗口下也优先保留卡片尺寸；卡片已经限制在内容区内时，
       最后一项只是兜底，不会越过项目区边界。 */
    return {
      side: "",
      left: clampLeft(sourceCenterX - cardWidth / 2),
      top: clampTop(sourceCenterY - cardHeight / 2),
    };
  }
  return fits[0];
}

function clearContextDetailContentMotion() {
  contextDetailContentAnim?.cancel();
  contextDetailContentAnim = null;
  contextDetailRevealAnims.forEach((anim) => anim.cancel());
  contextDetailRevealAnims = [];
  $("#contextScene")
    .querySelectorAll(".context-detail-content-layer")
    .forEach((node) => node.remove());
  const view = $("#contextMenu").querySelector(".context-detail-view");
  if (!view) return;
  view.style.opacity = "";
  view.style.transform = "";
  view.style.filter = "";
}

/* 详细不是一个居中的新弹窗，而是在操作菜单原位置向下展开：
   外层菜单从当前尺寸长到项目信息卡，旧菜单画面短暂盖住内容切换。 */
function expandContextDetail(item) {
  if (!contextMenuOpen || !item || contextDetailOpen) return;
  const scene = $("#contextScene");
  const menu = $("#contextMenu");
  const sceneRect = scene.getBoundingClientRect();
  const contentRect = $("#content").getBoundingClientRect();
  const oldRect = menu.getBoundingClientRect();
  const margin = 20;

  const oldMenuSource = menu.cloneNode(true);
  oldMenuSource.removeAttribute("id");
  oldMenuSource
    .querySelectorAll("[id]")
    .forEach((node) => node.removeAttribute("id"));
  oldMenuSource.setAttribute("aria-hidden", "true");

  menu.classList.add("is-item-detail");
  menu.setAttribute("role", "dialog");
  menu.setAttribute("aria-label", "项目详细");
  menu.style.height = "";
  menu.innerHTML = contextItemInfoHTML(item);
  bindContextMapPreview(menu);
  bindContextDetailAdjustButton(menu);
  const targetWidth = Math.min(
    CONTEXT_INFO_CARD_WIDTH,
    Math.max(250, contentRect.width - margin * 2),
  );
  menu.style.width = `${targetWidth}px`;
  menu.style.left = "0px";
  menu.style.top = "0px";
  const targetHeight = Math.min(
    menu.getBoundingClientRect().height,
    contentRect.height - margin * 2,
  );

  const oldLeft = oldRect.left - sceneRect.left;
  const oldTop = oldRect.top - sceneRect.top;
  const detailSource = $("#contextSource").getBoundingClientRect();
  /* 详细卡片与项目并排显示；靠近项目的一边始终留出 20px。
     优先延续普通菜单原来的方向，空间不足时自动改到另一边。 */
  const detailPlacement = placeContextDetailCard(
    detailSource,
    targetWidth,
    targetHeight,
    contentRect,
    sceneRect,
    { preferredSide: menu.dataset.contextSide },
  );
  const targetLeft = detailPlacement.left;
  const targetTop = detailPlacement.top;
  menu.dataset.contextSide = detailPlacement.side;

  menu.style.left = `${targetLeft}px`;
  menu.style.top = `${targetTop}px`;
  menu.style.height = `${targetHeight}px`;
  const fromTransform =
    `translate3d(${oldLeft - targetLeft}px, ` +
    `${oldTop - targetTop}px, 0) ` +
    `scale(${oldRect.width / targetWidth}, ${oldRect.height / targetHeight})`;
  const toTransform = "translate3d(0, 0, 0) scale(1, 1)";
  const detailExpandMs = MENU_DATE_OPEN_MS;
  const detailTiming = {
    duration: detailExpandMs,
    easing: MENU_DATE_OPEN_EASING,
  };
  const frameFrames = [
    {
      transformOrigin: "0 0",
      transform: fromTransform,
      borderRadius: "20px",
    },
    {
      transformOrigin: "0 0",
      transform: toTransform,
      borderRadius: "24px",
    },
  ];
  const oldContent = oldMenuSource.cloneNode(true);
  oldContent.removeAttribute("id");
  oldContent
    .querySelectorAll("[id]")
    .forEach((node) => node.removeAttribute("id"));
  oldContent.classList.add("context-detail-content-layer");
  oldContent.setAttribute("aria-hidden", "true");
  oldContent.style.left = `${targetLeft}px`;
  oldContent.style.top = `${targetTop}px`;
  oldContent.style.width = `${targetWidth}px`;
  oldContent.style.height = `${targetHeight}px`;
  oldContent.style.transform = fromTransform;
  scene.append(oldContent);
  oldContent.animate(frameFrames, { ...detailTiming, fill: "forwards" });
  /* 日期窗口展开时，原菜单行在原位轻微缩小并模糊退后；
     信息内容从略上方、稍小和低透明度浮出，内部区块随后依次显现。 */
  [...oldContent.querySelectorAll(".context-row, .context-separator")].forEach(
    (node, index) => {
      node.animate(
        [
          { opacity: 1, transform: "scale(1)", filter: "blur(0px)" },
          { opacity: 0, transform: "scale(0.97)", filter: "blur(2px)" },
        ],
        {
          duration: 210,
          delay: index * 4,
          easing: MENU_DATE_OPEN_EASING,
          fill: "forwards",
        },
      );
    },
  );
  contextDetailAnim = menu.animate([...frameFrames], detailTiming);
  const view = menu.querySelector(".context-detail-view");
  view.style.transformOrigin = "50% 0";
  contextDetailContentAnim = view.animate(
    [
      {
        opacity: 0.18,
        transform: "translateY(-12px) scale(0.985)",
      },
      {
        opacity: 1,
        transform: "translateY(0) scale(1)",
      },
    ],
    { ...detailTiming, fill: "forwards" },
  );
  contextDetailRevealAnims = [...view.children].map((node, index) => {
    const delay = Math.round(detailExpandMs * (0.12 + index * 0.055));
    return node.animate(
      [
        { opacity: 0, transform: "translateY(9px)", filter: "blur(2px)" },
        { opacity: 1, transform: "translateY(0)", filter: "blur(0px)" },
      ],
      {
        duration: detailExpandMs - delay,
        delay,
        easing: "cubic-bezier(0.2, 0.72, 0.26, 1)",
        fill: "both",
      },
    );
  });
  contextDetailAnim.finished.then(
    () => {
      if (!contextDetailOpen) return;
      clearContextDetailContentMotion();
    },
    () => {},
  );
  /* 详情展开后不再需要逐帧跟随项目边缘。 */
  contextDetailOpen = true;
  menu.focus({ preventScroll: true });
}

function resetContextMenuDom() {
  hideContextCrop();
  if (contextDateOpen) closeContextDate({ immediate: true });
  if (contextCloseTimer) {
    clearTimeout(contextCloseTimer);
    contextCloseTimer = null;
  }
  contextSourceAnim?.cancel();
  contextMenuAnim?.cancel();
  invalidateContextMotion();
  contextSourceImg = null;
  contextSourceVideo = null;
  contextSourceAnim = null;
  contextMenuAnim = null;
  contextDetailAnim?.cancel();
  contextDetailAnim = null;
  clearContextDetailContentMotion();
  contextDetailDrag = null;
  contextDetailOpen = false;
  contextSourceStart = null;
  contextSourceTarget = null;
  contextMenuTargetPlacement = null;
  contextMenuStartPlacement = null;
  $(".main").classList.remove("is-context-background");
  $(".main").classList.remove("is-context-backdrop-cheap");
  document.documentElement.classList.remove("context-preview-open");
  contextTile?.classList.remove("is-context-origin");
  contextTile = null;
  contextItemIndex = -1;
  const scene = $("#contextScene");
  scene.hidden = true;
  scene.classList.remove("is-closing");
  $("#contextSource").innerHTML = "";
  $("#contextSource").className = "context-source";
  $("#contextSource").removeAttribute("style");
  $("#contextMenu").innerHTML = "";
  $("#contextMenu").removeAttribute("style");
  $("#contextMenu").hidden = false;
  $("#contextMenu").removeAttribute("data-context-side");
  $("#contextMenu").removeAttribute("data-context-mode");
  $("#contextMenu").classList.remove("is-item-detail", "is-dragging");
  $("#contextMenu").setAttribute("role", "menu");
  $("#contextMenu").setAttribute("aria-label", "项目操作");
  const datePopup = $("#contextDatePopover");
  datePopup.hidden = true;
  datePopup.innerHTML = "";
  datePopup.removeAttribute("style");
  datePopup.classList.remove("menu-date-editor", "is-closing", "is-dragging");
}

function pinTileHover(tile, itemId) {
  if (!tile?.isConnected || itemId == null) return;
  clearPinnedHover();
  state.hoverPinId = itemId;
  tile.classList.add("is-hover-pinned");
  armPinnedHoverRelease();
}

function contextPointerOverTile(tile) {
  if (!tile?.isConnected) return false;
  const hit = document.elementFromPoint(contextPointerX, contextPointerY);
  return !!hit && (hit === tile || tile.contains(hit));
}

function closeItemContextMenu(
  immediate = false,
  { keepShadow = false, restoreFocus = false } = {},
) {
  if (!contextMenuOpen) {
    if (immediate) resetContextMenuDom();
    return;
  }
  const closingCrop = contextCropSession;
  contextMenuOpen = false;
  const closeTile = contextTile;
  const closeItemId = state.items[contextItemIndex]?.id;
  const restoreContextFocus = () => {
    if (!restoreFocus || !closeTile?.isConnected) return;
    window.setTimeout(() => {
      if (!closeTile.isConnected || !$("#viewer").hidden) return;
      closeTile.focus({ preventScroll: true });
    }, 0);
  };
  if (!keepShadow) clearPinnedHover();
  const scene = $("#contextScene");
  const menu = $("#contextMenu");
  const source = $("#contextSource");
  $(".main").classList.remove("is-context-background");
  if (immediate) {
    contextSourceVideo?.pause();
    resetContextMenuDom();
    restoreContextFocus();
    if (keepShadow && contextPointerOverTile(closeTile)) {
      pinTileHover(closeTile, closeItemId);
    }
    return;
  }

  const start = contextSourceStart;
  if (!start) {
    resetContextMenuDom();
    return;
  }
  if (closingCrop) animateContextCropClose(start);
  scene.classList.add("is-closing");
  const sceneRect = scene.getBoundingClientRect();
  const live = source.getBoundingClientRect();
  const target = contextSourceTarget || {
    left: source.offsetLeft,
    top: source.offsetTop,
    width: source.offsetWidth,
    height: source.offsetHeight,
  };
  const liveSource = {
    left: live.left - sceneRect.left,
    top: live.top - sceneRect.top,
    width: live.width,
    height: live.height,
  };
  contextSourceVideo?.pause();
  /* 菜单可能在展开途中就被点中：先记住它此刻的透明度和缩放，再从这一帧
     直接倒放，避免取消动画时先跳回完整尺寸再收。 */
  const menuLiveStyle = getComputedStyle(menu);
  const fromMenuOpacity = Number(menuLiveStyle.opacity);
  const closingDetail =
    contextDetailOpen || menu.classList.contains("is-item-detail");
  if (closingDetail) {
    contextDetailAnim?.cancel();
    contextDetailAnim = null;
    clearContextDetailContentMotion();
  }
  contextSourceAnim?.cancel();
  contextMenuAnim?.cancel();
  menu.style.opacity = String(fromMenuOpacity);
  menu.style.transform = "none";
  /* 直接动画外框的尺寸与位置，图片始终以 cover 铺满外框。这样从宽高比
     不同的预览缩回方形缩略图时，只发生裁切，不会短暂变形。 */
  contextSourceAnim = source.animate(
    [
      {
        left: `${liveSource.left}px`,
        top: `${liveSource.top}px`,
        width: `${liveSource.width}px`,
        height: `${liveSource.height}px`,
      },
      {
        left: `${start.left}px`,
        top: `${start.top}px`,
        width: `${start.width}px`,
        height: `${start.height}px`,
      },
    ],
    {
      duration: CONTEXT_PREVIEW_MOTION_MS,
      easing: CONTEXT_PREVIEW_EASING,
      fill: "forwards",
    },
  );
  contextSourceAnim.onfinish = layoutContextSourceImage;
  if (
    !closingCrop &&
    menu.style.visibility !== "hidden" &&
    menu.style.display !== "none"
  ) {
    const menuStyle = getComputedStyle(menu);
    const menuRect = menu.getBoundingClientRect();
    const menuBase = contextMenuTargetPlacement || {
      left: menu.offsetLeft,
      top: menu.offsetTop,
      width: menu.offsetWidth,
      height: menu.offsetHeight,
    };
    const menuStartScale = contextMenuStartScale(
      contextSourceStart.width,
      menuBase.width,
    );
    const menuLive = {
      left: menuRect.left - sceneRect.left,
      top: menuRect.top - sceneRect.top,
      width: menuRect.width,
      height: menuRect.height,
    };
    const fromMenuTransform = contextRectTransform(menuLive, menuBase);
    const toMenuTransform = contextMenuStartPlacement
      ? contextMenuTransform(
          contextMenuStartPlacement,
          menuBase,
          menuStartScale,
        )
      : fromMenuTransform;
    menu.style.left = `${menuBase.left}px`;
    menu.style.top = `${menuBase.top}px`;
    menu.style.width = `${menuBase.width}px`;
    menu.style.height = `${menuBase.height}px`;
    menu.style.transformOrigin = "0 0";
    const itemDetailClosing = menu.classList.contains("is-item-detail");
    const closeFrames = itemDetailClosing
      ? [
          {
            opacity: Number(menuStyle.opacity) || fromMenuOpacity,
            transform: fromMenuTransform,
            offset: 0,
          },
          { opacity: 0, transform: toMenuTransform, offset: 1 },
        ]
      : [
          {
            opacity: fromMenuOpacity,
            transform: fromMenuTransform,
            offset: 0,
          },
          {
            opacity: fromMenuOpacity,
            transform: toMenuTransform,
            offset: 0.55,
          },
          { opacity: 0, transform: toMenuTransform, offset: 1 },
        ];
    contextMenuAnim = menu.animate(closeFrames, {
      duration: CONTEXT_PREVIEW_MOTION_MS,
      easing: CONTEXT_PREVIEW_EASING,
      fill: "forwards",
    });
  }
  contextCloseTimer = setTimeout(() => {
    if (contextMenuOpen) return;
    layoutContextSourceImage();
    closeTile?.classList.remove("is-context-origin");
    resetContextMenuDom();
    restoreContextFocus();
    if (keepShadow && contextPointerOverTile(closeTile)) {
      pinTileHover(closeTile, closeItemId);
    } else {
      closeTile?.classList.remove("is-hover-pinned");
    }
  }, 400);
}

function openItemContextMenu(
  index,
  tile,
  { mode = "actions", keyboard = false } = {},
) {
  if (contextMenuOpen) closeItemContextMenu(true);
  else if (contextCloseTimer) resetContextMenuDom();
  const item = state.items[index];
  if (!item || !tile?.isConnected) return;
  const contextCropMode = mode === "crop";
  const contextPreviewOnly = mode === "preview";
  const motionDuration = keyboard ? 0 : CONTEXT_PREVIEW_MOTION_MS;
  closeMenu();
  hidePickerNow();
  clearPinnedHover();

  const scene = $("#contextScene");
  const source = $("#contextSource");
  const menu = $("#contextMenu");
  scene.hidden = false;
  const sceneRect = scene.getBoundingClientRect();
  const tileRect = tile.getBoundingClientRect();
  if (tileRect.width <= 0 || tileRect.height <= 0) {
    resetContextMenuDom();
    return;
  }

  const contentRect = $("#content").getBoundingClientRect();
  const contentLeft = contentRect.left - sceneRect.left;
  const contentRight = contentRect.right - sceneRect.left;
  const contentTop = contentRect.top - sceneRect.top;
  const contentBottom = contentRect.bottom - sceneRect.top;
  const contentMargin = 20;
  const availableWidth = Math.max(
    120,
    contentRight - contentLeft - contentMargin * 2,
  );

  menu.innerHTML =
    contextCropMode || contextPreviewOnly ? "" : contextMenuRows(item);
  const menuCssWidth = Math.min(208, availableWidth);
  menu.style.width = `${menuCssWidth}px`;
  menu.style.left = "0px";
  menu.style.top = "0px";
  const menuWidth = menu.offsetWidth;
  const menuHeight =
    contextCropMode || contextPreviewOnly ? 0 : menu.offsetHeight;
  const img = tile.querySelector("img");
  /* 照片墙格子的缩略图本身就是按裁剪参数生成的正方形，不能拿它的
     自然尺寸计算浮层比例，否则右键裁剪会把已经裁过的画面再当成原图。 */
  let aspect =
    contextCropMode && item.width && item.height ? item.width / item.height : 0;
  if (!aspect && img?.naturalWidth && img?.naturalHeight) {
    aspect = img.naturalWidth / img.naturalHeight;
  }
  if (!aspect && item.width && item.height) aspect = item.width / item.height;
  if (!aspect) aspect = 1;
  /* 预览最终始终是照片原始比例；正方形网格只决定它从多大的方形格子起步。 */
  const previewAspect = aspect;
  const startRect = tileMorphRect(tile) || tileRect;
  const start = {
    left: startRect.left - sceneRect.left,
    top: startRect.top - sceneRect.top,
    width: startRect.width,
    height: startRect.height,
  };

  const minTop = Math.max(12, contentTop + 8);
  const gap = 20;
  /* 所有项目使用同一个前移比例；不按各自宽高比单独设定放大上限。 */
  const previewForwardScale = 1.22;
  const centralSquare =
    Math.min(tileRect.width, tileRect.height) * previewForwardScale;
  /* 两种视图共用同一个终点尺寸：先放大中间正方形，再展开被挡住的部分。 */
  let width;
  let height;
  if (previewAspect >= 1) {
    height = centralSquare;
    width = height * previewAspect;
  } else {
    width = centralSquare;
    height = width / previewAspect;
  }
  if (width > availableWidth) {
    width = availableWidth;
    height = width / previewAspect;
  }
  const previewMaxHeight = Math.max(140, contentBottom - contentTop - 24);
  if (height > previewMaxHeight) {
    height = previewMaxHeight;
    width = height * previewAspect;
  }
  /* 当前右键/空格预览尺寸作为「小」的基准；中、大档在此基础上
     整体放大，再按项目区可用宽高封顶，不会撑出内容区。 */
  const previewMagnification = contextCropMode ? 1 : viewerPreviewScale();
  if (previewMagnification > 1) {
    width *= previewMagnification;
    height *= previewMagnification;
    if (width > availableWidth) {
      width = availableWidth;
      height = width / previewAspect;
    }
    if (height > previewMaxHeight) {
      height = previewMaxHeight;
      width = height * previewAspect;
    }
  }

  const centerX = start.left + start.width / 2;
  const centerY = start.top + start.height / 2;
  const minLeft = contentLeft + contentMargin;
  const maxLeft = Math.max(minLeft, contentRight - width - contentMargin);
  const desiredTop = centerY - height / 2;
  const belowTop = contentBottom - menuHeight - gap - height - 12;
  const canFitBelow = belowTop >= minTop;
  const contentAvailableHeight = Math.max(120, contentBottom - contentTop - 24);
  const needsSideLayout = !canFitBelow;
  let sideMenu = null;
  let menuTop;
  let targetTop;
  let target;
  if (needsSideLayout) {
    /* 内容和菜单竖着放不下时，不把预览搬到中间：保留它原本会落到的大致位置，
       只按左右余量选择一条侧边并适度收窄，让菜单贴着放大后的项目。 */
    const rightCenterLimit = contentRight - contentMargin - gap - menuWidth;
    const leftCenterLimit = contentLeft + contentMargin + gap + menuWidth;
    const rightWidthCapacity = Math.max(0, (rightCenterLimit - centerX) * 2);
    const leftWidthCapacity = Math.max(0, (centerX - leftCenterLimit) * 2);
    const originalRight = start.left + start.width;
    const originalLeft = start.left;
    const canUseRightAtOriginal =
      originalRight + gap + menuWidth <= contentRight - contentMargin;
    const canUseLeftAtOriginal =
      originalLeft - gap - menuWidth >= contentLeft + contentMargin;
    const contentCenterX = (contentLeft + contentRight) / 2;
    let useRight = centerX < contentCenterX;
    if (useRight && !canUseRightAtOriginal && canUseLeftAtOriginal)
      useRight = false;
    else if (!useRight && !canUseLeftAtOriginal && canUseRightAtOriginal)
      useRight = true;
    const sideWidthCapacity = Math.max(
      80,
      useRight ? rightWidthCapacity : leftWidthCapacity,
    );
    if (width > sideWidthCapacity) {
      width = sideWidthCapacity;
      height = width / previewAspect;
    }
    if (height > contentAvailableHeight) {
      height = contentAvailableHeight;
      width = height * previewAspect;
    }
    let previewLeft = Math.max(
      contentLeft + contentMargin,
      Math.min(centerX - width / 2, contentRight - contentMargin - width),
    );
    const sideTargetTop = Math.max(
      minTop,
      Math.min(desiredTop, contentBottom - contentMargin - height),
    );
    let rightMenuLeft = previewLeft + width + gap;
    let leftMenuLeft = previewLeft - gap - menuWidth;
    let rightFits = rightMenuLeft + menuWidth <= contentRight - contentMargin;
    let leftFits = leftMenuLeft >= contentLeft + contentMargin;
    const menuOnRight = useRight ? rightFits : !leftFits && rightFits;
    /* 窄窗口中的右侧项目可能同时放不下预览和菜单。先保持所选侧边，
       等比收窄预览，让“照片 + 间距 + 菜单”整体落在内容边界内。 */
    if (!leftFits && !rightFits) {
      const sideGroupWidth = menuWidth + gap;
      width = Math.max(
        80,
        Math.min(
          width,
          contentRight - contentLeft - contentMargin * 2 - sideGroupWidth,
        ),
      );
      height = width / previewAspect;
      previewLeft = menuOnRight
        ? contentLeft + contentMargin
        : contentLeft + contentMargin + sideGroupWidth;
      rightFits =
        previewLeft + width + gap + menuWidth <= contentRight - contentMargin;
      leftFits = previewLeft - gap - menuWidth >= contentLeft + contentMargin;
      rightMenuLeft = previewLeft + width + gap;
      leftMenuLeft = previewLeft - gap - menuWidth;
    }
    const menuLeft = menuOnRight ? rightMenuLeft : leftMenuLeft;
    target = { left: previewLeft, top: sideTargetTop, width, height };
    menuTop = Math.max(
      contentTop,
      Math.min(sideTargetTop, contentBottom - contentMargin - menuHeight),
    );
    sideMenu = { side: menuOnRight ? "right" : "left", left: menuLeft };
  } else if (canFitBelow) {
    targetTop = Math.min(Math.max(minTop, desiredTop), belowTop);
    menuTop = targetTop + height + gap;
    target = {
      left: Math.max(minLeft, Math.min(centerX - width / 2, maxLeft)),
      top: targetTop,
      width,
      height,
    };
  } else {
    /* 菜单放下方会越界时，项目保持同样大小，改为整体上移并把菜单放到上方。 */
    targetTop = Math.max(
      minTop,
      Math.min(desiredTop, contentBottom - height - 12),
    );
    menuTop = targetTop - gap - menuHeight;
    if (menuTop < minTop) {
      targetTop = Math.min(
        contentBottom - height - 12,
        minTop + menuHeight + gap,
      );
      menuTop = targetTop - gap - menuHeight;
    }
    target = {
      left: Math.max(minLeft, Math.min(centerX - width / 2, maxLeft)),
      top: targetTop,
      width,
      height,
    };
  }

  if (mode === "details" || contextPreviewOnly) {
    /* 信息卡从项目侧面展开，不再需要给下方菜单留位置。项目自身的尺寸
       足以从原格子顶边向下展开时，保持这条顶边不动，让放大只向下长；
       只有贴近内容区底边时才向上收，避免无谓地把项目搬到画面中部。 */
    const preferredDownwardTop = Math.max(minTop, start.top);
    const downwardLimit = contentBottom - 12 - target.height;
    target.top = Math.min(preferredDownwardTop, downwardLimit);
  }

  contextSourceTarget = { ...target };
  source.className = "context-source";
  source.style.left = `${target.left}px`;
  source.style.top = `${target.top}px`;
  source.style.width = `${target.width}px`;
  source.style.height = `${target.height}px`;
  source.style.borderRadius = "7px";
  source.style.transformOrigin = "0 0";
  source.style.transform = "none";
  source.innerHTML = "";
  contextSourceImg = null;
  contextSourceVideo = null;
  let startContextVideo = null;
  if (item.kind === "video") {
    const video = document.createElement("video");
    video.className = "context-source-video";
    video.src = fileUrl(item);
    video.poster = openingPosterUrl(item);
    video.loop = true;
    video.playsInline = true;
    video.preload = "auto";
    applyPreviewAudioPreference(video);
    video.disablePictureInPicture = true;
    video.setAttribute("disablepictureinpicture", "");
    video.setAttribute("disableremoteplayback", "");
    source.append(video);
    contextSourceVideo = video;
    startContextVideo = () => {
      if (!contextMenuOpen || !video.isConnected) return;
      applyPreviewAudioPreference(video);
      video.play().catch(() => {});
    };
    video.addEventListener("loadeddata", () => {
      if (
        contextMenuOpen &&
        contextSourceVideo === video &&
        contextSourceAnim?.playState === "finished"
      ) {
        startContextVideo();
      }
    });
  } else {
    let previewFallback = null;
    if (contextCropMode && (img?.currentSrc || img?.src)) {
      previewFallback = document.createElement("img");
      previewFallback.className = "context-source-fallback";
      previewFallback.src = img.currentSrc || img.src;
      previewFallback.alt = "";
      previewFallback.draggable = false;
      previewFallback.decoding = "sync";
      source.append(previewFallback);
    }
    const sourceImg = document.createElement("img");
    sourceImg.className = "context-source-image";
    sourceImg.src = contextCropMode
      ? itemThumbUrl(item, 1600, "inside")
      : img?.currentSrc || img?.src || itemThumbUrl(item, 1600, "inside");
    sourceImg.alt = "";
    sourceImg.draggable = false;
    sourceImg.loading = "eager";
    sourceImg.decoding = "async";
    sourceImg.fetchPriority = "high";
    sourceImg.style.position = "absolute";
    sourceImg.style.inset = "0";
    sourceImg.style.margin = "auto";
    sourceImg.style.objectFit = "fill";
    sourceImg.style.transformOrigin = "50% 50%";
    sourceImg.style.opacity = previewFallback ? "0" : "1";
    source.append(sourceImg);
    contextSourceImg = sourceImg;
    sourceImg.addEventListener(
      "load",
      () => {
        layoutContextSourceImage();
        if (previewFallback && contextSourceImg === sourceImg) {
          sourceImg.style.opacity = "1";
          previewFallback.style.opacity = "0";
        }
      },
      { once: true },
    );
    layoutContextSourceImage();
    /* 照片墙资料库右键只抬起静态封面用于裁剪，不启动实况伴生视频。 */
    const liveVideo = contextCropMode ? 0 : liveVideoId(item);
    if (liveVideo) {
      const video = document.createElement("video");
      video.className = "context-source-video context-source-live-video";
      video.src = fileUrl(liveVideo);
      video.loop = false;
      video.playsInline = true;
      video.preload = "auto";
      video.disablePictureInPicture = true;
      video.setAttribute("disablepictureinpicture", "");
      video.setAttribute("disableremoteplayback", "");
      const revealContextLive = () => {
        if (contextSourceVideo !== video) return;
        video.classList.add("is-playing");
        applyPreviewAudioPreference(video, { live: true });
        setLiveInfoBreathing($("#contextMenu"), true);
      };
      const waitForContextLiveFrame = () => {
        if (typeof video.requestVideoFrameCallback === "function") {
          video.requestVideoFrameCallback(() => revealContextLive());
          return;
        }
        video.addEventListener(
          "playing",
          () => {
            requestAnimationFrame(() =>
              requestAnimationFrame(revealContextLive),
            );
          },
          { once: true },
        );
      };
      video.addEventListener("ended", () => {
        if (contextSourceVideo !== video) return;
        video.classList.remove("is-playing");
        video.muted = true;
        setLiveInfoBreathing($("#contextMenu"), false);
      });
      source.append(video);
      contextSourceVideo = video;
      startContextVideo = () => {
        if (
          !contextMenuOpen ||
          contextSourceVideo !== video ||
          !video.isConnected
        )
          return;
        if (!video.paused) return;
        /* 右键实况预览同样等首帧就绪后再和声音一起交接。 */
        video.muted = true;
        video.volume = 1;
        waitForContextLiveFrame();
        video.play().catch(() => {});
      };
      video.addEventListener("loadeddata", () => {
        if (
          contextMenuOpen &&
          contextSourceVideo === video &&
          contextSourceAnim?.playState === "finished"
        ) {
          startContextVideo();
        }
      });
    }
  }

  const menuOnTop = !sideMenu && !canFitBelow;
  menu.dataset.contextSide = sideMenu?.side || "";
  menu.dataset.contextMode = mode;
  menu.style.transformOrigin = sideMenu
    ? sideMenu.side === "right"
      ? "0 0"
      : "100% 0"
    : menuOnTop
      ? "50% 100%"
      : "50% 0";
  const placeMenuBesideSource = (live) => {
    const liveLeft = live.left;
    const liveRight = live.left + live.width;
    const liveCenter = liveLeft + live.width / 2;
    const liveTop = live.top;
    const liveBottom = live.top + live.height;
    if (sideMenu) {
      const preferredLeft =
        sideMenu.side === "right"
          ? liveRight + gap
          : liveLeft - gap - menuWidth;
      const left = Math.max(
        contentLeft + contentMargin,
        Math.min(preferredLeft, contentRight - contentMargin - menuWidth),
      );
      return { left, top: liveTop, width: menuWidth, height: menuHeight };
    }
    const halfWidth = menuWidth / 2;
    const minCenter = contentLeft + contentMargin + halfWidth;
    const maxCenter = contentRight - contentMargin - halfWidth;
    const center =
      minCenter <= maxCenter
        ? Math.min(Math.max(liveCenter, minCenter), maxCenter)
        : (contentLeft + contentRight) / 2;
    const left = center - menuWidth / 2;
    const top = menuOnTop ? liveTop - gap - menuHeight : liveBottom + gap;
    return { left, top, width: menuWidth, height: menuHeight };
  };

  const renderedContextItemCount = $("#content").querySelectorAll(
    ".photo-grid .tile[data-index]",
  ).length;
  $(".main").classList.toggle(
    "is-context-backdrop-cheap",
    !contextCropMode &&
      renderedContextItemCount > CONTEXT_BACKDROP_BLUR_MAX_ITEMS,
  );
  /* 照片墙资料库右键只抬起当前照片做裁剪，其它照片保持清晰。 */
  if (!contextCropMode) $(".main").classList.add("is-context-background");
  tile.classList.add("is-context-origin");
  contextItemIndex = index;
  contextTile = tile;
  contextMenuOpen = true;
  document.documentElement.classList.add("context-preview-open");
  contextSourceStart = start;
  let finalMenuWidth = menuWidth;
  if (mode === "details") {
    /* 单击右键直接把信息卡作为浮层内容，沿用操作菜单的缩放入场；
       卡片在项目空间较宽的一侧跟随项目的实时边缘，并与项目保持间距。 */
    menu.classList.add("is-item-detail");
    menu.setAttribute("role", "dialog");
    menu.setAttribute("aria-label", "项目详细");
    menu.innerHTML = contextItemInfoHTML(item);
    bindContextMapPreview(menu);
    bindContextDetailAdjustButton(menu);
    finalMenuWidth = Math.min(
      CONTEXT_INFO_CARD_WIDTH,
      Math.max(250, availableWidth),
    );
    menu.style.width = `${finalMenuWidth}px`;
    menu.style.height = "";
    const infoHeight = Math.min(
      menu.getBoundingClientRect().height,
      Math.max(1, contentBottom - contentTop),
    );
    menu.style.height = `${infoHeight}px`;
    /* 信息卡保持固定尺寸；放大后的预览必须给它让出横向空间。 */
    const detailPreviewWidthLimit = Math.max(
      140,
      contentRight -
        contentLeft -
        contentMargin * 2 -
        finalMenuWidth -
        CONTEXT_DETAIL_GAP,
    );
    if (target.width > detailPreviewWidthLimit) {
      target.width = detailPreviewWidthLimit;
      target.height = target.width / previewAspect;
    }
    const infoPreferredSide =
      target.left + target.width / 2 < (contentLeft + contentRight) / 2
        ? "right"
        : "left";
    /* 放大后可能刚好占满“照片 + 间距 + 信息卡”的总宽度；此时把照片
       贴近对应侧边缘，而不是让信息卡退回照片中央。 */
    if (infoPreferredSide === "right") {
      const maxSourceLeft =
        contentRight -
        contentMargin -
        finalMenuWidth -
        CONTEXT_DETAIL_GAP -
        target.width;
      target.left = Math.max(
        contentLeft + contentMargin,
        Math.min(target.left, maxSourceLeft),
      );
    } else {
      const minSourceLeft =
        contentLeft + contentMargin + finalMenuWidth + CONTEXT_DETAIL_GAP;
      target.left = Math.min(
        contentRight - contentMargin - target.width,
        Math.max(target.left, minSourceLeft),
      );
    }
    const infoPlacementFor = (box) =>
      placeContextDetailCard(
        {
          left: sceneRect.left + box.left,
          top: sceneRect.top + box.top,
          right: sceneRect.left + box.left + box.width,
          bottom: sceneRect.top + box.top + box.height,
        },
        finalMenuWidth,
        infoHeight,
        contentRect,
        sceneRect,
        { preferredSide: infoPreferredSide, trackSourceTop: true },
      );
    let targetInfoPlacement = infoPlacementFor(target);
    /* 并排时项目和卡片共用顶边。若卡片较高、只能贴到内容区底边，
       项目跟着卡片的顶边一起上移，避免只剩底边对齐而出现明显错层。 */
    if (targetInfoPlacement.side && targetInfoPlacement.top < target.top) {
      target.top = targetInfoPlacement.top;
      targetInfoPlacement = infoPlacementFor(target);
    }
    const startInfoPlacement = infoPlacementFor(start);
    contextMenuTargetPlacement = {
      ...targetInfoPlacement,
      width: finalMenuWidth,
      height: infoHeight,
    };
    contextMenuStartPlacement = {
      ...startInfoPlacement,
      width: finalMenuWidth,
      height: infoHeight,
    };
    menu.dataset.contextSide = targetInfoPlacement.side;
  } else if (!contextCropMode && !contextPreviewOnly) {
    contextMenuStartPlacement = placeMenuBesideSource(start);
    contextMenuTargetPlacement = placeMenuBesideSource(target);
  }

  contextSourceTarget = { ...target };
  source.style.left = `${target.left}px`;
  source.style.top = `${target.top}px`;
  source.style.width = `${target.width}px`;
  source.style.height = `${target.height}px`;
  source.style.transform = "none";
  layoutContextSourceImage();

  contextSourceAnim = source.animate(
    [
      {
        left: `${start.left}px`,
        top: `${start.top}px`,
        width: `${start.width}px`,
        height: `${start.height}px`,
      },
      {
        left: `${target.left}px`,
        top: `${target.top}px`,
        width: `${target.width}px`,
        height: `${target.height}px`,
      },
    ],
    {
      duration: motionDuration,
      easing: CONTEXT_PREVIEW_EASING,
      fill: "forwards",
    },
  );
  contextSourceAnim.finished.then(
    () => {
      startContextVideo?.();
    },
    () => {},
  );
  const menuStartScale = contextMenuStartScale(start.width, finalMenuWidth);
  if (contextPreviewOnly) {
    menu.style.visibility = "hidden";
    menu.style.pointerEvents = "none";
    menu.style.opacity = "0";
  } else if (contextCropMode) {
    menu.style.display = "none";
  } else {
    const menuStartTransform = contextMenuStartPlacement
      ? contextMenuTransform(
          contextMenuStartPlacement,
          contextMenuTargetPlacement,
          menuStartScale,
        )
      : `scale(${menuStartScale})`;
    menu.style.left = `${contextMenuTargetPlacement.left}px`;
    menu.style.top = `${contextMenuTargetPlacement.top}px`;
    menu.style.width = `${finalMenuWidth}px`;
    menu.style.transformOrigin = "0 0";
    menu.style.transform = "none";
    menu.style.opacity = "0";
    contextMenuAnim = menu.animate(
      [
        {
          opacity: 0,
          transform: menuStartTransform,
          offset: 0,
        },
        {
          opacity: 1,
          transform: "translate3d(0, 0, 0) scale(1)",
          offset: 1,
        },
      ],
      {
        duration: motionDuration,
        easing: "cubic-bezier(0.25, 0.35, 0.25, 1)",
        fill: "forwards",
      },
    );
  }
  const finalizeMenu = () => {
    if (!contextMenuOpen) return;
    layoutContextSourceImage();
    contextMenuAnim?.cancel();
    contextMenuAnim = null;
    if (contextCropMode) {
      menu.style.display = "none";
      if (!contextCropSession) showContextCrop(item);
      return;
    }
    menu.style.width = `${finalMenuWidth}px`;
    menu.style.opacity = contextPreviewOnly ? "0" : "1";
    menu.style.transform = "none";
  };
  const finalizeToken = ++contextMotionToken;
  setTimeout(() => {
    if (contextMotionToken === finalizeToken) finalizeMenu();
  }, motionDuration + 50);
  if (
    !contextPreviewOnly &&
    !contextCropMode &&
    (keyboard || menu.classList.contains("is-item-detail"))
  ) {
    requestAnimationFrame(() => {
      if (!contextMenuOpen) return;
      if (menu.classList.contains("is-item-detail")) {
        menu.focus({ preventScroll: true });
      } else {
        syncContextMenuRovingFocus()?.focus({ preventScroll: true });
      }
    });
  }
}

function prepareContextSelection(index) {
  state.select = true;
  state.copyTarget = false;
  state.copyTargetParentId = null;
  state.selected = new Set([index]);
  state.selectedTrashAlbums.clear();
  state.cursor = index;
  state.cursorVisible = false;
}

async function setItemAsAlbumCover(item) {
  const albumId = typeof state.activeId === "number" ? state.activeId : null;
  const album = albumId ? albumById(albumId) : null;
  if (!album || !item) return;
  const beforeAlbums = state.albums;
  try {
    const res = await api(`/api/albums/${albumId}/cover`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ itemId: item.id }),
    });
    await preloadChangedCoverThumbs(beforeAlbums, res.state);
    applyState(res.state);
    render();
    try {
      lastRev = (await api("/api/revision")).rev;
    } catch {}
  } catch (err) {
    alert(err.message);
  }
}

function runContextAction(action) {
  const index = contextItemIndex;
  const item = state.items[index];
  if (!item) {
    closeItemContextMenu(true);
    return;
  }
  const moveMode = isUnfiledAlbum(albumById(state.activeId));
  if (action === "details") {
    expandContextDetail(item);
    return;
  }
  if (action === "show-library") {
    closeItemContextMenu(true);
    void showItemInLibrary(item.id);
    return;
  }
  /* 收藏、加入相簿等操作保留完整的收回动画。删除 / 从相簿移除会改变
     这一格的归属：被操作项目的浮层必须立刻收掉，否则它会继续停在原槽位，
     等网格已经补位后才消失，最后一帧看起来像画面跳了一下。 */
  const removesCurrentItem = action === "remove" || action === "delete";
  closeItemContextMenu(removesCurrentItem);
  if (action === "favorite") {
    favoriteItems([item]);
    return;
  }
  if (action === "add-album") {
    contextAddToAlbumPending = true;
    prepareContextSelection(index);
    openCopyTargetView(moveMode ? "move" : "add");
    return;
  }
  if (action === "cover") {
    setItemAsAlbumCover(item);
    return;
  }
  if (action === "copy") {
    prepareContextSelection(index);
    copySelectedItems();
    return;
  }
  if (action === "remove") {
    prepareContextSelection(index);
    removeSelectedFromAlbum();
    return;
  }
  if (action === "delete") {
    prepareContextSelection(index);
    trashSelected();
  }
}

async function ensureProgressiveTileRendered(index) {
  let tile = tileAt(index);
  if (tile) return tile;
  let passes = 0;
  while (!tile && progressivePhotoGridBatch && passes < 1000) {
    const next = nextProgressiveGridSpec();
    if (!next) break;
    appendProgressivePhotoGridChunk(next.spec);
    tile = tileAt(index);
    passes += 1;
    if (!tile && passes % 4 === 0) {
      await new Promise(requestAnimationFrame);
    }
  }
  return tile;
}

async function showItemInLibrary(itemId) {
  const targetId = Number(itemId);
  if (!Number.isInteger(targetId)) return;

  resetTransientAlbumFilters();
  state.zoomAnchorId = targetId;

  await select("library");
  if (state.activeId !== "library") return;
  /* 图库切换会在下一帧恢复上一次的滚动位置。必须等这次恢复结束后
     再定位目标，否则旧 scrollTop 会把刚设置的定位滚动覆盖掉。 */
  await new Promise(requestAnimationFrame);
  await new Promise(requestAnimationFrame);

  const index = state.items.findIndex((entry) => Number(entry.id) === targetId);
  if (index < 0) {
    toast("图库中找不到这个项目");
    return;
  }

  state.cursor = index;
  state.cursorVisible = false;
  const tile = await ensureProgressiveTileRendered(index);
  if (!tile?.isConnected) {
    toast("图库中找不到这个项目");
    return;
  }

  await new Promise(requestAnimationFrame);
  const content = $("#content");
  const tileRect = tile.getBoundingClientRect();
  const contentRect = content.getBoundingClientRect();
  const targetTop =
    content.scrollTop +
    tileRect.top -
    contentRect.top -
    (content.clientHeight - tileRect.height) / 2;
  content.scrollTo({
    top: Math.max(0, targetTop),
    behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
      ? "auto"
      : "smooth",
  });

  tile.classList.remove("is-library-located");
  void tile.offsetWidth;
  tile.classList.add("is-library-located");
  window.setTimeout(() => {
    tile.classList.remove("is-library-located");
  }, 1800);
  rememberTileFocus(index);
}

function clampContextDetailPosition() {
  const menu = $("#contextMenu");
  if (!contextMenuOpen || !menu.classList.contains("is-item-detail")) return;
  const sceneRect = $("#contextScene").getBoundingClientRect();
  const contentRect = $("#content").getBoundingClientRect();
  const inset = 8;
  const minLeft = contentRect.left - sceneRect.left + inset;
  const minTop = contentRect.top - sceneRect.top + inset;
  const maxLeft = Math.max(
    minLeft,
    contentRect.right - sceneRect.left - inset - menu.offsetWidth,
  );
  const maxTop = Math.max(
    minTop,
    contentRect.bottom - sceneRect.top - inset - menu.offsetHeight,
  );
  menu.style.left = `${Math.min(
    Math.max(minLeft, parseFloat(menu.style.left) || minLeft),
    maxLeft,
  )}px`;
  menu.style.top = `${Math.min(
    Math.max(minTop, parseFloat(menu.style.top) || minTop),
    maxTop,
  )}px`;
}

function endContextDetailDrag(event) {
  const drag = contextDetailDrag;
  if (!drag || (event.pointerId != null && event.pointerId !== drag.pointerId))
    return;
  contextDetailDrag = null;
  $("#contextMenu").classList.remove("is-dragging");
  try {
    drag.handle.releasePointerCapture(drag.pointerId);
  } catch {}
  clampContextDetailPosition();
}

$("#contextMenu").addEventListener("pointerdown", (event) => {
  if (
    !contextMenuOpen ||
    !$("#contextMenu").classList.contains("is-item-detail")
  )
    return;
  const handle = event.target.closest?.(
    ".context-detail-view .viewer-info-head",
  );
  if (
    !handle ||
    event.button !== 0 ||
    event.isPrimary === false ||
    event.target.closest("button, a, input, textarea, select")
  )
    return;
  const menu = $("#contextMenu");
  const sceneRect = $("#contextScene").getBoundingClientRect();
  const menuRect = menu.getBoundingClientRect();
  contextDetailAnim?.cancel();
  contextDetailAnim = null;
  clearContextDetailContentMotion();
  contextDetailDrag = {
    pointerId: event.pointerId,
    handle,
    startX: event.clientX,
    startY: event.clientY,
    left: menuRect.left - sceneRect.left,
    top: menuRect.top - sceneRect.top,
  };
  menu.style.left = `${contextDetailDrag.left}px`;
  menu.style.top = `${contextDetailDrag.top}px`;
  menu.classList.add("is-dragging");
  try {
    handle.setPointerCapture(event.pointerId);
  } catch {}
  event.preventDefault();
  event.stopPropagation();
});

$("#contextMenu").addEventListener("pointermove", (event) => {
  const drag = contextDetailDrag;
  if (!drag || event.pointerId !== drag.pointerId) return;
  const menu = $("#contextMenu");
  menu.style.left = `${drag.left + event.clientX - drag.startX}px`;
  menu.style.top = `${drag.top + event.clientY - drag.startY}px`;
  clampContextDetailPosition();
  event.preventDefault();
});

$("#contextMenu").addEventListener("pointerup", endContextDetailDrag);
$("#contextMenu").addEventListener("pointercancel", endContextDetailDrag);
$("#contextMenu").addEventListener(
  "lostpointercapture",
  endContextDetailDrag,
  true,
);

const contextCropLayerEl = $("#contextCropLayer");
const contextCropFrameEl = $("#contextCropFrame");

contextCropLayerEl?.addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  if (!contextCropSession || !contextCropImageRect) return;
  const sceneRect = $("#contextScene").getBoundingClientRect();
  const x = event.clientX - sceneRect.left;
  const y = event.clientY - sceneRect.top;
  const image = contextCropImageRect;
  const overPhoto =
    x >= image.left &&
    x <= image.left + image.width &&
    y >= image.top &&
    y <= image.top + image.height;
  if (!overPhoto) closeItemContextMenu();
});

contextCropFrameEl?.addEventListener("pointerdown", (event) => {
  if (
    !contextCropSession ||
    event.button !== 0 ||
    contextCropFrameEl.classList.contains("is-confirming") ||
    event.target.closest(".photo-wall-crop-action")
  )
    return;
  event.preventDefault();
  event.stopPropagation();
  const image = contextCropImageRect;
  if (!image) return;
  contextCropDrag = {
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    x: contextCropFrameState.x,
    y: contextCropFrameState.y,
    side:
      parseFloat(contextCropFrameEl.style.width) ||
      Math.min(image.width, image.height),
    image,
  };
  contextCropFrameEl.setPointerCapture?.(event.pointerId);
  contextCropFrameEl.classList.add("is-dragging");
});

contextCropFrameEl?.addEventListener("pointermove", (event) => {
  const drag = contextCropDrag;
  if (!drag || drag.pointerId !== event.pointerId) return;
  const dx = event.clientX - drag.startX;
  const dy = event.clientY - drag.startY;
  const half = drag.side / 2;
  const x = Math.min(
    (drag.image.width - half) / drag.image.width,
    Math.max(half / drag.image.width, drag.x + dx / drag.image.width),
  );
  const y = Math.min(
    (drag.image.height - half) / drag.image.height,
    Math.max(half / drag.image.height, drag.y + dy / drag.image.height),
  );
  contextCropFrameState = { ...contextCropFrameState, x, y };
  layoutContextCropFrame();
});

const endContextCropDrag = (event) => {
  if (!contextCropDrag || contextCropDrag.pointerId !== event.pointerId) return;
  try {
    contextCropFrameEl.releasePointerCapture?.(event.pointerId);
  } catch {}
  contextCropDrag = null;
  contextCropFrameEl.classList.remove("is-dragging");
};

contextCropFrameEl?.addEventListener("pointerup", endContextCropDrag);
contextCropFrameEl?.addEventListener("pointercancel", endContextCropDrag);
contextCropFrameEl?.addEventListener("lostpointercapture", endContextCropDrag);

contextCropLayerEl?.addEventListener(
  "wheel",
  (event) => {
    if (!contextCropSession || !contextCropImageRect) return;
    const image = contextCropImageRect;
    const sceneRect = $("#contextScene").getBoundingClientRect();
    const x = event.clientX - sceneRect.left;
    const y = event.clientY - sceneRect.top;
    if (
      x < image.left ||
      y < image.top ||
      x > image.left + image.width ||
      y > image.top + image.height
    )
      return;
    event.preventDefault();
    event.stopPropagation();
    const shortEdge = Math.min(image.width, image.height);
    const current = contextCropFrameState.size * shortEdge;
    const next = Math.min(
      shortEdge,
      Math.max(shortEdge * 0.5, current * Math.exp(-event.deltaY * 0.0015)),
    );
    contextCropFrameState = {
      ...contextCropFrameState,
      size: next / shortEdge,
    };
    layoutContextCropFrame();
  },
  { passive: false },
);

$("#contextCropReset")?.addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  contextCropFrameState = { x: 0.5, y: 0.5, size: 1 };
  layoutContextCropFrame();
});
$("#contextCropCurrent")?.addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  contextCropFrameState = { ...contextCropOriginalState };
  layoutContextCropFrame();
});
$("#contextCropConfirm")?.addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  contextCropConfirmAnim = animateCropConfirmation(contextCropFrameEl);
  void saveContextCrop(contextCropConfirmAnim);
});
$("#contextCropCancel")?.addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  closeItemContextMenu(event.detail === 0, {
    restoreFocus: event.detail === 0,
  });
});

$("#contextMenu").addEventListener("click", (e) => {
  const locationEdit = e.target.closest(
    "[data-context-location-add], [data-context-location-adjust]",
  );
  if (locationEdit) {
    e.preventDefault();
    e.stopPropagation();
    const item = state.items[contextItemIndex];
    closeItemContextMenu(true);
    requestAnimationFrame(() => {
      if (item) void askMetadataLocation([item]);
    });
    return;
  }
  const locationPreview = e.target.closest("[data-context-location-preview]");
  if (locationPreview) {
    e.preventDefault();
    e.stopPropagation();
    const item = state.items[contextItemIndex];
    closeItemContextMenu(true);
    requestAnimationFrame(() => {
      if (item) void askMetadataLocation([item], { readOnly: true });
    });
    return;
  }
  const path = e.target.closest(".viewer-info-path");
  if (path) {
    e.preventDefault();
    e.stopPropagation();
    revealItemInDisk(path.dataset.itemId);
    return;
  }
  const adjust = e.target.closest("[data-context-detail-adjust]");
  if (adjust) {
    e.preventDefault();
    e.stopPropagation();
    openContextDate({ anchorRect: adjust.getBoundingClientRect() });
    return;
  }
  const row = e.target.closest("[data-context-action]");
  if (!row) return;
  e.preventDefault();
  e.stopPropagation();
  runContextAction(row.dataset.contextAction);
});

function syncContextMenuRovingFocus(preferred = null) {
  const menu = $("#contextMenu");
  const rows = [
    ...menu.querySelectorAll('.context-row[role="menuitem"]:not(:disabled)'),
  ];
  const target = rows.includes(preferred) ? preferred : rows[0] || null;
  for (const row of rows) {
    row.tabIndex = row === target ? 0 : -1;
  }
  return target;
}

$("#contextMenu").addEventListener("keydown", (event) => {
  if (!event.currentTarget.classList.contains("is-item-detail")) {
    if (event.key === "Tab") {
      event.preventDefault();
      event.stopPropagation();
      closeItemContextMenu(true, { restoreFocus: true });
      return;
    }
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    const rows = [
      ...event.currentTarget.querySelectorAll(
        '.context-row[role="menuitem"]:not(:disabled)',
      ),
    ];
    if (!rows.length) return;
    const current = rows.indexOf(document.activeElement);
    const next =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? rows.length - 1
          : event.key === "ArrowDown"
            ? (Math.max(0, current) + 1) % rows.length
            : (Math.max(0, current) - 1 + rows.length) % rows.length;
    event.preventDefault();
    event.stopPropagation();
    syncContextMenuRovingFocus(rows[next]);
    rows[next].focus({ preventScroll: true });
    return;
  }
  const preview = event.target.closest?.("[data-context-location-preview]");
  if (!preview || event.target.closest("button")) return;
  if (event.key !== "Enter" && event.key !== " ") return;
  event.preventDefault();
  preview.click();
});

$("#contextSource").addEventListener("click", (e) => {
  if (!contextMenuOpen) return;
  e.preventDefault();
  e.stopPropagation();
  const rect = contextTile?.getBoundingClientRect();
  const overTile =
    !!rect &&
    e.clientX >= rect.left &&
    e.clientX <= rect.right &&
    e.clientY >= rect.top &&
    e.clientY <= rect.bottom;
  closeItemContextMenu(false, { keepShadow: overTile });
});

$("#contextScene").addEventListener("click", (e) => {
  if (contextDateOpen) {
    if (e.target.closest("#contextDatePopover")) return;
    closeContextDate();
    return;
  }
  if (e.target.closest("#contextMenu, #contextSource")) return;
  closeItemContextMenu(false, { keepShadow: false });
});
$("#contextScene").addEventListener("contextmenu", (e) => {
  e.preventDefault();
  e.stopPropagation();
});
document.addEventListener(
  "contextmenu",
  (e) => {
    if (!contextMenuOpen) return;
    e.preventDefault();
    e.stopPropagation();
  },
  true,
);

function canOpenItemContext(tile) {
  return (
    !!tile &&
    !state.select &&
    !state.copyTarget &&
    state.activeId !== "trash" &&
    state.activeId !== "photoWall" &&
    !state.photoWall &&
    $("#viewer").hidden
  );
}

$("#content").addEventListener("contextmenu", async (e) => {
  if (
    state.activeId === "photoWall" &&
    !state.photoWall &&
    state.mosaicWallAlbumId
  ) {
    const mosaicTile = e.target.closest(
      ".mosaic-wall-library-tile[data-index]",
    );
    if (mosaicTile) {
      e.preventDefault();
      e.stopPropagation();
      openWallCropPopup(
        "mosaic",
        Number(mosaicTile.dataset.index),
        e.clientX,
        e.clientY,
      );
      return;
    }
  }
  if (
    state.activeId === "photoWall" &&
    !state.photoWall &&
    state.masonryWallAlbumId
  ) {
    const masonryTile = e.target.closest(
      ".masonry-wall-library-tile[data-index]",
    );
    if (masonryTile) {
      e.preventDefault();
      e.stopPropagation();
      openMasonryCropPopup(
        Number(masonryTile.dataset.index),
        masonryTile,
        e.clientX,
        e.clientY,
      );
      return;
    }
  }
  if (
    state.activeId === "photoWall" &&
    !state.photoWall &&
    state.filmrollWallAlbumId
  ) {
    const filmrollTile = e.target.closest(
      ".filmroll-wall-library-tile[data-index]",
    );
    if (filmrollTile) {
      e.preventDefault();
      e.stopPropagation();
      openFilmrollCropPopup(
        Number(filmrollTile.dataset.index),
        filmrollTile,
        e.clientX,
        e.clientY,
      );
      return;
    }
  }
  if (
    photoWallAlbumSelectionActive() &&
    e.target.closest(".photo-wall-library-card[data-photo-wall-album]")
  ) {
    e.preventDefault();
    return;
  }
  const tile = e.target.closest(".photo-grid .tile[data-index]");
  if (!tile) return;
  const menuModifier = e.ctrlKey || e.metaKey;
  const keyboardOpen = e.button === 0;
  if (state.activeId === "photoWall" && !state.photoWall) {
    e.preventDefault();
    if (
      contextMenuOpen ||
      state.select ||
      state.copyTarget ||
      !$("#viewer").hidden
    )
      return;
    contextPointerX = e.clientX;
    contextPointerY = e.clientY;
    if (menuModifier) {
      /* 照片墙资料库只提供右键裁剪，不开放项目操作菜单。 */
      return;
    }
    /* 右键只在当前照片网格上抬起照片并出现正方形裁剪框；不进入查看器，
       也不显示详细参数卡。需要放大裁剪时仍由左键打开查看器。 */
    openItemContextMenu(Number(tile.dataset.index), tile, { mode: "crop" });
    return;
  }
  /* 普通右键打开信息卡；Ctrl + 右键打开项目操作菜单。 */
  e.preventDefault();
  if (contextMenuOpen || !canOpenItemContext(tile)) {
    return;
  }
  const tileRect = tile.getBoundingClientRect();
  contextPointerX = keyboardOpen
    ? tileRect.left + tileRect.width / 2
    : e.clientX;
  contextPointerY = keyboardOpen
    ? tileRect.top + tileRect.height / 2
    : e.clientY;
  const index = Number(tile.dataset.index);
  const mode = menuModifier ? "actions" : "details";
  if (mode === "details" && !keyboardOpen) {
    await waitForContextMapPreviewBeforeOpen(state.items[index]);
  }
  if (
    !tile.isConnected ||
    contextMenuOpen ||
    state.copyTarget ||
    !canOpenItemContext(tile)
  )
    return;
  openItemContextMenu(index, tile, { mode, keyboard: keyboardOpen });
});
document.addEventListener("pointerdown", (e) => {
  if (wallCropPopup && !wallCropPopup.contains(e.target)) {
    closeWallCropPopup();
  }
});
document.addEventListener("click", (e) => {
  if (!wallCropPopup?.contains(e.target)) return;
  const choice = e.target.closest("[data-wall-ratio-choice]");
  if (!choice || choice.disabled) return;
  e.preventDefault();
  e.stopPropagation();
  void applyWallCropChoice(choice.dataset.wallRatioChoice);
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && wallCropPopup) {
    e.preventDefault();
    closeWallCropPopup();
  }
});
$("#content").addEventListener(
  "scroll",
  () => {
    scheduleProgressivePhotoGridFill();
    scheduleVirtualPhotoGridWindow();
    closeWallCropPopup();
    if (contextMenuOpen) closeItemContextMenu(true);
    scheduleVisibleContextMapPreviews();
  },
  { passive: true },
);
window.addEventListener("resize", () => {
  if (contextMenuOpen) closeItemContextMenu(true);
});

/* 浏览器放不了的视频，丢给系统默认播放器 */
window.openInSystem = async (id) => {
  try {
    await api(`/api/open/${id}`, { method: "POST" });
  } catch (err) {
    alert(err.message);
  }
};

/* 文件路径本身是透明按钮：悬停时才显现，点击后让资源管理器定位到该项目。 */
async function revealItemInDisk(id) {
  const itemId = Number(id);
  if (!Number.isInteger(itemId) || itemId <= 0) return;
  try {
    await api(`/api/reveal/${itemId}`, { method: "POST" });
  } catch (err) {
    alert(err.message);
  }
}

$("#viewerInfoPath").addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  revealItemInDisk(event.currentTarget.dataset.itemId);
});

/* 鼠标停到视频卡片上时先把 1600 封面取回来：点开时封面层会铺满整块画面，
   提前拿到大图，飞行的最后一段就不会发虚。 */
document.addEventListener("pointerover", (e) => {
  if (!(e.target instanceof Element)) return;
  const photoTile = e.target.closest(".photo-grid .tile:not(.is-video)");
  if (photoTile) {
    const photo = state.items[Number(photoTile.dataset.index)];
    if (contextMapLocation(photo)) void enqueueContextMapPreview(photo);
  }
  const tile = e.target.closest(".photo-grid .tile.is-video");
  if (!tile) return;
  const item = state.items[Number(tile.dataset.index)];
  if (!item || item.kind !== "video") return;
  const key = `${thumbVersion()}:${item.id}`;
  if (videoPosterPrefetch.has(key)) return;
  videoPosterPrefetch.add(key);
  const img = new Image();
  img.decoding = "async";
  img.src = openingPosterUrl(item);
});

/* ------------------------------ 快捷键 ------------------------------ */

let shortcutsOpen = false;
let shortcutsReturnFocus = null;
let shortcutsDockedToSettings = false;

function syncSettingsShortcutsRow() {
  const row = $('#popMenu [data-setting-id="shortcuts"]');
  if (row) {
    row.setAttribute("aria-expanded", String(shortcutsOpen));
    row
      .querySelector(".menu-submenu-chevron")
      ?.classList.toggle("is-open", shortcutsOpen);
  }
  $('#popMenu [data-settings-category="shortcuts"]')?.setAttribute(
    "aria-expanded",
    String(shortcutsOpen),
  );
}

function positionSettingsShortcuts() {
  if (!shortcutsOpen || !shortcutsDockedToSettings || $("#shortcuts").hidden) {
    return;
  }
  const menu = $("#popMenu");
  const layer = $("#shortcuts");
  if (menu.hidden) return;
  const menuRect = menu.getBoundingClientRect();
  const margin = 10;
  const gap = 10;
  const availableRight = window.innerWidth - menuRect.right - gap - margin;
  const availableLeft = menuRect.left - gap - margin;
  const preferredSide = availableRight >= availableLeft ? "right" : "left";
  const sideSpace = Math.max(availableRight, availableLeft);
  const width = Math.min(680, Math.max(320, sideSpace));
  const left =
    preferredSide === "right"
      ? menuRect.right + gap
      : menuRect.left - gap - width;
  const top = Math.max(
    margin,
    Math.min(menuRect.top, window.innerHeight - 260 - margin),
  );
  const maxHeight = Math.max(260, window.innerHeight - top - margin);
  layer.style.left = `${Math.max(
    margin,
    Math.min(window.innerWidth - width - margin, left),
  )}px`;
  layer.style.top = `${top}px`;
  layer.style.setProperty("--shortcuts-docked-width", `${width}px`);
  layer.style.setProperty("--shortcuts-docked-max-height", `${maxHeight}px`);
}

function openShortcuts({ returnFocus = null, dockedToSettings = false } = {}) {
  if (shortcutsOpen) return;
  shortcutsOpen = true;
  shortcutsDockedToSettings = dockedToSettings;
  shortcutsReturnFocus =
    returnFocus instanceof HTMLElement && document.contains(returnFocus)
      ? returnFocus
      : document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
  const layer = $("#shortcuts");
  const card = layer.querySelector(".shortcuts-card");
  layer.classList.toggle("is-settings-panel", shortcutsDockedToSettings);
  layer.setAttribute("aria-hidden", "false");
  card.setAttribute("aria-modal", String(!shortcutsDockedToSettings));
  layer.hidden = false;
  if (shortcutsDockedToSettings) {
    layer.style.left = "";
    layer.style.top = "";
    positionSettingsShortcuts();
    syncSettingsShortcutsRow();
  } else {
    layer.style.left = "";
    layer.style.top = "";
    card.focus({ preventScroll: true });
  }
}

function closeShortcuts({ restoreFocus = true } = {}) {
  if (!shortcutsOpen) return;
  shortcutsOpen = false;
  shortcutsDockedToSettings = false;
  const layer = $("#shortcuts");
  layer.hidden = true;
  layer.classList.remove("is-settings-panel");
  layer.setAttribute("aria-hidden", "true");
  layer.querySelector(".shortcuts-card")?.setAttribute("aria-modal", "true");
  layer.style.left = "";
  layer.style.top = "";
  layer.style.removeProperty("--shortcuts-docked-width");
  layer.style.removeProperty("--shortcuts-docked-max-height");
  syncSettingsShortcutsRow();
  const back = shortcutsReturnFocus;
  shortcutsReturnFocus = null;
  if (restoreFocus && back && document.contains(back)) {
    back.focus({ preventScroll: true });
  }
}

let toggleWindowPending = false;

async function toggleAppWindow() {
  if (toggleWindowPending) return;
  toggleWindowPending = true;
  document.dispatchEvent(new CustomEvent("album:fullscreen-will-change"));
  let fullscreen = false;
  try {
    const res = await fetch("/api/window/toggle", { method: "POST" });
    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      throw new Error(data.error || `HTTP ${res.status}`);
    }
    const data = await res.json().catch(() => ({}));
    fullscreen = data.state === "fullscreen";
    document.documentElement.classList.toggle("is-fullscreen", fullscreen);
  } catch (err) {
    console.warn("切换窗口模式失败", err);
  } finally {
    document.dispatchEvent(
      new CustomEvent("album:fullscreen-changed", {
        detail: { fullscreen },
      }),
    );
    toggleWindowPending = false;
  }
}

$("#shortcuts").addEventListener("click", (e) => {
  if (e.target.closest("[data-shortcuts-close]")) closeShortcuts();
});

function isTypingTarget(target) {
  if (!(target instanceof HTMLElement)) return false;
  return (
    target.isContentEditable ||
    target.tagName === "INPUT" ||
    target.tagName === "TEXTAREA" ||
    target.tagName === "SELECT"
  );
}

function isActivationControl(target) {
  return (
    target instanceof Element &&
    !!target.closest(
      'button, a[href], input, textarea, select, [contenteditable="true"]',
    )
  );
}

/* Esc 是“退出”动作，不把上一次鼠标点击留下的焦点带进新界面。
   等当前 keydown 的所有处理完成后检查它确实被应用消费，再移走焦点；
   这样弹窗恢复焦点、选择模式重绘等同步动作也不会重新留下系统描边。 */
document.addEventListener(
  "keydown",
  (event) => {
    if (event.key !== "Escape" || event.repeat) return;
    setTimeout(() => {
      if (!event.defaultPrevented) return;
      const active = document.activeElement;
      if (
        active instanceof HTMLElement &&
        active !== document.body &&
        active !== document.documentElement
      ) {
        active.blur();
      }
    }, 0);
  },
  true,
);

let viewerFullscreenPending = false;

async function toggleViewerFullscreen() {
  if (viewerFullscreenPending) return false;
  viewerFullscreenPending = true;
  /* 先回到完整画面的等比尺寸；进入全屏后用户仍可继续手动缩放。 */
  resetViewerZoom();
  const wasFullscreen =
    document.documentElement.classList.contains("is-fullscreen");
  document.dispatchEvent(new CustomEvent("album:fullscreen-will-change"));
  let fullscreen = wasFullscreen;
  try {
    if (window.albumWindow?.toggleFullscreen) {
      const result = await window.albumWindow.toggleFullscreen();
      fullscreen = Boolean(result && result.fullscreen);
    } else {
      await toggleAppWindow();
      fullscreen = document.documentElement.classList.contains("is-fullscreen");
    }
    document.documentElement.classList.toggle("is-fullscreen", fullscreen);
  } finally {
    document.dispatchEvent(
      new CustomEvent("album:fullscreen-changed", {
        detail: { fullscreen },
      }),
    );
    viewerFullscreenPending = false;
  }
  return fullscreen;
}

function handleViewerKey(e, target) {
  const key = e.key;
  const video = $("#viewerStage video");

  /* Esc 是查看器的退出键，即使焦点停在视频进度条或控制按钮上，
     也不能被浏览器解释成焦点操作。 */
  if (key === "Escape") {
    e.preventDefault();
    if (viewerDateOpen) {
      closeViewerDate();
    } else if (viewerInfoOpen) {
      closeViewerInfo({ immediate: true, restoreFocus: true });
    } else if ($("#viewer").classList.contains("show-info")) {
      setViewerInfo(false);
    } else {
      closeViewerWithBackgroundAnimation();
    }
    return;
  }

  /* 时间卡片自己会处理滚轮和回车；其余按键不能穿透去翻照片。 */
  if (viewerDateOpen) {
    return;
  }

  if (viewerInfoOpen) {
    return;
  }

  if (photoWallCropSession) {
    if (
      (key === "ArrowLeft" || key === "ArrowRight") &&
      !photoWallCropConfirmed
    ) {
      e.preventDefault();
      return;
    }
    if (["ArrowUp", "ArrowDown", "z", "Z", "+", "=", "-"].includes(key)) {
      e.preventDefault();
      return;
    }
  }

  if (
    (key === "q" || key === "Q") &&
    !e.repeat &&
    !e.ctrlKey &&
    !e.metaKey &&
    !e.altKey
  ) {
    e.preventDefault();
    void toggleViewerFullscreen();
    return;
  }
  if (target instanceof Element && target.closest("#videoControls")) return;
  if (
    state.ratingMode &&
    !photoWallCropSession &&
    !e.repeat &&
    !e.ctrlKey &&
    !e.metaKey &&
    !e.altKey &&
    /^[0-5]$/.test(key) &&
    state.items[viewerIndex]?.kind === "photo"
  ) {
    e.preventDefault();
    void saveViewerRating(Number(key));
    return;
  }
  if (key === "?") {
    e.preventDefault();
    openShortcuts();
    return;
  }
  if (
    key === "ArrowUp" ||
    key === "ArrowDown" ||
    key === "w" ||
    key === "W" ||
    key === "s" ||
    key === "S"
  ) {
    e.preventDefault();
    if (!e.repeat) {
      rotateViewer(key === "ArrowUp" || key === "w" || key === "W" ? 90 : -90);
    }
    return;
  }
  if (key === "ArrowLeft") {
    e.preventDefault();
    stepViewer(-1);
    return;
  }
  if (key === "ArrowRight") {
    e.preventDefault();
    stepViewer(1);
    return;
  }
  if (key === "a" || key === "A") {
    e.preventDefault();
    stepViewer(-1);
    return;
  }
  if (key === "d" || key === "D") {
    e.preventDefault();
    stepViewer(1);
    return;
  }
  if (key === "Home") {
    e.preventDefault();
    showViewerAt(0);
    return;
  }
  if (key === "End") {
    e.preventDefault();
    showViewerAt(state.items.length - 1);
    return;
  }
  if (
    (key === "z" || key === "Z") &&
    !e.repeat &&
    !e.ctrlKey &&
    !e.metaKey &&
    !e.altKey
  ) {
    e.preventDefault();
    toggleViewerFavorite();
    return;
  }
  if (key === "+" || key === "=") {
    e.preventDefault();
    setViewerZoom(viewerZoom * 1.5);
    return;
  }
  if (key === "-" || key === "_") {
    e.preventDefault();
    setViewerZoom(viewerZoom / 1.5);
    return;
  }
  if (key === "0") {
    e.preventDefault();
    resetViewerZoom();
    return;
  }
  if (key === " " && video && !(target instanceof HTMLVideoElement)) {
    e.preventDefault();
    if (video.paused) video.play().catch(() => {});
    else video.pause();
  }
}

function tileUnderPointer() {
  if (!Number.isFinite(lastPointerX) || !Number.isFinite(lastPointerY))
    return null;
  const node = document.elementFromPoint(lastPointerX, lastPointerY);
  return node instanceof Element
    ? node.closest("#content .photo-grid .tile[data-index]")
    : null;
}

document.addEventListener("keydown", (e) => {
  const target = e.target;
  const key = e.key;
  const primary = e.ctrlKey || e.metaKey;

  /* 安装版由 window-controls.js 处理窗口快捷键；浏览器预览只保留全屏切换。 */
  if (primary && !e.altKey && !e.shiftKey && key === "0") {
    if (window.albumWindow) return;
    e.preventDefault();
    if (!e.repeat) toggleAppWindow();
    return;
  }
  if (nameDialogOpen) {
    if (key === "Escape") {
      e.preventDefault();
      closeNameDialog(null);
    }
    return;
  }
  if (metadataLocationOpen) {
    if (key === "Escape") {
      e.preventDefault();
      closeMetadataLocation(null);
    }
    return;
  }
  if (libraryPickerOpen) {
    if (key === "Escape") {
      e.preventDefault();
      closeLibraryPicker();
    } else if (key === "Tab") {
      const focusable = [
        ...$("#libraryPickerCard").querySelectorAll(
          'button:not(:disabled), [tabindex="0"]',
        ),
      ];
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      const current = document.activeElement;
      if (
        e.shiftKey &&
        (current === first || !$("#libraryPickerCard").contains(current))
      ) {
        e.preventDefault();
        last?.focus();
      } else if (
        !e.shiftKey &&
        (current === last || !$("#libraryPickerCard").contains(current))
      ) {
        e.preventDefault();
        first?.focus();
      }
    }
    return;
  }
  if (isTypingTarget(target)) return;

  if (
    !menuOpen &&
    key === "ArrowDown" &&
    !e.repeat &&
    !e.altKey &&
    !e.ctrlKey &&
    !e.metaKey &&
    target instanceof Element
  ) {
    const trigger = target.closest(
      "#moreTopBtn, #albumMenuBtn, #sidebarOptionsBtn, #librarySwitchBtn, #createBtn",
    );
    if (trigger) {
      const kind =
        trigger.id === "moreTopBtn"
          ? "photos"
          : trigger.id === "albumMenuBtn"
            ? albumMenuKindForCurrentView()
            : trigger.id === "sidebarOptionsBtn"
              ? "settings"
              : trigger.id === "librarySwitchBtn"
                ? "rootSwitch"
                : "create";
      e.preventDefault();
      openMenu(trigger, kind, { focusFirst: true });
      return;
    }
  }

  if (contextDateOpen) {
    if (key === "Escape") {
      e.preventDefault();
      closeContextDate();
    }
    return;
  }

  if (contextMenuOpen) {
    if (key === "Escape") {
      e.preventDefault();
      closeItemContextMenu(false, { restoreFocus: true });
    } else if (
      (key === "ArrowDown" || key === "ArrowUp") &&
      !$("#contextMenu").classList.contains("is-item-detail") &&
      target instanceof Element &&
      !$("#contextMenu").contains(target)
    ) {
      const rows = [
        ...$("#contextMenu").querySelectorAll(
          '.context-row[role="menuitem"]:not(:disabled)',
        ),
      ];
      const row = rows[key === "ArrowDown" ? 0 : rows.length - 1];
      if (row) {
        e.preventDefault();
        syncContextMenuRovingFocus(row);
        row.focus({ preventScroll: true });
      }
    } else if (
      key === " " &&
      !e.repeat &&
      $("#contextMenu").dataset.contextMode === "preview"
    ) {
      e.preventDefault();
      closeItemContextMenu(true, { restoreFocus: true });
    }
    return;
  }

  if (key === "Escape" && albumGesture) {
    e.preventDefault();
    cancelAlbumPress(albumGesture);
    return;
  }

  /* 有面板开着时，键盘先交给最上面那一层；不会顺手操作底下的照片 */
  if (askOpen) {
    if (key === "Escape") {
      e.preventDefault();
      askClose(false);
    } else if (key === "Tab") {
      const focusable = [
        ...$("#askCard").querySelectorAll("button:not(:disabled)"),
      ];
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      const current = document.activeElement;
      if (
        e.shiftKey &&
        (current === first || !$("#askCard").contains(current))
      ) {
        e.preventDefault();
        last.focus();
      } else if (
        !e.shiftKey &&
        (current === last || !$("#askCard").contains(current))
      ) {
        e.preventDefault();
        first.focus();
      }
    }
    return;
  }
  if (shortcutsOpen) {
    if (key === "Escape" || key === "?") {
      e.preventDefault();
      closeShortcuts();
    }
    return;
  }
  if (pickerOpen) {
    if (key === "Escape") {
      e.preventDefault();
      closePicker();
    }
    return;
  }
  if (e.altKey && !primary && !e.shiftKey && key.toLowerCase() === "d") {
    e.preventDefault();
    if (!e.repeat) {
      if (menuOpen) closeMenu({ duration: 120 });
      void pickFolder();
    }
    return;
  }
  if (
    !e.shiftKey &&
    ((primary && !e.altKey && key === "9") ||
      (e.altKey && !primary && key.toLowerCase() === "q"))
  ) {
    e.preventDefault();
    if (!e.repeat) {
      if (photoEditorOpen) toast("请先完成或取消照片编辑");
      else void switchToNextRoot();
    }
    return;
  }
  if (menuOpen) {
    if (key === "Escape") {
      e.preventDefault();
      closeMenu({ restoreFocus: true });
    } else if (
      (key === "ArrowDown" || key === "ArrowUp") &&
      target instanceof Element &&
      !$("#popMenu").contains(target)
    ) {
      const items = popMenuKeyboardTargets();
      if (items.length) {
        e.preventDefault();
        items[key === "ArrowDown" ? 0 : items.length - 1]?.focus({
          preventScroll: true,
        });
      }
    }
    return;
  }
  if (anyWallSelectionActive() && key === "Escape") {
    e.preventDefault();
    if (state.filmrollWallSelectMode) cancelFilmrollWallAlbumSelection();
    else if (state.masonryWallSelectMode) cancelMasonryWallAlbumSelection();
    else cancelPhotoWallAlbumSelection();
    return;
  }
  if (state.copyTarget && key === "Escape") {
    e.preventDefault();
    closeCopyTargetView();
    return;
  }

  if (primary && !e.altKey && !e.shiftKey && key.toLowerCase() === "c") {
    if (state.select && !state.copyTarget && state.selected.size > 0) {
      e.preventDefault();
      if (!e.repeat) copySelectedItems();
      return;
    }
  }

  /* 撤销优先于查看器 / 网格：撤完再回到刷新后的列表 */
  if (primary && !e.altKey && !e.shiftKey && key.toLowerCase() === "z") {
    e.preventDefault();
    undoLast();
    return;
  }

  /* 焦点在按钮 / 链接上时，空格和回车是它们在用，别抢去打开照片 */
  if ((key === " " || key === "Enter") && isActivationControl(target)) return;

  if (!$("#viewer").hidden) {
    if ($("#viewer").classList.contains("is-closing")) return;
    handleViewerKey(e, target);
    return;
  }

  if (key === "?") {
    e.preventDefault();
    openShortcuts();
    return;
  }

  if (state.filmstrip && !state.select) {
    if (key === "Escape") {
      e.preventDefault();
      setFilmstripMode(false);
      return;
    }
    if (key === "Home" || key === "End") {
      e.preventDefault();
      if (key === "Home") setFilmstripIndex(0);
      else setFilmstripIndex(state.items.length - 1);
      return;
    }
    if (
      key === "ArrowUp" ||
      key === "ArrowDown" ||
      key === "w" ||
      key === "W" ||
      key === "s" ||
      key === "S"
    ) {
      e.preventDefault();
      if (!e.repeat) {
        rotateFilmstripMedia(
          key === "ArrowUp" || key === "w" || key === "W" ? 90 : -90,
        );
      }
      return;
    }
    if (key === "ArrowLeft" || key === "ArrowRight") {
      e.preventDefault();
      stepFilmstrip(key === "ArrowLeft" ? -1 : 1);
      return;
    }
  }

  const targetMosaicAlbum =
    target instanceof Element
      ? target.closest(".photo-wall-library-card[data-mosaic-wall-album]")
      : null;
  if (targetMosaicAlbum && (key === " " || key === "Enter")) {
    e.preventDefault();
    if (mosaicWallAlbumSelectionActive()) {
      toggleMosaicWallAlbumSelected(
        Number(targetMosaicAlbum.dataset.mosaicWallAlbum),
      );
    } else {
      void openMosaicWallAlbum(
        Number(targetMosaicAlbum.dataset.mosaicWallAlbum),
      );
    }
    return;
  }
  const targetLibraryAlbum =
    target instanceof Element
      ? target.closest(".photo-wall-library-card[data-photo-wall-album]")
      : null;
  if (targetLibraryAlbum && (key === " " || key === "Enter")) {
    e.preventDefault();
    if (photoWallAlbumSelectionActive()) {
      togglePhotoWallAlbumSelected(
        Number(targetLibraryAlbum.dataset.photoWallAlbum),
      );
    } else {
      void openPhotoWallAlbum(
        Number(targetLibraryAlbum.dataset.photoWallAlbum),
      );
    }
    return;
  }
  const targetMasonryAlbum =
    target instanceof Element
      ? target.closest(".photo-wall-library-card[data-masonry-wall-album]")
      : null;
  if (targetMasonryAlbum && (key === " " || key === "Enter")) {
    e.preventDefault();
    if (masonryWallAlbumSelectionActive()) {
      toggleMasonryWallAlbumSelected(
        Number(targetMasonryAlbum.dataset.masonryWallAlbum),
      );
    } else {
      void openMasonryWallAlbum(
        Number(targetMasonryAlbum.dataset.masonryWallAlbum),
      );
    }
    return;
  }
  const targetFilmrollAlbum =
    target instanceof Element
      ? target.closest(".photo-wall-library-card[data-filmroll-wall-album]")
      : null;
  if (targetFilmrollAlbum && (key === " " || key === "Enter")) {
    e.preventDefault();
    if (filmrollWallAlbumSelectionActive()) {
      toggleFilmrollWallAlbumSelected(
        Number(targetFilmrollAlbum.dataset.filmrollWallAlbum),
      );
    } else {
      void openFilmrollWallAlbum(
        Number(targetFilmrollAlbum.dataset.filmrollWallAlbum),
      );
    }
    return;
  }

  /* Esc 从最里面一层往外退：多选 → 编辑 → 相簿层级内返回。
     任何会落到「所有相簿」的返回都不执行；返回按钮仍照常工作。 */
  if (key === "Escape") {
    if (state.select) {
      e.preventDefault();
      exitSelection({ focusGrid: true });
    } else if (state.edit) {
      e.preventDefault();
      setEditMode(false);
    } else if (
      !state.photoWall &&
      (state.activeId === "library" ||
        (state.activeId === "photoWall" &&
          !state.photoWallAlbumId &&
          !state.masonryWallAlbumId &&
          !state.filmrollWallAlbumId &&
          !state.mosaicWallAlbumId))
    ) {
      e.preventDefault();
    } else if (state.activeId !== "all") {
      e.preventDefault();
      if (!escapeWouldReturnToAllAlbums()) goBack();
    }
    return;
  }

  if (e.altKey && key === "ArrowLeft") {
    e.preventDefault();
    if (state.mosaicWallSelectMode) cancelMosaicWallAlbumSelection();
    else if (state.filmrollWallSelectMode) cancelFilmrollWallAlbumSelection();
    else if (state.photoWallSelectMode) cancelPhotoWallAlbumSelection();
    else if (state.masonryWallSelectMode) cancelMasonryWallAlbumSelection();
    else goBack();
    return;
  }

  if (primary && !e.altKey) {
    if (key.toLowerCase() !== "a") return;
    if (!hasGridItems()) return;
    e.preventDefault();

    if (e.shiftKey) {
      if (!state.select) return;
      clearSelection();
      state.cursorVisible = true;
      render();
      if (state.cursor >= 0) focusTile(state.cursor);
      return;
    }

    enterSelection({ selectAll: true, showFocus: true });
    return;
  }

  if (primary || e.altKey) return;

  /* 从 Tab 进来的第一张也能直接按空格 / 回车，不必先按方向键 */
  const targetTile =
    target instanceof Element
      ? target.closest(".photo-grid .tile[data-index]")
      : null;
  const pointerTile = key === " " && !state.select ? tileUnderPointer() : null;
  const targetTrashAlbum =
    target instanceof Element
      ? target.closest(".trash-album-card[data-trash-album]")
      : null;
  if (targetTrashAlbum && state.select && (key === " " || key === "Enter")) {
    e.preventDefault();
    toggleTrashAlbumSelected(
      Number(targetTrashAlbum.dataset.trashAlbum),
      targetTrashAlbum,
    );
    return;
  }
  if (targetTile) {
    const index = Number(targetTile.dataset.index);
    if (Number.isInteger(index) && index !== state.cursor)
      rememberTileFocus(index);
  }

  if (
    ["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(
      key,
    )
  ) {
    if (!state.items.length) return;
    e.preventDefault();
    moveGridFocus(key);
    return;
  }

  /* 刚打开相簿、还没有用键盘定位到任何照片时，空格不打开第一张，
     也不让浏览器拿它去滚动内容。Tab 到具体格子或方向键建立焦点后仍照常打开。 */
  if (
    key === " " &&
    !state.select &&
    !state.cursorVisible &&
    !targetTile &&
    !pointerTile
  ) {
    e.preventDefault();
    return;
  }

  if (key === " " || key === "Enter") {
    if (!state.items.length) return;
    e.preventDefault();
    const pointerIndex = pointerTile ? Number(pointerTile.dataset.index) : NaN;
    if (Number.isInteger(pointerIndex) && !state.select) {
      openItemContextMenu(pointerIndex, pointerTile, { mode: "preview" });
      return;
    }
    if (state.cursor < 0 || state.cursor >= state.items.length) {
      state.cursor = 0;
    }
    if (state.select) {
      setTileSelected(state.cursor, !state.selected.has(state.cursor));
      syncSelbar();
      paintKeyboardFocus();
    } else {
      openViewer(state.cursor);
    }
    return;
  }

  if (key === "Delete") {
    if (
      !state.select ||
      (state.selected.size === 0 && state.selectedTrashAlbums.size === 0)
    )
      return;
    e.preventDefault();
    if (state.activeId === "trash") deleteTrashSelected();
    else trashSelected();
    return;
  }

  if (key === "s" || key === "S") {
    if (state.select || !hasGridItems()) return;
    e.preventDefault();
    enterSelection({ showFocus: true });
    return;
  }

  if (key === "r" || key === "R") {
    e.preventDefault();
    cyclePhotoStyle();
    return;
  }

  if (key === "e" || key === "E") {
    const button = $("#editBtn");
    if (button.hidden || button.disabled) return;
    e.preventDefault();
    toggleEditMode();
    return;
  }
});

/* ------------------------------ 启动 ------------------------------ */

localStorage.removeItem("album-sidebar-collapsed");
/* 清掉旧版本留下的长期相簿记录，避免升级后仍跨软件启动恢复。 */
localStorage.removeItem(ACTIVE_VIEW_KEY);

/* 每次启动按设置里的“默认打开”恢复视图；默认打开「图库」。
   没有根目录时必须停留在「图库」展示导入提示；相簿被删掉或读取失败时
   才退回「所有相簿」。 */
async function restoreActiveView() {
  if (!state.roots.length) {
    state.activeId = "library";
    try {
      await loadLibrary();
    } catch {
      state.busy = "";
      fallbackToAllAlbums();
    }
    return;
  }

  const saved = normalizeDefaultOpenView(defaultOpenView);
  if (!saved) {
    state.activeId = "library";
    try {
      await loadLibrary();
    } catch {
      state.busy = "";
      fallbackToAllAlbums();
    }
    return;
  }

  if (saved === "all") {
    state.activeId = "all";
    return;
  }

  if (saved === "library") {
    state.activeId = "library";
    try {
      await loadLibrary();
    } catch {
      state.busy = "";
      fallbackToAllAlbums();
    }
    return;
  }

  if (saved === "locations") {
    state.activeId = "locations";
    state.locationSubview = "map";
    try {
      await loadLocationItems();
      state.items = sortedLocationItems();
    } catch {
      state.busy = "";
      fallbackToAllAlbums();
    }
    return;
  }

  if (saved === "photoWall") {
    state.activeId = "photoWall";
    state.wallLibraryKind = normalizeWallLibraryKind(photoWallDefaultKind);
    try {
      await loadPhotoWallAlbums();
    } catch {
      state.busy = "";
      fallbackToAllAlbums();
    }
    return;
  }

  if (saved === "favorites") {
    state.activeId = "favorites";
    try {
      await loadFavorites();
    } catch {
      state.busy = "";
      fallbackToAllAlbums();
    }
    return;
  }

  if (saved === "trash") {
    state.activeId = "trash";
    try {
      await loadTrash();
    } catch {
      state.busy = "";
      fallbackToAllAlbums();
    }
    return;
  }

  const id = Number(saved);
  if (!Number.isInteger(id) || !albumById(id)) {
    fallbackToAllAlbums();
    return;
  }

  state.activeId = id;
  try {
    await loadAlbum(id);
  } catch {
    state.busy = "";
    fallbackToAllAlbums();
  }
}

/* 打开时先让上次的封面显示出来。等这些图真的上了屏，再去后台清缓存、重扫，
   免得启动阶段先摆一排空白格。 */
function waitForVisibleCoverImages(timeout = 1200) {
  const imgs = [
    ...document.querySelectorAll(
      ".album-card img, .nav-item img, .photo-grid .tile img",
    ),
  ].filter((img) => {
    if (img.complete) return false;
    const rect = img.getBoundingClientRect();
    return (
      rect.bottom > 0 &&
      rect.top < window.innerHeight &&
      rect.right > 0 &&
      rect.left < window.innerWidth
    );
  });
  if (!imgs.length) return Promise.resolve();
  return new Promise((resolve) => {
    let left = imgs.length;
    let settled = false;
    const finish = () => {
      if (settled) return;
      settled = true;
      resolve();
    };
    const one = () => {
      if (--left <= 0) finish();
    };
    for (const img of imgs) {
      img.addEventListener("load", one, { once: true });
      img.addEventListener("error", one, { once: true });
    }
    setTimeout(finish, timeout);
  });
}

let startupCoverSyncStarted = false;
async function syncCoversAfterOpen() {
  if (startupCoverSyncStarted) return;
  startupCoverSyncStarted = true;
  let applied = false;
  try {
    const res = await api("/api/covers/refresh", { method: "POST" });
    if (!res.changed) return;
    /* 用户已经开始选择 / 看大图 / 拖相簿时先别换，等这轮交互结束再走正常的自动刷新。 */
    if (
      state.select ||
      !$("#viewer").hidden ||
      galleryZoomBusy ||
      albumGesture ||
      albumSettling
    ) {
      pendingUpdate = true;
      return;
    }
    await preloadCoverThumbs(res.state);
    const scrollTop = $("#content").scrollTop;
    applyState(res.state);
    if (state.activeId === "locations") {
      await reloadActiveCollection();
    } else if (state.activeId === "trash") {
      await loadTrash();
    } else if (state.activeId === "library") {
      await loadLibrary();
    } else if (state.activeId === "favorites") {
      await loadFavorites();
    } else if (state.activeId !== "all" && albumById(state.activeId)) {
      await loadAlbum(state.activeId, { quiet: true });
    } else if (state.activeId !== "all") {
      fallbackToAllAlbums();
    }
    render();
    $("#content").scrollTop = scrollTop;
    applied = true;
  } catch {
    /* 后台检查失败就保持上次的封面，下次打开再试。 */
  } finally {
    if (applied) {
      try {
        lastRev = (await api("/api/revision")).rev;
      } catch {}
    }
  }
}

let startupScreenDismissed = false;
function setStartupStatus(message) {
  if (startupScreenDismissed) return;
  const status = $("#startupScreen .startup-copy");
  if (status) status.textContent = message;
}

function dismissStartupScreen({ immediate = false } = {}) {
  if (startupScreenDismissed) return;
  startupScreenDismissed = true;
  const screen = $("#startupScreen");
  if (!screen) return;
  if (immediate) {
    screen.hidden = true;
    return;
  }
  screen.classList.add("is-leaving");
  setTimeout(() => {
    screen.hidden = true;
  }, 110);
}

function showWindowWithInterface() {
  document.documentElement.classList.remove("app-initializing");
  dismissStartupScreen({ immediate: true });
  window.albumWindow?.showWhenReady?.();
  progressivePhotoGridReady = true;
  setTimeout(scheduleProgressivePhotoGridFill, 120);
}

async function handleUnavailableRoots() {
  const unavailable = state.roots.filter((root) => root.available === false);
  for (const root of unavailable) {
    const message =
      `根目录暂时无法访问：\n\n${root.path}\n\n` +
      "如果目录已经被删除或移动，点击“确定”将从软件中移除记录。\n" +
      "将清除该根目录的索引、相簿、收藏、编辑参数和最近删除记录，" +
      "不会删除磁盘文件，也不影响其他根目录。\n\n" +
      "如果只是移动硬盘或网络目录暂时离线，请点击“取消”保留记录。";
    if (confirm(message)) {
      await removeRoot(root.id, { confirmRemoval: false });
    }
  }
}

/* 白色内容卡不能再靠 `inset(... round ...)` 表达连续曲率：
   按当前窗口尺寸生成一条超椭圆裁切路径，窗口一变就重算。
   外层玻璃仍由 DWM 裁切，这条路径只负责窗口内部的内容卡。 */
function continuousCardPath(
  width,
  height,
  insetX,
  insetTop,
  insetBottom,
  radius,
) {
  const x = insetX;
  const y = insetTop;
  const w = Math.max(1, width - insetX * 2);
  const bottom = Math.max(y + 1, height - insetBottom);
  const h = bottom - y;
  const r = Math.min(radius, w / 2, h / 2);
  const exponent = 4.5;
  const steps = 16;

  const corner = (cx, cy, from, to) => {
    let points = "";
    for (let i = 1; i <= steps; i += 1) {
      const angle = from + (to - from) * (i / steps);
      const cos = Math.cos(angle);
      const sin = Math.sin(angle);
      const px =
        cx + r * Math.sign(cos) * Math.pow(Math.abs(cos), 2 / exponent);
      const py =
        cy + r * Math.sign(sin) * Math.pow(Math.abs(sin), 2 / exponent);
      points += ` L ${px.toFixed(2)} ${py.toFixed(2)}`;
    }
    return points;
  };

  let d = `M ${(x + r).toFixed(2)} ${y.toFixed(2)}`;
  d += ` L ${(x + w - r).toFixed(2)} ${y.toFixed(2)}`;
  d += corner(x + w - r, y + r, -Math.PI / 2, 0);
  d += ` L ${(x + w).toFixed(2)} ${(y + h - r).toFixed(2)}`;
  d += corner(x + w - r, y + h - r, 0, Math.PI / 2);
  d += ` L ${(x + r).toFixed(2)} ${(y + h).toFixed(2)}`;
  d += corner(x + r, y + h - r, Math.PI / 2, Math.PI);
  d += ` L ${x.toFixed(2)} ${(y + r).toFixed(2)}`;
  d += corner(x + r, y + r, -Math.PI, -Math.PI / 2);
  return d + " Z";
}

let windowCardClipFrame = 0;
function syncWindowCardClip() {
  const path = document.getElementById("windowCardClipPath");
  const app = document.querySelector(".app");
  if (!path || !app) return;
  const root = getComputedStyle(document.documentElement);
  const readPixels = (property, fallback) => {
    const value = parseFloat(root.getPropertyValue(property));
    return Number.isFinite(value) ? value : fallback;
  };
  const insetX = readPixels("--window-frame", 6);
  const insetTop = readPixels("--app-frame-top", 6);
  const insetBottom = readPixels("--app-frame-bottom", 6);
  const radius = readPixels("--window-card-radius", 8);
  path.setAttribute(
    "d",
    continuousCardPath(
      app.clientWidth,
      app.clientHeight,
      insetX,
      insetTop,
      insetBottom,
      radius,
    ),
  );
  app.style.clipPath = "url(#windowCardClip)";
}

function scheduleWindowCardClip() {
  if (windowCardClipFrame) return;
  windowCardClipFrame = requestAnimationFrame(() => {
    windowCardClipFrame = 0;
    syncWindowCardClip();
  });
}

syncWindowCardClip();
window.addEventListener("resize", scheduleWindowCardClip);

(async function boot() {
  try {
    hydrateCurveLoaders();
  } catch (error) {
    console.error("[Fotora curve loader]", error);
    document.documentElement.dataset.curveLoaderError = String(
      error?.stack || error,
    );
  }
  setStartupStatus("正在读取图库…");
  try {
    await refreshState();
  } catch (err) {
    $("#content").innerHTML = renderEmpty(
      "连不上本地服务：" +
        esc(err.message) +
        "<br><br>先在项目目录运行 npm start",
    );
    showWindowWithInterface();
    return;
  }
  await hydratePersistentSettings();
  void persistPersistentSettings();
  setStartupStatus("正在整理照片…");
  await restoreActiveView();
  setStartupStatus("正在准备首屏…");
  render();
  restoreCollectionScroll();
  if (!photoWallLibraryRailIsLocked()) {
    const storedSidebarRailCollapsed = readSidebarRailCollapsed();
    if (
      hoverExpandSidebar ||
      (storedSidebarRailCollapsed ?? state.roots.length === 0)
    ) {
      setSidebarRailCollapsed(true, { animate: false });
    } else {
      syncSidebarHoverPeekMode();
    }
  } else {
    syncSidebarHoverPeekMode();
  }
  await resumePendingPhotoWallEntry();
  /* 先让完成后的界面提交一帧，再同时显示原生窗口和内容。
     封面继续在后台补齐，占位底色不会露成空白窗口。 */
  requestAnimationFrame(() => {
    requestAnimationFrame(showWindowWithInterface);
  });
  await handleUnavailableRoots();
  void promptFolderImports();
  /* 盯着磁盘的变化：服务端扫完会把版本号 +1，这里轮询到就自动刷新 */
  await pollRevision();
  setInterval(pollRevision, POLL_MS);
  setTimeout(async () => {
    await waitForVisibleCoverImages();
    if (hasIncompleteProgressivePhotoGrid()) return;
    if (typeof requestIdleCallback === "function") {
      await new Promise((resolve) =>
        requestIdleCallback(resolve, { timeout: 1800 }),
      );
    } else {
      await new Promise((resolve) => setTimeout(resolve, 120));
    }
    await syncCoversAfterOpen();
  }, 1200);
})();
